--
-- Name: broadcast_recipients_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.broadcast_recipients_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if NEW.state is distinct from OLD.state then
    -- The claim, settled: the one failed that is not a verdict.
    if OLD.state = 'failed' and OLD.reason = 'outcome_unknown' and NEW.state in ('sent', 'skipped') then
      return NEW;
    end if;
    -- Or released, when WhatsApp refused the send as too many, too fast: nothing was taken, and the release says so.
    if OLD.state = 'failed' and OLD.reason = 'outcome_unknown' and NEW.state = 'queued' and NEW.reason = 'throttled' then
      return NEW;
    end if;
    if OLD.state in ('sent', 'skipped', 'failed') then
      raise exception 'broadcast_recipients.state is terminal (% -> % refused)', OLD.state, NEW.state;
    end if;
    -- From queued the CHECK admits only sent, skipped and failed.
  end if;
  return NEW;
end $$;


--
-- Name: FUNCTION broadcast_recipients_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.broadcast_recipients_guard() IS 'queued -> sent|skipped|failed, once; a claim (failed, outcome_unknown) -> sent|skipped, or back to queued as throttled when WhatsApp said not now; sent, skipped and other failures are final. A same-state update is not a move.';


--
-- Name: broadcasts_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.broadcasts_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if NEW.state is distinct from OLD.state then
    if OLD.state in ('sent', 'canceled', 'failed') then
      raise exception 'broadcasts.state is terminal (% -> % refused)', OLD.state, NEW.state;
    end if;
    if OLD.state = 'pending_approval' and NEW.state not in ('scheduled', 'canceled', 'failed') then
      raise exception 'a broadcast awaiting approval may only be scheduled, canceled or failed (% refused)', NEW.state;
    end if;
    if OLD.state = 'scheduled' and NEW.state not in ('sending', 'canceled', 'failed', 'pending_approval') then
      raise exception 'a scheduled broadcast may only start sending, be canceled, fail, or go back for approval (% refused)', NEW.state;
    end if;
    if OLD.state = 'sending' and NEW.state not in ('sent', 'failed', 'canceled') then
      raise exception 'a sending broadcast may only finish, fail or be canceled (% refused)', NEW.state;
    end if;
  end if;
  return NEW;
end $$;


--
-- Name: FUNCTION broadcasts_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.broadcasts_guard() IS 'The edges a broadcast may take: pending_approval -> scheduled|canceled|failed; scheduled -> sending|canceled|failed|pending_approval; sending -> sent|failed|canceled; sent, canceled and failed are final. A same-state update is not a move.';


--
-- Name: calendars_due(timestamp with time zone, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calendars_due(p_before timestamp with time zone, p_limit integer, p_tenant_id uuid DEFAULT NULL::uuid) RETURNS TABLE(tenant_id uuid, config jsonb, timezone text, due_total bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select c.tenant_id, c.config, z.tz, count(*) over ()
    from public.tenant_config c
    join public.tenants t on t.id = c.tenant_id
    cross join lateral (select public.safe_zone(coalesce(nullif(btrim(t.timezone), ''), 'America/New_York')) as tz) z
   where nullif(btrim(c.config->'calendar'->>'ical_url'), '') is not null
     and (p_tenant_id is null or c.tenant_id = p_tenant_id)
     and (c.calendar_checked_at is null or c.calendar_checked_at < p_before)
   order by c.calendar_checked_at nulls first, c.tenant_id
   limit greatest(coalesce(p_limit, 0), 0)
$$;


--
-- Name: FUNCTION calendars_due(p_before timestamp with time zone, p_limit integer, p_tenant_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.calendars_due(p_before timestamp with time zone, p_limit integer, p_tenant_id uuid) IS 'The workspaces with a calendar feed never read or last read before p_before, never read first, then least recently read, each with its zone, with due_total the count of all that were due. The calendar sweep''s page (00245).';


--
-- Name: call_status_rank(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.call_status_rank(p_status text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case p_status
           when 'registered' then 0
           when 'ongoing'    then 1
           else 2   -- ended, error, not_connected: terminal
         end
$$;


--
-- Name: caller_has_permission(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.caller_has_permission(p_tenant_id uuid, p_permission text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.has_permission((select auth.uid()), p_tenant_id, p_permission)
     and not exists (
       select 1 from public.memberships m
        where m.user_id = (select auth.uid()) and m.tenant_id = p_tenant_id and m.role = 'partner'
          and not public.session_shows_second_factor()
     );
$$;


--
-- Name: FUNCTION caller_has_permission(p_tenant_id uuid, p_permission text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.caller_has_permission(p_tenant_id uuid, p_permission text) IS 'has_permission for the calling session: whether the caller may do this in this workspace, a partner only on a session that showed its second factor (0013). Answers only about the caller, which is why every session may ask.';


--
-- Name: campaign_series(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.campaign_series(p_tenant_id uuid, p_days integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  v_tz     text;
  v_days   integer := least(greatest(coalesce(p_days, 30), 1), 90);
  v_span   integer;
  v_today  date;
  v_start  timestamptz;
  v_cur    date;
  v_result jsonb;
begin
  select timezone into v_tz from tenants where id = p_tenant_id;
  if v_tz is null then
    return jsonb_build_object('error', 'unknown_tenant');
  end if;

  v_span  := v_days * 2;
  v_today := (now() at time zone v_tz)::date;
  v_start := ((v_today - (v_span - 1))::timestamp) at time zone v_tz;
  v_cur   := v_today - (v_days - 1);

  with days as (
    select (v_today - (v_span - 1) + g)::date as day
      from generate_series(0, v_span - 1) g
  ),
  -- Every message a broadcast or a playbook run actually sent in the span,
  -- with the receipt WhatsApp gave it and the thread it landed in.
  sent as (
    select r.broadcast_id, r.contact_id, r.sent_at,
           (r.sent_at at time zone v_tz)::date as day,
           m.status as message_status, m.conversation_id,
           b.playbook_id, b.name as broadcast_name, b.template_name
      from broadcast_recipients r
      join broadcasts b on b.id = r.broadcast_id
      left join messages m on m.id = r.message_id
     where r.tenant_id = p_tenant_id
       and r.state = 'sent'
       and r.sent_at >= v_start
  ),
  -- Replied: the customer wrote in that thread after the message went out —
  -- the same rule the Broadcasts page counts by.
  sent_r as (
    select s.*,
           (s.message_status in ('delivered', 'read')) as delivered,
           (s.message_status = 'read')                as was_read,
           exists (select 1 from messages i
                    where i.conversation_id = s.conversation_id
                      and i.direction = 'inbound'
                      and i.created_at > s.sent_at
                      and i.created_at <= s.sent_at + interval '72 hours')  as replied
      from sent s
  ),
  -- A yes or a stop, from the desk or in the customer's own words: the
  -- consent ledger both doors write (00013, 00043). Not email's own answer (00174).
  consent as (
    select (e.created_at at time zone v_tz)::date as day, e.data->>'consent' as consent
      from events e
     where e.tenant_id = p_tenant_id
       and e.kind = 'contact.consent_changed'
       and e.created_at >= v_start
       and coalesce(e.data->>'purpose', '') <> 'email_marketing'
  ),
  -- Each day from one pass over each source, grouped by the day (00251), where a scalar subquery per day and per
  -- count scanned both again for every day.
  per_day as (
    select d.day,
           coalesce(s.sent, 0)      as sent,
           coalesce(s.delivered, 0) as delivered,
           coalesce(s.was_read, 0)  as was_read,
           coalesce(s.replied, 0)   as replied,
           coalesce(c.opt_ins, 0)   as opt_ins,
           coalesce(c.opt_outs, 0)  as opt_outs
      from days d
      left join (select s.day, count(*) as sent,
                        count(*) filter (where s.delivered) as delivered,
                        count(*) filter (where s.was_read)  as was_read,
                        count(*) filter (where s.replied)   as replied
                   from sent_r s group by s.day) s on s.day = d.day
      left join (select c.day,
                        count(*) filter (where c.consent = 'opted_in')  as opt_ins,
                        count(*) filter (where c.consent = 'opted_out') as opt_outs
                   from consent c group by c.day) c on c.day = d.day
  ),
  -- The current period by source: a playbook's runs together, a one-off
  -- broadcast on its own.
  sources as (
    select coalesce(s.playbook_id, s.broadcast_id) as id,
           (s.playbook_id is not null)             as is_playbook,
           coalesce(max(p.name), max(s.broadcast_name)) as name,
           max(s.template_name)                    as template_name,
           count(distinct s.broadcast_id)          as runs,
           count(*)                                as sent,
           count(*) filter (where s.delivered)     as delivered,
           count(*) filter (where s.was_read)      as was_read,
           count(*) filter (where s.replied)       as replied,
           max(s.sent_at)                          as last_at
      from sent_r s
      left join playbooks p on p.id = s.playbook_id
     where s.day >= v_cur
     group by coalesce(s.playbook_id, s.broadcast_id), (s.playbook_id is not null)
  )
  select jsonb_build_object(
    'timezone', v_tz,
    'days', v_days,
    'span_days', v_span,
    'today', to_char(v_today, 'YYYY-MM-DD'),
    'series', (select jsonb_agg(jsonb_build_object(
                 'day', to_char(p.day, 'YYYY-MM-DD'),
                 'sent', p.sent,
                 'delivered', p.delivered,
                 'read', p.was_read,
                 'replied', p.replied,
                 'opt_ins', p.opt_ins,
                 'opt_outs', p.opt_outs) order by p.day)
               from per_day p),
    'sources', coalesce((select jsonb_agg(jsonb_build_object(
                 'id', x.id,
                 'kind', case when x.is_playbook then 'playbook' else 'broadcast' end,
                 'name', x.name,
                 'template_name', x.template_name,
                 'runs', x.runs,
                 'sent', x.sent,
                 'delivered', x.delivered,
                 'read', x.was_read,
                 'replied', x.replied,
                 'last_at', x.last_at) order by x.sent desc, x.last_at desc)
               from sources x), '[]'::jsonb)
  ) into v_result;

  return v_result;
end $$;


--
-- Name: FUNCTION campaign_series(p_tenant_id uuid, p_days integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.campaign_series(p_tenant_id uuid, p_days integer) IS 'Reports › Campaigns: messages sent by broadcasts and playbook runs, delivered and read receipts, replies, yeses and stops (not an unsubscribe from email, 00174) — day by day over two periods, and the current period by playbook or broadcast. Invoker''s RLS.';


--
-- Name: claim_conversation_control(uuid, uuid, text, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_conversation_control(p_tenant_id uuid, p_conversation_id uuid, p_kind text, p_by uuid, p_ref text, p_seconds integer) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_kind  text;
  v_by    uuid;
  v_ref   text;
  v_until timestamptz;
  v_same  boolean;
  v_live  boolean;
begin
  if p_kind not in ('person', 'call') then
    raise exception 'control kind must be person or call' using errcode = '22023';
  end if;
  if p_seconds is null or p_seconds < 1 or p_seconds > 86400 then
    raise exception 'a hold lasts between a second and a day' using errcode = '22023';
  end if;
  -- FOR UPDATE, so two claimants in the same instant are decided by the
  -- database and not by whichever of them read first. That is the whole point
  -- of the function: the same question asked as a select and then an update
  -- lets both callers believe the thread was free.
  select c.control_kind, c.control_by, c.control_ref, c.control_until
    into v_kind, v_by, v_ref, v_until
    from conversations c
   where c.id = p_conversation_id and c.tenant_id = p_tenant_id
     for update;
  if not found then
    return 'gone';
  end if;
  -- A live hold, and whose it is decides what happens next.
  --
  --   the same holder    renewing, not competing. A call sends an event every
  --                      few turns, and that is what keeps a long call from
  --                      lapsing mid-sentence.
  --   a person claiming  takes it, always. A person stepping in outranks the
  --                      machine -- that is what stepping in MEANS -- and a
  --                      colleague is not locked out of a thread by another
  --                      colleague. Coordinating between people is theirs to
  --                      do; this fact exists to keep the machine off.
  --   a call claiming    never takes a hold somebody else has. The call still
  --                      happens; it simply does not get to say the thread is
  --                      its own while a person is on it.
  v_live := v_until is not null and v_until >= now();
  v_same := v_kind = p_kind and v_by is not distinct from p_by and v_ref is not distinct from p_ref;
  if v_live and not v_same and p_kind <> 'person' then
    return 'held';
  end if;
  update conversations
     set control_kind  = p_kind,
         control_by    = p_by,
         control_ref   = p_ref,
         control_until = now() + make_interval(secs => p_seconds)
   where id = p_conversation_id and tenant_id = p_tenant_id;
  -- Renewed is the same holder going on; taking one from somebody else is a
  -- claim, and the caller is owed the difference -- it is the line in the log
  -- that says a person stepped into a call.
  return case when v_live and v_same then 'renewed' else 'claimed' end;
end $$;


--
-- Name: FUNCTION claim_conversation_control(p_tenant_id uuid, p_conversation_id uuid, p_kind text, p_by uuid, p_ref text, p_seconds integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.claim_conversation_control(p_tenant_id uuid, p_conversation_id uuid, p_kind text, p_by uuid, p_ref text, p_seconds integer) IS 'Take the live hold on a thread, or renew one this holder already has. A person takes it from anyone; a call never takes one somebody else holds. Returns claimed, renewed, held or gone. Atomic: the row is locked, so two claimants cannot both be told the thread was free.';


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: jobs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    kind text NOT NULL,
    due_at timestamp with time zone NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    state text DEFAULT 'scheduled'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    fired_at timestamp with time zone,
    last_error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    lease_until timestamp with time zone,
    CONSTRAINT jobs_kind_check CHECK ((kind = ANY (ARRAY['outbound_send'::text, 'broadcast_send'::text, 'line_provision'::text, 'email_ingest'::text, 'lead_round_start'::text, 'lead_collect'::text, 'lead_check'::text, 'push_send'::text, 'push_receipts'::text, 'reply_read'::text]))),
    CONSTRAINT jobs_state_check CHECK ((state = ANY (ARRAY['scheduled'::text, 'fired'::text, 'done'::text, 'canceled'::text, 'failed'::text])))
);


--
-- Name: COLUMN jobs.lease_until; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.jobs.lease_until IS 'While in the future, a run holds this row. Once past, the run is presumed dead and claim_due_jobs() may take the row again with attempts + 1; whether that run goes ahead or gives up is verdictFor() in packages/jobs/src/ledger.ts.';


--
-- Name: claim_due_jobs(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_due_jobs(p_limit integer, p_lease_seconds integer) RETURNS SETOF public.jobs
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with due as (
    select id
      from public.jobs
     where (state = 'scheduled' and due_at <= now())
        or (state = 'fired' and lease_until < now())
     order by due_at
     limit p_limit
     for update skip locked
  )
  update public.jobs j
     set state       = 'fired',
         fired_at    = now(),
         attempts    = j.attempts + 1,
         lease_until = now() + make_interval(secs => p_lease_seconds)
    from due
   where j.id = due.id
  returning j.*
$$;


--
-- Name: FUNCTION claim_due_jobs(p_limit integer, p_lease_seconds integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.claim_due_jobs(p_limit integer, p_lease_seconds integer) IS 'The only way a job becomes fired. Concurrent ticks take disjoint rows (SKIP LOCKED). attempts counts claims: 1 is the first run; more means a lease ran out before a run reported back.';


--
-- Name: clear_control_of_departed_member(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clear_control_of_departed_member() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update conversations
     set assignee_user_id = null
   where tenant_id = old.tenant_id and assignee_user_id = old.user_id;
  update conversations
     set control_kind = null, control_by = null, control_ref = null, control_until = null
   where tenant_id = old.tenant_id and control_kind = 'person' and control_by = old.user_id;
  return old;
end $$;


--
-- Name: FUNCTION clear_control_of_departed_member(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.clear_control_of_departed_member() IS 'A member removed from a workspace stops being responsible for its threads and stops holding any. Without this, a departed colleague went on owning conversations that then sat in nobody''s queue, and the door went on refusing the receptionist''s drafts on their behalf for ever.';


--
-- Name: cold_receipts_owed(timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cold_receipts_owed(p_from timestamp with time zone, p_to timestamp with time zone) RETURNS TABLE(tenant_id uuid, host text, sent integer, unanswered integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select d.tenant_id, d.host,
         count(*)::integer,
         (count(*) filter (where m.status = 'sent'))::integer
    from public.sending_domains d
    join public.messages m
      on m.tenant_id = d.tenant_id and m.channel = 'email' and m.direction = 'outbound'
     and public.email_from_host(m.meta) = lower(d.host)
     and m.created_at >= p_from - interval '30 days' and m.created_at < p_to
     and public.email_left(m.status, m.error)
     and public.email_sent_at(m.meta, m.status_updated_at, m.created_at) >= p_from
     and public.email_sent_at(m.meta, m.status_updated_at, m.created_at) < p_to
   where d.state = 'verified'
   group by d.tenant_id, d.host
$$;


--
-- Name: FUNCTION cold_receipts_owed(p_from timestamp with time zone, p_to timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cold_receipts_owed(p_from timestamp with time zone, p_to timestamp with time zone) IS 'Per verified own domain: the emails that left it, sent in the window, and how many no receipt has reached (apps/edge api/cron/domains.ts). Service role only.';


--
-- Name: contact_email_change_clears_suppression(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contact_email_change_clears_suppression() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.email is distinct from old.email then
    new.email_suppressed_at := null;
    new.email_suppressed_reason := null;
  end if;
  return new;
end $$;


--
-- Name: contact_email_on_erase(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contact_email_on_erase() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.erased_at is not null and old.erased_at is null then
    new.email := null;
    new.email_suppressed_at := null;
    new.email_suppressed_reason := null;
  end if;
  return new;
end $$;


--
-- Name: contact_events_on_erase(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contact_events_on_erase() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.erased_at is not null and old.erased_at is null then
    perform public.scrub_contact_events(new.tenant_id, new.id);
  end if;
  return new;
end $$;


--
-- Name: contact_proposal_on_erase(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contact_proposal_on_erase() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.erased_at is not null and old.erased_at is null then
    new.proposal_url := null;
  end if;
  return new;
end $$;


--
-- Name: create_mailbox(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_mailbox(p_tenant_id uuid, p_local_part text, p_from_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_user  uuid := auth.uid();
  v_local text := lower(btrim(coalesce(p_local_part, '')));
  v_name  text := btrim(coalesce(p_from_name, ''));
  v_row   public.mailboxes;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  if not public.caller_has_permission(p_tenant_id, 'settings') then
    raise exception 'Only an owner can set up email.' using errcode = '42501';
  end if;
  begin
    insert into mailboxes (tenant_id, local_part, reply_token, from_name)
    values (p_tenant_id, v_local, public.mint_reply_token(), v_name)
    returning * into v_row;
  exception
    when check_violation then
      raise exception 'That cannot be used as an address or a name.' using errcode = '22023';
    when unique_violation then
      if exists (select 1 from mailboxes m where m.tenant_id = p_tenant_id) then
        raise exception 'This workspace already has an email address.' using errcode = '23505';
      end if;
      raise exception 'That address is taken. Try another.' using errcode = '23505';
  end;
  insert into events (tenant_id, kind, category, subject_type, subject_id, data)
  values (p_tenant_id, 'mailbox.created', 'system', 'mailbox', v_row.id, jsonb_build_object('by', v_user));
  return jsonb_build_object('id', v_row.id, 'local_part', v_row.local_part, 'from_name', v_row.from_name);
end $$;


--
-- Name: FUNCTION create_mailbox(p_tenant_id uuid, p_local_part text, p_from_name text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_mailbox(p_tenant_id uuid, p_local_part text, p_from_name text) IS 'An owner, or the partner who set the workspace up, gives it its email address, once. The reply route''s token is minted here; the event records who, never the address.';


--
-- Name: create_person(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_person(p_tenant_id uuid, p_phone_e164 text, p_display_name text, p_source text, p_title text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_user    uuid := auth.uid();
  v_name    text := nullif(btrim(regexp_replace(coalesce(p_display_name, ''), '\s+', ' ', 'g')), '');
  v_phone   text := btrim(coalesce(p_phone_e164, ''));
  v_source  text := coalesce(nullif(btrim(p_source), ''), 'manual');
  v_id      uuid;
  v_existed boolean := false;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  if p_tenant_id is null or not public.is_acting_member(p_tenant_id) then
    raise exception 'Workspace not found.' using errcode = 'P0002';
  end if;
  if v_phone !~ '^\+[1-9][0-9]{7,14}$' then
    raise exception 'A phone number in international form is needed.' using errcode = '22023';
  end if;
  if v_name is not null and char_length(v_name) > 80 then
    raise exception 'A name is at most 80 characters.' using errcode = '22023';
  end if;

  select c.id into v_id
    from contacts c
   where c.tenant_id = p_tenant_id
     and c.phone_e164 = v_phone
     and c.erased_at is null
     and c.merged_into_contact_id is null
   limit 1;

  if v_id is not null then
    v_existed := true;
    -- A name we did not have is worth keeping; one we have is never overwritten.
    if v_name is not null then
      update contacts set display_name = v_name, updated_at = now()
       where id = v_id and display_name is null;
    end if;
  else
    begin
      insert into contacts (tenant_id, phone_e164, display_name)
      values (p_tenant_id, v_phone, v_name)
      returning id into v_id;
      insert into events (tenant_id, kind, category, subject_type, subject_id, data)
      values (p_tenant_id, 'contact.added', 'contact', 'contact', v_id,
              jsonb_build_object('source', v_source, 'title', p_title, 'by', v_user));
    exception when unique_violation then
      -- Someone else won the race: theirs is the one, nothing is created twice.
      select c.id into v_id from contacts c
       where c.tenant_id = p_tenant_id and c.phone_e164 = v_phone
       limit 1;
      v_existed := true;
    end;
  end if;

  return jsonb_build_object('contact_id', v_id, 'existed', v_existed, 'source', v_source);
end $_$;


--
-- Name: FUNCTION create_person(p_tenant_id uuid, p_phone_e164 text, p_display_name text, p_source text, p_title text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_person(p_tenant_id uuid, p_phone_e164 text, p_display_name text, p_source text, p_title text) IS 'Owner or operator adds a person by phone — get-or-create; a name fills only an empty one; consent stays unknown; a contact.added event says where they came from.';


--
-- Name: create_workspace(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_workspace(p_name text, p_timezone text DEFAULT NULL::text, p_partner_code text DEFAULT NULL::text) RETURNS TABLE(id uuid, slug text, name text, status text, timezone text, locale text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  return query
    select w.id, w.slug, w.name, w.status, w.timezone, w.locale
      from public.create_workspace_for(auth.uid(), p_name, p_timezone, p_partner_code) w;
end $$;


--
-- Name: FUNCTION create_workspace(p_name text, p_timezone text, p_partner_code text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_workspace(p_name text, p_timezone text, p_partner_code text) IS 'Create a workspace and make the calling user its owner, in one transaction; p_partner_code credits the partner whose link brought them (0012). Caller is auth.uid(), never a parameter; the body lives in create_workspace_for.';


--
-- Name: create_workspace_for(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_workspace_for(p_user uuid, p_name text, p_timezone text DEFAULT NULL::text, p_partner_code text DEFAULT NULL::text) RETURNS TABLE(id uuid, slug text, name text, status text, timezone text, locale text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user    uuid := p_user;
  v_name    text := btrim(coalesce(p_name, ''));
  v_tz      text := nullif(btrim(coalesce(p_timezone, '')), '');
  v_code    text := nullif(lower(btrim(coalesce(p_partner_code, ''))), '');
  v_base    text;
  v_slug    text;
  v_try     int := 0;
  v_owned   int;
  v_id      uuid;
  v_partner public.partners;
  v_why     text;
begin
  -- No user, no workspace: the whole model is "this person becomes the owner".
  if v_user is null then
    raise exception 'A user is required.' using errcode = '28000';
  end if;

  if length(v_name) < 2 then
    raise exception 'A workspace needs a name of at least 2 characters.' using errcode = '22023';
  end if;
  if length(v_name) > 120 then
    raise exception 'That name is too long — 120 characters at most.' using errcode = '22023';
  end if;

  -- An unreal zone is not a cosmetic mistake (see 00021). Rejected at the door.
  -- `pg_timezone_names.name` is qualified because this function RETURNS a
  -- column called `name`; every table reference below is aliased for the same
  -- reason.
  if v_tz is not null
     and not exists (select 1 from pg_timezone_names z where z.name = v_tz) then
    raise exception 'Unknown timezone: %', v_tz using errcode = '22023';
  end if;

  -- Anti-abuse, not a product limit.
  select count(*) into v_owned
    from public.memberships m
   where m.user_id = v_user and m.role = 'owner';
  if v_owned >= 10 then
    raise exception 'This account already owns 10 workspaces.' using errcode = '54000';
  end if;

  -- Slug: lowercase ASCII, single dashes, no leading or trailing dash.
  v_base := lower(v_name);
  v_base := translate(
    v_base,
    'àáâãäåāăąèéêëēĕėęěìíîïĩīĭįòóôõöøōŏőùúûüũūŭůñńçćčšž',
    'aaaaaaaaaeeeeeeeeeiiiiiiiiooooooooouuuuuuuunncccsz'
  );
  v_base := regexp_replace(v_base, '[^a-z0-9]+', '-', 'g');
  v_base := btrim(v_base, '-');
  v_base := left(v_base, 40);
  v_base := btrim(v_base, '-');
  if v_base = '' then
    v_base := 'workspace';
  end if;

  -- Collision handling that terminates.
  v_slug := v_base;
  while exists (select 1 from public.tenants t where t.slug = v_slug) loop
    v_try := v_try + 1;
    if v_try > 50 then
      v_slug := v_base || '-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 8);
      exit;
    end if;
    v_slug := v_base || '-' || v_try::text;
  end loop;

  -- The AFTER INSERT trigger from 00017 provisions policies + config here.
  insert into public.tenants (slug, name, timezone)
  values (v_slug, v_name, coalesce(v_tz, 'America/New_York'))
  returning tenants.id into v_id;

  insert into public.memberships (tenant_id, user_id, role)
  values (v_id, v_user, 'owner');

  -- The partner (0012): credited only when the code names an active partner who is not the caller, and only now.
  -- A code that names nobody creditable is recorded as ignored, with why, and the workspace is made all the same:
  -- the link is the partner's affair, never the business's problem.
  if v_code is not null then
    select p.* into v_partner from public.partners p where p.code = v_code;
    if v_partner.id is null then
      v_why := 'unknown';
    elsif v_partner.status <> 'active' then
      v_why := v_partner.status;
    elsif v_partner.user_id = v_user then
      v_why := 'self';
    end if;
    if v_why is null then
      insert into public.partner_tenants (tenant_id, partner_id, code_used)
      values (v_id, v_partner.id, v_code);
      insert into public.memberships (tenant_id, user_id, role)
      values (v_id, v_partner.user_id, 'partner');
      insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
      values (v_id, 'partner.attributed', 'workspace', 'tenant', v_id,
              jsonb_build_object('partner_id', v_partner.id, 'code', v_code, 'by', v_user));
    else
      insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
      values (v_id, 'partner.code_ignored', 'workspace', 'tenant', v_id,
              jsonb_build_object('code', v_code, 'why', v_why, 'by', v_user));
    end if;
  end if;

  return query
    select t.id, t.slug, t.name, t.status, t.timezone, t.locale
      from public.tenants t
     where t.id = v_id;
end $$;


--
-- Name: FUNCTION create_workspace_for(p_user uuid, p_name text, p_timezone text, p_partner_code text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_workspace_for(p_user uuid, p_name text, p_timezone text, p_partner_code text) IS 'Create a workspace and make p_user its owner, in one transaction; with p_partner_code, credit the partner it names and seat them on the team (0012). Service role only; create_workspace wraps it for signed-in callers.';


--
-- Name: create_workspace_for_business(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_workspace_for_business(p_name text, p_timezone text, p_owner_email text) RETURNS TABLE(id uuid, slug text, name text, status text, timezone text, locale text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_user    uuid := auth.uid();
  v_email   text := lower(btrim(coalesce(p_owner_email, '')));
  v_mine    text;
  v_partner public.partners;
  v_waiting int;
  v_id      uuid;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  if not public.session_shows_second_factor() then
    raise exception 'Enter the code from your authenticator app first: a partner signs in with two steps.'
      using errcode = '42501';
  end if;
  select p.* into v_partner from public.partners p where p.user_id = v_user for update;
  if v_partner.id is null then
    raise exception 'Only a partner can set a workspace up for a business.' using errcode = '42501';
  end if;
  if v_partner.status <> 'active' then
    raise exception 'Your partner account is %, so it cannot set up a workspace.', v_partner.status
      using errcode = '42501';
  end if;
  if length(v_email) > 254 or v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
    raise exception 'Enter the business owner''s email address.' using errcode = '22023';
  end if;
  select lower(u.email) into v_mine from auth.users u where u.id = v_user;
  if v_email = v_mine then
    raise exception 'That is your own address. Enter the business owner''s.' using errcode = '22023';
  end if;
  -- Anti-abuse, as create_workspace_for's ten owned: a workspace nobody owns is the platform's to keep. The partner's
  -- row is locked above, so two presses at once count each other.
  select count(*) into v_waiting
    from public.partner_tenants pt
   where pt.partner_id = v_partner.id and pt.origin = 'handover' and pt.handover_accepted_at is null;
  if v_waiting >= 10 then
    raise exception 'Ten workspaces are already waiting for their owners. When one is accepted, set up the next.'
      using errcode = '54000';
  end if;

  -- The name, the zone, the slug and the workspace's provisioning are create_workspace_for's, once; the partner's
  -- seat it makes is an owner's, and becomes a partner's in the same transaction.
  select w.id into v_id from public.create_workspace_for(v_user, p_name, p_timezone, null) w;
  update public.memberships m set role = 'partner' where m.tenant_id = v_id and m.user_id = v_user;

  insert into public.partner_tenants
    (tenant_id, partner_id, code_used, origin, handover_email, handover_sent_at, handover_expires_at)
  values
    (v_id, v_partner.id, v_partner.code, 'handover', v_email, now(), now() + interval '14 days');
  insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
  values (v_id, 'partner.handover_sent', 'workspace', 'tenant', v_id,
          jsonb_build_object('partner_id', v_partner.id, 'by', v_user));

  return query
    select t.id, t.slug, t.name, t.status, t.timezone, t.locale
      from public.tenants t
     where t.id = v_id;
end $_$;


--
-- Name: FUNCTION create_workspace_for_business(p_name text, p_timezone text, p_owner_email text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_workspace_for_business(p_name text, p_timezone text, p_owner_email text) IS 'The calling partner makes a workspace for a business (0016): seated as partner, never owner, credited at creation, and the workspace handed to p_owner_email for fourteen days. At most ten waiting for an owner.';


--
-- Name: deadman_candidates(interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deadman_candidates(p_older_than interval DEFAULT '02:00:00'::interval) RETURNS TABLE(escalation_id uuid, tenant_id uuid, conversation_id uuid, reason text, details text, opened_at timestamp with time zone, phone_e164 text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select e.id, e.tenant_id, e.conversation_id, e.reason, e.details, e.created_at, c.phone_e164
    from escalations e
    join conversations v on v.id = e.conversation_id
    left join contacts c on c.id = v.contact_id
   where e.state = 'open'
     and e.deadman_alerted_at is null
     and e.created_at < now() - p_older_than
   order by e.created_at
   limit 50;
$$;


--
-- Name: deadman_mark_alerted(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deadman_mark_alerted(p_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_count integer;
begin
  update escalations set deadman_alerted_at = now()
   where id = any(p_ids) and deadman_alerted_at is null;
  get diagnostics v_count = row_count;
  return v_count;
end $$;


--
-- Name: deal_record(uuid, text, uuid, integer, text, timestamp with time zone, integer, text, text, jsonb, text, date, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deal_record(p_contact_id uuid, p_stage text, p_deal_id uuid DEFAULT NULL::uuid, p_version integer DEFAULT NULL::integer, p_service text DEFAULT NULL::text, p_when timestamp with time zone DEFAULT NULL::timestamp with time zone, p_amount_cents integer DEFAULT NULL::integer, p_per text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_evidence jsonb DEFAULT NULL::jsonb, p_proposal_url text DEFAULT NULL::text, p_valid_until date DEFAULT NULL::date, p_lost_reason text DEFAULT NULL::text, p_clear text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_user    uuid := auth.uid();
  v_tenant  uuid;
  v_row     public.deals%rowtype;
  v_from    text;
  v_service text := nullif(btrim(coalesce(p_service, '')), '');
  v_note    text := nullif(btrim(coalesce(p_note, '')), '');
  v_when    timestamptz := coalesce(p_when, now());
  v_url     text := nullif(btrim(coalesce(p_proposal_url, '')), '');
  v_clear   text[] := coalesce(p_clear, '{}'::text[]);
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  if p_stage is null or p_stage not in ('proposed', 'won', 'lost', 'ended') then
    return jsonb_build_object('error', 'bad_stage');
  end if;
  if p_per is not null and p_per not in ('once', 'month', 'year') then
    return jsonb_build_object('error', 'bad_per');
  end if;
  if p_amount_cents is not null and p_amount_cents < 0 then
    return jsonb_build_object('error', 'bad_amount');
  end if;
  if v_note is not null and char_length(v_note) > 200 then
    return jsonb_build_object('error', 'note_too_long');
  end if;
  if v_service is not null and char_length(v_service) > 80 then
    return jsonb_build_object('error', 'service_too_long');
  end if;
  if v_url is not null and (char_length(v_url) not between 10 and 500 or v_url !~ '^https?://[^[:space:]]+$') then
    return jsonb_build_object('error', 'bad_link');
  end if;
  if p_lost_reason is not null
     and p_lost_reason not in ('price', 'timing', 'elsewhere', 'no_reply', 'not_a_fit', 'other') then
    return jsonb_build_object('error', 'bad_reason');
  end if;
  if exists (
    select 1 from unnest(v_clear) as c(field)
     where c.field is null or c.field not in ('proposal_url', 'valid_until', 'amount', 'note')
  ) then
    return jsonb_build_object('error', 'bad_clear');
  end if;

  select c.tenant_id into v_tenant
    from contacts c
   where c.id = p_contact_id and c.erased_at is null and c.merged_into_contact_id is null;
  if v_tenant is null or not public.is_acting_member(v_tenant) then
    return jsonb_build_object('error', 'not_found');
  end if;

  if p_deal_id is null then
    -- A new engagement starts as a proposal, and only one may be open per service.
    if p_stage <> 'proposed' then
      return jsonb_build_object('error', 'bad_move');
    end if;
    if exists (
      select 1 from deals d
       where d.contact_id = p_contact_id and d.stage in ('proposed', 'won')
         and coalesce(d.service, '') = coalesce(v_service, '')
    ) then
      return jsonb_build_object('error', 'already_open');
    end if;
    insert into deals (tenant_id, contact_id, lead_id, service, stage, proposed_at, amount_cents, per, note, evidence,
                       proposal_url, valid_until, created_by)
    values (
      v_tenant, p_contact_id,
      (select l.id from leads l where l.contact_id = p_contact_id and l.erased_at is null
        order by l.converted_at desc nulls last limit 1),
      v_service, 'proposed', v_when, p_amount_cents, p_per, v_note, p_evidence,
      v_url, p_valid_until, v_user
    )
    returning * into v_row;
    insert into events (tenant_id, kind, category, subject_type, subject_id, data)
    values (v_tenant, 'deal.proposed', 'deal', 'deal', v_row.id,
            jsonb_build_object('deal_id', v_row.id, 'contact_id', p_contact_id, 'stage', 'proposed',
                               'from', null, 'service', v_row.service, 'by', v_user));
    return jsonb_build_object('deal', to_jsonb(v_row), 'from', null);
  end if;

  select * into v_row from deals d
   where d.id = p_deal_id and d.tenant_id = v_tenant and d.contact_id = p_contact_id
   for update;
  if v_row.id is null then
    return jsonb_build_object('error', 'not_found');
  end if;
  if p_version is not null and p_version <> v_row.version then
    return jsonb_build_object('error', 'moved', 'version', v_row.version);
  end if;
  if v_row.stage = 'ended' and p_stage <> 'ended' then
    -- An ended engagement is re-signed as a new row, so tenure and amounts keep their history.
    return jsonb_build_object('error', 'ended');
  end if;
  if p_stage in ('proposed', 'won') and v_row.stage = 'lost' and exists (
    select 1 from deals d
     where d.contact_id = p_contact_id and d.id <> v_row.id and d.stage in ('proposed', 'won')
       and coalesce(d.service, '') = coalesce(v_row.service, '')
  ) then
    return jsonb_build_object('error', 'already_open');
  end if;

  v_from := v_row.stage;
  update deals d
     set stage        = p_stage,
         proposed_at  = case when p_stage = 'proposed' and v_from = 'lost' then v_when else d.proposed_at end,
         decided_at   = case when p_stage in ('won', 'lost') and v_from <> p_stage then v_when
                             when p_stage = 'proposed' then null
                             else d.decided_at end,
         ended_at     = case when p_stage = 'ended' and v_from <> 'ended' then v_when else d.ended_at end,
         amount_cents = case when 'amount' = any(v_clear) then null else coalesce(p_amount_cents, d.amount_cents) end,
         per          = case when 'amount' = any(v_clear) then null else coalesce(p_per, d.per) end,
         note         = case when 'note' = any(v_clear) then null else coalesce(v_note, d.note) end,
         evidence     = coalesce(p_evidence, d.evidence),
         proposal_url = case when 'proposal_url' = any(v_clear) then null else coalesce(v_url, d.proposal_url) end,
         valid_until  = case when 'valid_until' = any(v_clear) then null
                             when p_stage = 'proposed' and v_from = 'lost' then p_valid_until
                             else coalesce(p_valid_until, d.valid_until) end,
         -- Passing keeps the reason it was given, or the one it had; any other stage has none.
         lost_reason  = case when p_stage = 'lost'
                             then coalesce(p_lost_reason, case when v_from = 'lost' then d.lost_reason end)
                             else null end,
         version      = d.version + 1
   where d.id = v_row.id
  returning * into v_row;

  if v_from = p_stage then
    -- Refreshing a row's details is not a move: no event.
    return jsonb_build_object('deal', to_jsonb(v_row), 'from', v_from);
  end if;
  if p_stage = 'proposed' then
    insert into events (tenant_id, kind, category, subject_type, subject_id, data)
    values (v_tenant, 'deal.proposed', 'deal', 'deal', v_row.id,
            jsonb_build_object('deal_id', v_row.id, 'contact_id', p_contact_id, 'stage', 'proposed',
                               'from', v_from, 'service', v_row.service, 'by', v_user));
  elsif p_stage = 'won' then
    insert into events (tenant_id, kind, category, subject_type, subject_id, data)
    values (v_tenant, 'deal.won', 'deal', 'deal', v_row.id,
            jsonb_build_object('deal_id', v_row.id, 'contact_id', p_contact_id, 'stage', 'won',
                               'from', v_from, 'service', v_row.service, 'by', v_user));
  elsif p_stage = 'lost' then
    insert into events (tenant_id, kind, category, subject_type, subject_id, data)
    values (v_tenant, 'deal.lost', 'deal', 'deal', v_row.id,
            jsonb_build_object('deal_id', v_row.id, 'contact_id', p_contact_id, 'stage', 'lost',
                               'from', v_from, 'service', v_row.service, 'by', v_user));
  else
    insert into events (tenant_id, kind, category, subject_type, subject_id, data)
    values (v_tenant, 'deal.ended', 'deal', 'deal', v_row.id,
            jsonb_build_object('deal_id', v_row.id, 'contact_id', p_contact_id, 'stage', 'ended',
                               'from', v_from, 'service', v_row.service, 'by', v_user));
  end if;
  return jsonb_build_object('deal', to_jsonb(v_row), 'from', v_from);
end $_$;


--
-- Name: FUNCTION deal_record(p_contact_id uuid, p_stage text, p_deal_id uuid, p_version integer, p_service text, p_when timestamp with time zone, p_amount_cents integer, p_per text, p_note text, p_evidence jsonb, p_proposal_url text, p_valid_until date, p_lost_reason text, p_clear text[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.deal_record(p_contact_id uuid, p_stage text, p_deal_id uuid, p_version integer, p_service text, p_when timestamp with time zone, p_amount_cents integer, p_per text, p_note text, p_evidence jsonb, p_proposal_url text, p_valid_until date, p_lost_reason text, p_clear text[]) IS 'Record a deal on a person''s word (0004, 0008). No id: a new engagement, which starts proposed, with its link, value and valid-until day; one open engagement per person per service. An id and the version the page saw: a move (any stage to any, except out of ended, which is re-signed as a new row) that keeps what it is not told; p_clear names what a person emptied (proposal_url, valid_until, amount, note). Passing sets the reason, any other stage clears it. A stale version answers {error: moved}. Owner or operator. Writes the stage''s event; the route records the decision. Answers {deal, from} or {error}: bad_link, bad_reason and bad_clear beside 00156''s.';


--
-- Name: deals_erase_on_contact(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deals_erase_on_contact() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if NEW.erased_at is not null and OLD.erased_at is null then
    update deals set note = null, evidence = null, proposal_url = null, version = version + 1 where contact_id = NEW.id;
  end if;
  return null;
end $$;


--
-- Name: FUNCTION deals_erase_on_contact(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.deals_erase_on_contact() IS 'When a person is erased, their deals keep no words: the note, the evidence and the proposal link are blanked; stage, dates and amount stay (0004, 0008).';


--
-- Name: delete_my_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_my_account() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user uuid := auth.uid();
  v_headless integer;
  v_orphaned integer;
  v_emptied uuid[];
  v_partner integer;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  -- Every membership of every workspace the caller is in, locked: two owners deleting at once take turns.
  perform 1 from memberships
   where tenant_id in (select tenant_id from memberships where user_id = v_user)
   for update;
  -- A partner record that holds workspaces brought or money earned: the platform closes it first. Closed, it outlives
  -- the account (00207: user_id set null, the ledger kept), so a closed partner may go.
  select count(*) into v_partner
  from partners p
  where p.user_id = v_user
    and p.status <> 'closed'
    and (exists (select 1 from partner_tenants pt where pt.partner_id = p.id)
      or exists (select 1 from partner_earnings pe where pe.partner_id = p.id));
  if v_partner > 0 then
    raise exception 'partner_records' using errcode = 'P0001',
      hint = 'Your partner record holds workspaces you brought or money you earned. Write to us to close it first.';
  end if;
  -- A workspace with other members whose only owner is the caller.
  select count(*) into v_headless
  from memberships m
  where m.user_id = v_user
    and m.role = 'owner'
    and exists (select 1 from memberships o where o.tenant_id = m.tenant_id and o.user_id <> v_user)
    and not exists (select 1 from memberships o where o.tenant_id = m.tenant_id and o.user_id <> v_user and o.role = 'owner');
  if v_headless > 0 then
    raise exception 'sole_owner' using errcode = 'P0001',
      hint = 'You are the only owner of a workspace with other members. Make someone else an owner first.';
  end if;
  -- Workspaces that will have nobody left: kept, for the platform to erase, and ended now (00262): the receptionist
  -- stops (paused, as billing pauses one) and the mark tells billing never to resume it; the edge ends its plan.
  select coalesce(array_agg(m.tenant_id), '{}'), count(*) into v_emptied, v_orphaned
  from memberships m
  where m.user_id = v_user
    and not exists (select 1 from memberships o where o.tenant_id = m.tenant_id and o.user_id <> v_user);
  update tenants set status = 'paused', left_empty_at = now()
   where id = any(v_emptied) and left_empty_at is null;
  -- Nobody joins an ended workspace: the invitations still open for it go with it (a team invite seats an operator
  -- or a viewer, never an owner, so one accepted now would seat someone who could not even pay for it).
  update invitations set revoked_at = now()
   where tenant_id = any(v_emptied) and accepted_at is null and revoked_at is null;
  delete from partner_invitations where tenant_id = any(v_emptied);
  delete from push_devices where user_id = v_user;
  delete from notification_marks where user_id = v_user;
  delete from notification_reads where user_id = v_user;
  delete from memberships where user_id = v_user;
  delete from auth.users where id = v_user;
  return jsonb_build_object('deleted', true, 'workspaces_left_empty', v_orphaned, 'workspaces_emptied', to_jsonb(v_emptied));
end $$;


--
-- Name: drop_google_credentials(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.drop_google_credentials(p_tenant_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault'
    AS $$
declare
  v_name text := 'google-creds-' || p_tenant_id::text;
  v_id   uuid;
begin
  select id into v_id from vault.secrets where name = v_name;
  if v_id is null then return false; end if;
  delete from vault.secrets where id = v_id;
  update public.google_connections set credentials_ref = null where tenant_id = p_tenant_id;
  return true;
end $$;


--
-- Name: FUNCTION drop_google_credentials(p_tenant_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.drop_google_credentials(p_tenant_id uuid) IS 'Service-role only: deletes a workspace''s Google token from Vault. Called on disconnect, after Google was asked to revoke it.';


--
-- Name: email_from_host(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.email_from_host(p_meta jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
  select lower(substring(p_meta->'email'->'request'->>'from' from '@([^@<>[:space:]"]+)>?[[:space:]]*$'))
$_$;


--
-- Name: FUNCTION email_from_host(p_meta jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.email_from_host(p_meta jsonb) IS 'The domain an email row left from: its frozen request''s From (channels mailboxHeader: "Name" <local@host>, or local@host).';


--
-- Name: email_left(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.email_left(p_status text, p_error jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select p_status in ('sent', 'delivered', 'read')
      or (p_status = 'failed' and coalesce(p_error->>'provider', '') in ('bounced', 'failed'))
$$;


--
-- Name: FUNCTION email_left(p_status text, p_error jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.email_left(p_status text, p_error jsonb) IS 'Whether an email row left (the provider took it): sent, delivered, or failed by a bounce or failure receipt. 00179.';


--
-- Name: email_marketing_on_erase(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.email_marketing_on_erase() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.erased_at is not null and old.erased_at is null then
    if new.email_marketing is distinct from 'unknown' then
      new.email_marketing := 'unknown';
      new.email_marketing_source := 'erasure';
      new.email_marketing_updated_at := now();
    end if;
    if old.email is not null then
      insert into public.lead_suppressions (tenant_id, kind, hash, what)
      values (old.tenant_id, 'email', public.lead_suppression_hash(old.tenant_id, old.email), 'erased')
      on conflict (tenant_id, kind, hash) do update set what = 'erased';
    end if;
  end if;
  return new;
end $$;


--
-- Name: email_sent_at(jsonb, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.email_sent_at(p_meta jsonb, p_status_updated_at timestamp with time zone, p_created_at timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select coalesce((p_meta->'status_at'->>'sent')::timestamptz, p_status_updated_at, p_created_at)
$$;


--
-- Name: FUNCTION email_sent_at(p_meta jsonb, p_status_updated_at timestamp with time zone, p_created_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.email_sent_at(p_meta jsonb, p_status_updated_at timestamp with time zone, p_created_at timestamp with time zone) IS 'When an email row left, or tried to: status_at.sent, else status_updated_at, else created_at. The day''s share and the cold-receipt watch both count by it (00180).';


--
-- Name: enforce_money_lock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_money_lock() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.class = 'money' and new.mode <> 'never' then
    raise exception 'money decisions are owner-only by charter — the mode is locked to never';
  end if;
  if tg_op = 'UPDATE' and (
       new.tenant_id    is distinct from old.tenant_id
    or new.class        is distinct from old.class
    or new.subject_type is distinct from old.subject_type
    or new.subject_id   is distinct from old.subject_id
  ) then
    raise exception 'a policy row keeps its workspace, class and subject for life — make another row instead';
  end if;
  return new;
end $$;


--
-- Name: FUNCTION enforce_money_lock(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enforce_money_lock() IS 'Before insert or update on policies: a money row is always mode never, and no row changes its workspace, class or subject. The trigger policies_money_lock (00012) runs it.';


--
-- Name: ensure_events_partition(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_events_partition(p_month date) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_start date := date_trunc('month', p_month)::date;
  v_end   date := (date_trunc('month', p_month) + interval '1 month')::date;
  v_name  text := 'events_y' || to_char(v_start, 'YYYY') || 'm' || to_char(v_start, 'MM');
begin
  execute format(
    'create table if not exists public.%I partition of public.events for values from (%L) to (%L)',
    v_name, v_start, v_end
  );
  execute format('alter table public.%I enable row level security', v_name);
  -- Read through events, never by name, so the month keeps no session grant
  -- (00121). Also run for a month that already exists: a stray grant goes.
  execute format('revoke all on table public.%I from anon, authenticated', v_name);
end
$$;


--
-- Name: erase_contact(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.erase_contact(p_contact_id uuid, p_legs jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user          uuid := auth.uid();
  v_tenant        uuid;
  v_erased        timestamptz;
  v_conversations uuid[];
  v_messages      uuid[];
  v_escalations   uuid[];
  v_calls         uuid[];
  v_paths         text[];
  v_subjects      uuid[];
  v_jobs_canceled int := 0;
  v_counts        jsonb;
  v_decision_id   uuid;
begin
  -- The caller is auth.uid(), read HERE. It is not a parameter, so it cannot
  -- be spoofed by anyone who can reach the RPC (00021's rule).
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;

  if p_legs is not null and length(p_legs::text) > 4000 then
    raise exception 'Leg report too large.' using errcode = '22023';
  end if;

  select c.tenant_id, c.erased_at into v_tenant, v_erased
    from contacts c where c.id = p_contact_id;
  if v_tenant is null then
    raise exception 'Contact not found.' using errcode = 'P0002';
  end if;

  -- A signed-in stranger must not learn that this uuid exists. The lookup
  -- above found the row because this function bypasses RLS, so the membership
  -- test has to restore what RLS would have said: no membership at all is
  -- indistinguishable from no such contact.
  if not exists (
    select 1 from memberships m
     where m.tenant_id = v_tenant and m.user_id = v_user
  ) then
    raise exception 'Contact not found.' using errcode = 'P0002';
  end if;

  -- OWNER, not merely a member. This is the most destructive verb in the
  -- product and it is irreversible; an operator who can reply to a customer
  -- must not be able to delete them.
  if not exists (
    select 1 from memberships m
     where m.tenant_id = v_tenant and m.user_id = v_user and m.role = 'owner'
  ) then
    raise exception 'Only an owner can erase a customer''s data.' using errcode = '42501';
  end if;

  -- Idempotent: a second request is answered, not re-executed. The route uses
  -- this to re-drive the legs it runs itself without destroying anything twice.
  if v_erased is not null then
    return jsonb_build_object(
      'already_erased', true,
      'contact_id',     p_contact_id,
      'tenant_id',      v_tenant,
      'erased_at',      v_erased,
      'storage_paths',  '[]'::jsonb,
      'counts',         '{}'::jsonb);
  end if;

  /* ---- COLLECT FIRST. Everything below this block is destructive, and each
     of these sets is unrecoverable the moment the row it comes from is gone. */

  select coalesce(array_agg(cv.id), '{}') into v_conversations
    from conversations cv
   where cv.tenant_id = v_tenant and cv.contact_id = p_contact_id;

  select coalesce(array_agg(m.id), '{}') into v_messages
    from messages m
   where m.tenant_id = v_tenant
     and (m.contact_id = p_contact_id or m.conversation_id = any (v_conversations));

  select coalesce(array_agg(e.id), '{}') into v_escalations
    from escalations e
   where e.tenant_id = v_tenant and e.conversation_id = any (v_conversations);

  select coalesce(array_agg(k.id), '{}') into v_calls
    from calls k
   where k.tenant_id = v_tenant
     and (k.contact_id = p_contact_id or k.conversation_id = any (v_conversations));

  -- Every private object this person's data put in Storage: the copied call
  -- recording (retell-webhook.ts writes
  -- <tenant>/calls/<call_id>.<ext>) and any inbound media (whatsapp.ts writes
  -- <tenant>/<conversation_id>/<message_id>.<ext>). Returned to the caller,
  -- which is the only party that can talk to the Storage API.
  select coalesce(array_agg(distinct q.p), '{}') into v_paths
    from (
      select k.recording->>'storage_path' as p
        from calls k
       where k.tenant_id = v_tenant
         and (k.contact_id = p_contact_id or k.conversation_id = any (v_conversations))
         and k.recording->>'storage_path' is not null
      union
      select m.media->>'storage_path' as p
        from messages m
       where m.tenant_id = v_tenant
         and (m.contact_id = p_contact_id or m.conversation_id = any (v_conversations))
         and m.media->>'storage_path' is not null
    ) q;

  v_counts := jsonb_build_object(
    'conversations',  coalesce(array_length(v_conversations, 1), 0),
    'messages',       coalesce(array_length(v_messages, 1), 0),
    'escalations',    coalesce(array_length(v_escalations, 1), 0),
    'calls',          coalesce(array_length(v_calls, 1), 0),
    'storage_objects',coalesce(array_length(v_paths, 1), 0));

  /* ---- Nothing scheduled may fire at a thread that is about to stop
     existing. Done HERE, in the same transaction as the delete, rather than by
     the caller beforehand: a job scheduled between the caller's cancel and this
     commit would otherwise survive. Comparison is on text, never
     (payload->>'x')::uuid, because a payload key holding a non-uuid would then
     abort the whole erasure. claim_job is the real gate and refuses anything
     not 'scheduled'.

     NO KIND IS SPARED. One was: the route used to queue a blob_thread_erase
     job before calling this function, and cancelling it would have cancelled
     the leg that removed the second copy of the conversation. There is no
     second copy and no such kind (00151), so every scheduled job that names
     this person is withdrawn -- and its payload scrubbed in the same
     statement (jobs_guard allows a payload change on any row): the number it
     carried must not outlive the row, and a re-driven erasure has no digits
     to find it by. */
  update jobs
     set state = 'canceled', last_error = 'contact erased',
         payload = jsonb_build_object('scrubbed_at', now(), 'reason', 'contact erased')
   where tenant_id = v_tenant
     and state = 'scheduled'
     and (payload->>'conversation_id' = any (v_conversations::text[])
          or payload->>'message_id'   = any (v_messages::text[])
          or payload->>'contact_id'   = p_contact_id::text);
  get diagnostics v_jobs_canceled = row_count;

  /* ---- Calls FIRST and EXPLICITLY. calls.contact_id and calls.conversation_id
     are ON DELETE SET NULL, so letting the contact cascade run would leave
     every one of these rows behind carrying from_e164, from_raw, the verbatim
     transcript, the summary and the recording path -- the defect 00027 was
     written to close, unchanged here. */
  delete from calls
   where tenant_id = v_tenant
     and (contact_id = p_contact_id or conversation_id = any (v_conversations));

  /* ---- Messages EXPLICITLY, before the cascade. The conversation cascade
     reaches only messages inside this contact's own conversations; a message
     carrying this contact_id in someone else's thread is reached by nothing,
     and because the contact row survives as a tombstone the NO ACTION FK never
     raises to tell us. It would simply keep the customer's words.
     calls.message_id is ON DELETE SET NULL, so another contact's call that
     linked one of these notes degrades instead of blocking. */
  delete from messages
   where tenant_id = v_tenant and id = any (v_messages);

  -- The cascade: conversations -> messages -> escalations.
  delete from conversations
   where tenant_id = v_tenant and contact_id = p_contact_id;

  -- Not reached by any cascade now that the contact row survives, and these
  -- carry the wa_id and the caller's E.164 verbatim.
  delete from contact_identities
   where tenant_id = v_tenant and contact_id = p_contact_id;

  /* ---- The free-form half of the ledger.
     verb, subject_type, subject_id, actor and created_at stay: that IS the
     audit. payload is the only operator-shaped column in decisions, and 'edit'
     is a declared verb meaning "the operator changed the words" -- so even
     though every payload written today holds ids and booleans only (verified
     against the live tenant: paused_until, message_id, template, window_open),
     the erasure must not depend on that staying true. */
  v_subjects := array[p_contact_id] || v_conversations || v_messages
                || v_escalations || v_calls;
  update decisions
     set payload = jsonb_build_object('scrubbed_at', now())
   where tenant_id = v_tenant
     and subject_id = any (v_subjects)
     and payload <> '{}'::jsonb;

  /* ---- events.data is deliberately NOT scrubbed. Verified against the live
     tenant, every key is a count or an enum -- call.recorded {direction,status},
     message.received {channel,type}, message.sent {sender},
     usage.voice_seconds {seconds}, conversation.reopened {from_state,trigger} --
     and two of them ARE the billing record. Once the contact, conversation,
     messages and calls are gone, those subject_ids resolve to nothing and the
     only surviving link (subject_type='contact') resolves to a tombstone with
     no identifiers. Deleting them would destroy metering, not personal data.
     tooling/scripts/tests/erasure.integration.test.mjs pins that. */

  /* ---- The tombstone. */
  update contacts
     set phone_e164         = null,
         display_name       = null,
         wa_profile_name    = null,
         consent            = 'unknown',
         consent_source     = 'erasure',
         consent_updated_at = now(),
         dnc                = true,
         erased_at          = now()
   where id = p_contact_id;

  -- A contact merged INTO this one must stop pointing at it. No merge path
  -- exists today and every value is null; this is here because
  -- contacts_merged_into_contact_id_fkey is NO ACTION and would otherwise be
  -- the thing that breaks the day one does. Tenant-scoped: this function runs
  -- as its owner, so an unscoped predicate would be a cross-tenant write.
  update contacts set merged_into_contact_id = null
   where tenant_id = v_tenant and merged_into_contact_id = p_contact_id;

  insert into events (tenant_id, kind, category, subject_type, subject_id, data)
  values (v_tenant, 'contact.erased', 'contact', 'contact', p_contact_id,
          v_counts || jsonb_build_object('jobs_canceled', v_jobs_canceled));

  -- The ledger row. p_legs is what the caller already did (the Storage
  -- objects it removed) so one row tells the whole story and a failed leg is
  -- visible without joining anything.
  insert into decisions (tenant_id, subject_type, subject_id, verb,
                         actor_type, actor_user_id, payload)
  values (v_tenant, 'contact', p_contact_id, 'erase', 'user', v_user,
          jsonb_build_object(
            'counts',        v_counts,
            'jobs_canceled', v_jobs_canceled,
            'storage_paths', to_jsonb(v_paths),
            'legs',          coalesce(p_legs, '{}'::jsonb)))
  returning id into v_decision_id;

  return jsonb_build_object(
    'already_erased', false,
    'contact_id',     p_contact_id,
    'tenant_id',      v_tenant,
    'decision_id',    v_decision_id,
    'storage_paths',  to_jsonb(v_paths),
    'counts',         v_counts,
    'jobs_canceled',  v_jobs_canceled);
end $$;


--
-- Name: FUNCTION erase_contact(p_contact_id uuid, p_legs jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.erase_contact(p_contact_id uuid, p_legs jsonb) IS 'Erase one customer: delete their calls and messages explicitly (the call FKs are SET NULL and the message FK is NO ACTION), cascade the conversation, cancel every scheduled job that names them, scrub decision payloads, and tombstone the contact. Returns the Storage paths the caller must remove. Owner-only, checked against auth.uid() inside the body.';


--
-- Name: erase_marketing_consent(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.erase_marketing_consent(p_contact_id uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  update public.contacts
     set marketing_consent = 'unknown',
         marketing_consent_source = 'erasure',
         marketing_consent_updated_at = now()
   where id = p_contact_id;
$$;


--
-- Name: FUNCTION erase_marketing_consent(p_contact_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.erase_marketing_consent(p_contact_id uuid) IS 'Clears the marketing answer as part of an erasure. Split from erase_contact rather than rewriting it: that function is long, it is the one path a person''s right to be forgotten runs through, and recreating it to add two columns is a risk with no upside.';


--
-- Name: erasure_digest(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.erasure_digest(p_tenant_id uuid, p_value text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_legacy text;
begin
  if p_value is null then
    return null;
  end if;
  v_legacy := public.erasure_digest_legacy(p_tenant_id, p_value);
  if (select k.keyed_at from public.erasure_keying k where k.id) is null then
    return v_legacy;
  end if;
  return public.erasure_key(v_legacy);
end $$;


--
-- Name: erasure_digest_keyed_on_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.erasure_digest_keyed_on_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if (select k.keyed_at from public.erasure_keying k where k.id) is null then
    return NEW;
  end if;
  if TG_TABLE_NAME = 'contacts' then
    NEW.erased_phone_hash := public.erasure_key(NEW.erased_phone_hash);
    NEW.erased_email_hash := public.erasure_key(NEW.erased_email_hash);
  else
    NEW.hash := public.erasure_key(NEW.hash);
  end if;
  return NEW;
end $$;


--
-- Name: erasure_digest_legacy(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.erasure_digest_legacy(p_tenant_id uuid, p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select encode(sha256(convert_to(p_tenant_id::text || ':' || p_value, 'UTF8')), 'hex')
$$;


--
-- Name: erasure_digests(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.erasure_digests(p_tenant_id uuid, p_values text[]) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(array_agg(public.erasure_digest(p_tenant_id, v) order by n), '{}')
    from unnest(p_values) with ordinality as u(v, n)
$$;


--
-- Name: erasure_key(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.erasure_key(p_digest text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_pepper text;
begin
  if p_digest is null or p_digest like 'h1:%' then
    return p_digest;
  end if;
  select decrypted_secret into v_pepper from vault.decrypted_secrets where name = 'erasure_pepper';
  if v_pepper is null then
    raise exception 'erasure_key: no pepper in Vault' using errcode = 'P0001';
  end if;
  return 'h1:' || encode(extensions.hmac(p_digest, v_pepper, 'sha256'), 'hex');
end $$;


--
-- Name: erasure_rekey(boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.erasure_rekey(p_apply boolean DEFAULT false, p_tenant_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_phone   integer;
  v_email   integer;
  v_supp    integer;
  v_replies integer;
  v_keyed   timestamptz;
begin
  select count(*) into v_phone from contacts
   where erased_phone_hash is not null and erased_phone_hash not like 'h1:%' and (p_tenant_id is null or tenant_id = p_tenant_id);
  select count(*) into v_email from contacts
   where erased_email_hash is not null and erased_email_hash not like 'h1:%' and (p_tenant_id is null or tenant_id = p_tenant_id);
  select count(*) into v_supp from lead_suppressions
   where hash not like 'h1:%' and (p_tenant_id is null or tenant_id = p_tenant_id);
  select count(*) into v_replies from reach_out_replies o
   where (p_tenant_id is null or o.tenant_id = p_tenant_id)
     and exists (select 1 from jsonb_array_elements(
                   case when jsonb_typeof(o.plan->'changed'->'holds') = 'array' then o.plan->'changed'->'holds' else '[]'::jsonb end
                   || case when jsonb_typeof(o.plan->'changed'->'suppressions') = 'array' then o.plan->'changed'->'suppressions' else '[]'::jsonb end) x
                  where x->>'hash' is not null and x->>'hash' not like 'h1:%');
  select keyed_at into v_keyed from erasure_keying where id;
  if p_apply then
    update contacts set erased_phone_hash = erasure_key(erased_phone_hash)
     where erased_phone_hash is not null and erased_phone_hash not like 'h1:%' and (p_tenant_id is null or tenant_id = p_tenant_id);
    update contacts set erased_email_hash = erasure_key(erased_email_hash)
     where erased_email_hash is not null and erased_email_hash not like 'h1:%' and (p_tenant_id is null or tenant_id = p_tenant_id);
    -- A legacy row whose keyed twin stands: the twin keeps the stronger reason (an erasure wins, as 00177's writers
    -- say), and the legacy row goes, so re-keying it cannot collide on (tenant_id, kind, hash).
    create temporary table erasure_rekey_twins on commit drop as
      select s.id, s.tenant_id, s.kind, s.what, erasure_key(s.hash) as keyed
        from lead_suppressions s
       where s.hash not like 'h1:%' and (p_tenant_id is null or s.tenant_id = p_tenant_id);
    update lead_suppressions k set what = 'erased'
      from erasure_rekey_twins t
     where t.what = 'erased' and k.what <> 'erased'
       and k.tenant_id = t.tenant_id and k.kind = t.kind and k.hash = t.keyed;
    delete from lead_suppressions s
     using erasure_rekey_twins t
     where s.id = t.id
       and exists (select 1 from lead_suppressions k
                    where k.tenant_id = t.tenant_id and k.kind = t.kind and k.hash = t.keyed);
    update lead_suppressions s set hash = t.keyed
      from erasure_rekey_twins t
     where s.id = t.id;
    drop table erasure_rekey_twins;
    -- Only the two lists a reply keeps for its undo, each where it is; the rest of the plan as it was.
    update reach_out_replies o
       set plan = o.plan || jsonb_build_object('changed', (o.plan->'changed')
             || case when o.plan->'changed' ? 'holds'
                     then jsonb_build_object('holds', public.erasure_rekey_hashes(o.plan->'changed'->'holds'))
                     else '{}'::jsonb end
             || case when o.plan->'changed' ? 'suppressions'
                     then jsonb_build_object('suppressions', public.erasure_rekey_hashes(o.plan->'changed'->'suppressions'))
                     else '{}'::jsonb end)
     where jsonb_typeof(o.plan->'changed') = 'object' and (p_tenant_id is null or o.tenant_id = p_tenant_id)
       and exists (select 1 from jsonb_array_elements(
                     case when jsonb_typeof(o.plan->'changed'->'holds') = 'array' then o.plan->'changed'->'holds' else '[]'::jsonb end
                     || case when jsonb_typeof(o.plan->'changed'->'suppressions') = 'array' then o.plan->'changed'->'suppressions' else '[]'::jsonb end) x
                    where x->>'hash' is not null and x->>'hash' not like 'h1:%');
    -- The mark is the whole database's: a run kept to one workspace (a test's) keys its rows and marks nothing.
    if p_tenant_id is null then
      update erasure_keying set keyed_at = coalesce(keyed_at, now()) where id returning keyed_at into v_keyed;
    end if;
  end if;
  return jsonb_build_object(
    'applied', p_apply,
    'contacts_phone', v_phone,
    'contacts_email', v_email,
    'lead_suppressions', v_supp,
    'reach_out_replies', v_replies,
    'keyed_at', v_keyed);
end $$;


--
-- Name: erasure_rekey_hashes(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.erasure_rekey_hashes(p_list jsonb) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case
    when p_list is null or jsonb_typeof(p_list) <> 'array' then p_list
    else coalesce((
      select jsonb_agg(case when jsonb_typeof(x->'hash') = 'string'
                            then jsonb_set(x, '{hash}', to_jsonb(public.erasure_key(x->>'hash')))
                            else x end
                       order by n)
        from jsonb_array_elements(p_list) with ordinality as e(x, n)), '[]'::jsonb)
  end
$$;


--
-- Name: escalations_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.escalations_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if NEW.state is distinct from OLD.state then
    if OLD.state = 'resolved' then
      raise exception 'escalations.state is terminal (% -> % refused); a new concern is a new row', OLD.state, NEW.state;
    end if;
  end if;
  return NEW;
end $$;


--
-- Name: FUNCTION escalations_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.escalations_guard() IS 'open -> resolved, once. A resolved escalation is not reopened; a new concern is a new row.';


--
-- Name: expire_stale_pauses(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expire_stale_pauses() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_count integer;
begin
  update conversations
     set control_kind = null, control_by = null, control_ref = null, control_until = null
   where control_until is not null and control_until < now();

  with expired as (
    update conversations c
       set state = 'open', paused_until = null, assignee_user_id = null
     where c.state = 'needs_human'
       and c.paused_until is not null
       and c.paused_until < now()
       and not exists (
         select 1 from escalations e
          where e.conversation_id = c.id and e.state = 'open')
    returning c.id, c.tenant_id
  )
  insert into events (tenant_id, kind, category, subject_type, subject_id, data)
  select tenant_id, 'conversation.pause_expired', 'conversation', 'conversation', id, '{}'::jsonb
    from expired;
  get diagnostics v_count = row_count;
  return v_count;
end $$;


--
-- Name: FUNCTION expire_stale_pauses(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.expire_stale_pauses() IS 'Ends what has run out on a thread: the hold on who is speaking, always; and the pause, when no escalation still asks for a person. Returns the number of pauses ended (00006, 00130).';


--
-- Name: first_replies(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.first_replies(p_tenant_id uuid, p_start timestamp with time zone) RETURNS TABLE(asked_at timestamp with time zone, conversation_id uuid, ai_at timestamp with time zone, human_at timestamp with time zone, who text, ai_seconds numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with real_msgs as not materialized (
    select * from messages
     where tenant_id = p_tenant_id
       and coalesce(meta->>'backfill', 'false') <> 'true'
  ),
  asks as (
    select m.created_at as asked_at, m.conversation_id
      from real_msgs m
     where m.created_at >= p_start
       and m.direction = 'inbound' and m.sender = 'customer'
  ),
  -- when each outbound row actually LEFT: the send event for the queued path,
  -- the row itself for an immediate send
  sent as not materialized (
    select o.id, o.conversation_id, o.sender, o.created_at,
           coalesce((select min(e.created_at) from events e
                      where e.tenant_id = p_tenant_id
                        and e.kind = 'message.sent'
                        and e.subject_type = 'message'
                        and e.subject_id = o.id), o.created_at) as sent_at
      from real_msgs o
     where o.direction = 'outbound'
       and o.status in ('sent', 'delivered', 'read')
  ),
  firsts as (
    select a.asked_at, a.conversation_id,
           (select min(s.sent_at) from sent s
             where s.conversation_id = a.conversation_id and s.sender = 'ai'
               and s.created_at > a.asked_at) as ai_at,
           (select min(s.sent_at) from sent s
             where s.conversation_id = a.conversation_id and s.sender = 'human'
               and s.created_at > a.asked_at) as human_at
      from asks a
  )
  select asked_at, conversation_id, ai_at, human_at,
         case when ai_at is not null and (human_at is null or ai_at <= human_at) then 'ai'
              when human_at is not null then 'you'
              else 'none' end as who,
         case when ai_at is not null and (human_at is null or ai_at <= human_at)
              then extract(epoch from (ai_at - asked_at)) end as ai_seconds
    from firsts
$$;


--
-- Name: get_channel_credentials(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_channel_credentials(p_channel_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault'
    AS $$
declare
  v_ref    text;
  v_secret text;
begin
  select credentials_ref into v_ref from public.tenant_channels where id = p_channel_id;
  if v_ref is null then return null; end if;
  select decrypted_secret into v_secret from vault.decrypted_secrets where name = v_ref;
  if v_secret is null then return null; end if;
  return v_secret::jsonb;
end $$;


