--
-- Name: handover_accept(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handover_accept(p_tenant uuid) RETURNS TABLE(id uuid, slug text, name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user  uuid := auth.uid();
  v_email text;
  v_row   public.partner_tenants;
  v_by    uuid;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  select lower(u.email) into v_email from auth.users u where u.id = v_user and u.email_confirmed_at is not null;
  select pt.* into v_row
    from public.partner_tenants pt
   where pt.tenant_id = p_tenant and pt.origin = 'handover'
   for update;
  -- Not found, and not "not yours": whether a workspace waits for an address is its addressee's to know.
  if v_row.tenant_id is null or v_email is null or v_row.handover_email <> v_email then
    raise exception 'There is no workspace waiting for you there.' using errcode = 'P0002';
  end if;
  select p.user_id into v_by from public.partners p where p.id = v_row.partner_id;
  if v_by = v_user then
    raise exception 'A partner cannot take over a workspace they set up.' using errcode = '42501';
  end if;
  if v_row.handover_accepted_at is not null then
    raise exception 'This workspace already has its owner.' using errcode = '55000';
  end if;
  if v_row.handover_declined_at is not null then
    raise exception 'You declined this workspace. Ask your partner to send it again.' using errcode = '55000';
  end if;
  if v_row.handover_expires_at <= now() then
    raise exception 'This invitation has expired. Ask your partner to send it again.' using errcode = '55000';
  end if;

  insert into public.memberships (tenant_id, user_id, role)
  values (p_tenant, v_user, 'owner')
  on conflict (user_id, tenant_id) do update set role = 'owner';
  update public.partner_tenants pt
     set handover_accepted_at = now(), handover_accepted_by = v_user
   where pt.tenant_id = p_tenant;
  insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
  values (p_tenant, 'partner.handover_accepted', 'workspace', 'tenant', p_tenant,
          jsonb_build_object('partner_id', v_row.partner_id, 'by', v_user));

  return query select t.id, t.slug, t.name from public.tenants t where t.id = p_tenant;
end $$;


--
-- Name: FUNCTION handover_accept(p_tenant uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.handover_accept(p_tenant uuid) IS 'The caller, by the confirmed address a workspace was handed to (0016), becomes its owner: the first, with billing and the team. Never the partner who set it up; never after it was declined or expired.';


--
-- Name: handover_decline(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handover_decline(p_tenant uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user  uuid := auth.uid();
  v_email text;
  v_row   public.partner_tenants;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  select lower(u.email) into v_email from auth.users u where u.id = v_user and u.email_confirmed_at is not null;
  select pt.* into v_row
    from public.partner_tenants pt
   where pt.tenant_id = p_tenant and pt.origin = 'handover'
   for update;
  if v_row.tenant_id is null or v_email is null or v_row.handover_email <> v_email
     or v_row.handover_accepted_at is not null then
    raise exception 'There is no workspace waiting for you there.' using errcode = 'P0002';
  end if;
  if v_row.handover_declined_at is not null then
    return;
  end if;
  update public.partner_tenants pt set handover_declined_at = now() where pt.tenant_id = p_tenant;
  insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
  values (p_tenant, 'partner.handover_declined', 'workspace', 'tenant', p_tenant,
          jsonb_build_object('partner_id', v_row.partner_id, 'by', v_user));
end $$;


--
-- Name: FUNCTION handover_decline(p_tenant uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.handover_decline(p_tenant uuid) IS 'The addressee of a handover (0016) says no. The workspace stays with the partner, who hears it in their letter and may send it again.';


--
-- Name: handovers_mine(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handovers_mine() RETURNS TABLE(tenant_id uuid, workspace text, partner_code text, expires_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select pt.tenant_id, t.name, p.code, pt.handover_expires_at
    from auth.users u
    join public.partner_tenants pt
      on pt.handover_email = lower(u.email)
     and pt.origin = 'handover'
     and pt.handover_accepted_at is null
     and pt.handover_declined_at is null
     and pt.handover_expires_at > now()
    join public.tenants t on t.id = pt.tenant_id
    join public.partners p on p.id = pt.partner_id
   where u.id = auth.uid()
     -- A proved address only: an account that has not confirmed its email is not yet the person it names.
     and u.email_confirmed_at is not null
     and p.user_id is distinct from u.id
   order by pt.handover_sent_at
$$;


--
-- Name: FUNCTION handovers_mine(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.handovers_mine() IS 'The open handovers (0016) addressed to the caller''s confirmed email: which workspace, from which partner, open until when. The accept screen reads it at boot.';


--
-- Name: has_permission(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_permission(p_user uuid, p_tenant_id uuid, p_permission text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from public.memberships m
     where m.user_id = p_user and m.tenant_id = p_tenant_id
       and m.role = any (case p_permission
         when 'approve'    then array['owner', 'operator', 'partner']
         when 'autonomy'   then array['owner', 'operator', 'partner']
         when 'disconnect' then array['owner', 'partner']
         when 'billing'    then array['owner']
         when 'team'       then array['owner']
         when 'settings'   then array['owner', 'partner']
         when 'export'     then array['owner']
         when 'find'       then array['owner', 'partner']
         else array[]::text[] end)
       -- A partner's seat, asked about the calling session, counts only once it showed its second factor (0013).
       and (m.role <> 'partner' or p_user is distinct from (select auth.uid()) or public.session_shows_second_factor())
  )
$$;


--
-- Name: FUNCTION has_permission(p_user uuid, p_tenant_id uuid, p_permission text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.has_permission(p_user uuid, p_tenant_id uuid, p_permission text) IS 'Whether this user may do this in this workspace, by role: contracts'' ROLE_PERMS, restated once in SQL. A partner (0012) sets the workspace up: settings, disconnect and find beside what an operator has; billing, team and export stay the owner''s.';


--
-- Name: import_person(uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.import_person(p_tenant_id uuid, p_name text, p_phone_e164 text, p_email text, p_phone_digest text DEFAULT NULL::text, p_email_digest text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_user      uuid := auth.uid();
  v_name      text := left(nullif(btrim(regexp_replace(coalesce(p_name, ''), '\s+', ' ', 'g')), ''), 80);
  v_phone     text := nullif(btrim(coalesce(p_phone_e164, '')), '');
  v_email     text := nullif(lower(btrim(coalesce(p_email, ''))), '');
  v_new_email text;
  v_id        uuid;
  v_email_out text := null;   -- 'set' | 'kept' | 'taken' | null
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  if p_tenant_id is null or not public.is_acting_member(p_tenant_id) then
    raise exception 'Workspace not found.' using errcode = 'P0002';
  end if;
  if v_phone is not null and v_phone !~ '^\+[1-9][0-9]{7,14}$' then
    raise exception 'A phone number in international form is needed.' using errcode = '22023';
  end if;
  if v_email is not null and (
       char_length(v_email) not between 3 and 254
       or v_email !~ '^[^[:space:]@<>]+@[^[:space:]@<>]+\.[^[:space:]@<>]+$') then
    raise exception 'That is not an email address.' using errcode = '22023';
  end if;
  if v_phone is null and v_email is null then
    raise exception 'A number or an address is needed.' using errcode = '22023';
  end if;
  -- The erased stay erased: a line that names one is left alone (00124, 00125). The digests are the database's own
  -- (00263 erasure_digest, keyed once the re-key has run): a digest the caller hands in is not read, since only the
  -- database holds the pepper.
  if (v_phone is not null and exists (
        select 1 from contacts c
         where c.tenant_id = p_tenant_id and c.erased_phone_hash = public.erasure_digest(p_tenant_id, v_phone)))
     or (v_email is not null and exists (
        select 1 from contacts c
         where c.tenant_id = p_tenant_id and c.erased_email_hash = public.erasure_digest(p_tenant_id, v_email))) then
    raise exception 'That person asked to be forgotten.' using errcode = 'PE001';
  end if;

  -- Find, else make, in two attempts at most: a line that loses a race to make
  -- the same person (their number or their address written by another line
  -- between the look and the insert) looks again and fills the person who won,
  -- rather than dropping its name and its address.
  for v_try in 1..2 loop
    v_id := null;
    if v_phone is not null then
      select c.id into v_id from contacts c
       where c.tenant_id = p_tenant_id and c.phone_e164 = v_phone
         and c.erased_at is null and c.merged_into_contact_id is null
       limit 1;
    end if;
    if v_id is null and v_email is not null then
      select c.id into v_id from contacts c
       where c.tenant_id = p_tenant_id and c.email = v_email
         and c.erased_at is null and c.merged_into_contact_id is null
         and (v_phone is null or c.phone_e164 is null)  -- two numbers are two people
       limit 1;
    end if;
    exit when v_id is not null;

    -- Nobody: they are made, with the address only when nobody here holds it.
    v_new_email := case
      when v_email is not null
       and not exists (select 1 from contacts c where c.tenant_id = p_tenant_id and c.email = v_email)
      then v_email
    end;
    -- Never a person with neither. The early checks make this impossible for
    -- the line as written; it reads what the insert would write, because the
    -- address may be one another person holds and so be left out.
    if v_phone is null and v_new_email is null then
      raise exception 'A number or an address is needed.' using errcode = '22023';
    end if;
    begin
      insert into contacts (tenant_id, phone_e164, email, display_name)
      values (p_tenant_id, v_phone, v_new_email, v_name)
      returning id into v_id;
    exception when unique_violation then
      if v_try = 2 then
        raise;
      end if;
    end;
    if v_id is not null then
      insert into events (tenant_id, kind, category, subject_type, subject_id, data)
      values (p_tenant_id, 'contact.added', 'contact', 'contact', v_id,
              jsonb_build_object('source', 'import', 'title', null, 'by', v_user));
      return jsonb_build_object(
        'contact_id', v_id,
        'existed', false,
        'email', case when v_email is null then null when v_new_email is null then 'taken' else 'set' end);
    end if;
  end loop;

  -- Found. A name, a number or an address we did not have is worth keeping; one
  -- we have is never overwritten.
  if v_name is not null then
    update contacts set display_name = v_name, updated_at = now() where id = v_id and display_name is null;
  end if;
  if v_phone is not null then
    begin
      update contacts set phone_e164 = v_phone, updated_at = now() where id = v_id and phone_e164 is null;
    exception when unique_violation then
      null; -- another person here holds the number: theirs stays theirs
    end;
  end if;
  if v_email is not null then
    if exists (select 1 from contacts c where c.id = v_id and c.email is not null) then
      v_email_out := 'kept';
    elsif exists (select 1 from contacts c where c.tenant_id = p_tenant_id and c.email = v_email) then
      v_email_out := 'taken';
    else
      begin
        perform public.set_person_email(v_id, v_email);
        v_email_out := 'set';
      exception when unique_violation then
        v_email_out := 'taken'; -- another line wrote it between the look and the write
      end;
    end if;
  end if;

  return jsonb_build_object('contact_id', v_id, 'existed', true, 'email', v_email_out);
end $_$;


--
-- Name: FUNCTION import_person(p_tenant_id uuid, p_name text, p_phone_e164 text, p_email text, p_phone_digest text, p_email_digest text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.import_person(p_tenant_id uuid, p_name text, p_phone_e164 text, p_email text, p_phone_digest text, p_email_digest text) IS 'One line of an imported client list: find by number, then address (two numbers are two people); fill what is empty; never a yes; the erased stay erased (PE001).';


--
-- Name: ingest_call(uuid, text, text, text, text, text, text, text, text, timestamp with time zone, timestamp with time zone, integer, text, text, boolean, boolean, text, text, jsonb, jsonb, text, jsonb, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ingest_call(p_tenant_id uuid, p_retell_call_id text, p_agent_id text, p_from_e164 text, p_from_raw text, p_to_e164 text, p_direction text, p_call_type text, p_status text, p_started_at timestamp with time zone, p_ended_at timestamp with time zone, p_duration_ms integer, p_disconnection text, p_sentiment text, p_successful boolean, p_in_voicemail boolean, p_summary text, p_transcript text, p_transcript_obj jsonb, p_recording jsonb, p_public_log_url text, p_cost jsonb, p_latency jsonb, p_raw jsonb, p_analysis jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_contact_id      uuid;
  v_conversation_id uuid;
  v_channel_id      uuid;
  v_call_id         uuid;
  v_is_new          boolean := false;
  v_rec_state       text;
  v_rec_attempts    integer;
  v_prev_duration   integer;
  v_had_row         boolean := false;
  v_ts              timestamptz := coalesce(p_started_at, now());
  v_raw             jsonb := public.scrub_call_raw(p_raw);
  -- The provider's custom analysis, filed as columns: what the caller
  -- wanted, how it ended, what a person should do next, the name they gave.
  v_wanted          text := nullif(btrim(p_analysis->>'caller_wanted'), '');
  v_outcome         text := case when p_analysis->>'outcome' in ('answered','booking_link_sent','callback_needed','voicemail','no_request','other')
                                 then p_analysis->>'outcome' end;
  v_follow_up       text := nullif(btrim(p_analysis->>'follow_up'), '');
  v_caller_name     text := nullif(btrim(p_analysis->>'caller_name'), '');
  v_analysis        jsonb := case when jsonb_typeof(p_analysis) = 'object' and p_analysis <> '{}'::jsonb then p_analysis end;
begin
  -- Only the call's own workspace's line (00164): whatever agent id it
  -- carries, a call is never filed under another workspace's channel.
  select id into v_channel_id from tenant_channels
   where kind = 'voice' and external_id = p_agent_id and tenant_id = p_tenant_id;

  -- ONE ingest of a given call at a time. Taken BEFORE the prior-state read
  -- below: two concurrent deliveries that both read "no duration yet" would
  -- both meter the call.
  perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text || '|call|' || p_retell_call_id, 42));

  -- What we already knew about this call. The usage event must fire exactly
  -- once, when the duration FIRST becomes known -- which, for a call that
  -- arrived as `call_started`, is the second or third event, not the first.
  select true, duration_ms into v_had_row, v_prev_duration
    from calls where tenant_id = p_tenant_id and retell_call_id = p_retell_call_id;

  if p_from_e164 is not null then
    perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text || '|voice|' || p_from_e164, 42));

    select contact_id into v_contact_id from contact_identities
     where tenant_id = p_tenant_id and channel = 'voice' and external_id = p_from_e164;

    if v_contact_id is null then
      select id into v_contact_id from contacts
       where tenant_id = p_tenant_id and phone_e164 = p_from_e164;
    end if;

    if v_contact_id is null then
      insert into contacts (tenant_id, phone_e164, last_seen_at)
      values (p_tenant_id, p_from_e164, greatest(v_ts, now() - interval '10 years'))
      on conflict (tenant_id, phone_e164) where phone_e164 is not null
        do update set last_seen_at = greatest(contacts.last_seen_at, excluded.last_seen_at)
      returning id into v_contact_id;
    end if;

    insert into contact_identities (tenant_id, contact_id, channel, external_id)
    values (p_tenant_id, v_contact_id, 'voice', p_from_e164)
    on conflict (tenant_id, channel, external_id) do nothing;

    insert into conversations (tenant_id, contact_id, last_message_at, last_inbound_at)
    values (p_tenant_id, v_contact_id, v_ts, v_ts)
    on conflict (tenant_id, contact_id)
      do update set last_message_at = greatest(conversations.last_message_at, excluded.last_message_at),
                    last_inbound_at = greatest(conversations.last_inbound_at, excluded.last_inbound_at)
      -- Only when something moves. Every transcript turn of a live call
      -- re-ingests the same started_at; an unconditional DO UPDATE wrote the
      -- row -- and fired a realtime event that repainted every surface --
      -- for no change at all.
      where conversations.last_message_at is distinct from greatest(conversations.last_message_at, excluded.last_message_at)
         or conversations.last_inbound_at is distinct from greatest(conversations.last_inbound_at, excluded.last_inbound_at)
    returning id into v_conversation_id;
    if v_conversation_id is null then
      select id into v_conversation_id from conversations
       where tenant_id = p_tenant_id and contact_id = v_contact_id;
    end if;
  end if;

  insert into calls (
    tenant_id, channel_id, retell_call_id, agent_id, contact_id, conversation_id,
    direction, call_type, from_e164, to_e164, from_raw, status,
    started_at, ended_at, duration_ms, disconnection_reason,
    sentiment, call_successful, in_voicemail, summary, transcript, transcript_object,
    recording, public_log_url, cost, latency, raw,
    wanted, outcome, follow_up, caller_name, analysis
  ) values (
    p_tenant_id, v_channel_id, p_retell_call_id, p_agent_id, v_contact_id, v_conversation_id,
    coalesce(p_direction, 'inbound'), p_call_type, p_from_e164, p_to_e164, p_from_raw,
    coalesce(p_status, 'ended'),
    p_started_at, p_ended_at, p_duration_ms, p_disconnection,
    p_sentiment, p_successful, p_in_voicemail, p_summary, p_transcript, p_transcript_obj,
    p_recording, null, p_cost, p_latency, v_raw,
    v_wanted, v_outcome, v_follow_up, v_caller_name, v_analysis
  )
  on conflict (tenant_id, retell_call_id) do update set
    status               = excluded.status,
    ended_at             = coalesce(excluded.ended_at, calls.ended_at),
    duration_ms          = coalesce(excluded.duration_ms, calls.duration_ms),
    disconnection_reason = coalesce(excluded.disconnection_reason, calls.disconnection_reason),
    sentiment            = coalesce(excluded.sentiment, calls.sentiment),
    call_successful      = coalesce(excluded.call_successful, calls.call_successful),
    in_voicemail         = coalesce(excluded.in_voicemail, calls.in_voicemail),
    summary              = coalesce(excluded.summary, calls.summary),
    transcript           = coalesce(excluded.transcript, calls.transcript),
    -- a live `transcript_updated` turn replaces the previous partial; the
    -- final transcript on call_ended replaces the last partial the same way
    transcript_object    = coalesce(excluded.transcript_object, calls.transcript_object),
    -- a stored, given-up or purged copy is TERMINAL: a re-ingest must never
    -- regress it to pending, a purged one least of all -- pending sends the
    -- copy to fetch the audio again (00148); a pending one keeps its attempt
    -- count across events
    recording            = case
                             when calls.recording->>'fetch_state' in ('stored', 'failed', 'purged') then calls.recording
                             when calls.recording->>'fetch_state' = 'pending' and excluded.recording is not null
                               then calls.recording || excluded.recording
                             else coalesce(excluded.recording, calls.recording)
                           end,
    public_log_url       = null,
    cost                 = coalesce(excluded.cost, calls.cost),
    latency              = coalesce(excluded.latency, calls.latency),
    -- the analysis arrives on call_analyzed and stays: a retried call_ended
    -- carries none and must not blank it
    wanted               = coalesce(excluded.wanted, calls.wanted),
    outcome              = coalesce(excluded.outcome, calls.outcome),
    follow_up            = coalesce(excluded.follow_up, calls.follow_up),
    caller_name          = coalesce(excluded.caller_name, calls.caller_name),
    analysis             = coalesce(excluded.analysis, calls.analysis),
    contact_id           = coalesce(calls.contact_id, excluded.contact_id),
    conversation_id      = coalesce(calls.conversation_id, excluded.conversation_id),
    -- the audit copy keeps the analysis: a retried call_ended landing after
    -- call_analyzed ranks equal and must not replace the richer payload
    raw                  = case
                             when (calls.raw ? 'call_analysis') and not (excluded.raw ? 'call_analysis') then calls.raw
                             else excluded.raw
                           end
  -- FORWARD ONLY. An event older than the row (a retried call_started after
  -- call_ended, a partial transcript after the final one) changes nothing.
  where public.call_status_rank(excluded.status) >= public.call_status_rank(calls.status)
  returning id, (xmax = 0), recording->>'fetch_state', (recording->>'attempts')::int
    into v_call_id, v_is_new, v_rec_state, v_rec_attempts;

  if v_call_id is null then
    -- The upsert declined: nothing moved, including updated_at, so a stale
    -- event cannot restart the heartbeat isLiveCall() reads. Answer from the
    -- row as it stands.
    select id, recording->>'fetch_state', (recording->>'attempts')::int, contact_id, conversation_id
      into v_call_id, v_rec_state, v_rec_attempts, v_contact_id, v_conversation_id
      from calls where tenant_id = p_tenant_id and retell_call_id = p_retell_call_id;
    return jsonb_build_object(
      'call_id', v_call_id, 'is_new', false, 'skipped', true,
      'recording_state', v_rec_state, 'recording_attempts', v_rec_attempts,
      'contact_id', v_contact_id, 'conversation_id', v_conversation_id);
  end if;

  if v_is_new then
    insert into events (tenant_id, kind, category, subject_type, subject_id, data)
    values (p_tenant_id, 'call.recorded', 'call', 'call', v_call_id,
            jsonb_build_object('direction', coalesce(p_direction, 'inbound'), 'status', coalesce(p_status, 'ended')));
  end if;

  -- Metered once, on the event that first carries a duration -- and never a
  -- second row for the same call, whatever the caller believed it knew.
  if p_duration_ms is not null and p_duration_ms > 0
     and (not v_had_row or v_prev_duration is null)
     and not exists (select 1 from events e
                      where e.kind = 'usage.voice_seconds'
                        and e.subject_type = 'call'
                        and e.subject_id = v_call_id) then
    insert into events (tenant_id, kind, category, subject_type, subject_id, data)
    values (p_tenant_id, 'usage.voice_seconds', 'usage', 'call', v_call_id,
            jsonb_build_object('seconds', round(p_duration_ms / 1000.0)));
  end if;

  return jsonb_build_object(
    'call_id', v_call_id, 'is_new', v_is_new, 'skipped', false,
    'recording_state', v_rec_state, 'recording_attempts', v_rec_attempts,
    'contact_id', v_contact_id, 'conversation_id', v_conversation_id);
end $$;


--
-- Name: ingest_inbound(uuid, text, text, text, text, text, text, text, timestamp with time zone, jsonb, jsonb, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ingest_inbound(p_tenant_id uuid, p_channel text, p_identity_external_id text, p_phone_e164 text, p_wa_profile_name text, p_message_external_id text, p_type text, p_body text, p_channel_ts timestamp with time zone, p_media jsonb DEFAULT NULL::jsonb, p_meta jsonb DEFAULT '{}'::jsonb, p_opt_out boolean DEFAULT false, p_opt_in boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_contact_id      uuid;
  v_conversation_id uuid;
  v_message_id      uuid;
  v_state           text;
  v_paused          timestamptz;
  v_prev_wa         timestamptz;
  v_processed       timestamptz;
  v_consent         text;
  v_dnc             boolean;
  v_ts              timestamptz := coalesce(p_channel_ts, now());
begin
  -- serialize per identity: closes the NULL-phone concurrent-first-message race
  perform pg_advisory_xact_lock(
    hashtextextended(p_tenant_id::text || '|' || p_channel || '|' || p_identity_external_id, 42));

  select contact_id into v_contact_id
    from contact_identities
   where tenant_id = p_tenant_id and channel = p_channel and external_id = p_identity_external_id;

  if v_contact_id is null and p_phone_e164 is not null then
    select id into v_contact_id from contacts
     where tenant_id = p_tenant_id and phone_e164 = p_phone_e164;
  end if;

  if v_contact_id is null then
    insert into contacts (tenant_id, phone_e164, wa_profile_name, last_seen_at)
    values (p_tenant_id, p_phone_e164, p_wa_profile_name, now())
    on conflict (tenant_id, phone_e164) where phone_e164 is not null
      do update set last_seen_at = now(),
                    wa_profile_name = coalesce(excluded.wa_profile_name, contacts.wa_profile_name)
    returning id into v_contact_id;
  else
    update contacts
       set last_seen_at = now(),
           wa_profile_name = coalesce(p_wa_profile_name, wa_profile_name)
     where id = v_contact_id;
  end if;

  if p_opt_out then
    update contacts
       set consent = 'opted_out', dnc = true,
           consent_source = 'customer_message', consent_updated_at = now()
     where id = v_contact_id and consent is distinct from 'opted_out';
    if found then
      insert into events (tenant_id, kind, category, subject_type, subject_id, data)
      values (p_tenant_id, 'contact.consent_changed', 'contact', 'contact', v_contact_id,
              jsonb_build_object('consent', 'opted_out', 'source', 'customer_message',
                                 'channel', p_channel, 'message_external_id', p_message_external_id,
                                 'words', left(p_body, 80)));
    end if;
  elsif p_opt_in then
    -- The way back. Only an explicit word (START / ALTA / UNSTOP) reaches here,
    -- never an ordinary message — otherwise the block would lift itself the
    -- moment the customer said anything at all.
    update contacts
       set consent = 'opted_in', dnc = false,
           consent_source = 'customer_message', consent_updated_at = now()
     where id = v_contact_id and consent is distinct from 'opted_in';
    if found then
      insert into events (tenant_id, kind, category, subject_type, subject_id, data)
      values (p_tenant_id, 'contact.consent_changed', 'contact', 'contact', v_contact_id,
              jsonb_build_object('consent', 'opted_in', 'source', 'customer_message',
                                 'channel', p_channel, 'message_external_id', p_message_external_id,
                                 'words', left(p_body, 80)));
    end if;
  end if;

  -- Read back AFTER the update above, so a STOP arriving in this very batch is
  -- already reflected in what the caller is told.
  select consent, dnc into v_consent, v_dnc from contacts where id = v_contact_id;

  insert into contact_identities (tenant_id, contact_id, channel, external_id)
  values (p_tenant_id, v_contact_id, p_channel, p_identity_external_id)
  on conflict (tenant_id, channel, external_id) do nothing;

  -- monotone recency: a replayed/out-of-order old message can never rewind
  insert into conversations (tenant_id, contact_id, last_message_at, last_inbound_at)
  values (p_tenant_id, v_contact_id, v_ts, v_ts)
  on conflict (tenant_id, contact_id)
    do update set last_message_at = greatest(conversations.last_message_at, excluded.last_message_at),
                  last_inbound_at = greatest(conversations.last_inbound_at, excluded.last_inbound_at)
  returning id, state, paused_until, last_wa_inbound_at
    into v_conversation_id, v_state, v_paused, v_prev_wa;

  -- the atomic replay gate: a duplicate wamid short-circuits BEFORE any
  -- window/metering/reopen side effect
  insert into messages (tenant_id, conversation_id, contact_id, channel, direction, sender,
                        type, body, media, external_id, channel_ts, status, meta)
  values (p_tenant_id, v_conversation_id, v_contact_id, p_channel, 'inbound', 'customer',
          p_type, p_body, p_media, p_message_external_id, p_channel_ts, 'received', p_meta)
  on conflict (tenant_id, external_id) where external_id is not null do nothing
  returning id into v_message_id;

  if v_message_id is null then
    select id, (meta->>'processed_at')::timestamptz
      into v_message_id, v_processed
      from messages
     where tenant_id = p_tenant_id and external_id = p_message_external_id;
    return jsonb_build_object(
      'message_id', v_message_id, 'conversation_id', v_conversation_id,
      'contact_id', v_contact_id, 'is_new', false,
      'processed', v_processed is not null,
      'state', v_state, 'paused_until', v_paused,
      'consent', v_consent, 'dnc', v_dnc);
  end if;

  -- a new customer message reopens a closed thread (never overrides a human)
  if v_state in ('archived', 'snoozed') then
    update conversations
       set state = 'open', snooze_until = null
     where id = v_conversation_id;
    insert into events (tenant_id, kind, category, subject_type, subject_id, data)
    values (p_tenant_id, 'conversation.reopened', 'conversation', 'conversation', v_conversation_id,
            jsonb_build_object('from_state', v_state, 'trigger', 'customer_message'));
    v_state := 'open';
  end if;

  if p_channel = 'whatsapp' then
    -- Meta bills per service conversation; a >24h gap opens a new one (metering).
    if v_prev_wa is null or v_prev_wa < now() - interval '24 hours' then
      insert into events (tenant_id, kind, category, subject_type, subject_id, data)
      values (p_tenant_id, 'usage.wa_conversation', 'usage', 'conversation', v_conversation_id, '{}'::jsonb);
    end if;
    update conversations
       set last_wa_inbound_at = greatest(coalesce(last_wa_inbound_at, 'epoch'::timestamptz), v_ts)
     where id = v_conversation_id;
  end if;

  insert into events (tenant_id, kind, category, subject_type, subject_id, data)
  values (p_tenant_id, 'message.received', 'message', 'message', v_message_id,
          jsonb_build_object('channel', p_channel, 'type', p_type));

  return jsonb_build_object(
    'message_id', v_message_id, 'conversation_id', v_conversation_id,
    'contact_id', v_contact_id, 'is_new', true, 'processed', false,
    'state', v_state, 'paused_until', v_paused,
    'consent', v_consent, 'dnc', v_dnc);
end $$;


--
-- Name: is_acting_member(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_acting_member(p_tenant uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from public.memberships m
     where m.user_id = (select auth.uid())
       and m.tenant_id = p_tenant
       and (m.role in ('owner', 'operator') or (m.role = 'partner' and public.session_shows_second_factor()))
  );
$$;


--
-- Name: FUNCTION is_acting_member(p_tenant uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.is_acting_member(p_tenant uuid) IS 'True when the caller may COMMIT changes in this tenant: an owner or an operator, or a partner on a session that showed its second factor (0013). Viewers read only.';


--
-- Name: is_platform_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_platform_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (select 1 from public.platform_admins a where a.user_id = auth.uid());
$$;


--
-- Name: FUNCTION is_platform_admin(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.is_platform_admin() IS 'Whether the calling session is a Chanlytics platform admin. Answers only about the caller, which is why every session may ask; platform_overview() is what the answer unlocks.';


--
-- Name: is_workspace_owner(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_workspace_owner(p_tenant uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from public.memberships m
     where m.user_id = (select auth.uid())
       and m.tenant_id = p_tenant
       and m.role = 'owner'
  );
$$;


--
-- Name: FUNCTION is_workspace_owner(p_tenant uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.is_workspace_owner(p_tenant uuid) IS 'True when the caller owns this tenant. Narrower than is_acting_member (00014), which admits operators.';


--
-- Name: jobs_backlog(interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jobs_backlog(p_wait interval DEFAULT '00:02:00'::interval) RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select count(*)::int from public.jobs
   where state = 'scheduled' and due_at < now() - p_wait;
$$;


--
-- Name: FUNCTION jobs_backlog(p_wait interval); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.jobs_backlog(p_wait interval) IS 'How many scheduled jobs have been due for longer than p_wait (default two minutes) and not been claimed. Zero when the heartbeat is draining.';


--
-- Name: jobs_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jobs_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if NEW.state is distinct from OLD.state then
    if OLD.state in ('done', 'failed', 'canceled') then
      raise exception 'jobs.state is terminal (% -> % refused)', OLD.state, NEW.state;
    end if;
    if OLD.state = 'scheduled' and NEW.state not in ('fired', 'canceled') then
      raise exception 'a scheduled job may only be fired or canceled (% refused)', NEW.state;
    end if;
    if OLD.state = 'fired' and NEW.state not in ('done', 'failed') then
      raise exception 'a fired job may only finish or fail (% refused)', NEW.state;
    end if;
  end if;
  return NEW;
end $$;


--
-- Name: FUNCTION jobs_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.jobs_guard() IS 'scheduled -> fired | canceled; fired -> fired (a lease taken back) | done | failed; done, failed and canceled are final. A payload may still change on any row: an erasure scrubs finished ones.';


--
-- Name: lead_address_suppressed(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_address_suppressed(p_tenant_id uuid, p_address text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (select 1 from public.lead_addresses_suppressed(p_tenant_id, array[p_address]))
$$;


--
-- Name: FUNCTION lead_address_suppressed(p_tenant_id uuid, p_address text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_address_suppressed(p_tenant_id uuid, p_address text) IS 'Whether one address is on the never-again list: lead_addresses_suppressed for one, so the rule is written once. Service role only.';


--
-- Name: lead_addresses_suppressed(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_addresses_suppressed(p_tenant_id uuid, p_addresses text[]) RETURNS SETOF text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with asked as (
    select distinct lower(btrim(a)) as address
      from unnest(coalesce(p_addresses, '{}'::text[])) as a
     where nullif(btrim(a), '') is not null
  )
  select q.address from asked q
   where exists (
     select 1 from public.lead_suppressions s
      where s.tenant_id = p_tenant_id
        and ((s.kind = 'email' and s.hash = public.lead_suppression_hash(p_tenant_id, q.address))
          or (s.kind = 'domain' and position('@' in q.address) > 0 and split_part(q.address, '@', -1) <> ''
              and s.hash = public.lead_suppression_hash(p_tenant_id, split_part(q.address, '@', -1)))))
$$;


--
-- Name: FUNCTION lead_addresses_suppressed(p_tenant_id uuid, p_addresses text[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_addresses_suppressed(p_tenant_id uuid, p_addresses text[]) IS 'The never-again list for addresses (Reach out Part 5, G9): each asked address, lower-cased and trimmed, that an email row holds, or whose domain (after its last "@") a domain row holds. The one predicate the send door''s facts, the audience and the finder ask. Service role only.';


--
-- Name: lead_blank(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_blank(p_lead_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_n integer;
begin
  -- Kept: id, tenant_id, stage, closed_reason, contact_id, converted_at,
  -- contacted_at, exported_at, found_at, erased_at, the counts on its
  -- memberships. Everything that names the place, reaches it or came off its
  -- site goes, and its place id with it, so the place found again is new.
  update public.leads
     set place_id = null, business_name = '', category = null, street = null, city = null, region = null, postal_code = null,
         lat = null, lng = null, website_host = null, instagram_url = null, phone_e164 = null, phone_sources = 0,
         email = null, email_alternates = '[]'::jsonb, email_state = 'none', email_checked_at = null, rating = null, reviews = null,
         last_outcome = null, last_note = null, blanked_at = coalesce(blanked_at, now()),
         -- What the listing showed about the business goes with the rest (D2).
         about = null, hours = '[]'::jsonb, image_url = null, price = null, reviews_dist = null,
         facebook_url = null, linkedin_url = null, tiktok_url = null, claimed = null, maps_url = null, rank = null, neighborhood = null, logo_url = null, mark_path = null
   where id = p_lead_id;
  get diagnostics v_n = row_count;
  delete from public.lead_places where lead_id = p_lead_id;
  update public.lead_search_members
     set judgment = '{}'::jsonb, reason = '', blanked_at = coalesce(blanked_at, now())
   where lead_id = p_lead_id;
  return v_n;
end $$;


--
-- Name: FUNCTION lead_blank(p_lead_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_blank(p_lead_id uuid) IS 'Removes everything that names or reaches a place, and its memberships'' judgments, keeping the stage, the link to a person and the counts. The one function retention and erasure blank through.';


--
-- Name: lead_bulk(uuid, text, uuid[], jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_bulk(p_tenant_id uuid, p_action text, p_ids uuid[] DEFAULT NULL::uuid[], p_view jsonb DEFAULT NULL::jsonb, p_search_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user   uuid := auth.uid();
  v_ids    uuid[];
  v_stage  text;
  v_reason text;
  v_before jsonb := '{}'::jsonb;
  v_done   integer := 0;
  v_op     uuid;
  v_m      record;
  v_a      jsonb;
  v_stop   jsonb;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  if p_tenant_id is null or not public.is_acting_member(p_tenant_id) then
    raise exception 'Workspace not found.' using errcode = 'P0002';
  end if;
  if p_action not in ('contacted', 'not_a_fit', 'keep', 'exclude') then
    raise exception 'action must be contacted, not_a_fit, keep or exclude' using errcode = '22023';
  end if;
  if (p_ids is null) = (p_view is null) then
    raise exception 'name the leads, or the view, and not both' using errcode = '22023';
  end if;

  -- Keep and Exclude over a selection of Needs review (D3, 00145): the owner's, through the member's own
  -- door (lead_member_move) once per lead, so each counts or is refused exactly as the row's own Keep is.
  -- The search named is the one the pile is read in; without it, the lead's newest membership in review.
  -- One lead_operations row per member, as the row's act writes, and no bulk row: the acts undo one by one.
  -- The month running out stops the run and is said with what was done before it.
  if p_action in ('keep', 'exclude') then
    if p_ids is null then
      raise exception 'keep and exclude take the leads by id' using errcode = '22023';
    end if;
    if not public.has_permission(v_user, p_tenant_id, 'find') then
      raise exception 'Only an owner can keep or exclude a lead.' using errcode = '42501';
    end if;
    for v_m in
      select distinct on (m.lead_id) m.search_id, m.lead_id
        from unnest(p_ids) as x(id)
        join public.lead_search_members m on m.lead_id = x.id and m.tenant_id = p_tenant_id and m.class = 'review' and m.blanked_at is null
        join public.lead_rounds r on r.id = m.round_id
       order by m.lead_id, (m.search_id is not distinct from p_search_id) desc, r.created_at desc
    loop
      v_a := public.lead_member_move(v_m.search_id, v_m.lead_id, p_action);
      if v_a ? 'error' then
        if v_a->>'error' = 'month_leads_used' then
          v_stop := v_a;
          exit;
        end if;
      else
        v_done := v_done + 1;
      end if;
    end loop;
    return jsonb_build_object('done', v_done, 'skipped', cardinality(p_ids) - v_done, 'op_id', null, 'version', 1)
        || coalesce(v_stop, '{}'::jsonb);
  end if;
  v_stage  := case p_action when 'contacted' then 'nurture' else 'archived' end;
  v_reason := case p_action when 'not_a_fit' then 'not_a_fit' else null end;

  -- The same rows the page would show: the selection, or the view's filters
  -- with no paging. lead_in_list holds the list rule for both.
  if p_ids is not null then
    select coalesce(array_agg(l.id), '{}') into v_ids
      from public.leads l
     where l.tenant_id = p_tenant_id and l.id = any (p_ids)
       and l.erased_at is null and l.blanked_at is null;
  else
    select coalesce(array_agg(distinct m.lead_id), '{}') into v_ids
      from public.lead_search_members m
      join public.leads l on l.id = m.lead_id
     where m.tenant_id = p_tenant_id
       and (p_view->>'search' is null or m.search_id = (p_view->>'search')::uuid)
       and m.class = coalesce(p_view->>'class', 'qualified')
       and (m.class <> 'qualified' or m.counted)
       and public.lead_in_list(l.stage, l.closed_reason, coalesce(p_view->>'list', 'all'))
       and m.blanked_at is null and l.blanked_at is null and l.erased_at is null;
  end if;
  if coalesce(array_length(v_ids, 1), 0) = 0 then
    return jsonb_build_object('done', 0, 'op_id', null, 'version', 1);
  end if;

  -- What each row was, read before anything is written, with the version this
  -- act will leave it at: Undo restores only the rows nobody touched since.
  select coalesce(jsonb_object_agg(l.id::text, jsonb_build_object(
           'stage', l.stage, 'closed_reason', l.closed_reason, 'seen', l.version + 1)), '{}'::jsonb)
    into v_before
    from public.leads l
   where l.tenant_id = p_tenant_id and l.id = any (v_ids);

  update public.leads l
     set stage         = v_stage,
         closed_reason = case when v_stage = 'archived' then v_reason else null end,
         contacted_at  = case when v_stage = 'nurture' then coalesce(l.contacted_at, now()) else l.contacted_at end,
         version       = l.version + 1
   where l.tenant_id = p_tenant_id and l.id = any (v_ids);
  get diagnostics v_done = row_count;

  -- One event for the act, not one per lead: the operation row holds the ids,
  -- and an activity log with 1,240 rows in it says nothing.
  if p_action = 'not_a_fit' then
    insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
    values (p_tenant_id, 'lead.not_a_fit', 'lead', 'lead', null,
            jsonb_build_object('why', null, 'count', v_done, 'bulk', true, 'by', v_user));
  else
    insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
    values (p_tenant_id, 'lead.stage', 'lead', 'lead', null,
            jsonb_build_object('stage', v_stage, 'reason', v_reason, 'count', v_done, 'bulk', true, 'by', v_user));
  end if;

  -- version 1: a bulk row names no single lead, so the operation is guarded by
  -- undone_at and each lead by the version in `before`.
  insert into public.lead_operations (tenant_id, kind, search_id, lead_ids, before, after, version, by)
  values (p_tenant_id, 'bulk', null, v_ids, v_before,
          jsonb_build_object('action', p_action, 'done', v_done), 1, v_user)
  returning id into v_op;
  return jsonb_build_object('done', v_done, 'op_id', v_op, 'version', 1);
end $$;


--
-- Name: FUNCTION lead_bulk(p_tenant_id uuid, p_action text, p_ids uuid[], p_view jsonb, p_search_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_bulk(p_tenant_id uuid, p_action text, p_ids uuid[], p_view jsonb, p_search_id uuid) IS 'Operator for contacted and not_a_fit; owner (permission find) for keep and exclude, which go through lead_member_move once per lead in review -- in the search named, else the lead''s newest -- and stop when the month''s leads run out ({error: month_leads_used} beside what was done). Marks many leads contacted, or not a fit: the ids the owner selected, or every lead the view matches (the same filters leads_page reads, with no paging), never both. One lead_operations row (kind bulk) holds every id with what it was and the version this act leaves it at, so lead_undo restores the rows nobody touched since and says how many it kept. Returns {done, op_id, version}.';


--
-- Name: lead_cap(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_cap(p_name text) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
declare
  v numeric;
begin
  v := case p_name
    when 'month_leads'      then 500   -- Qualified leads a workspace finds in its month (LEAD_MONTHLY_ALLOWANCE)
    when 'month_usd'        then 25    -- what searching may cost a workspace in its month (LEAD_MONTHLY_BUDGET_USD)
    when 'day_usd'          then 10    -- ... in its day (LEAD_DAY_CAP_USD)
    when 'platform_day_usd' then 50    -- ... what it may cost the platform in a UTC day (LEAD_PLATFORM_DAY_CAP_USD)
    when 'list_rows'        then 500   -- rows a file brings, leads one press chooses (LEAD_LIST_MAX)
  end;
  -- A name it does not know is a mistake in the caller, never "no cap": a comparison with null would let anything by.
  if v is null then
    raise exception 'lead_cap: no cap is named %', coalesce(p_name, 'null') using errcode = '22023';
  end if;
  return v;
end;
$$;


--
-- Name: FUNCTION lead_cap(p_name text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_cap(p_name text) IS 'The lead finder''s caps, the one place SQL writes them (00272): month_leads, month_usd, day_usd, platform_day_usd, list_rows. contracts'' caps.ts and lead-import.ts say the same, and lead-caps.db.test.mjs holds the two together. A name it does not know raises.';


--
-- Name: lead_check_again(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_check_again(p_tenant_id uuid, p_lead_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user uuid := auth.uid();
  v_ids  uuid[] := '{}';
  v_r    record;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  if p_tenant_id is null or not public.has_permission(v_user, p_tenant_id, 'find') then
    raise exception 'Only an owner can check a lead again.' using errcode = '42501';
  end if;
  -- The switch, read before anything is scheduled (§0.5): the mailbox check is money too.
  if not public.lead_searches_on(p_tenant_id) then
    return jsonb_build_object('error', 'paused');
  end if;
  -- One job per round the leads were found in: the re-check runs under the round, as the round's own checks
  -- did, and commits through lead_check_commit. Only an address whose last check did not answer is asked
  -- again; a lead whose search is still running is left to that search's own checks; a lead with no address
  -- has nothing to check; and a lead of another workspace is not this owner's to ask about.
  for v_r in
    select m.round_id, array_agg(m.lead_id) as lead_ids
      from (
        select distinct on (m.lead_id) m.lead_id, m.round_id
          from unnest(p_lead_ids) as x(id)
          join public.leads l on l.id = x.id and l.tenant_id = p_tenant_id and l.erased_at is null and l.blanked_at is null
          join public.lead_search_members m on m.lead_id = l.id and m.tenant_id = p_tenant_id and m.class = 'review' and m.blanked_at is null
          join public.lead_rounds r on r.id = m.round_id and r.state = 'ended'
         where l.email is not null and l.email_state = 'unknown'
         order by m.lead_id, r.created_at desc
      ) m
     group by m.round_id
  loop
    update public.leads set email_state = 'checking' where id = any (v_r.lead_ids);
    insert into public.jobs (tenant_id, kind, due_at, payload)
    values (p_tenant_id, 'lead_check', now(),
            jsonb_build_object('round_id', v_r.round_id, 'batch', 0, 'again', gen_random_uuid()::text, 'lead_ids', to_jsonb(v_r.lead_ids)));
    v_ids := v_ids || v_r.lead_ids;
  end loop;
  return jsonb_build_object('scheduled', cardinality(v_ids), 'skipped', cardinality(p_lead_ids) - cardinality(v_ids));
end $$;


--
-- Name: FUNCTION lead_check_again(p_tenant_id uuid, p_lead_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_check_again(p_tenant_id uuid, p_lead_ids uuid[]) IS 'Owner (permission find). Asks the mailbox check again for the named leads whose last check did not answer (email_state unknown), once their search has finished: each goes to checking and one lead_check job per round is written with {round_id, batch 0, again <nonce>, lead_ids}, so the engine runs it under the round with a run id of its own and commits through lead_check_commit. {error: paused} while searching is off. Returns {scheduled, skipped}.';


--
-- Name: lead_check_commit(uuid, uuid, jsonb, numeric, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_check_commit(p_round_id uuid, p_run_id uuid, p_results jsonb, p_usage_usd numeric, p_last boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_round   public.lead_rounds;
  v_r       jsonb;
  v_m       record;
  v_newly   integer := 0;
  v_counted integer := 0;
  v_room    integer;
  v_counter public.lead_counters;
  v_prev    numeric;
  v_delta   numeric;
  v_ended   boolean := false;
  v_month   text;
  v_later   integer := 0;
begin
  select * into v_round from public.lead_rounds where id = p_round_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'why', 'round');
  end if;
  -- A round that ended gave its unused reservation back (lead_round_end), so no room is left on it: a member
  -- that qualifies now, from a Check again (00145), counts through the month's allowance the way Keep does.
  v_room := case when v_round.state = 'ended' then 0 else greatest(v_round.allowance_reserved - v_round.allowance_used, 0) end;
  for v_r in select * from jsonb_array_elements(coalesce(p_results, '[]'::jsonb)) loop
    update public.leads
       set email_state = v_r->>'email_state', email_checked_at = coalesce((v_r->>'checked_at')::timestamptz, now())
     where id = (v_r->>'lead_id')::uuid and tenant_id = v_round.tenant_id
       and blanked_at is null and erased_at is null
       and (v_r->>'email_state') in ('ok', 'catch_all', 'unknown', 'invalid');
  end loop;
  -- A member the email standard alone held back, whose address now checks
  -- out, qualifies. It counts only through the round's reservation, the way
  -- lead_collect_commit counts a page's Qualified places: past the room the
  -- member is Qualified and uncounted, and no counter moves.
  for v_m in
    select m.search_id, m.lead_id, m.judgment
      from public.lead_search_members m
      join public.leads l on l.id = m.lead_id
     where m.round_id = p_round_id and m.class = 'review' and m.blanked_at is null and l.email_state = 'ok'
       and jsonb_typeof(m.judgment->'reasons') = 'array'
       and jsonb_array_length(m.judgment->'reasons') > 0
       and not exists (select 1 from jsonb_array_elements_text(m.judgment->'reasons') x where x not like 'email:%')
  loop
    if v_round.state = 'ended' then
      v_month   := public.lead_month(v_round.tenant_id, now());
      v_counter := public.lead_counter_take(v_round.tenant_id, 'allowance', v_month);
      -- The month is full: the member stays Needs review with its address now known good, for Keep to count later.
      if v_counter.used + v_counter.reserved + 1 > public.lead_cap('month_leads') then
        continue;
      end if;
      update public.lead_counters set used = used + 1, updated_at = now() where id = v_counter.id;
      update public.lead_search_members
         set class = 'qualified', counted = true, counted_month = v_month, version = version + 1,
             judgment = judgment || jsonb_build_object('reasons', '[]'::jsonb)
       where search_id = v_m.search_id and lead_id = v_m.lead_id;
      v_newly := v_newly + 1;
      v_later := v_later + 1;
      continue;
    end if;
    update public.lead_search_members
       set class = 'qualified', counted = (v_room > 0),
           counted_month = case when v_room > 0 then v_round.month else counted_month end,
           version = version + 1,
           judgment = judgment || jsonb_build_object('reasons', '[]'::jsonb)
     where search_id = v_m.search_id and lead_id = v_m.lead_id;
    v_newly := v_newly + 1;
    if v_room > 0 then
      v_room    := v_room - 1;
      v_counted := v_counted + 1;
    end if;
  end loop;
  -- Delivery settles inside the reservation, as lead_collect_commit's does:
  -- nothing counted past the room, so the month's reserved becomes used.
  if v_counted > 0 then
    update public.lead_rounds set allowance_used = allowance_used + v_counted where id = p_round_id;
    v_counter := public.lead_counter_take(v_round.tenant_id, 'allowance', v_round.month);
    update public.lead_counters set used = used + v_counted, reserved = greatest(reserved - v_counted, 0), updated_at = now() where id = v_counter.id;
  end if;
  -- The checker run's total so far, not this batch's delta: only what is new
  -- settles, so a check job tried again charges the batch once (E4, the rule
  -- lead_collect_commit takes). The run is locked after the round, never
  -- before it.
  if p_run_id is not null and coalesce(p_usage_usd, 0) > 0 then
    select r.usage_usd into v_prev from public.lead_runs r where r.id = p_run_id and r.round_id = p_round_id for update;
    if found and p_usage_usd > v_prev then
      v_delta := p_usage_usd - v_prev;
      perform public.lead_settle_usage(v_round.tenant_id, v_round.month, v_round.day, v_round.platform_day, v_delta,
        case when v_round.state = 'ended' then 0 else v_round.cost_reserved_usd - v_round.cost_usd end);
      -- An ended round is final (its trigger refuses a change): the month's counters carry the cents, the round's own cost stays what it ended at.
      if v_round.state <> 'ended' then
        update public.lead_rounds set cost_usd = cost_usd + v_delta where id = p_round_id;
      end if;
      update public.lead_runs set usage_usd = p_usage_usd where id = p_run_id;
    end if;
  end if;
  if p_last then
    select * into v_round from public.lead_rounds where id = p_round_id;
    v_ended := public.lead_round_end(p_round_id, coalesce(v_round.ending_pending,
      case when v_round.allowance_used >= v_round.target then 'target_reached' else 'searched_everything' end));
  end if;
  return jsonb_build_object('ok', true, 'qualified', v_newly, 'counted', v_counted + v_later, 'ended', v_ended);
end $$;


--
-- Name: FUNCTION lead_check_commit(p_round_id uuid, p_run_id uuid, p_results jsonb, p_usage_usd numeric, p_last boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_check_commit(p_round_id uuid, p_run_id uuid, p_results jsonb, p_usage_usd numeric, p_last boolean) IS 'A batch of mailbox answers ([{lead_id, email_state, checked_at}]) from the check run p_run_id: each lead''s state is set (never a blanked or erased one); a member of the round held in review by the email standard alone, whose address now checks out, is Qualified -- counted through the round''s reservation while the round runs, and through the month''s allowance the way Keep is once the round has ended (Check again, 00145; it stays in review when the month is full). The run''s usage settles by its total so far (E4). p_last ends the round with the ending left pending, or by its target. Returns {ok, qualified, counted, ended}.';


--
-- Name: lead_collect_commit(uuid, text, integer, integer, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_collect_commit(p_run_id uuid, p_owner text, p_gen integer, p_from_offset integer, p_to_offset integer, p_page jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_run       public.lead_runs;
  v_round     public.lead_rounds;
  v_room      integer;
  v_counted   integer := 0;
  v_qualified integer := 0;
  v_review    integer := 0;
  v_excluded  integer := 0;
  v_month     text;
  v_usage     numeric;
  v_delta     numeric;
  v_n         integer;
  v_j         jsonb;
  v_el        jsonb;
  v_pl        jsonb;
  v_m         jsonb;
  v_dup       text;
  v_lead      uuid;
  v_class     text;
  v_next      jsonb;
  v_r         jsonb;
  v_state     text;
  v_counter   public.lead_counters;
begin
  -- One lock order everywhere: the ROUND first, then its runs, as
  -- lead_round_stop and lead_search_remove take them. So the run is read
  -- without a lock, only to learn which round it belongs to (a run never
  -- moves), and read again under lock once the round is held; a Stop arriving
  -- mid-page then waits instead of deadlocking (40P01). The lease and the
  -- offset are judged on the locked copy, so the compare-and-set still holds.
  select * into v_run from public.lead_runs where id = p_run_id;
  if not found then
    return jsonb_build_object('ok', false, 'why', 'run');
  end if;
  select * into v_round from public.lead_rounds where id = v_run.round_id for update;
  select * into v_run from public.lead_runs where id = p_run_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'why', 'run');
  end if;
  if v_run.lease_owner is distinct from p_owner or v_run.lease_gen <> p_gen then
    return jsonb_build_object('ok', false, 'why', 'lease');
  end if;
  if v_run.read_offset <> p_from_offset then
    return jsonb_build_object('ok', false, 'why', 'offset');
  end if;
  -- A check run may commit after its round ended (Check again, 00145): it decides nothing, its answers
  -- reach the leads through lead_check_commit, and its usage settles below against nothing outstanding.
  if v_round.state = 'ended' and v_run.purpose <> 'check' then
    return jsonb_build_object('ok', false, 'why', 'ended');
  end if;
  v_month := v_round.month;
  v_room  := greatest(v_round.allowance_reserved - v_round.allowance_used, 0);

  -- The judge's answers for the page's batches, kept once each by op_id.
  for v_j in select * from jsonb_array_elements(
      case jsonb_typeof(p_page->'judgment') when 'array' then p_page->'judgment'
           when 'object' then jsonb_build_array(p_page->'judgment') else '[]'::jsonb end) loop
    insert into public.lead_judgments (tenant_id, round_id, batch, op_id, request_hash, answer, model, tokens)
    values (v_round.tenant_id, v_round.id, coalesce((v_j->>'batch')::integer, 0), v_j->>'op_id', v_j->>'request_hash',
            coalesce(v_j->'answer', '{}'::jsonb), v_j->>'model', coalesce((v_j->>'tokens')::integer, 0))
    on conflict (op_id) do nothing;
    get diagnostics v_n = row_count;
    if v_n = 1 then
      update public.lead_rounds
         set judge_tokens = judge_tokens + coalesce((v_j->>'tokens')::integer, 0),
             judge_model  = coalesce(v_j->>'model', judge_model)
       where id = v_round.id;
    end if;
  end loop;

  -- The places: a lead by place id (once), a duplicate listing folded into
  -- the lead it belongs to, a membership (once), the count.
  for v_el in select * from jsonb_array_elements(coalesce(p_page->'places', '[]'::jsonb)) loop
    v_pl  := v_el->'place';
    v_m   := v_el->'member';
    v_dup := v_el->>'duplicate_of_place_id';
    if v_pl->>'place_id' is null then continue; end if;
    -- Never a place, number or address on the never-again list: a customer
    -- is hidden from every search, an erased person from everything (S8).
    if exists (select 1 from public.lead_suppressions s where s.tenant_id = v_round.tenant_id and (
           (s.kind = 'place' and s.what in ('customer', 'erased') and s.hash = public.lead_suppression_hash(v_round.tenant_id, v_pl->>'place_id'))
        or (s.kind = 'phone' and s.what = 'erased' and v_pl->>'phone_e164' is not null and s.hash = public.lead_suppression_hash(v_round.tenant_id, v_pl->>'phone_e164'))
        or (s.kind = 'email' and s.what = 'erased' and v_pl->>'email' is not null and s.hash = public.lead_suppression_hash(v_round.tenant_id, v_pl->>'email')))) then
      continue;
    end if;
    v_lead := null;
    if v_dup is not null then
      select l.id into v_lead from public.leads l
       where l.tenant_id = v_round.tenant_id and l.blanked_at is null and l.erased_at is null
         and (l.place_id = v_dup or exists (select 1 from public.lead_places p where p.tenant_id = l.tenant_id and p.lead_id = l.id and p.place_id = v_dup))
       limit 1;
      if v_lead is not null then
        insert into public.lead_places (lead_id, tenant_id, place_id, title, street)
        values (v_lead, v_round.tenant_id, v_pl->>'place_id', left(v_pl->>'business_name', 200), left(v_pl->>'street', 200))
        on conflict (tenant_id, place_id) do nothing;
      end if;
    end if;
    if v_lead is null then
      insert into public.leads (tenant_id, place_id, business_name, category, street, city, region, postal_code, country, lat, lng,
                                website_host, website_root, instagram_url, phone_e164, phone_sources, phone_wrong, email, email_alternates, email_state, rating, reviews,
                                about, hours, image_url, price, reviews_dist, facebook_url, linkedin_url, tiktok_url, claimed, maps_url, rank, neighborhood, logo_url, mark_path)
      values (v_round.tenant_id, v_pl->>'place_id', coalesce(left(v_pl->>'business_name', 200), ''), left(v_pl->>'category', 120),
              left(v_pl->>'street', 200), left(v_pl->>'city', 120), left(v_pl->>'region', 40), left(v_pl->>'postal_code', 20),
              coalesce(v_pl->>'country', 'US'), (v_pl->>'lat')::double precision, (v_pl->>'lng')::double precision,
              left(v_pl->>'website_host', 120), (v_pl->>'website_root')::boolean, left(v_pl->>'instagram_url', 200), v_pl->>'phone_e164',
              coalesce((v_pl->>'phone_sources')::smallint, 0), coalesce((v_pl->>'phone_wrong')::boolean, false),
              v_pl->>'email', coalesce(v_pl->'email_alternates', '[]'::jsonb), coalesce(v_pl->>'email_state', 'none'),
              (v_pl->>'rating')::numeric, (v_pl->>'reviews')::integer,
              left(v_pl->>'about', 600), coalesce(v_pl->'hours', '[]'::jsonb), left(v_pl->>'image_url', 500), left(v_pl->>'price', 8),
              v_pl->'reviews_dist', left(v_pl->>'facebook_url', 300), left(v_pl->>'linkedin_url', 300), left(v_pl->>'tiktok_url', 300),
              (v_pl->>'claimed')::boolean, left(v_pl->>'maps_url', 500), (v_pl->>'rank')::integer, left(v_pl->>'neighborhood', 120), left(v_pl->>'logo_url', 500),
              -- The copy we keep (00161): its name, when it is one of ours; anything else is no copy at all.
              case when v_pl->>'mark_path' ~ '^[0-9a-f]{64}\.(png|jpg|webp|gif|ico)$' then v_pl->>'mark_path' end)
      -- A place already here keeps its worked state and gains what this listing shows where it had none (D2):
      -- these columns and nothing else, so a lead's stage, its email state and its version are untouched. Whether its
      -- website is its host's root (00237) is one of them: a lead found before it was kept learns it when found again.
      on conflict (tenant_id, place_id) where place_id is not null do update set
        about        = coalesce(public.leads.about, excluded.about),
        hours        = case when public.leads.hours = '[]'::jsonb then excluded.hours else public.leads.hours end,
        image_url    = coalesce(public.leads.image_url, excluded.image_url),
        price        = coalesce(public.leads.price, excluded.price),
        reviews_dist = coalesce(public.leads.reviews_dist, excluded.reviews_dist),
        facebook_url = coalesce(public.leads.facebook_url, excluded.facebook_url),
        linkedin_url = coalesce(public.leads.linkedin_url, excluded.linkedin_url),
        tiktok_url   = coalesce(public.leads.tiktok_url, excluded.tiktok_url),
        claimed      = coalesce(public.leads.claimed, excluded.claimed),
        maps_url     = coalesce(public.leads.maps_url, excluded.maps_url),
        rank         = coalesce(public.leads.rank, excluded.rank),
        neighborhood = coalesce(public.leads.neighborhood, excluded.neighborhood),
        logo_url     = coalesce(public.leads.logo_url, excluded.logo_url),
        mark_path    = coalesce(public.leads.mark_path, excluded.mark_path),
        website_root = coalesce(public.leads.website_root, excluded.website_root);
      select l.id into v_lead from public.leads l where l.tenant_id = v_round.tenant_id and l.place_id = v_pl->>'place_id';
    end if;
    if v_lead is null then continue; end if;
    v_class := coalesce(v_m->>'class', 'review');
    insert into public.lead_search_members (search_id, lead_id, round_id, tenant_id, judgment, class, excluded_by, fit, reason, distance_m)
    values (v_round.search_id, v_lead, v_round.id, v_round.tenant_id,
            coalesce(v_m->'judgment', '{}'::jsonb) || jsonb_build_object('shares', coalesce(v_el->'shares', '[]'::jsonb)),
            v_class, v_m->>'excluded_by', v_m->>'fit', coalesce(left(v_m->>'reason', 120), ''), (v_m->>'distance_m')::integer)
    on conflict (search_id, lead_id) do nothing;
    get diagnostics v_n = row_count;
    if v_n = 0 then continue; end if;
    if v_class = 'qualified' then
      v_qualified := v_qualified + 1;
      if v_room > 0 then
        update public.lead_search_members set counted = true, counted_month = v_month
         where search_id = v_round.search_id and lead_id = v_lead;
        v_room := v_room - 1;
        v_counted := v_counted + 1;
      end if;
    elsif v_class = 'review' then
      v_review := v_review + 1;
    else
      v_excluded := v_excluded + 1;
    end if;
  end loop;

  -- Delivery settles against the reservation (E2): the round's used grows,
  -- the month's reserved becomes used.
  if v_counted > 0 then
    update public.lead_rounds set allowance_used = allowance_used + v_counted where id = v_round.id;
    v_counter := public.lead_counter_take(v_round.tenant_id, 'allowance', v_month);
    update public.lead_counters set used = used + v_counted, reserved = greatest(reserved - v_counted, 0), updated_at = now() where id = v_counter.id;
  end if;

  -- The run's usage so far, as the provider reports it; only what is new
  -- settles.
  v_usage := (p_page->>'usage_usd')::numeric;
  if v_usage is not null and v_usage > v_run.usage_usd then
    v_delta := v_usage - v_run.usage_usd;
    perform public.lead_settle_usage(v_round.tenant_id, v_month, v_round.day, v_round.platform_day, v_delta,
      case when v_round.state = 'ended' then 0 else v_round.cost_reserved_usd - v_round.cost_usd end);
    -- An ended round is final (its trigger refuses a change): the month's counters carry a re-check's cents, the round's own cost stays what it ended at.
    if v_round.state <> 'ended' then
      update public.lead_rounds set cost_usd = cost_usd + v_delta where id = v_round.id;
    end if;
    update public.lead_runs set usage_usd = v_usage where id = p_run_id;
  end if;

  -- The offset moves (compare-and-set held above), the run's state follows
  -- the provider's, and the next collect is written once.
  update public.lead_runs
     set read_offset = p_to_offset,
         items_seen  = coalesce((p_page->>'items_seen')::integer, items_seen),
         state       = coalesce(p_page->>'run_state', state),
         finished_at = case when coalesce(p_page->>'run_state', state) in ('succeeded', 'failed', 'aborted', 'timed_out') then coalesce(finished_at, now()) else finished_at end
   where id = p_run_id;
  v_next := p_page->'next';
  if v_next is not null and jsonb_typeof(v_next) = 'object' then
    if v_next->>'kind' = 'lead_check' then
      insert into public.jobs (tenant_id, kind, due_at, payload)
      values (v_round.tenant_id, 'lead_check', now() + make_interval(secs => coalesce((v_next->>'run_after_seconds')::integer, 0)),
              jsonb_build_object('round_id', v_round.id, 'batch', coalesce((v_next->>'batch')::integer, 1)));
    else
      insert into public.jobs (tenant_id, kind, due_at, payload)
      values (v_round.tenant_id, 'lead_collect', now() + make_interval(secs => coalesce((v_next->>'run_after_seconds')::integer, 0)),
              jsonb_build_object('run_id', p_run_id, 'seq', coalesce(v_next->>'seq', 'p' || p_to_offset)))
      on conflict ((payload->>'run_id'), (payload->>'seq')) where kind = 'lead_collect' and state <> 'failed' do nothing;
    end if;
  end if;

  -- The round: a bigger target once the probe passed, the question, the
  -- pending ending, a state, or its ending (which releases and records).
  v_r := coalesce(p_page->'round', '{}'::jsonb);
  if v_r->>'target' is not null then
    update public.lead_rounds set target = greatest((v_r->>'target')::integer, target) where id = v_round.id;
  end if;
  if v_r->>'ending_pending' is not null then
    update public.lead_rounds set ending_pending = v_r->>'ending_pending' where id = v_round.id;
  end if;
  -- Where to look next, when the area ran dry (D3, 00145): written with the ending it belongs to, before the
  -- round is final.
  if v_r->'nearby' is not null and jsonb_typeof(v_r->'nearby') = 'array' then
    update public.lead_rounds set nearby = v_r->'nearby' where id = v_round.id;
  end if;
  if v_r->'question' is not null and jsonb_typeof(v_r->'question') = 'object' then
    update public.lead_rounds set question = v_r->'question', waiting_since = now() where id = v_round.id;
  end if;
  if v_r->>'ending' is not null then
    perform public.lead_round_end(v_round.id, v_r->>'ending');
  elsif v_r->>'state' is not null and v_r->>'state' <> v_round.state then
    update public.lead_rounds
       set state = v_r->>'state', started_at = coalesce(started_at, now())
     where id = v_round.id;
    insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
    values (v_round.tenant_id, 'lead.round', 'lead', 'lead_round', v_round.id,
            jsonb_build_object('search_id', v_round.search_id, 'seq', v_round.seq, 'state', v_r->>'state'));
  end if;
  select state into v_state from public.lead_rounds where id = v_round.id;
  return jsonb_build_object('ok', true, 'counted', v_counted, 'qualified', v_qualified, 'review', v_review, 'excluded', v_excluded, 'round_state', v_state);
end $_$;


--
-- Name: FUNCTION lead_collect_commit(p_run_id uuid, p_owner text, p_gen integer, p_from_offset integer, p_to_offset integer, p_page jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_collect_commit(p_run_id uuid, p_owner text, p_gen integer, p_from_offset integer, p_to_offset integer, p_page jsonb) IS 'One page of one run, in one transaction (E4). Refuses {ok:false, why} on a stale lease, a wrong offset or an ended round (a check run, which decides nothing, may still commit after the round ended: Check again, 00145). Keeps judgments by op_id, inserts leads (once per place id) and members (once per search), counts Qualified members up to the round''s reservation, settles usage, advances the offset, writes the next job once, moves the round, appends the events. Replayed with the same offset it does nothing twice; replayed after the offset moved it is refused.';


--
-- Name: lead_convert_by(uuid, uuid, text, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_convert_by(p_tenant_id uuid, p_lead_id uuid, p_how text, p_data jsonb DEFAULT NULL::jsonb, p_any_stage boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_lead public.leads%rowtype;
begin
  if p_how is null or p_how not in ('call', 'reply', 'booking', 'deal') then
    raise exception 'how must be call, reply, booking or deal' using errcode = '22023';
  end if;
  update public.leads l
     set stage        = 'converted',
         closed_reason = null,
         converted_at = coalesce(l.converted_at, now()),
         contacted_at = coalesce(l.contacted_at, now()),
         version      = l.version + 1
   where l.id = p_lead_id and l.tenant_id = p_tenant_id
     and l.erased_at is null and l.blanked_at is null
     and (l.stage in ('ready', 'nurture') or coalesce(p_any_stage, false))
  returning * into v_lead;
  if not found then
    return jsonb_build_object('moved', false, 'version',
      (select l.version from public.leads l where l.id = p_lead_id and l.tenant_id = p_tenant_id));
  end if;
  -- The door's own fact is written last, so no data handed in can say another way.
  insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
  values (p_tenant_id, 'lead.converted', 'lead', 'lead', p_lead_id,
          coalesce(p_data, '{}'::jsonb) || jsonb_build_object('how', p_how));
  return jsonb_build_object('moved', true, 'version', v_lead.version);
end $$;


--
-- Name: FUNCTION lead_convert_by(p_tenant_id uuid, p_lead_id uuid, p_how text, p_data jsonb, p_any_stage boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_convert_by(p_tenant_id uuid, p_lead_id uuid, p_how text, p_data jsonb, p_any_stage boolean) IS 'A lead''s conversion, written once for the doors that convert (Reach out Part 5, G19; lead_link_contact still converts on its own): a ready or nurture lead (any, with p_any_stage) becomes converted, closed_reason null, converted_at and contacted_at kept or now, version + 1, with lead.converted {how} and what the caller adds. how is call, reply, booking or deal. Answers {moved, version}. Called only by definer doors; nobody holds EXECUTE.';


--
-- Name: lead_counters; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lead_counters (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid,
    kind text NOT NULL,
    period text NOT NULL,
    used numeric(10,4) DEFAULT 0 NOT NULL,
    reserved numeric(10,4) DEFAULT 0 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT lead_counters_check CHECK (((kind = 'day'::text) OR (tenant_id IS NOT NULL))),
    CONSTRAINT lead_counters_check1 CHECK (
CASE kind
    WHEN 'day'::text THEN (period ~ '^\d{4}-\d{2}-\d{2}$'::text)
    ELSE (period ~ '^\d{4}-\d{2}$'::text)
END),
    CONSTRAINT lead_counters_kind_check CHECK ((kind = ANY (ARRAY['allowance'::text, 'budget'::text, 'day'::text]))),
    CONSTRAINT lead_counters_reserved_check CHECK ((reserved >= (0)::numeric)),
    CONSTRAINT lead_counters_used_check CHECK ((used >= (0)::numeric))
);


--
-- Name: TABLE lead_counters; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.lead_counters IS 'The month''s allowance (Qualified leads) and searching budget (usd) per workspace, and the day''s spend per workspace and for the platform (tenant_id null). Locked for update in one fixed order, allowance, budget, day, platform, inside one door, never across a provider or model call (E2).';


--
-- Name: lead_counter_take(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_counter_take(p_tenant_id uuid, p_kind text, p_period text) RETURNS public.lead_counters
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v public.lead_counters;
begin
  insert into public.lead_counters (tenant_id, kind, period) values (p_tenant_id, p_kind, p_period)
  on conflict (tenant_id, kind, period) do nothing;
  select * into v from public.lead_counters
   where tenant_id is not distinct from p_tenant_id and kind = p_kind and period = p_period
   for update;
  return v;
end $$;


--
-- Name: FUNCTION lead_counter_take(p_tenant_id uuid, p_kind text, p_period text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_counter_take(p_tenant_id uuid, p_kind text, p_period text) IS 'The counter row for a period, made if missing and locked for update. Callers take rows in one order only: allowance, budget, the workspace''s day, the platform''s day (E2).';


--
-- Name: lead_day(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_day(p_tenant_id uuid, p_at timestamp with time zone DEFAULT now()) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select to_char(p_at at time zone coalesce((select t.timezone from public.tenants t where t.id = p_tenant_id), 'UTC'), 'YYYY-MM-DD')
$$;


--
-- Name: FUNCTION lead_day(p_tenant_id uuid, p_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_day(p_tenant_id uuid, p_at timestamp with time zone) IS 'The workspace''s calendar day of an instant, YYYY-MM-DD, in its zone; the platform''s day (tenant null) is UTC. The period of the day counters.';


--
-- Name: lead_erase(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_erase(p_lead_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user uuid := auth.uid();
  v_lead public.leads%rowtype;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  select * into v_lead from public.leads where id = p_lead_id for update;
  if not found or not exists (select 1 from public.memberships m where m.tenant_id = v_lead.tenant_id and m.user_id = v_user) then
    raise exception 'Lead not found.' using errcode = 'P0002';
  end if;
  if not exists (select 1 from public.memberships m where m.tenant_id = v_lead.tenant_id and m.user_id = v_user and m.role = 'owner') then
    raise exception 'Only an owner can erase a lead.' using errcode = '42501';
  end if;
  if v_lead.erased_at is not null then
    -- Idempotent: a second request is answered, not re-executed.
    return jsonb_build_object('erased', true, 'already', true);
  end if;
  -- The tombstones first, exactly as an erased person's leads are hashed
  -- (00140 leads_erase_on_contact), so no search ever finds this place, this
  -- number or this address again (§0.4).
  if v_lead.place_id is not null then
    insert into public.lead_suppressions (tenant_id, kind, hash, what)
    values (v_lead.tenant_id, 'place', public.lead_suppression_hash(v_lead.tenant_id, v_lead.place_id), 'erased')
    on conflict (tenant_id, kind, hash) do nothing;
  end if;
  if v_lead.phone_e164 is not null then
    insert into public.lead_suppressions (tenant_id, kind, hash, what)
    values (v_lead.tenant_id, 'phone', public.lead_suppression_hash(v_lead.tenant_id, v_lead.phone_e164), 'erased')
    on conflict (tenant_id, kind, hash) do nothing;
  end if;
  if v_lead.email is not null then
    insert into public.lead_suppressions (tenant_id, kind, hash, what)
    values (v_lead.tenant_id, 'email', public.lead_suppression_hash(v_lead.tenant_id, v_lead.email), 'erased')
    on conflict (tenant_id, kind, hash) do nothing;
  end if;
  perform public.lead_blank(p_lead_id);
  update public.leads set erased_at = now(), version = version + 1 where id = p_lead_id;
  -- No operation row: this one is final.
  return jsonb_build_object('erased', true, 'already', false);
end $$;


--
-- Name: FUNCTION lead_erase(p_lead_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_erase(p_lead_id uuid) IS 'Owner. Erases one lead for good: the place, the number and the address are hashed onto lead_suppressions as erased first, so no search finds them again (§0.4), then lead_blank takes everything that names or reaches the place and erased_at is set. No operation row, because nothing undoes it. Idempotent.';


--
-- Name: lead_export_mark(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_export_mark(p_tenant_id uuid, p_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user uuid := auth.uid();
  v_n    integer;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  if p_tenant_id is null or not public.has_permission(v_user, p_tenant_id, 'export') then
    raise exception 'Workspace not found.' using errcode = 'P0002';
  end if;
  update public.leads
     set exported_at = now()
   where tenant_id = p_tenant_id and id = any (coalesce(p_ids, '{}'::uuid[]))
     and exported_at is null and erased_at is null and blanked_at is null;
  get diagnostics v_n = row_count;
  return v_n;
end $$;


--
-- Name: FUNCTION lead_export_mark(p_tenant_id uuid, p_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_export_mark(p_tenant_id uuid, p_ids uuid[]) IS 'Owner (permission export). Stamps exported_at on the leads a download took, once each, and answers how many it marked. An exported lead keeps its charge when a removed search is undone (E9).';


--
-- Name: lead_in_list(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_in_list(p_stage text, p_closed_reason text, p_list text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select coalesce(case coalesce(p_list, 'all')
    when 'all'       then true
    when 'ready'     then p_stage = 'ready'
    when 'nurture'   then p_stage = 'nurture'
    when 'converted' then p_stage = 'converted'
    when 'said_no'   then p_stage = 'archived' and p_closed_reason = 'said_no'
    when 'not_a_fit' then p_stage = 'archived' and p_closed_reason in ('not_a_fit', 'customer')
    else false
  end, false)
$$;


--
-- Name: FUNCTION lead_in_list(p_stage text, p_closed_reason text, p_list text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_in_list(p_stage text, p_closed_reason text, p_list text) IS 'The rail''s lists as one rule (§6.1): all, ready, nurture (Contacted), converted (Talking), said_no, not_a_fit (which holds "Already a customer" too). leads_page, lead_list_counts and lead_bulk all ask it, so the lists cannot drift apart.';


--
-- Name: lead_link_contact(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_link_contact() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_lead uuid;
begin
  begin
    if current_setting('chanlytics.link_lead', true) = 'off' then return null; end if;
    if auth.uid() is not null then return null; end if;
    if NEW.erased_at is not null or NEW.merged_into_contact_id is not null then return null; end if;
    if NEW.phone_e164 is null and NEW.email is null then return null; end if;
    -- Two guarded single-column lookups, never one OR over two nullable
    -- parameters: this runs on EVERY contacts insert (the inbound hot path),
    -- and an OR of two nullable parameters plans as a sequential scan over
    -- leads. Each lookup reaches its own index (leads_tenant_phone,
    -- leads_tenant_email); the number is tried first, being the stronger
    -- identity.
    if NEW.phone_e164 is not null then
      select l.id into v_lead from public.leads l
       where l.tenant_id = NEW.tenant_id and l.phone_e164 = NEW.phone_e164
         and l.contact_id is null and l.erased_at is null and l.blanked_at is null
       order by l.found_at desc
       limit 1;
    end if;
    if v_lead is null and NEW.email is not null then
      select l.id into v_lead from public.leads l
       where l.tenant_id = NEW.tenant_id and l.email = NEW.email
         and l.contact_id is null and l.erased_at is null and l.blanked_at is null
       order by l.found_at desc
       limit 1;
    end if;
    if v_lead is null then return null; end if;
    update public.leads
       set contact_id = NEW.id, stage = 'converted', closed_reason = null, converted_at = now(), contacted_at = coalesce(contacted_at, now())
     where id = v_lead;
    if not exists (select 1 from public.events e where e.tenant_id = NEW.tenant_id and e.subject_type = 'contact' and e.subject_id = NEW.id and e.kind = 'contact.added') then
      insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
      values (NEW.tenant_id, 'contact.added', 'contact', 'contact', NEW.id, jsonb_build_object('source', 'lead'));
    end if;
  exception when others then
    raise warning 'lead_link_contact: %', sqlerrm;
  end;
  return null;
end $$;


--
-- Name: FUNCTION lead_link_contact(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_link_contact() IS 'A person the edge makes from a message or a call, whose number or address a lead holds, links that lead and converts it; the event that says where they came from reads "a lead you found". A signed-in caller''s insert never links.';


--
-- Name: lead_list_counts(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_list_counts(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with mine as (
    select distinct l.id, l.stage, l.closed_reason
      from public.lead_search_members m
      join public.leads l on l.id = m.lead_id
     where m.tenant_id = p_tenant_id and m.class = 'qualified' and m.counted
       and m.blanked_at is null and l.blanked_at is null and l.erased_at is null
  )
  select jsonb_build_object(
    'all',       count(*),
    'ready',     count(*) filter (where public.lead_in_list(stage, closed_reason, 'ready')),
    'nurture',   count(*) filter (where public.lead_in_list(stage, closed_reason, 'nurture')),
    'converted', count(*) filter (where public.lead_in_list(stage, closed_reason, 'converted')),
    'said_no',   count(*) filter (where public.lead_in_list(stage, closed_reason, 'said_no')),
    'not_a_fit', count(*) filter (where public.lead_in_list(stage, closed_reason, 'not_a_fit'))
  ) from mine
$$;


--
-- Name: FUNCTION lead_list_counts(p_tenant_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_list_counts(p_tenant_id uuid) IS 'The six numbers under Leads in the rail: every lead the workspace owns (a qualified membership that counted, not blanked, not erased) and the five stage lists over them, counted once per lead however many searches found it. Never over an erased or blanked row. all is the total, not the sum: a lead closed stale or search_removed is in All and in no other list.';


--
-- Name: lead_member_exclude(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_member_exclude(p_search_id uuid, p_lead_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ select public.lead_member_move(p_search_id, p_lead_id, 'exclude') $$;


--
-- Name: FUNCTION lead_member_exclude(p_search_id uuid, p_lead_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_member_exclude(p_search_id uuid, p_lead_id uuid) IS 'Owner (permission find). A member in review is excluded by the owner; free. Returns {op_id, version}.';


--
-- Name: lead_member_keep(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_member_keep(p_search_id uuid, p_lead_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ select public.lead_member_move(p_search_id, p_lead_id, 'keep') $$;


--
-- Name: FUNCTION lead_member_keep(p_search_id uuid, p_lead_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_member_keep(p_search_id uuid, p_lead_id uuid) IS 'Owner (permission find). A member in review, or qualified and not yet counted, is kept: Qualified, counted this month through the allowance ({error: month_leads_used} when none is left). Returns {op_id, version}.';


--
-- Name: lead_member_move(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_member_move(p_search_id uuid, p_lead_id uuid, p_kind text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user    uuid := auth.uid();
  s         public.lead_searches;
  m         public.lead_search_members;
  l         public.leads;
  v_month   text;
  v_counter public.lead_counters;
  v_before  jsonb;
  v_after   jsonb;
  v_op      uuid;
  v_counts  boolean := false;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  select * into s from public.lead_searches where id = p_search_id;
  if not found or not public.has_permission(v_user, s.tenant_id, 'find') then
    raise exception 'Search not found.' using errcode = 'P0002';
  end if;
  -- A removed search charges nobody: Keep and Put back each spend a lead of
  -- the month's allowance, and its members are blanked. lead_search_more says
  -- the same word.
  if s.removed_at is not null then
    return jsonb_build_object('error', 'removed');
  end if;
  select * into m from public.lead_search_members where search_id = p_search_id and lead_id = p_lead_id for update;
  if not found then
    return jsonb_build_object('error', 'not_found');
  end if;
  select * into l from public.leads where id = p_lead_id;
  if m.blanked_at is not null or l.blanked_at is not null or l.erased_at is not null then
    return jsonb_build_object('error', 'hidden');
  end if;
  v_before := jsonb_build_object('class', m.class, 'excluded_by', m.excluded_by, 'counted', m.counted, 'counted_month', m.counted_month, 'kept_at', m.kept_at, 'kept_by', m.kept_by);

  if p_kind = 'exclude' then
    if m.class <> 'review' then
      return jsonb_build_object('error', 'state', 'class', m.class);
    end if;
    update public.lead_search_members
       set class = 'excluded', excluded_by = 'owner', kept_at = null, kept_by = null, version = version + 1
     where id = m.id
    returning * into m;
  else
    if p_kind = 'put_back' then
      if m.class <> 'excluded' then
        return jsonb_build_object('error', 'state', 'class', m.class);
      end if;
      -- Neither Put back nor Keep revives a suppression or an out-of-area place (§0.1).
      if l.place_id is null or exists (select 1 from public.lead_suppressions x where x.tenant_id = s.tenant_id and x.kind = 'place'
                    and x.what in ('customer', 'erased') and x.hash = public.lead_suppression_hash(s.tenant_id, l.place_id)) then
        return jsonb_build_object('error', 'hidden');
      end if;
      if m.judgment->'reasons' ? 'out_of_area' then
        return jsonb_build_object('error', 'out_of_area');
      end if;
    elsif not (m.class = 'review' or (m.class = 'qualified' and not m.counted)) then
      return jsonb_build_object('error', 'state', 'class', m.class);
    end if;
    -- Keep and Put back count, through the month's allowance (§0.2).
    if not m.counted then
      v_month := public.lead_month(s.tenant_id, now());
      v_counter := public.lead_counter_take(s.tenant_id, 'allowance', v_month);
      if v_counter.used + v_counter.reserved + 1 > public.lead_cap('month_leads') then
        return jsonb_build_object('error', 'month_leads_used', 'left', 0,
          'sentence', 'You have found this month''s ' || public.lead_cap('month_leads') || ' leads. Your leads renew on ' || public.lead_renews_on(s.tenant_id) || '.');
      end if;
      update public.lead_counters set used = used + 1, updated_at = now() where id = v_counter.id;
      v_counts := true;
    end if;
    update public.lead_search_members
       set class = 'qualified', excluded_by = null,
           counted = true, counted_month = coalesce(counted_month, v_month),
           kept_at = now(), kept_by = v_user, version = version + 1
     where id = m.id
    returning * into m;
  end if;

  v_after := jsonb_build_object('class', m.class, 'excluded_by', m.excluded_by, 'counted', m.counted, 'counted_month', m.counted_month, 'kept_at', m.kept_at, 'kept_by', m.kept_by);
  insert into public.lead_operations (tenant_id, kind, search_id, lead_ids, before, after, version, by)
  values (s.tenant_id, p_kind, p_search_id, array[p_lead_id], v_before, v_after, m.version, v_user)
  returning id into v_op;
  return jsonb_build_object('op_id', v_op, 'version', m.version, 'counted', v_counts);
end $$;


--
-- Name: FUNCTION lead_member_move(p_search_id uuid, p_lead_id uuid, p_kind text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_member_move(p_search_id uuid, p_lead_id uuid, p_kind text) IS 'The body of lead_member_keep, lead_member_exclude and lead_member_put_back: the state each expects, the change, the allowance when it counts, and one lead_operations row with the member''s new version. {error: removed} on a search that was removed, as lead_search_more says it.';


--
-- Name: lead_member_of(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_member_of(p_tenant_id uuid, p_lead_id uuid, p_search_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select to_jsonb(x)
    from (
      select m.id, m.lead_id, m.search_id, m.class, m.excluded_by, m.fit, m.reason, m.distance_m, m.counted, m.judgment
        from public.lead_search_members m
       where m.tenant_id = p_tenant_id
         and m.lead_id = p_lead_id
         and (p_search_id is null or m.search_id = p_search_id)
         and m.blanked_at is null
         and public.lead_member_shown(m.class, m.counted)
       order by m.created_at desc, m.id desc
       limit 1
    ) x
$$;


--
-- Name: FUNCTION lead_member_of(p_tenant_id uuid, p_lead_id uuid, p_search_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_member_of(p_tenant_id uuid, p_lead_id uuid, p_search_id uuid) IS 'The membership of one lead the Leads page would show (lead_member_shown, not blanked): the one in p_search_id when it names one, else the newest; null when there is none. Under the caller''s row security. GET leads/[id] reads it (00212).';


--
-- Name: lead_member_put_back(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_member_put_back(p_search_id uuid, p_lead_id uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ select public.lead_member_move(p_search_id, p_lead_id, 'put_back') $$;


--
-- Name: FUNCTION lead_member_put_back(p_search_id uuid, p_lead_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_member_put_back(p_search_id uuid, p_lead_id uuid) IS 'Owner (permission find). An excluded member goes back through keep''s path and counts; refused for a hidden place ({error: hidden}: a customer or an erasure) and for one outside the area ({error: out_of_area}). Returns {op_id, version}.';


--
-- Name: lead_member_shown(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_member_shown(p_class text, p_counted boolean) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select p_class <> 'qualified' or p_counted
$$;


--
-- Name: FUNCTION lead_member_shown(p_class text, p_counted boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_member_shown(p_class text, p_counted boolean) IS 'Whether the Leads page shows a membership of this class: every review and excluded one, and a qualified one once it is counted. leads_page and lead_member_of both ask it, so the list and the peek cannot disagree (00212).';


--
-- Name: lead_month(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_month(p_tenant_id uuid, p_at timestamp with time zone DEFAULT now()) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select to_char(p_at at time zone t.timezone, 'YYYY-MM') from public.tenants t where t.id = p_tenant_id
$$;


--
-- Name: FUNCTION lead_month(p_tenant_id uuid, p_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_month(p_tenant_id uuid, p_at timestamp with time zone) IS 'The workspace''s calendar month of an instant, YYYY-MM, in tenants.timezone: the month a lead counts in and the allowance renews on (15). contracts'' leadMonth() says the same.';


--
-- Name: lead_month_used(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_month_used(p_tenant_id uuid, p_period text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user uuid := auth.uid();
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  -- Finding is the owner's alone (ROLE_PERMS.find), so what finding has left
  -- this month is the owner's to read too: the card is the only reader.
  if not public.has_permission(v_user, p_tenant_id, 'find') then
    raise exception 'Only an owner can find businesses for you.' using errcode = '42501';
  end if;
  return (
    select jsonb_object_agg(k.kind, jsonb_build_object(
             'used',     coalesce(c.used, 0),
             'reserved', coalesce(c.reserved, 0)
           ))
      from (values ('allowance'), ('budget')) as k(kind)
      left join public.lead_counters c
        on c.tenant_id = p_tenant_id and c.kind = k.kind and c.period = p_period
  );
end;
$$;


--
-- Name: FUNCTION lead_month_used(p_tenant_id uuid, p_period text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_month_used(p_tenant_id uuid, p_period text) IS 'What this workspace has used and reserved of the month''s two ceilings, as {allowance: {used, reserved}, budget: {used, reserved}} -- leads for the allowance, US dollars for the budget. A month nothing has spent in answers zeros rather than nothing, so the plan card never guesses at a missing row. The whole of each ceiling is contracts'' (LEAD_MONTHLY_ALLOWANCE, LEAD_MONTHLY_BUDGET_USD) and the card subtracts. The owner''s alone, like finding itself; the platform''s own day counter (tenant_id null) is never reachable through it.';


--
-- Name: lead_name_key(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_name_key(p_name text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$ select nullif(btrim(regexp_replace(lower(coalesce(p_name, '')), '[^a-z0-9]+', ' ', 'g')), '') $$;


--
-- Name: lead_niche_prior(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_niche_prior(p_category_key text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object('places', n.places, 'matched', n.matched, 'with_email', n.with_email)
    from public.lead_niche_priors n where n.category_key = p_category_key
$$;


--
-- Name: FUNCTION lead_niche_prior(p_category_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_niche_prior(p_category_key text) IS 'The platform-wide prior for a kind of business ({places, matched, with_email}), or null when the kind was never searched. Aggregates only.';


--
-- Name: lead_plan_check(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_plan_check(p_plan jsonb) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
declare
  v jsonb;
begin
  if p_plan is null or jsonb_typeof(p_plan) <> 'object' then raise exception 'plan: an object' using errcode = '22023'; end if;
  if p_plan->>'card' is null then raise exception 'plan.card' using errcode = '22023'; end if;
  if coalesce(char_length(p_plan->>'name'), 0) not between 2 and 80 then raise exception 'plan.name' using errcode = '22023'; end if;
  if coalesce(char_length(p_plan->>'asked'), 0) not between 1 and 400 then raise exception 'plan.asked' using errcode = '22023'; end if;
  if jsonb_typeof(p_plan->'terms') <> 'array' or jsonb_array_length(p_plan->'terms') not between 1 and 5 then raise exception 'plan.terms' using errcode = '22023'; end if;
  -- The same phrase twice is a term asked for nothing, and it is the provider
  -- who is asked twice. Case does not make a second phrase.
  if (select count(distinct lower(btrim(t))) from jsonb_array_elements_text(p_plan->'terms') t) <> jsonb_array_length(p_plan->'terms') then
    raise exception 'plan.terms' using errcode = '22023';
  end if;
  if jsonb_typeof(p_plan->'area') <> 'object' or p_plan->'area'->>'label' is null
     or p_plan->'area'->>'kind' not in ('zip', 'city', 'radius')
     or (jsonb_typeof(p_plan->'area'->'center') <> 'null' and (p_plan->'area'->'center'->>'lat' is null or p_plan->'area'->'center'->>'lng' is null)) then
    raise exception 'plan.area' using errcode = '22023';
  end if;
  -- A radius is drawn around a point, so it brings one. A ZIP ask may still
  -- arrive without a centre: release A2 derives it from the ZCTA table, and a
  -- city may wait for its own. LeadSearchPlanSchema says exactly this, and the
  -- door is the floor: it is granted to authenticated, so a plan that reaches
  -- it without the route must be held to the same rule.
  if p_plan->'area'->>'kind' = 'radius' and coalesce(jsonb_typeof(p_plan->'area'->'center'), 'null') = 'null' then
    raise exception 'plan.area.center' using errcode = '22023';
  end if;
  -- A whole number of metres, between the smallest area worth a run and the
  -- largest the provider takes.
  if jsonb_typeof(p_plan->'area'->'radius_m') <> 'number' or p_plan->'area'->>'radius_m' !~ '^\d+$'
     or (p_plan->'area'->>'radius_m')::integer not between 500 and 200000 then
    raise exception 'plan.area.radius_m' using errcode = '22023';
  end if;
  -- A real state or DC: the fifty and one LeadSearchPlanSchema holds. Two
  -- capitals are not a place.
  if p_plan->'area'->>'state' not in (
    'AL', 'AK', 'AZ', 'AR', 'CA', 'CO', 'CT', 'DE', 'DC', 'FL', 'GA', 'HI', 'ID', 'IL', 'IN', 'IA', 'KS', 'KY', 'LA', 'ME', 'MD',
    'MA', 'MI', 'MN', 'MS', 'MO', 'MT', 'NE', 'NV', 'NH', 'NJ', 'NM', 'NY', 'NC', 'ND', 'OH', 'OK', 'OR', 'PA', 'RI', 'SC',
    'SD', 'TN', 'TX', 'UT', 'VT', 'VA', 'WA', 'WV', 'WI', 'WY') then
    raise exception 'plan.area.state' using errcode = '22023';
  end if;
  -- The words the provider is actually given for the area.
  if coalesce(char_length(btrim(p_plan->'area'->>'query')), 0) not between 2 and 120 then
    raise exception 'plan.area.query' using errcode = '22023';
  end if;
  -- A ZIP ask needs its ZIP: A2 derives the centre from it.
  if p_plan->'area'->>'kind' = 'zip' and coalesce(p_plan->'area'->>'zip', '') !~ '^\d{5}$' then
    raise exception 'plan.area.zip' using errcode = '22023';
  end if;
  if coalesce((p_plan->>'count')::integer, 0) not between 1 and 1000 then raise exception 'plan.count' using errcode = '22023'; end if;
  if p_plan->>'contact' not in ('phone', 'email') then raise exception 'plan.contact' using errcode = '22023'; end if;
  if jsonb_typeof(p_plan->'criteria') <> 'array' or jsonb_array_length(p_plan->'criteria') > 8 then raise exception 'plan.criteria' using errcode = '22023'; end if;
  for v in select * from jsonb_array_elements(p_plan->'criteria') loop
    if v->>'key' !~ '^[a-z][a-z0-9_]{0,39}$' or v->>'text' is null or v->>'standard' not in ('likely', 'seen') or jsonb_typeof(v->'required') <> 'boolean' then
      raise exception 'plan.criteria[]' using errcode = '22023';
    end if;
  end loop;
  if jsonb_typeof(p_plan->'exclusions') <> 'array' or jsonb_array_length(p_plan->'exclusions') > 8 then raise exception 'plan.exclusions' using errcode = '22023'; end if;
  for v in select * from jsonb_array_elements(p_plan->'exclusions') loop
    if v->>'key' !~ '^[a-z][a-z0-9_]{0,39}$' or v->>'text' is null or v->>'origin' not in ('claude', 'you_said') then
      raise exception 'plan.exclusions[]' using errcode = '22023';
    end if;
  end loop;
  -- Every criterion and every exclusion has a key of its own, across both:
  -- the judge answers by key, so two of a name is one answer lost.
  if (select count(distinct x.k) from (
        select v2->>'key' as k from jsonb_array_elements(p_plan->'criteria') v2
        union all
        select v2->>'key' from jsonb_array_elements(p_plan->'exclusions') v2) x)
     <> jsonb_array_length(p_plan->'criteria') + jsonb_array_length(p_plan->'exclusions') then
    raise exception 'plan.criteria[].key' using errcode = '22023';
  end if;
end $_$;


--
-- Name: FUNCTION lead_plan_check(p_plan jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_plan_check(p_plan jsonb) IS 'Raises 22023 naming the key when a plan is not the shape LeadSearchPlanSchema describes: the same rules, including at most five terms and no phrase twice, at most eight criteria and eight exclusions with a key each, a radius of 500 to 200000 metres with a centre to draw it around, a real state, the area''s query, and a ZIP for a ZIP ask. The door is granted to authenticated, so this is what a plan is held to when the route is stepped around.';


--
-- Name: lead_release(uuid, text, text, text, integer, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_release(p_tenant_id uuid, p_month text, p_day text, p_platform_day text, p_leads integer, p_usd numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v public.lead_counters;
begin
  v := public.lead_counter_take(p_tenant_id, 'allowance', p_month);
  update public.lead_counters set reserved = greatest(reserved - p_leads, 0), updated_at = now() where id = v.id;
  v := public.lead_counter_take(p_tenant_id, 'budget', p_month);
  update public.lead_counters set reserved = greatest(reserved - p_usd, 0), updated_at = now() where id = v.id;
  v := public.lead_counter_take(p_tenant_id, 'day', p_day);
  update public.lead_counters set reserved = greatest(reserved - p_usd, 0), updated_at = now() where id = v.id;
  v := public.lead_counter_take(null, 'day', p_platform_day);
  update public.lead_counters set reserved = greatest(reserved - p_usd, 0), updated_at = now() where id = v.id;
end $$;


--
-- Name: FUNCTION lead_release(p_tenant_id uuid, p_month text, p_day text, p_platform_day text, p_leads integer, p_usd numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_release(p_tenant_id uuid, p_month text, p_day text, p_platform_day text, p_leads integer, p_usd numeric) IS 'Gives back what a round reserved and did not use, to the four rows it took from -- the round''s own month, day and platform_day -- in the same lock order as lead_reserve. Never below zero.';


--
-- Name: lead_renews_on(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_renews_on(p_tenant_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select to_char(date_trunc('month', now() at time zone t.timezone) + interval '1 month', 'Mon FMDD') from public.tenants t where t.id = p_tenant_id
$$;


--
-- Name: FUNCTION lead_renews_on(p_tenant_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_renews_on(p_tenant_id uuid) IS 'The first day of the workspace''s next calendar month, as the sentence says it: "Oct 1".';


--
-- Name: lead_reserve(uuid, text, text, text, integer, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_reserve(p_tenant_id uuid, p_month text, p_day text, p_platform_day text, p_leads integer, p_usd numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_allowance public.lead_counters;
  v_budget    public.lead_counters;
  v_day       public.lead_counters;
  v_platform  public.lead_counters;
  v_left      numeric;
begin
  v_allowance := public.lead_counter_take(p_tenant_id, 'allowance', p_month);
  if v_allowance.used + v_allowance.reserved + p_leads > public.lead_cap('month_leads') then
    v_left := greatest(public.lead_cap('month_leads') - v_allowance.used - v_allowance.reserved, 0);
    return jsonb_build_object('error', 'month_leads_used', 'left', v_left::integer,
      'sentence', case when v_left <= 0
        then 'You have found this month''s ' || public.lead_cap('month_leads') || ' leads. Your leads renew on ' || public.lead_renews_on(p_tenant_id) || '.'
        else 'You have ' || v_left::integer || ' leads left this month. Find ' || v_left::integer || ' now, or all ' || p_leads || ' when your leads renew on ' || public.lead_renews_on(p_tenant_id) || '?' end);
  end if;
  v_budget := public.lead_counter_take(p_tenant_id, 'budget', p_month);
  if v_budget.used + v_budget.reserved + p_usd > public.lead_cap('month_usd') then
    v_left := greatest(public.lead_cap('month_usd') - v_budget.used - v_budget.reserved, 0);
    return jsonb_build_object('error', 'budget_used', 'left_usd', v_left,
      'sentence', 'This month''s searching is nearly used up. Try a smaller search, or a phone standard; it renews on ' || public.lead_renews_on(p_tenant_id) || '.');
  end if;
  v_day := public.lead_counter_take(p_tenant_id, 'day', p_day);
  if v_day.used + v_day.reserved + p_usd > public.lead_cap('day_usd') then
    return jsonb_build_object('error', 'day_cap', 'sentence', 'Today''s searching is used up. Try again tomorrow.');
  end if;
  v_platform := public.lead_counter_take(null, 'day', p_platform_day);
  if v_platform.used + v_platform.reserved + p_usd > public.lead_cap('platform_day_usd') then
    return jsonb_build_object('error', 'day_cap', 'sentence', 'Searching is busy today. Try again tomorrow.');
  end if;
  update public.lead_counters set reserved = reserved + p_leads, updated_at = now() where id = v_allowance.id;
  update public.lead_counters set reserved = reserved + p_usd,   updated_at = now() where id = v_budget.id;
  update public.lead_counters set reserved = reserved + p_usd,   updated_at = now() where id = v_day.id;
  update public.lead_counters set reserved = reserved + p_usd,   updated_at = now() where id = v_platform.id;
  return null;
end $$;


--
-- Name: FUNCTION lead_reserve(p_tenant_id uuid, p_month text, p_day text, p_platform_day text, p_leads integer, p_usd numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_reserve(p_tenant_id uuid, p_month text, p_day text, p_platform_day text, p_leads integer, p_usd numeric) IS 'Reserves p_leads from the month''s allowance and p_usd from the month''s budget, the workspace''s day and the platform''s day (the UTC day p_platform_day, which the round stores), each cap lead_cap''s (00272), in that lock order; null when reserved, else {error, sentence} naming the cap that binds (§0.2, §13.3).';


--
-- Name: lead_round_answer(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_round_answer(p_round_id uuid, p_answer text, p_plan jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user  uuid := auth.uid();
  r       public.lead_rounds;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  if p_answer not in ('keep', 'include', 'stop') then
    raise exception 'answer is keep, include or stop' using errcode = '22023';
  end if;
  select * into r from public.lead_rounds where id = p_round_id for update;
  if not found or not public.has_permission(v_user, r.tenant_id, 'find') then
    raise exception 'Round not found.' using errcode = 'P0002';
  end if;
  if r.state <> 'waiting_on_owner' then
    return jsonb_build_object('error', 'state', 'state', r.state);
  end if;
  if p_answer = 'stop' then
    update public.lead_rounds set answered = 'stop' where id = p_round_id;
    perform public.lead_round_end(p_round_id, 'stopped');
    return jsonb_build_object('round_id', p_round_id, 'state', 'ended');
  end if;
  if p_answer = 'include' then
    if p_plan is null then
      raise exception 'include carries the amended plan' using errcode = '22023';
    end if;
    perform public.lead_plan_check(p_plan);
    if coalesce((p_plan->>'version')::integer, 0) <> r.plan_version + 1 then
      raise exception 'the amended plan is version %', r.plan_version + 1 using errcode = '22023';
    end if;
    update public.lead_searches set plan = p_plan where id = r.search_id;
    update public.lead_rounds set plan = p_plan, plan_version = r.plan_version + 1 where id = p_round_id;
  end if;
  update public.lead_rounds
     set state = 'running', answered = p_answer, waiting_since = null,
         target = greatest(target, (coalesce(p_plan, r.plan)->>'count')::integer)
   where id = p_round_id;
  insert into public.jobs (tenant_id, kind, due_at, payload)
  values (r.tenant_id, 'lead_round_start', now(), jsonb_build_object('round_id', p_round_id, 'resume', true));
  insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
  values (r.tenant_id, 'lead.round', 'lead', 'lead_round', p_round_id,
          jsonb_build_object('search_id', r.search_id, 'seq', r.seq, 'state', 'running', 'answered', p_answer, 'by', v_user));
  return jsonb_build_object('round_id', p_round_id, 'state', 'running');
end $$;


--
-- Name: FUNCTION lead_round_answer(p_round_id uuid, p_answer text, p_plan jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_round_answer(p_round_id uuid, p_answer text, p_plan jsonb) IS 'Owner answers the question after 25 on a round waiting on them. keep: the round runs on (a resume job for the same round); include: the amended plan (version + 1) is stored on the search and the round, then as keep; stop: the round ends stopped. {error: state} when the round is not waiting.';


--
-- Name: lead_round_end(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_round_end(p_round_id uuid, p_ending text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  r public.lead_rounds;
begin
  if p_ending not in ('target_reached', 'searched_everything', 'month_leads_used', 'budget_used', 'few_new_matches', 'stopped', 'source_failed', 'question_unanswered', 'paused') then
    raise exception 'not one of the nine endings: %', p_ending using errcode = '22023';
  end if;
  select * into r from public.lead_rounds where id = p_round_id for update;
  if not found or r.state = 'ended' then
    return false;
  end if;
  update public.lead_rounds
     set state = 'ended', ending = p_ending, ended_at = now(), waiting_since = null
   where id = p_round_id;
  perform public.lead_release(r.tenant_id, r.month, r.day, r.platform_day,
    greatest(r.allowance_reserved - r.allowance_used, 0), greatest(r.cost_reserved_usd - r.cost_usd, 0));
  insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
  values (r.tenant_id, 'lead.round', 'lead', 'lead_round', p_round_id,
          jsonb_build_object('search_id', r.search_id, 'seq', r.seq, 'state', 'ended', 'ending', p_ending,
                             'counted', r.allowance_used, 'cost_usd', r.cost_usd));
  return true;
end $$;


--
-- Name: FUNCTION lead_round_end(p_round_id uuid, p_ending text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_round_end(p_round_id uuid, p_ending text) IS 'Ends a round with one of the nine endings: state ended, ended_at, and what it reserved and did not use goes back to the counters. True once; false when already ended.';


--
-- Name: lead_round_rejudge(uuid, integer, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_round_rejudge(p_round_id uuid, p_plan_version integer, p_places jsonb, p_judgment jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_round     public.lead_rounds;
  m           public.lead_search_members;
  l           public.leads;
  v_j         jsonb;
  v_el        jsonb;
  v_pl        jsonb;
  v_m         jsonb;
  v_n         integer;
  v_class     text;
  v_room      integer;
  v_changed   integer := 0;
  v_counted   integer := 0;
  v_uncounted integer := 0;
  v_counter   public.lead_counters;
begin
  select * into v_round from public.lead_rounds where id = p_round_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'why', 'round');
  end if;
  if v_round.state <> 'running' then
    return jsonb_build_object('ok', false, 'why', 'state');
  end if;
  if v_round.plan_version <> p_plan_version then
    return jsonb_build_object('ok', false, 'why', 'version');
  end if;

  -- The judge's answers, kept once each by op_id.
  for v_j in select * from jsonb_array_elements(
      case jsonb_typeof(p_judgment) when 'array' then p_judgment
           when 'object' then jsonb_build_array(p_judgment) else '[]'::jsonb end) loop
    insert into public.lead_judgments (tenant_id, round_id, batch, op_id, request_hash, answer, model, tokens)
    values (v_round.tenant_id, v_round.id, coalesce((v_j->>'batch')::integer, 0), v_j->>'op_id', v_j->>'request_hash',
            coalesce(v_j->'answer', '{}'::jsonb), v_j->>'model', coalesce((v_j->>'tokens')::integer, 0))
    on conflict (op_id) do nothing;
    get diagnostics v_n = row_count;
    if v_n = 1 then
      update public.lead_rounds
         set judge_tokens = judge_tokens + coalesce((v_j->>'tokens')::integer, 0),
             judge_model  = coalesce(v_j->>'model', judge_model)
       where id = v_round.id;
    end if;
  end loop;

  v_room := greatest(v_round.allowance_reserved - v_round.allowance_used, 0);
  for v_el in select * from jsonb_array_elements(coalesce(p_places, '[]'::jsonb)) loop
    v_pl := v_el->'place';
    v_m  := v_el->'member';
    if v_pl->>'place_id' is null or v_m is null then continue; end if;
    select * into l from public.leads where tenant_id = v_round.tenant_id and place_id = v_pl->>'place_id';
    if not found or l.blanked_at is not null or l.erased_at is not null then continue; end if;
    select * into m from public.lead_search_members
     where search_id = v_round.search_id and lead_id = l.id for update;
    if not found or m.round_id is distinct from v_round.id or m.blanked_at is not null then continue; end if;
    -- The owner's own decision stands, and so does a lead they have already worked: untouched as
    -- lead_search_undo reads it (00142), and nothing less.
    if m.kept_at is not null or coalesce(m.excluded_by, '') = 'owner'
       or l.stage <> 'ready' or l.contact_id is not null or l.contacted_at is not null
       or l.last_outcome is not null or l.phone_wrong then
      continue;
    end if;
    -- Judged under this plan already: a replay, or a second job's pass.
    if coalesce((m.judgment->>'plan_version')::integer, 1) >= p_plan_version then continue; end if;

    v_class := coalesce(v_m->>'class', 'review');
    update public.lead_search_members
       set class       = v_class,
           excluded_by = v_m->>'excluded_by',
           fit         = v_m->>'fit',
           reason      = coalesce(left(v_m->>'reason', 120), ''),
           judgment    = coalesce(v_m->'judgment', '{}'::jsonb)
                         || jsonb_build_object('shares', coalesce(m.judgment->'shares', '[]'::jsonb), 'plan_version', p_plan_version),
           version     = version + 1
     where id = m.id;

    if m.class = 'excluded' and v_class <> 'excluded' then
      -- In now: what the listing shows and the address the judge picked, where the lead has none (00144's columns).
      update public.leads
         set email            = coalesce(email, v_pl->>'email'),
             email_alternates = case when email is null then coalesce(v_pl->'email_alternates', '[]'::jsonb) else email_alternates end,
             email_state      = case when email is null and v_pl->>'email' is not null then coalesce(v_pl->>'email_state', 'checking') else email_state end,
             about        = coalesce(about, left(v_pl->>'about', 600)),
             hours        = case when hours = '[]'::jsonb then coalesce(v_pl->'hours', '[]'::jsonb) else hours end,
             image_url    = coalesce(image_url, left(v_pl->>'image_url', 500)),
             price        = coalesce(price, left(v_pl->>'price', 8)),
             reviews_dist = coalesce(reviews_dist, v_pl->'reviews_dist'),
             facebook_url = coalesce(facebook_url, left(v_pl->>'facebook_url', 300)),
             linkedin_url = coalesce(linkedin_url, left(v_pl->>'linkedin_url', 300)),
             tiktok_url   = coalesce(tiktok_url, left(v_pl->>'tiktok_url', 300)),
             claimed      = coalesce(claimed, (v_pl->>'claimed')::boolean),
             maps_url     = coalesce(maps_url, left(v_pl->>'maps_url', 500)),
             rank         = coalesce(rank, (v_pl->>'rank')::integer),
             neighborhood = coalesce(neighborhood, left(v_pl->>'neighborhood', 120)),
             logo_url     = coalesce(logo_url, left(v_pl->>'logo_url', 500)),
             mark_path    = coalesce(mark_path,
                              case when v_pl->>'mark_path' ~ '^[0-9a-f]{64}\.(png|jpg|webp|gif|ico)$' then v_pl->>'mark_path' end)
       where id = l.id;
    elsif m.class <> 'excluded' and v_class = 'excluded' then
      -- Out now: a left-out place keeps no address to write to and nothing its listing showed (PRD §0.4).
      update public.leads
         set email = null, email_alternates = '[]'::jsonb, email_state = 'none', email_checked_at = null,
             about = null, hours = '[]'::jsonb, image_url = null, price = null, reviews_dist = null,
             facebook_url = null, linkedin_url = null, tiktok_url = null, claimed = null, maps_url = null,
             rank = null, neighborhood = null, logo_url = null, mark_path = null
       where id = l.id;
    end if;

    -- Counted as the collect counts: from the round's reservation, while it has room.
    if v_class = 'qualified' and not m.counted and v_room > 0 then
      update public.lead_search_members set counted = true, counted_month = v_round.month where id = m.id;
      v_room := v_room - 1;
      v_counted := v_counted + 1;
    elsif v_class <> 'qualified' and m.counted then
      update public.lead_search_members set counted = false, counted_month = null where id = m.id;
      v_room := v_room + 1;
      v_uncounted := v_uncounted + 1;
    end if;
    v_changed := v_changed + 1;
  end loop;

  if v_counted <> v_uncounted then
    update public.lead_rounds
       set allowance_used = allowance_used + v_counted - v_uncounted
     where id = v_round.id;
    v_counter := public.lead_counter_take(v_round.tenant_id, 'allowance', v_round.month);
    update public.lead_counters
       set used     = greatest(used + v_counted - v_uncounted, 0),
           reserved = greatest(reserved - v_counted + v_uncounted, 0),
           updated_at = now()
     where id = v_counter.id;
  end if;
  if v_changed > 0 then
    insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
    values (v_round.tenant_id, 'lead.round', 'lead', 'lead_round', v_round.id,
            jsonb_build_object('search_id', v_round.search_id, 'seq', v_round.seq, 'state', v_round.state,
                               'rejudged', v_changed, 'plan_version', p_plan_version,
                               'counted', v_counted, 'uncounted', v_uncounted));
  end if;
  return jsonb_build_object('ok', true, 'changed', v_changed, 'counted', v_counted, 'uncounted', v_uncounted);
end $_$;


--
-- Name: FUNCTION lead_round_rejudge(p_round_id uuid, p_plan_version integer, p_places jsonb, p_judgment jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_round_rejudge(p_round_id uuid, p_plan_version integer, p_places jsonb, p_judgment jsonb) IS 'The runner''s. Commits the verdicts of an answer that changed the plan over the places the round''s probe already judged: only on a round running at that plan version ({ok:false, why:round|state|version}); judgments kept once by op_id; never over the owner''s decision or a worked lead, never twice (judgment.plan_version); a place leaving Excluded filled, one entering it cleared (PRD 0.4); counted from the round''s reservation both ways. Answers {ok, changed, counted, uncounted}.';


--
-- Name: lead_round_stop(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_round_stop(p_search_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user   uuid := auth.uid();
  s        public.lead_searches;
  r        public.lead_rounds;
  v_rounds integer := 0;
  v_runs   integer := 0;
  v_live   integer;
  run      record;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  select * into s from public.lead_searches where id = p_search_id;
  if not found or not public.is_acting_member(s.tenant_id) then
    raise exception 'Search not found.' using errcode = 'P0002';
  end if;
  for r in select * from public.lead_rounds where search_id = p_search_id and state <> 'ended' for update loop
    v_rounds := v_rounds + 1;
    v_live := 0;
    for run in select * from public.lead_runs where round_id = r.id and purpose = 'discover' and state in ('claimed', 'starting', 'running', 'unknown') for update loop
      -- The generation moves: a late worker's commit is refused (E3).
      update public.lead_runs set lease_gen = lease_gen + 1 where id = run.id;
      if run.state = 'running' then
        insert into public.jobs (tenant_id, kind, due_at, payload)
        values (r.tenant_id, 'lead_collect', now(), jsonb_build_object('run_id', run.id, 'seq', 'stop'))
        on conflict ((payload->>'run_id'), (payload->>'seq')) where kind = 'lead_collect' and state <> 'failed' do nothing;
        v_live := v_live + 1;
      end if;
      v_runs := v_runs + 1;
    end loop;
    update public.lead_rounds set ending_pending = 'stopped' where id = r.id;
    -- Nothing running on the provider, and no emails being checked: the round
    -- ends now. Otherwise the collect that aborts the run, or the last check
    -- batch, ends it stopped (17: the emails of leads found are still checked).
    if v_live = 0 and r.state <> 'checking' then
      perform public.lead_round_end(r.id, 'stopped');
    end if;
  end loop;
  return jsonb_build_object('rounds', v_rounds, 'runs', v_runs);
end $$;


--
-- Name: FUNCTION lead_round_stop(p_search_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_round_stop(p_search_id uuid) IS 'Operator. For every live round of the search: bumps the lease generation of its live runs, schedules a stop collect for each running discover run, records the ending as pending stopped; a round with nothing running and no checks out ends stopped at once. The strip says "Stopping · checking the emails" while the rest finish.';


--
-- Name: lead_rounds_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_rounds_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if TG_OP = 'INSERT' then
    if NEW.state <> 'queued' then
      raise exception 'a round starts queued (% refused)', NEW.state;
    end if;
    if exists (select 1 from public.lead_rounds r where r.search_id = NEW.search_id and r.state <> 'ended') then
      raise exception 'one live round per search';
    end if;
    -- Carry on, Try again, a top-up and Find new ones make a NEW round from an
    -- ended one, and only a signed-in person may: the edge and the sweep hold
    -- the service key, and they never revive a search (§12.3).
    if NEW.seq > 1 and auth.uid() is null then
      raise exception 'only a signed-in person may start a round after an ended one';
    end if;
    return NEW;
  end if;
  if OLD.state = 'ended' then
    raise exception 'a round is final once ended (% refused)', case when NEW.state is distinct from OLD.state then NEW.state else 'a change' end;
  end if;
  if NEW.state is distinct from OLD.state then
    if not (
         (OLD.state = 'queued'           and NEW.state in ('probing', 'running', 'ended'))
      or (OLD.state = 'probing'          and NEW.state in ('waiting_on_owner', 'running', 'checking', 'ended'))
      or (OLD.state = 'waiting_on_owner' and NEW.state in ('running', 'ended'))
      or (OLD.state = 'running'          and NEW.state in ('checking', 'ended'))
      or (OLD.state = 'checking'         and NEW.state in ('ended'))
    ) then
      raise exception 'lead_rounds.state % -> % refused', OLD.state, NEW.state;
    end if;
  end if;
  -- The plan a round runs is the plan it ran, except the one amendment
  -- Include makes while the round waits (§0.5 the only in-place change).
  if NEW.plan is distinct from OLD.plan or NEW.plan_version is distinct from OLD.plan_version then
    if OLD.state <> 'waiting_on_owner' or NEW.plan_version <> OLD.plan_version + 1 then
      raise exception 'a round''s plan changes only while it waits on the owner, as the next version';
    end if;
  end if;
  return NEW;
end $$;


--
-- Name: FUNCTION lead_rounds_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_rounds_guard() IS 'queued -> probing | running | ended; probing -> waiting_on_owner | running | checking | ended; waiting_on_owner -> running | ended; running -> checking | ended; checking -> ended; ended is final. One live round per search; a later round needs a signed-in person; the plan changes only while waiting, as version + 1.';


--
-- Name: lead_rounds_notify(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_rounds_notify() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_name text;
  v_via  text;
  v_n    integer;
  v_id   uuid;
begin
  select s.name, s.via into v_name, v_via from public.lead_searches s where s.id = NEW.search_id;
  if v_name is null then return null; end if;
  -- A list: a file rings once its check ran; a choice never rings (00242).
  if v_via = 'chosen' or (v_via = 'import' and coalesce(OLD.state, '') <> 'checking') then return null; end if;
  if NEW.state = 'waiting_on_owner' and coalesce(OLD.state, '') <> 'waiting_on_owner' then
    insert into public.notifications (tenant_id, kind, title, body, route, subject_type, subject_id)
    select NEW.tenant_id, 'leads_question', left('Your search for ' || v_name || ' is waiting for your answer', 200),
           coalesce(NEW.question->>'sentence', ''), 'clients/leads:s-' || NEW.search_id::text || ':c-excluded', 'lead_round', NEW.id::text
     where not exists (select 1 from public.notifications n
                        where n.tenant_id = NEW.tenant_id and n.kind = 'leads_question' and n.subject_id = NEW.id::text)
    returning id into v_id;
  elsif NEW.state = 'ended' and coalesce(OLD.state, '') <> 'ended' and coalesce(NEW.ending, '') not in ('stopped', 'question_unanswered') then
    select count(*)::integer into v_n from public.lead_search_members m
     where m.round_id = NEW.id and m.class = 'qualified' and m.blanked_at is null;
    insert into public.notifications (tenant_id, kind, title, body, route, subject_type, subject_id)
    select NEW.tenant_id, 'leads_ready',
           case when v_via <> 'import' then left('Your search for ' || v_name || ' is done', 200)
                when NEW.ending in ('target_reached', 'searched_everything') then left('Your list ' || v_name || ' is checked', 200)
                else left('Your list ' || v_name || ' could not be checked', 200) end,
           case when v_via <> 'import' then case when v_n > 0 then v_n || ' found.' else 'Nothing new was counted.' end
                when NEW.ending not in ('target_reached', 'searched_everything') then 'Its addresses wait in Needs review.'
                when v_n > 0 then v_n || ' have a checked address.' else 'None of the addresses checked out.' end,
           'clients/leads:s-' || NEW.search_id::text, 'lead_round', NEW.id::text
     where not exists (select 1 from public.notifications n
                        where n.tenant_id = NEW.tenant_id and n.kind = 'leads_ready' and n.subject_id = NEW.id::text)
    returning id into v_id;
  end if;
  -- The phone hears what the bell hears (00162's push_send, payload { notification_id }).
  if v_id is not null then
    insert into public.jobs (tenant_id, kind, due_at, payload)
    values (NEW.tenant_id, 'push_send', now(), jsonb_build_object('notification_id', v_id));
  end if;
  return null;
end $$;


--
-- Name: FUNCTION lead_rounds_notify(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_rounds_notify() IS 'The bell''s two lead kinds: one leads_question row when a round stops to ask, pointing at the search''s left-out pile (the places the question is about), and one leads_ready row when it ends with anything but "stopped" or "question_unanswered", pointing at the search; each once per round, each with a push_send job so a phone hears it too. A file of the owner''s own (via import, 00242) rings "Your list … is checked" with how many have a checked address once its check ran, or "could not be checked" when the check ended any other way; a chosen search rings nothing. A member''s own read mark is notification_marks'', as for every other kind.';


--
-- Name: lead_run_claim(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_run_claim(p_run_id uuid, p_owner text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.lead_runs set claimed_by = p_owner, claimed_at = now(), state = 'starting'
   where id = p_run_id and claimed_by is null and state = 'claimed';
  return found;
end $$;


--
-- Name: FUNCTION lead_run_claim(p_run_id uuid, p_owner text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_run_claim(p_run_id uuid, p_owner text) IS 'The dispatch claim (E1): the run row is taken by one owner token before any provider call; a second start finds it taken and does nothing. True once, for the claimer.';


--
-- Name: lead_run_lease(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_run_lease(p_run_id uuid, p_owner text, p_seconds integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_gen integer;
begin
  update public.lead_runs
     set lease_owner = p_owner, lease_until = now() + make_interval(secs => p_seconds)
   where id = p_run_id and (lease_until is null or lease_until < now() or lease_owner = p_owner)
  returning lease_gen into v_gen;
  return v_gen;
end $$;


--
-- Name: FUNCTION lead_run_lease(p_run_id uuid, p_owner text, p_seconds integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_run_lease(p_run_id uuid, p_owner text, p_seconds integer) IS 'Takes or renews the collect lease on a run: free, run out, or already this owner''s. Returns the generation the owner must present to commit; null when another owner holds it (E3).';


--
-- Name: lead_run_mark_unknown(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_run_mark_unknown(p_run_id uuid, p_owner text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.lead_runs set state = 'unknown'
   where id = p_run_id and claimed_by = p_owner and state = 'starting';
  return found;
end $$;


--
-- Name: FUNCTION lead_run_mark_unknown(p_run_id uuid, p_owner text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_run_mark_unknown(p_run_id uuid, p_owner text) IS 'The start''s answer was lost: the run is unknown, reconciled by the sweep from the provider''s own list, never blindly started again (E1).';


--
-- Name: lead_run_reconcile(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_run_reconcile(p_run_id uuid, p_apify_run_id text, p_dataset_id text, p_state text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_state not in ('running', 'succeeded', 'failed', 'aborted', 'timed_out') then
    raise exception 'a reconciled run is running or finished (% refused)', p_state using errcode = '22023';
  end if;
  update public.lead_runs
     set apify_run_id = p_apify_run_id, dataset_id = p_dataset_id, state = p_state,
         finished_at = case when p_state = 'running' then null else coalesce(finished_at, now()) end
   where id = p_run_id and state = 'unknown';
  return found;
end $$;


--
-- Name: FUNCTION lead_run_reconcile(p_run_id uuid, p_apify_run_id text, p_dataset_id text, p_state text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_run_reconcile(p_run_id uuid, p_apify_run_id text, p_dataset_id text, p_state text) IS 'The sweep found the unknown run in the provider''s list (ours carry the run row id in their input): record it and its state. Only from unknown.';


--
-- Name: lead_run_record_start(uuid, text, text, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_run_record_start(p_run_id uuid, p_owner text, p_apify_run_id text, p_dataset_id text, p_cap_usd numeric) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.lead_runs set apify_run_id = p_apify_run_id, dataset_id = p_dataset_id, cap_usd = p_cap_usd, state = 'running'
   where id = p_run_id and claimed_by = p_owner and state = 'starting';
  return found;
end $$;


--
-- Name: FUNCTION lead_run_record_start(p_run_id uuid, p_owner text, p_apify_run_id text, p_dataset_id text, p_cap_usd numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_run_record_start(p_run_id uuid, p_owner text, p_apify_run_id text, p_dataset_id text, p_cap_usd numeric) IS 'The claimer records the provider''s answer: the run id, its dataset and the cap it was started with. Only the claimer, only from starting.';


--
-- Name: lead_run_release(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_run_release(p_run_id uuid, p_owner text, p_gen integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.lead_runs set lease_owner = null, lease_until = null
   where id = p_run_id and lease_owner = p_owner and lease_gen = p_gen;
  return found;
end $$;


--
-- Name: FUNCTION lead_run_release(p_run_id uuid, p_owner text, p_gen integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_run_release(p_run_id uuid, p_owner text, p_gen integer) IS 'Releases a lease, conditional on the owner and the generation: an old collector cannot release a newer one''s (E3).';


--
-- Name: lead_runs_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_runs_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if OLD.claimed_by is not null and NEW.claimed_by is distinct from OLD.claimed_by then
    raise exception 'a run''s claim is never rewritten (E1)';
  end if;
  if NEW.webhook_token_hash is distinct from OLD.webhook_token_hash then
    raise exception 'a run''s webhook token is made once and never rewritten (E1)';
  end if;
  if OLD.state in ('succeeded', 'failed', 'aborted', 'timed_out') and NEW.state is distinct from OLD.state then
    raise exception 'lead_runs.state is terminal (% -> % refused)', OLD.state, NEW.state;
  end if;
  return NEW;
end $$;


--
-- Name: FUNCTION lead_runs_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_runs_guard() IS 'The claim and the webhook token are written once; succeeded, failed, aborted and timed_out are final. The offset, the lease and the usage still move on a finished run: the final collect reads what is left.';


--
-- Name: lead_search_choose(uuid, text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_search_choose(p_tenant_id uuid, p_name text, p_lead_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user    uuid := auth.uid();
  v_name    text := left(btrim(coalesce(p_name, '')), 120);
  v_ids     uuid[];
  v_join    uuid[];
  v_gone    integer;
  v_nomail  integer;
  v_uncount integer;
  v_month   text;
  v_plan    jsonb;
  v_search  uuid;
  v_round   uuid;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  if not public.has_permission(v_user, p_tenant_id, 'approve') then
    raise exception 'Only an owner or an operator can write to leads.' using errcode = '42501';
  end if;
  select coalesce(array_agg(distinct x), '{}') into v_ids from unnest(coalesce(p_lead_ids, '{}')) as x;
  if cardinality(v_ids) = 0 or cardinality(v_ids) > public.lead_cap('list_rows') then
    raise exception 'leads: 1 to %', public.lead_cap('list_rows') using errcode = '22023';
  end if;
  if char_length(v_name) = 0 then
    raise exception 'a list is named' using errcode = '22023';
  end if;

  -- Only a lead already counted in one of the workspace's kept searches joins (J7): it was found and paid for once,
  -- so it is counted in the new search without drawing the month again. The rest are said, never written.
  select coalesce(array_agg(l.id), '{}') into v_join
    from public.leads l
   where l.tenant_id = p_tenant_id and l.id = any (v_ids) and l.erased_at is null and l.blanked_at is null
     and nullif(btrim(l.email), '') is not null
     and exists (select 1 from public.lead_search_members m
                   join public.lead_searches s on s.id = m.search_id and s.removed_at is null
                  where m.lead_id = l.id and m.counted and m.blanked_at is null);
  select count(*) filter (where l.id is null or l.erased_at is not null or l.blanked_at is not null),
         count(*) filter (where l.id is not null and l.erased_at is null and l.blanked_at is null and nullif(btrim(l.email), '') is null)
    into v_gone, v_nomail
    from unnest(v_ids) as x
    left join public.leads l on l.id = x and l.tenant_id = p_tenant_id;
  v_uncount := cardinality(v_ids) - cardinality(v_join) - v_gone - v_nomail;
  if cardinality(v_join) = 0 then
    return jsonb_build_object('error', 'nothing',
      'sentence', 'None of these can be written to yet: a reach-out writes to counted leads with an address. Keep the ones in Needs review first.',
      'left_out', jsonb_build_object('not_counted', v_uncount, 'no_email', v_nomail, 'gone', v_gone));
  end if;

  v_month := public.lead_month(p_tenant_id, now());
  v_plan  := jsonb_build_object('version', 1, 'card', 'local_businesses', 'list', 'chosen', 'name', v_name, 'asked', '',
    'terms', '[]'::jsonb, 'count', cardinality(v_join), 'contact', 'email', 'criteria', '[]'::jsonb, 'exclusions', '[]'::jsonb);
  insert into public.lead_searches (tenant_id, created_by, via, card, name, asked, plan)
  values (p_tenant_id, v_user, 'chosen', 'local_businesses', v_name, '', v_plan)
  returning id into v_search;
  -- Its round is made and ended at once (queued -> ended), so the view carries its counts and nothing is checked.
  insert into public.lead_rounds (tenant_id, search_id, seq, purpose, plan, plan_version, target, state, month, day, platform_day)
  values (p_tenant_id, v_search, 1, 'main', v_plan, 1, cardinality(v_join), 'queued', v_month,
          public.lead_day(p_tenant_id, now()), to_char(now() at time zone 'UTC', 'YYYY-MM-DD'))
  returning id into v_round;
  -- Outside the round, as a file's joined leads are: Remove the ones you haven't touched gives back nothing here.
  insert into public.lead_search_members (search_id, lead_id, round_id, tenant_id, class, fit, counted, counted_month)
  select v_search, x, null, p_tenant_id, 'qualified',
         (select m.fit from public.lead_search_members m where m.lead_id = x and m.counted and m.blanked_at is null
           order by case m.fit when 'strong' then 0 when 'look' then 1 when 'long' then 2 else 3 end limit 1),
         true, v_month
    from unnest(v_join) as x
  on conflict (search_id, lead_id) do nothing;
  update public.lead_rounds set state = 'ended', ending = 'target_reached', ended_at = now() where id = v_round;
  insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
  values (p_tenant_id, 'lead.round', 'lead', 'lead_round', v_round,
          jsonb_build_object('search_id', v_search, 'seq', 1, 'state', 'ended', 'purpose', 'main', 'via', 'chosen',
                             'target', cardinality(v_join), 'by', v_user));
  return jsonb_build_object('search_id', v_search, 'round_id', v_round, 'counted', cardinality(v_join),
    'left_out', jsonb_build_object('not_counted', v_uncount, 'no_email', v_nomail, 'gone', v_gone));
end $$;


--
-- Name: FUNCTION lead_search_choose(p_tenant_id uuid, p_name text, p_lead_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_search_choose(p_tenant_id uuid, p_name text, p_lead_ids uuid[]) IS 'An acting member''s choice of leads (1 to lead_cap(''list_rows'') ids) as a search of its own, via chosen, for a reach-out to write to (00242, J7). Only a lead of this workspace with an address and counted in one of its kept searches joins, Qualified and counted without drawing the month again; the rest are counted as not_counted, no_email or gone. Its round is made and ended at once (target_reached), so nothing is checked and nothing rings. Refuses {error: nothing, sentence} when none joins. Returns {search_id, round_id, counted, left_out: {not_counted, no_email, gone}}.';


--
-- Name: lead_search_create(uuid, jsonb, text, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_search_create(p_tenant_id uuid, p_plan jsonb, p_via text, p_estimate_usd numeric, p_thread_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user   uuid := auth.uid();
  v_count  integer;
  v_month  text;
  v_day    text;
  v_pday   text;
  v_err    jsonb;
  v_search uuid;
  v_round  uuid;
  v_thread uuid;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  if not public.has_permission(v_user, p_tenant_id, 'find') then
    raise exception 'Only an owner can find businesses for you.' using errcode = '42501';
  end if;
  if p_via not in ('people', 'ask') then
    raise exception 'via is people or ask' using errcode = '22023';
  end if;
  if p_estimate_usd is null or p_estimate_usd < 0 or p_estimate_usd > public.lead_cap('month_usd') then
    raise exception 'estimate: 0 to % usd', public.lead_cap('month_usd') using errcode = '22023';
  end if;
  perform public.lead_plan_check(p_plan);
  if coalesce((p_plan->>'version')::integer, 0) <> 1 then
    raise exception 'a new search starts at plan version 1' using errcode = '22023';
  end if;
  v_count := (p_plan->>'count')::integer;

  if not public.lead_searches_on(p_tenant_id) then
    return jsonb_build_object('error', 'paused', 'sentence', 'Lead searches are paused for now. Your leads are all here, and nothing is being counted.');
  end if;
  -- An unapproved card never runs for an owner (28). The ask is logged as
  -- demand: the words, never a place.
  if p_plan->>'card' <> 'local_businesses' then
    insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
    values (p_tenant_id, 'lead.no_card', 'lead', 'lead_search', null,
            jsonb_build_object('card', left(p_plan->>'card', 40), 'asked', left(p_plan->>'asked', 400), 'by', v_user));
    return jsonb_build_object('error', 'no_card', 'sentence', 'I can find local businesses for now.');
  end if;

  -- The thread it was planned in, only when it is the caller's own in this
  -- workspace (00040: a thread is one person's). Anything else is null.
  if p_thread_id is not null then
    select t.id into v_thread from public.ask_threads t
     where t.id = p_thread_id and t.user_id = v_user and t.tenant_id = p_tenant_id;
  end if;

  v_month := public.lead_month(p_tenant_id, now());
  v_day   := public.lead_day(p_tenant_id, now());
  v_pday  := to_char(now() at time zone 'UTC', 'YYYY-MM-DD');
  v_err   := public.lead_reserve(p_tenant_id, v_month, v_day, v_pday, v_count, p_estimate_usd);
  if v_err is not null then
    return v_err;
  end if;

  insert into public.lead_searches (tenant_id, created_by, via, card, name, asked, plan, thread_id)
  values (p_tenant_id, v_user, p_via, p_plan->>'card', left(p_plan->>'name', 120), p_plan->>'asked', p_plan, v_thread)
  returning id into v_search;
  insert into public.lead_rounds (tenant_id, search_id, seq, purpose, plan, plan_version, target, state, allowance_reserved, cost_reserved_usd, month, day, platform_day)
  values (p_tenant_id, v_search, 1, 'probe', p_plan, 1, least(25, v_count), 'queued', v_count, p_estimate_usd, v_month, v_day, v_pday)
  returning id into v_round;
  insert into public.jobs (tenant_id, kind, due_at, payload)
  values (p_tenant_id, 'lead_round_start', now(), jsonb_build_object('round_id', v_round));
  insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
  values (p_tenant_id, 'lead.round', 'lead', 'lead_round', v_round,
          jsonb_build_object('search_id', v_search, 'seq', 1, 'state', 'queued', 'purpose', 'probe', 'target', least(25, v_count), 'by', v_user));
  return jsonb_build_object('search_id', v_search, 'round_id', v_round);
end $$;


--
-- Name: FUNCTION lead_search_create(p_tenant_id uuid, p_plan jsonb, p_via text, p_estimate_usd numeric, p_thread_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_search_create(p_tenant_id uuid, p_plan jsonb, p_via text, p_estimate_usd numeric, p_thread_id uuid) IS 'Owner. Checks the plan (version 1, the shape), the switch ({error: paused}), the card ({error: no_card}, logged as demand), then in one transaction reserves the count from the month''s allowance and the estimate from the budget and both day caps ({error: month_leads_used | budget_used | day_cap}, each with a sentence), inserts the search, its probe round (seq 1, target least(25, count)), the start job and the event. p_thread_id (00172) is the Ask thread the search was planned in, kept only when it is the caller''s own in this workspace, else null. Returns {search_id, round_id}.';


--
-- Name: lead_search_import(uuid, text, text, jsonb, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_search_import(p_tenant_id uuid, p_name text, p_asked text, p_rows jsonb, p_estimate_usd numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_user     uuid := auth.uid();
  v_name     text := left(btrim(coalesce(p_name, '')), 120);
  v_asked    text := left(btrim(coalesce(p_asked, '')), 400);
  v_x        jsonb;
  v_email    text;
  v_phone    text;
  v_host     text;
  v_region   text;
  v_lead     uuid;
  v_seen     text[] := '{}';
  v_new      jsonb := '[]'::jsonb;
  v_check    uuid[] := '{}';
  v_counted  uuid[] := '{}';
  v_unread   integer := 0;
  v_twice    integer := 0;
  v_customer integer := 0;
  v_never    integer := 0;
  v_busy     integer := 0;
  v_n        integer;
  v_estimate numeric := greatest(coalesce(p_estimate_usd, 0), 0.5);
  v_shares   jsonb;
  v_month    text;
  v_day      text;
  v_pday     text;
  v_err      jsonb;
  v_left     integer;
  v_plan     jsonb;
  v_search   uuid;
  v_round    uuid;
  v_id       uuid;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  if not public.has_permission(v_user, p_tenant_id, 'find') then
    raise exception 'Only an owner or a partner can import leads.' using errcode = '42501';
  end if;
  if jsonb_typeof(p_rows) is distinct from 'array' or jsonb_array_length(p_rows) = 0 or jsonb_array_length(p_rows) > public.lead_cap('list_rows') then
    raise exception 'rows: 1 to %', public.lead_cap('list_rows') using errcode = '22023';
  end if;
  if char_length(v_name) = 0 then
    raise exception 'a list is named' using errcode = '22023';
  end if;
  if p_estimate_usd is null or p_estimate_usd < 0 or p_estimate_usd > public.lead_cap('month_usd') then
    raise exception 'estimate: 0 to % usd', public.lead_cap('month_usd') using errcode = '22023';
  end if;
  if not public.lead_searches_on(p_tenant_id) then
    return jsonb_build_object('error', 'paused', 'sentence', 'Lead searches are paused for now, and a list is checked the way a search is. Nothing was imported.');
  end if;

  -- Each row once, read as the page read it (contracts leadImportRowsOf) and read again here: a business name and an
  -- address, the rest only when it is well formed. Nothing is written until every row is placed.
  for v_x in select value from jsonb_array_elements(p_rows) loop
    v_email := lower(btrim(coalesce(v_x->>'email', '')));
    if char_length(v_email) > 254 or v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$'
       or char_length(btrim(coalesce(v_x->>'name', ''))) = 0 then
      v_unread := v_unread + 1;
      continue;
    end if;
    if v_email = any (v_seen) then
      v_twice := v_twice + 1;
      continue;
    end if;
    v_seen  := v_seen || v_email;
    v_phone := case when v_x->>'phone' ~ '^\+[1-9][0-9]{6,14}$' then v_x->>'phone' end;
    -- Never a customer's: a person in People holds the address (as theirs, or as one they wrote from) or the number.
    if exists (select 1 from public.contacts c where c.tenant_id = p_tenant_id and c.erased_at is null
                 and (c.email = v_email or (v_phone is not null and c.phone_e164 = v_phone)))
       or exists (select 1 from public.contact_identities i
                    join public.contacts c on c.id = i.contact_id and c.erased_at is null
                   where i.tenant_id = p_tenant_id and i.channel = 'email' and i.external_id = v_email) then
      v_customer := v_customer + 1;
      continue;
    end if;
    -- Never the never-again list: the address (the one predicate, 00220) or the number.
    if public.lead_address_suppressed(p_tenant_id, v_email)
       or (v_phone is not null and exists (select 1 from public.lead_suppressions x
             where x.tenant_id = p_tenant_id and x.kind = 'phone' and x.hash = public.lead_suppression_hash(p_tenant_id, v_phone))) then
      v_never := v_never + 1;
      continue;
    end if;
    -- An address already a lead joins as that lead, never a copy, and the row changes nothing of what it holds (J4).
    -- One counted in a kept search joins counted; any other is checked with the rest, but for one another round is
    -- checking now, which is left for that round to answer (its check waits for exactly the addresses it asked).
    select l.id into v_lead from public.leads l
     where l.tenant_id = p_tenant_id and l.email = v_email and l.erased_at is null and l.blanked_at is null
     order by l.found_at
     limit 1;
    if v_lead is not null then
      if exists (select 1 from public.lead_search_members m
                   join public.lead_searches s on s.id = m.search_id and s.removed_at is null
                  where m.lead_id = v_lead and m.counted and m.blanked_at is null) then
        v_counted := v_counted || v_lead;
      elsif exists (select 1 from public.lead_search_members m join public.lead_rounds r on r.id = m.round_id
                     where m.lead_id = v_lead and r.state <> 'ended') then
        v_busy := v_busy + 1;
      else
        v_check := v_check || v_lead;
      end if;
      continue;
    end if;
    v_host   := case when lower(v_x->>'website_host') ~ '^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$'
                     and char_length(v_x->>'website_host') <= 120 then lower(v_x->>'website_host') end;
    v_region := case when v_x->>'region' ~ '^[A-Z]{2}$' then v_x->>'region' end;
    v_new := v_new || jsonb_build_object(
      'name', left(btrim(v_x->>'name'), 200), 'email', v_email, 'phone', v_phone, 'host', v_host,
      'city', nullif(left(btrim(coalesce(v_x->>'city', '')), 120), ''), 'region', v_region,
      'category', nullif(left(btrim(coalesce(v_x->>'category', '')), 120), ''));
  end loop;

  v_n := jsonb_array_length(v_new) + coalesce(array_length(v_check, 1), 0);
  if v_n + coalesce(array_length(v_counted, 1), 0) = 0 then
    return jsonb_build_object('error', 'nothing', 'sentence', 'None of these rows can be written to: each is already in People, on your never-again list, being checked in another search, or missing a name or an address.',
      'left_out', jsonb_build_object('unreadable', v_unread, 'twice', v_twice, 'customer', v_customer, 'never_again', v_never, 'elsewhere', v_busy));
  end if;

  -- What a list costs (J3): a lead of the month for each address it checks, and the check's cents, reserved as a
  -- search reserves, never under the checker run's own floor ($0.50, core check.ts); what does not check out goes back
  -- when the round ends.
  v_month := public.lead_month(p_tenant_id, now());
  v_day   := public.lead_day(p_tenant_id, now());
  v_pday  := to_char(now() at time zone 'UTC', 'YYYY-MM-DD');
  if v_n > 0 then
    v_err := public.lead_reserve(p_tenant_id, v_month, v_day, v_pday, v_n, v_estimate);
    if v_err is not null then
      if v_err->>'error' = 'month_leads_used' then
        v_left := coalesce((v_err->>'left')::integer, 0);
        return jsonb_build_object('error', 'month_leads_used', 'left', v_left,
          'sentence', case when v_left <= 0
            then 'This month''s ' || public.lead_cap('month_leads') || ' leads are used, and a list counts each address that checks out. Your leads renew on ' || public.lead_renews_on(p_tenant_id) || '.'
            else 'This list has ' || v_n || ' addresses to check and you have ' || v_left || case when v_left = 1 then ' lead' else ' leads' end
              || ' left this month; a list counts each address that checks out. Import at most ' || v_left || ' now, or the rest when your leads renew on ' || public.lead_renews_on(p_tenant_id) || '.' end);
      end if;
      return v_err;
    end if;
  end if;

  -- The search, with the plan's shape and no area (J8): nothing searches it again.
  v_plan := jsonb_build_object('version', 1, 'card', 'local_businesses', 'list', 'import', 'name', v_name,
    'asked', coalesce(nullif(v_asked, ''), v_name), 'terms', '[]'::jsonb, 'count', v_n, 'contact', 'email',
    'criteria', '[]'::jsonb, 'exclusions', '[]'::jsonb);
  insert into public.lead_searches (tenant_id, created_by, via, card, name, asked, plan)
  values (p_tenant_id, v_user, 'import', 'local_businesses', v_name, coalesce(nullif(v_asked, ''), v_name), v_plan)
  returning id into v_search;
  insert into public.lead_rounds (tenant_id, search_id, seq, purpose, plan, plan_version, target, state, allowance_reserved,
                                  cost_reserved_usd, month, day, platform_day)
  values (p_tenant_id, v_search, 1, 'main', v_plan, 1, v_n, 'queued', v_n, case when v_n > 0 then v_estimate else 0 end,
          v_month, v_day, v_pday)
  returning id into v_round;

  -- The new leads and the ones to check again wait in Needs review for their address alone (J2): the one reason
  -- lead_check_commit (00145) promotes on once the address checks out. A new lead that shares a number or a website
  -- with another of the workspace's leads (one found, or an earlier row of this file) carries the share, as the finder
  -- marks one (00237): the audience never writes to it, so one business is never written to twice.
  for v_x in select value from jsonb_array_elements(v_new) loop
    insert into public.leads (tenant_id, business_name, category, city, region, website_host, phone_e164, email, email_state)
    values (p_tenant_id, v_x->>'name', v_x->>'category', v_x->>'city', v_x->>'region', v_x->>'host', v_x->>'phone',
            v_x->>'email', 'checking')
    returning id into v_id;
    select coalesce(jsonb_agg(jsonb_build_object('kind', x.kind, 'lead_id', x.id)), '[]'::jsonb) into v_shares
      from (select l.id, case when v_x->>'phone' is not null and l.phone_e164 = v_x->>'phone' then 'phone' else 'host' end as kind
              from public.leads l
             where l.tenant_id = p_tenant_id and l.id <> v_id and l.erased_at is null and l.blanked_at is null
               and ((v_x->>'phone' is not null and l.phone_e164 = v_x->>'phone')
                 or (v_x->>'host' is not null and l.website_host = v_x->>'host'))
             limit 5) x;
    insert into public.lead_search_members (search_id, lead_id, round_id, tenant_id, judgment, class, reason)
    values (v_search, v_id, v_round, p_tenant_id,
            jsonb_build_object('reasons', jsonb_build_array('email:checking'), 'shares', v_shares), 'review', '');
  end loop;
  update public.leads set email_state = 'checking'
   where tenant_id = p_tenant_id and id = any (v_check) and email_state <> 'checking';
  insert into public.lead_search_members (search_id, lead_id, round_id, tenant_id, judgment, class, reason)
  select v_search, x, v_round, p_tenant_id, jsonb_build_object('reasons', jsonb_build_array('email:checking')), 'review', ''
    from unnest(v_check) as x
  on conflict (search_id, lead_id) do nothing;
  -- A lead already counted joins counted, and draws nothing again (one lead, one charge). It joins outside the round:
  -- the round is the check's, so its bell counts what the check answered, and Remove the ones you haven't touched
  -- (lead_search_undo, 00142, which gives back the round's untouched counted members) never gives back what never drew.
  insert into public.lead_search_members (search_id, lead_id, round_id, tenant_id, class, fit, counted, counted_month)
  select v_search, x, null, p_tenant_id, 'qualified',
         (select m.fit from public.lead_search_members m where m.lead_id = x and m.counted and m.blanked_at is null
           order by case m.fit when 'strong' then 0 when 'look' then 1 when 'long' then 2 else 3 end limit 1),
         true, v_month
    from unnest(v_counted) as x
  on conflict (search_id, lead_id) do nothing;

  if v_n > 0 then
    update public.lead_rounds set state = 'running', started_at = now() where id = v_round;
    update public.lead_rounds set state = 'checking' where id = v_round;
    insert into public.jobs (tenant_id, kind, due_at, payload)
    values (p_tenant_id, 'lead_check', now(), jsonb_build_object('round_id', v_round, 'batch', 0));
  else
    update public.lead_rounds set state = 'ended', ending = 'target_reached', ended_at = now() where id = v_round;
  end if;
  insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
  values (p_tenant_id, 'lead.round', 'lead', 'lead_round', v_round,
          jsonb_build_object('search_id', v_search, 'seq', 1, 'state', case when v_n > 0 then 'checking' else 'ended' end,
                             'purpose', 'main', 'via', 'import', 'target', v_n, 'by', v_user));
  return jsonb_build_object('search_id', v_search, 'round_id', v_round,
    'added', jsonb_array_length(v_new), 'checking', v_n, 'counted', coalesce(array_length(v_counted, 1), 0),
    'left_out', jsonb_build_object('unreadable', v_unread, 'twice', v_twice, 'customer', v_customer, 'never_again', v_never,
                                   'elsewhere', v_busy));
end $_$;


--
-- Name: FUNCTION lead_search_import(p_tenant_id uuid, p_name text, p_asked text, p_rows jsonb, p_estimate_usd numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_search_import(p_tenant_id uuid, p_name text, p_asked text, p_rows jsonb, p_estimate_usd numeric) IS 'An owner''s or a partner''s file of leads (1 to lead_cap(''list_rows'') rows of {name, email, phone?, website_host?, city?, region?, category?}) as a search of its own, via import (00242, J2-J6). A row without a name or an address, a second row of one address, an address or number a person in People holds and one on the never-again list are left out and counted. An address already a lead joins as that lead: counted in a kept search, it joins counted, outside the round, and draws nothing; one another round is checking is left out (elsewhere); otherwise it is checked. Every other address is a new lead in Needs review for its address alone, marked with any lead it shares a number or a website with, checked by the finder''s own round (queued, running, checking; a lead_check job), which lead_check_commit settles. One lead of the month is reserved per address checked, with the check''s estimate, never under $0.50 ({error: month_leads_used | budget_used | day_cap, sentence}); paused searching refuses ({error: paused}); nothing to add refuses ({error: nothing}). Returns {search_id, round_id, added, checking, counted, left_out: {unreadable, twice, customer, never_again, elsewhere}}.';


--
-- Name: lead_search_more(uuid, text, jsonb, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_search_more(p_search_id uuid, p_purpose text, p_plan jsonb, p_estimate_usd numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user    uuid := auth.uid();
  s         public.lead_searches;
  last      public.lead_rounds;
  v_count   integer;
  v_counted integer;
  v_target  integer;
  v_version integer;
  v_month   text;
  v_day     text;
  v_pday    text;
  v_err     jsonb;
  v_round   uuid;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  if p_purpose not in ('topup', 'renew') then
    raise exception 'purpose is topup or renew' using errcode = '22023';
  end if;
  if p_estimate_usd is null or p_estimate_usd < 0 or p_estimate_usd > public.lead_cap('month_usd') then
    raise exception 'estimate: 0 to % usd', public.lead_cap('month_usd') using errcode = '22023';
  end if;
  select * into s from public.lead_searches where id = p_search_id for update;
  if not found or not public.has_permission(v_user, s.tenant_id, 'find') then
    raise exception 'Search not found.' using errcode = 'P0002';
  end if;
  if s.removed_at is not null then
    return jsonb_build_object('error', 'removed');
  end if;
  perform public.lead_plan_check(p_plan);
  select * into last from public.lead_rounds where search_id = p_search_id order by seq desc limit 1;
  if last.state <> 'ended' then
    return jsonb_build_object('error', 'live', 'state', last.state);
  end if;
  v_version := coalesce((p_plan->>'version')::integer, 0);
  if v_version not in ((s.plan->>'version')::integer, (s.plan->>'version')::integer + 1) then
    raise exception 'the plan is the current version or the next' using errcode = '22023';
  end if;
  v_count := (p_plan->>'count')::integer;
  if p_purpose = 'topup' then
    select count(*) into v_counted from public.lead_search_members m where m.search_id = p_search_id and m.counted;
    v_target := v_count - v_counted;
    if v_target <= 0 then
      return jsonb_build_object('error', 'nothing_to_add', 'counted', v_counted);
    end if;
  else
    v_target := v_count;
  end if;
  if not public.lead_searches_on(s.tenant_id) then
    return jsonb_build_object('error', 'paused', 'sentence', 'Lead searches are paused for now. Your leads are all here, and nothing is being counted.');
  end if;
  v_month := public.lead_month(s.tenant_id, now());
  v_day   := public.lead_day(s.tenant_id, now());
  v_pday  := to_char(now() at time zone 'UTC', 'YYYY-MM-DD');
  v_err   := public.lead_reserve(s.tenant_id, v_month, v_day, v_pday, v_target, p_estimate_usd);
  if v_err is not null then
    return v_err;
  end if;
  if v_version <> (s.plan->>'version')::integer then
    update public.lead_searches set plan = p_plan where id = p_search_id;
  end if;
  insert into public.lead_rounds (tenant_id, search_id, seq, purpose, plan, plan_version, target, state, allowance_reserved, cost_reserved_usd, month, day, platform_day)
  values (s.tenant_id, p_search_id, last.seq + 1, p_purpose, p_plan, v_version, v_target, 'queued', v_target, p_estimate_usd, v_month, v_day, v_pday)
  returning id into v_round;
  insert into public.jobs (tenant_id, kind, due_at, payload)
  values (s.tenant_id, 'lead_round_start', now(), jsonb_build_object('round_id', v_round));
  insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
  values (s.tenant_id, 'lead.round', 'lead', 'lead_round', v_round,
          jsonb_build_object('search_id', p_search_id, 'seq', last.seq + 1, 'state', 'queued', 'purpose', p_purpose, 'target', v_target, 'by', v_user));
  return jsonb_build_object('search_id', p_search_id, 'round_id', v_round, 'seq', last.seq + 1, 'target', v_target);
end $$;


--
-- Name: FUNCTION lead_search_more(p_search_id uuid, p_purpose text, p_plan jsonb, p_estimate_usd numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_search_more(p_search_id uuid, p_purpose text, p_plan jsonb, p_estimate_usd numeric) IS 'Owner. A new round on an ended search: topup reserves the count minus what already counted, renew the whole count, through the same reservation as create; the plan is the current version or the next (stored on the search). {error: live} while a round is open; {error: nothing_to_add} when the count is already met.';


--
-- Name: lead_search_remove(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_search_remove(p_search_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user  uuid := auth.uid();
  s       public.lead_searches;
  r       public.lead_rounds;
  run     record;
  v_ids   uuid[];
  v_op    uuid;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  select * into s from public.lead_searches where id = p_search_id for update;
  if not found or not public.has_permission(v_user, s.tenant_id, 'find') then
    raise exception 'Search not found.' using errcode = 'P0002';
  end if;
  if s.removed_at is not null then
    return jsonb_build_object('error', 'removed');
  end if;
  for r in select * from public.lead_rounds where search_id = p_search_id and state <> 'ended' for update loop
    for run in select * from public.lead_runs where round_id = r.id and state in ('claimed', 'starting', 'running', 'unknown') for update loop
      update public.lead_runs set lease_gen = lease_gen + 1 where id = run.id;
      if run.state = 'running' then
        insert into public.jobs (tenant_id, kind, due_at, payload)
        values (r.tenant_id, 'lead_collect', now(), jsonb_build_object('run_id', run.id, 'seq', 'stop'))
        on conflict ((payload->>'run_id'), (payload->>'seq')) where kind = 'lead_collect' and state <> 'failed' do nothing;
      end if;
    end loop;
    perform public.lead_round_end(r.id, 'stopped');
  end loop;
  -- Members whose lead is being worked (contacted, or a person now) stay;
  -- the rest of the memberships are blanked, and the operation remembers
  -- which, so Undo can bring them back.
  select coalesce(array_agg(m.lead_id), '{}') into v_ids
    from public.lead_search_members m join public.leads l on l.id = m.lead_id
   where m.search_id = p_search_id and m.blanked_at is null and l.stage not in ('nurture', 'converted');
  update public.lead_search_members set blanked_at = now(), version = version + 1
   where search_id = p_search_id and lead_id = any (v_ids);
  update public.lead_searches set removed_at = now() where id = p_search_id;
  insert into public.lead_operations (tenant_id, kind, search_id, lead_ids, before, after, version, by)
  values (s.tenant_id, 'undo_search', p_search_id, v_ids, jsonb_build_object('removed_at', null), jsonb_build_object('removed_at', now()), 1, v_user)
  returning id into v_op;
  return jsonb_build_object('op_id', v_op, 'version', 1, 'blanked', coalesce(array_length(v_ids, 1), 0));
end $$;


--
-- Name: FUNCTION lead_search_remove(p_search_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_search_remove(p_search_id uuid) IS 'Owner. Removes a search: live rounds end stopped (their running runs get a stop collect), memberships of leads not being worked are blanked, the rest stay, and one undo_search operation records which. Returns {op_id, version}.';


--
-- Name: lead_search_rename(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_search_rename(p_search_id uuid, p_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user uuid := auth.uid();
  s      public.lead_searches;
  v_name text := nullif(btrim(regexp_replace(coalesce(p_name, ''), '\s+', ' ', 'g')), '');
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  if v_name is null or char_length(v_name) > 120 then
    raise exception 'A name is 1 to 120 characters.' using errcode = '22023';
  end if;
  select * into s from public.lead_searches where id = p_search_id;
  if not found or not public.is_acting_member(s.tenant_id) then
    raise exception 'Search not found.' using errcode = 'P0002';
  end if;
  update public.lead_searches set name = v_name where id = p_search_id;
  return jsonb_build_object('search_id', p_search_id, 'name', v_name);
end $$;


--
-- Name: FUNCTION lead_search_rename(p_search_id uuid, p_name text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_search_rename(p_search_id uuid, p_name text) IS 'Operator. Renames a search; the plan and the rounds are untouched.';


--
-- Name: lead_search_undo(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_search_undo(p_search_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user     uuid := auth.uid();
  s          public.lead_searches;
  r          public.lead_rounds;
  v_ids      uuid[] := '{}';
  v_credit   jsonb := '{}'::jsonb;
  v_counter  public.lead_counters;
  v_removed  integer := 0;
  v_credited integer := 0;
  v_op       uuid;
  rec        record;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  select * into s from public.lead_searches where id = p_search_id for update;
  -- The owner's alone (permission find): it gives leads back to the month, and
  -- only the person who spends them may.
  if not found or not public.has_permission(v_user, s.tenant_id, 'find') then
    raise exception 'Search not found.' using errcode = 'P0002';
  end if;
  if s.removed_at is not null then
    return jsonb_build_object('error', 'removed');
  end if;
  select * into r from public.lead_rounds where search_id = p_search_id order by seq desc limit 1;
  if not found or r.state <> 'ended' then
    return jsonb_build_object('error', 'running');
  end if;
  if r.ended_at is null or r.ended_at < now() - interval '24 hours' then
    return jsonb_build_object('error', 'too_late');
  end if;

  for rec in
    select m.id as member_id, m.lead_id, m.counted, m.counted_month, l.exported_at
      from public.lead_search_members m
      join public.leads l on l.id = m.lead_id
     where m.search_id = p_search_id and m.round_id = r.id and m.blanked_at is null
       and l.erased_at is null and l.blanked_at is null
       -- untouched, read off the work
       and l.stage = 'ready' and l.contact_id is null and l.contacted_at is null
       and l.last_outcome is null and not l.phone_wrong
       and m.kept_at is null and coalesce(m.excluded_by, '') <> 'owner'
     for update of m
  loop
    if rec.counted and rec.exported_at is null then
      v_counter := public.lead_counter_take(s.tenant_id, 'allowance', rec.counted_month);
      update public.lead_counters set used = greatest(used - 1, 0), updated_at = now() where id = v_counter.id;
      v_credit   := v_credit || jsonb_build_object(rec.lead_id::text, rec.counted_month);
      v_credited := v_credited + 1;
      update public.lead_search_members
         set blanked_at = now(), counted = false, counted_month = null, version = version + 1
       where id = rec.member_id;
    else
      -- Exported, or never counted: it leaves the search and keeps its charge.
      update public.lead_search_members set blanked_at = now(), version = version + 1 where id = rec.member_id;
    end if;
    v_ids     := array_append(v_ids, rec.lead_id);
    v_removed := v_removed + 1;
  end loop;

  if v_removed = 0 then
    -- Everything here has been worked: there is nothing to give back, and an
    -- operation row with no leads in it is nothing to undo.
    return jsonb_build_object('removed', 0, 'credited', 0, 'op_id', null, 'version', 1);
  end if;
  insert into public.lead_operations (tenant_id, kind, search_id, lead_ids, before, after, version, by)
  values (s.tenant_id, 'undo_search', p_search_id, v_ids,
          jsonb_build_object('removed_at', null, 'credited', v_credit),
          jsonb_build_object('round_id', r.id, 'removed', v_removed, 'credited', v_credited), 1, v_user)
  returning id into v_op;
  return jsonb_build_object('removed', v_removed, 'credited', v_credited, 'op_id', v_op, 'version', 1);
end $$;


--
-- Name: FUNCTION lead_search_undo(p_search_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_search_undo(p_search_id uuid) IS 'Owner (permission find). The Done strip''s Undo, for twenty-four hours after a round ends (§8.6): every lead of that round nobody has touched leaves the search, and the ones that counted go back to the allowance of the month they counted in (S11), except a lead exported or copied, which leaves but keeps its charge (§0.2). Touched is read off the work: the stage moved, a person was made, a call or an email was recorded, a number was marked wrong, or the membership was kept, put back or excluded by hand. Writes one undo_search operation so the toast can put it back through lead_undo. {error: removed | running | too_late} when it cannot.';


--
-- Name: lead_searches_on(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_searches_on(p_tenant_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce((select p.searches_on or p_tenant_id = any (p.tenants_on) from public.lead_platform p where p.id), false)
$$;


--
-- Name: FUNCTION lead_searches_on(p_tenant_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_searches_on(p_tenant_id uuid) IS 'Whether this workspace may search: the platform switch is on, or the workspace is listed in lead_platform.tenants_on (30). Read before every start; ships false for everyone.';


--
-- Name: lead_set_stage(uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_set_stage(p_lead_id uuid, p_stage text DEFAULT NULL::text, p_reason text DEFAULT NULL::text, p_fit_reason text DEFAULT NULL::text, p_outcome text DEFAULT NULL::text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_user     uuid := auth.uid();
  v_lead     public.leads%rowtype;
  v_before   jsonb;
  v_contact  uuid;
  v_made     jsonb;
  v_existed  boolean := false;
  v_convert  boolean := coalesce(p_outcome = 'interested', false);   -- the one act that makes a person (§9.6)
  v_stage    text;
  v_hash     text;
  v_supp     boolean := false;
  v_op       uuid;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  select * into v_lead from public.leads where id = p_lead_id;
  -- A stranger learns nothing: not a member reads as not found (00027's rule).
  -- Viewers read only, so they are strangers to this door too.
  if not found or not public.is_acting_member(v_lead.tenant_id) then
    raise exception 'Lead not found.' using errcode = 'P0002';
  end if;
  if v_lead.erased_at is not null or v_lead.blanked_at is not null then
    raise exception 'This lead is gone.' using errcode = 'P0002';
  end if;
  if p_stage is not null and p_stage not in ('ready', 'nurture', 'converted', 'archived') then
    raise exception 'stage must be ready, nurture, converted or archived' using errcode = '22023';
  end if;
  if p_reason is not null and p_reason not in ('said_no', 'not_a_fit', 'customer', 'stale', 'search_removed') then
    raise exception 'reason must be one of the closed reasons' using errcode = '22023';
  end if;
  if p_fit_reason is not null and p_fit_reason not in ('chain', 'wrong_kind', 'too_far', 'customer', 'other') then
    raise exception 'fit_reason must be chain, wrong_kind, too_far, customer or other' using errcode = '22023';
  end if;
  if p_outcome is not null and p_outcome not in ('interested', 'call_back', 'not_interested', 'voicemail', 'no_answer', 'wrong_number', 'emailed') then
    raise exception 'outcome must be one of the six, or emailed' using errcode = '22023';
  end if;
  if p_note is not null and char_length(p_note) > 280 then
    raise exception 'Note too long.' using errcode = '22023';
  end if;

  v_before := jsonb_build_object('stage', v_lead.stage, 'closed_reason', v_lead.closed_reason,
                                 'phone_wrong', v_lead.phone_wrong, 'contact_id', v_lead.contact_id);
  v_stage  := case when v_convert then 'converted' else p_stage end;

  if v_convert then
    -- A real conversation. The person whose number this is, else the person
    -- whose address it is, else a new one named for the business.
    if v_lead.contact_id is not null then
      v_contact := v_lead.contact_id;
      v_existed := true;
    elsif v_lead.phone_e164 ~ '^\+[1-9][0-9]{7,14}$' then
      -- create_person is get-or-create by number (00053), so the workspace
      -- never gets a second person for a number it already has (25), and its
      -- contact.added event with source 'lead' is what People reads back as
      -- "A lead you found" (00138).
      v_made    := public.create_person(v_lead.tenant_id, v_lead.phone_e164, left(nullif(v_lead.business_name, ''), 80), 'lead');
      v_contact := (v_made->>'contact_id')::uuid;
      v_existed := coalesce((v_made->>'existed')::boolean, false);
      -- 00125's door adds the address to a person created by phone, but only
      -- when they have none and nobody else here holds it: a unique violation
      -- inside this door would lose the whole act.
      if v_lead.email is not null
         and not exists (select 1 from public.contacts c where c.id = v_contact and c.email is not null)
         and not exists (select 1 from public.contacts c where c.tenant_id = v_lead.tenant_id and c.email = lower(btrim(v_lead.email))) then
        perform public.set_person_email(v_contact, v_lead.email);
      end if;
    else
      -- A lead with no number converts the way an email-only person arrives:
      -- the address is the identity, and the same contact.added event says
      -- where they came from.
      select c.id into v_contact from public.contacts c
       where c.tenant_id = v_lead.tenant_id and c.email = lower(btrim(coalesce(v_lead.email, '')))
         and c.erased_at is null and c.merged_into_contact_id is null
       limit 1;
      v_existed := v_contact is not null;
      if v_contact is null then
        insert into public.contacts (tenant_id, display_name, email)
        values (v_lead.tenant_id, left(nullif(v_lead.business_name, ''), 80), nullif(lower(btrim(coalesce(v_lead.email, ''))), ''))
        returning id into v_contact;
        insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
        values (v_lead.tenant_id, 'contact.added', 'contact', 'contact', v_contact,
                jsonb_build_object('source', 'lead', 'title', null, 'by', v_user));
      end if;
    end if;
  end if;

  -- One statement, so the version moves exactly once however the lead was
  -- worked, and a stage that was not named is kept (wrong_number). A conversion
  -- is lead_convert_by's (its stage, closed reason, days and version), below.
  update public.leads
     set stage         = case when v_convert then stage else coalesce(v_stage, stage) end,
         closed_reason = case when v_convert then closed_reason
                              when v_stage = 'archived' then p_reason
                              when v_stage is not null then null
                              else closed_reason end,
         phone_wrong   = (phone_wrong or coalesce(p_outcome, '') = 'wrong_number'),
         contact_id    = coalesce(v_contact, contact_id),
         contacted_at  = case when not v_convert and coalesce(v_stage, '') in ('nurture', 'converted') then coalesce(contacted_at, now()) else contacted_at end,
         last_outcome  = coalesce(p_outcome, last_outcome),
         last_note     = case when p_outcome is not null then p_note else last_note end,
         version       = case when v_convert then version else version + 1 end
   where id = p_lead_id
  returning * into v_lead;

  if v_convert then
    -- Erased or blanked since it was read above: nothing converts, and the door says so rather than claim it.
    if not coalesce((public.lead_convert_by(v_lead.tenant_id, p_lead_id, 'call',
                       jsonb_build_object('contact_id', v_contact, 'existed', v_existed, 'by', v_user), true)->>'moved')::boolean, false) then
      raise exception 'This lead is gone.' using errcode = 'P0002';
    end if;
    select * into v_lead from public.leads where id = p_lead_id;
  end if;

  if p_outcome is not null and p_outcome <> 'emailed' then
    insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
    values (v_lead.tenant_id, 'lead.call', 'lead', 'lead', p_lead_id,
            jsonb_build_object('outcome', p_outcome, 'note', p_note, 'by', v_user));
  elsif p_outcome = 'emailed' then
    -- S12: what is recorded is that the OWNER said they sent it.
    insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
    values (v_lead.tenant_id, 'lead.emailed', 'lead', 'lead', p_lead_id,
            jsonb_build_object('by', v_user));
  elsif p_reason in ('not_a_fit', 'customer') then
    insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
    values (v_lead.tenant_id, 'lead.not_a_fit', 'lead', 'lead', p_lead_id,
            jsonb_build_object('why', p_fit_reason, 'by', v_user));
    -- "Already a customer" hides the place from every future search (§0.4,
    -- S8). The hash is A's keyed digest, so the collect's suppression read
    -- refuses the place byte for byte.
    if p_reason = 'customer' and v_lead.place_id is not null then
      v_hash := public.lead_suppression_hash(v_lead.tenant_id, v_lead.place_id);
      insert into public.lead_suppressions (tenant_id, kind, hash, what)
      values (v_lead.tenant_id, 'place', v_hash, 'customer')
      on conflict (tenant_id, kind, hash) do nothing;
      v_supp := found;
    end if;
  else
    insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
    values (v_lead.tenant_id, 'lead.stage', 'lead', 'lead', p_lead_id,
            jsonb_build_object('stage', v_stage, 'reason', p_reason, 'by', v_user));
  end if;

  insert into public.lead_operations (tenant_id, kind, search_id, lead_ids, before, after, version, by)
  values (v_lead.tenant_id, 'stage', null, array[p_lead_id], v_before,
          jsonb_build_object('stage', v_lead.stage, 'closed_reason', v_lead.closed_reason,
                             'phone_wrong', v_lead.phone_wrong, 'contact_id', v_lead.contact_id,
                             'converted', v_convert, 'suppressed', v_supp, 'place_hash', v_hash),
          v_lead.version, v_user)
  returning id into v_op;

  return jsonb_build_object('stage', v_lead.stage, 'closed_reason', v_lead.closed_reason,
                            'contact_id', v_lead.contact_id, 'existed', v_existed, 'converted', v_convert,
                            'op_id', v_op, 'version', v_lead.version);
end $_$;


--
-- Name: FUNCTION lead_set_stage(p_lead_id uuid, p_stage text, p_reason text, p_fit_reason text, p_outcome text, p_note text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_set_stage(p_lead_id uuid, p_stage text, p_reason text, p_fit_reason text, p_outcome text, p_note text) IS 'Operator. The one door for a lead''s stage, its six call outcomes, "Did you send it?" and Not a fit. A click to converted marks Talking and nothing else: contact_id stays null and the answer says converted false (§9.6). Only outcome interested makes a person -- the one whose number this is when the workspace has them, else whose address, else a new one named for the business with source lead -- and links it. wrong_number marks the number and keeps the stage. reason customer hides the place from every future search. Writes one lead_operations row (kind stage) with the lead''s new version.';


--
-- Name: lead_settle_usage(uuid, text, text, text, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_settle_usage(p_tenant_id uuid, p_month text, p_day text, p_platform_day text, p_delta numeric, p_outstanding numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v      public.lead_counters;
  v_take numeric := least(greatest(p_delta, 0), greatest(p_outstanding, 0));
begin
  if p_delta <= 0 then return; end if;
  v := public.lead_counter_take(p_tenant_id, 'budget', p_month);
  update public.lead_counters set used = used + p_delta, reserved = greatest(reserved - v_take, 0), updated_at = now() where id = v.id;
  v := public.lead_counter_take(p_tenant_id, 'day', p_day);
  update public.lead_counters set used = used + p_delta, reserved = greatest(reserved - v_take, 0), updated_at = now() where id = v.id;
  v := public.lead_counter_take(null, 'day', p_platform_day);
  update public.lead_counters set used = used + p_delta, reserved = greatest(reserved - v_take, 0), updated_at = now() where id = v.id;
end $$;


--
-- Name: FUNCTION lead_settle_usage(p_tenant_id uuid, p_month text, p_day text, p_platform_day text, p_delta numeric, p_outstanding numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_settle_usage(p_tenant_id uuid, p_month text, p_day text, p_platform_day text, p_delta numeric, p_outstanding numeric) IS 'A run''s new usage, settled against the month''s budget and both day counters -- the round''s own day and the platform_day it reserved in: used grows by the delta; reserved shrinks by what the round still had outstanding.';


--
-- Name: lead_site_key(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_site_key(p_host text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$ select nullif(regexp_replace(lower(btrim(coalesce(p_host, ''))), '^www\.', ''), '') $$;


--
-- Name: lead_suppression_hash(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_suppression_hash(p_tenant_id uuid, p_value text) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
begin
  return public.erasure_digest(p_tenant_id, p_value);
end $$;


--
-- Name: FUNCTION lead_suppression_hash(p_tenant_id uuid, p_value text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_suppression_hash(p_tenant_id uuid, p_value text) IS 'The erasure digest (00263 erasure_digest): legacy sha256 of "<tenant_id>:<value>" until the re-key, keyed with Vault''s pepper after it.';


--
-- Name: lead_undo(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lead_undo(p_op_id uuid, p_version integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user    uuid := auth.uid();
  op        public.lead_operations;
  m         public.lead_search_members;
  l         public.leads;
  v_counter public.lead_counters;
  v_restored integer := 0;
  v_kept     integer := 0;
  v_recharged integer := 0;
  r          record;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  select * into op from public.lead_operations where id = p_op_id for update;
  if not found or not public.has_permission(v_user, op.tenant_id, 'find') then
    raise exception 'Operation not found.' using errcode = 'P0002';
  end if;
  if op.undone_at is not null then
    return jsonb_build_object('error', 'undone');
  end if;
  if op.version <> p_version then
    return jsonb_build_object('error', 'changed');
  end if;
  if op.kind in ('keep', 'exclude', 'put_back', 'include') then
    select * into m from public.lead_search_members where search_id = op.search_id and lead_id = op.lead_ids[1] for update;
    if not found or m.version <> op.version then
      return jsonb_build_object('error', 'changed');
    end if;
    update public.lead_search_members
       set class = op.before->>'class', excluded_by = op.before->>'excluded_by',
           counted = (op.before->>'counted')::boolean, counted_month = op.before->>'counted_month',
           kept_at = (op.before->>'kept_at')::timestamptz, kept_by = (op.before->>'kept_by')::uuid,
           version = version + 1
     where id = m.id
    returning * into m;
    -- The lead goes back to the allowance of the month it counted in, never
    -- to the budget (S11); a refund after that month credits that month.
    if (op.after->>'counted')::boolean and not (op.before->>'counted')::boolean then
      v_counter := public.lead_counter_take(op.tenant_id, 'allowance', op.after->>'counted_month');
      update public.lead_counters set used = greatest(used - 1, 0), updated_at = now() where id = v_counter.id;
    end if;
    update public.lead_operations set undone_at = now() where id = p_op_id;
    return jsonb_build_object('ok', true, 'version', m.version);
  end if;
  if op.kind = 'undo_search' then
    -- Two acts write this kind and one branch puts both back: a search that was
    -- removed (lead_search_remove) and a finished round the owner took back
    -- (lead_search_undo). The search comes back with the memberships the act
    -- blanked, except a lead exported or copied since: those are kept as they
    -- are and stay charged (E9).
    update public.lead_searches set removed_at = null where id = op.search_id;
    -- version is qualified on the right: since release B the LEAD has one too,
    -- and an UPDATE ... FROM leads leaves a bare `version` ambiguous (A's line
    -- read `version + 1` and stopped compiling the moment leads.version
    -- existed).
    update public.lead_search_members m2
       set blanked_at = null, version = m2.version + 1
      from public.leads l2
     where m2.search_id = op.search_id and m2.lead_id = l2.id and m2.lead_id = any (op.lead_ids)
       and l2.exported_at is null and l2.blanked_at is null and l2.erased_at is null;
    get diagnostics v_restored = row_count;
    v_kept := coalesce(array_length(op.lead_ids, 1), 0) - v_restored;
    -- And what the act gave back to the month is taken again, lead by lead, in
    -- the month each counted in (S11), and only for the memberships that came
    -- back: one left blanked is exported or was never credited, and either way
    -- it is not charged twice.
    for r in select key, value from jsonb_each_text(coalesce(op.before->'credited', '{}'::jsonb)) loop
      update public.lead_search_members
         set counted = true, counted_month = r.value
       where search_id = op.search_id and lead_id = r.key::uuid and blanked_at is null and not counted;
      if found then
        v_counter := public.lead_counter_take(op.tenant_id, 'allowance', r.value);
        update public.lead_counters set used = used + 1, updated_at = now() where id = v_counter.id;
        v_recharged := v_recharged + 1;
      end if;
    end loop;
    update public.lead_operations set undone_at = now() where id = p_op_id;
    return jsonb_build_object('ok', true, 'restored', v_restored, 'kept', v_kept, 'recharged', v_recharged);
  end if;
  if op.kind = 'stage' then
    -- A person who was made is never unmade from a toast: the route offers no
    -- Undo after a conversion, and the door refuses one if it is asked.
    if coalesce((op.after->>'converted')::boolean, false) then
      return jsonb_build_object('error', 'person');
    end if;
    select * into l from public.leads where id = op.lead_ids[1] for update;
    if not found or l.erased_at is not null or l.blanked_at is not null or l.version <> op.version then
      return jsonb_build_object('error', 'changed');
    end if;
    update public.leads
       set stage = op.before->>'stage', closed_reason = op.before->>'closed_reason',
           phone_wrong = coalesce((op.before->>'phone_wrong')::boolean, false),
           contact_id = (op.before->>'contact_id')::uuid,
           version = version + 1
     where id = l.id
    returning * into l;
    -- "Already a customer" wrote a suppression; taking the act back takes it
    -- back too. Only the one this act wrote, and only a customer's: an email
    -- opt-out and an erasure are nobody's to lift.
    if coalesce((op.after->>'suppressed')::boolean, false) and op.after->>'place_hash' is not null then
      delete from public.lead_suppressions
       where tenant_id = op.tenant_id and kind = 'place' and what = 'customer' and hash = op.after->>'place_hash';
    end if;
    update public.lead_operations set undone_at = now() where id = p_op_id;
    return jsonb_build_object('ok', true, 'version', l.version);
  end if;
  if op.kind = 'bulk' then
    for r in select key as lead_id, value as was from jsonb_each(op.before) loop
      update public.leads
         set stage = r.was->>'stage', closed_reason = r.was->>'closed_reason', version = version + 1
       where id = r.lead_id::uuid and version = (r.was->>'seen')::integer
         and erased_at is null and blanked_at is null;
      if found then v_restored := v_restored + 1; else v_kept := v_kept + 1; end if;
    end loop;
    update public.lead_operations set undone_at = now() where id = p_op_id;
    return jsonb_build_object('ok', true, 'restored', v_restored, 'kept', v_kept);
  end if;
  return jsonb_build_object('error', 'kind');
end $$;


--
-- Name: FUNCTION lead_undo(p_op_id uuid, p_version integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lead_undo(p_op_id uuid, p_version integer) IS 'Owner. Undoes one operation by its id and the version the client saw: {error: changed} when the operation or any touched row moved since; restores `before`; returns a counted lead to the allowance of the month it counted in, never the budget; a removed search, or a finished round the owner took back, comes back without the leads exported since and takes its credit again; a stage change goes back and takes its "Already a customer" suppression with it, unless it made a person, which is never unmade here; a bulk act restores every row nobody has touched and says how many it kept.';


--
-- Name: leads_convert_on_deal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.leads_convert_on_deal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid;
begin
  for v_id in
    select l.id from public.leads l
     where l.tenant_id = new.tenant_id and l.contact_id = new.contact_id
       and l.stage in ('ready', 'nurture')
       and l.erased_at is null and l.blanked_at is null
  loop
    perform public.lead_convert_by(new.tenant_id, v_id, 'deal', jsonb_build_object('deal_id', new.id));
  end loop;
  return null;
exception when others then
  -- The deal is the member's word; a lead that could not follow it is a warning, never a refused deal.
  raise warning 'leads_convert_on_deal: %', sqlerrm;
  return null;
end $$;


--
-- Name: FUNCTION leads_convert_on_deal(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.leads_convert_on_deal() IS 'After a deal is inserted (Reach out Part 5, G19): each ready or nurture lead of the deal''s person converts through lead_convert_by (how deal, with the deal''s id). Keyed by contact_id, never deals.lead_id. A failure warns and never refuses the deal.';


--
-- Name: leads_erase_on_contact(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.leads_erase_on_contact() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  r record;
begin
  if NEW.erased_at is not null and OLD.erased_at is null then
    for r in select l.id, l.place_id, l.phone_e164, l.email from public.leads l where l.tenant_id = NEW.tenant_id and l.contact_id = NEW.id loop
      if r.place_id is not null then
        insert into public.lead_suppressions (tenant_id, kind, hash, what) values (NEW.tenant_id, 'place', public.lead_suppression_hash(NEW.tenant_id, r.place_id), 'erased') on conflict (tenant_id, kind, hash) do update set what = 'erased';
      end if;
      if r.phone_e164 is not null then
        insert into public.lead_suppressions (tenant_id, kind, hash, what) values (NEW.tenant_id, 'phone', public.lead_suppression_hash(NEW.tenant_id, r.phone_e164), 'erased') on conflict (tenant_id, kind, hash) do update set what = 'erased';
      end if;
      if r.email is not null then
        insert into public.lead_suppressions (tenant_id, kind, hash, what) values (NEW.tenant_id, 'email', public.lead_suppression_hash(NEW.tenant_id, r.email), 'erased') on conflict (tenant_id, kind, hash) do update set what = 'erased';
      end if;
      perform public.lead_blank(r.id);
      update public.leads set erased_at = now() where id = r.id;
    end loop;
  end if;
  return NEW;
end $$;


--
-- Name: FUNCTION leads_erase_on_contact(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.leads_erase_on_contact() IS 'When a person is erased, each lead linked to them is hashed onto lead_suppressions as erased (place, phone, email) and blanked through lead_blank.';


--
-- Name: leads_page(uuid, uuid, text, text, text, integer, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.leads_page(p_tenant_id uuid, p_search_id uuid DEFAULT NULL::uuid, p_class text DEFAULT 'qualified'::text, p_sort text DEFAULT 'found'::text, p_after_key text DEFAULT NULL::text, p_limit integer DEFAULT 200, p_list text DEFAULT 'all'::text, p_dir text DEFAULT 'asc'::text, p_after_id uuid DEFAULT NULL::uuid) RETURNS TABLE(member_id uuid, lead_id uuid, place_id text, search_id uuid, round_id uuid, class text, excluded_by text, fit text, reason text, distance_m integer, counted boolean, counted_month text, judgment jsonb, shares jsonb, business_name text, category text, street text, city text, region text, postal_code text, lat double precision, lng double precision, website_host text, instagram_url text, phone_e164 text, phone_sources smallint, phone_wrong boolean, email text, email_alternates jsonb, email_state text, email_checked_at timestamp with time zone, rating numeric, reviews integer, stage text, closed_reason text, last_outcome text, last_note text, contact_id uuid, contacted_at timestamp with time zone, converted_at timestamp with time zone, exported_at timestamp with time zone, found_at timestamp with time zone, places integer, version integer, page_key text, sort_key text, about text, hours jsonb, image_url text, price text, reviews_dist jsonb, facebook_url text, linkedin_url text, tiktok_url text, claimed boolean, maps_url text, rank integer, neighborhood text, mark_path text)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with args as (
    select coalesce(p_dir, 'asc') = 'desc' as descending,
           case when p_after_id is not null then p_after_key else split_part(coalesce(p_after_key, ''), '|', 1) end as after_k,
           coalesce(p_after_id::text, nullif(split_part(coalesce(p_after_key, ''), '|', 2), '')) as after_id
  ),
  base as (
    select m.id as member_id, m.lead_id, l.place_id, m.search_id, m.round_id, m.class, m.excluded_by, m.fit, m.reason, m.distance_m,
           m.counted, m.counted_month, m.judgment, coalesce(m.judgment->'shares', '[]'::jsonb) as shares,
           l.business_name, l.category, l.street, l.city, l.region, l.postal_code, l.lat, l.lng, l.website_host, l.instagram_url,
           l.phone_e164, l.phone_sources, l.phone_wrong, l.email, l.email_alternates, l.email_state, l.email_checked_at, l.rating, l.reviews,
           l.stage, l.closed_reason, l.last_outcome, l.last_note, l.contact_id, l.contacted_at, l.converted_at, l.exported_at, l.found_at,
           (select count(*)::integer from public.lead_places p where p.lead_id = l.id) as places, l.version,
           l.about, l.hours, l.image_url, l.price, l.reviews_dist, l.facebook_url, l.linkedin_url, l.tiktok_url, l.claimed, l.maps_url, l.rank, l.neighborhood, l.mark_path,
           case coalesce(p_sort, 'found')
             when 'fit' then (case m.fit when 'strong' then '0' when 'look' then '1' when 'long' then '2' else '3' end)
                             || lpad((9999999999 - floor(extract(epoch from l.found_at)))::bigint::text, 10, '0')
             when 'distance' then lpad(coalesce(m.distance_m, 999999999)::text, 9, '0')
                             || lpad((9999999999 - floor(extract(epoch from l.found_at)))::bigint::text, 10, '0')
             -- The three column sorts B adds. A key is text and never holds
             -- the "|" the packed key splits on.
             when 'business' then left(replace(lower(coalesce(nullif(l.business_name, ''), 'zzzz')), '|', ' '), 60)
                             || lpad((9999999999 - floor(extract(epoch from l.found_at)))::bigint::text, 10, '0')
             when 'rating' then lpad(coalesce((l.rating * 10)::integer, 0)::text, 3, '0')
                             || lpad((9999999999 - floor(extract(epoch from l.found_at)))::bigint::text, 10, '0')
             when 'stage' then (case l.stage when 'ready' then '0' when 'nurture' then '1' when 'converted' then '2' else '3' end)
                             || lpad((9999999999 - floor(extract(epoch from l.found_at)))::bigint::text, 10, '0')
             else lpad((9999999999 - floor(extract(epoch from l.found_at)))::bigint::text, 10, '0')
           end as k
      from public.lead_search_members m
      join public.leads l on l.id = m.lead_id
     where m.tenant_id = p_tenant_id
       and (p_search_id is null or m.search_id = p_search_id)
       and m.class = coalesce(p_class, 'qualified')
       and public.lead_member_shown(m.class, m.counted)
       and public.lead_in_list(l.stage, l.closed_reason, coalesce(p_list, 'all'))
       and m.blanked_at is null and l.blanked_at is null and l.erased_at is null
  )
  select b.member_id, b.lead_id, b.place_id, b.search_id, b.round_id, b.class, b.excluded_by, b.fit, b.reason, b.distance_m,
         b.counted, b.counted_month, b.judgment, b.shares,
         b.business_name, b.category, b.street, b.city, b.region, b.postal_code, b.lat, b.lng, b.website_host, b.instagram_url,
         b.phone_e164, b.phone_sources, b.phone_wrong, b.email, b.email_alternates, b.email_state, b.email_checked_at, b.rating, b.reviews,
         b.stage, b.closed_reason, b.last_outcome, b.last_note, b.contact_id, b.contacted_at, b.converted_at, b.exported_at, b.found_at,
         b.places, b.version,
         b.k as page_key,
         b.k || '|' || b.member_id::text as sort_key,
         b.about, b.hours, b.image_url, b.price, b.reviews_dist, b.facebook_url, b.linkedin_url, b.tiktok_url, b.claimed, b.maps_url, b.rank, b.neighborhood, b.mark_path
    from base b, args a
   where p_after_key is null
      or (a.descending and (b.k, b.member_id::text) < (a.after_k, a.after_id))
      or (not a.descending and (b.k, b.member_id::text) > (a.after_k, a.after_id))
   -- One query, two directions: the pair that is not this call's is a constant
   -- null for every row and sorts nothing.
   order by (case when a.descending then b.k end) desc, (case when a.descending then b.member_id::text end) desc,
            (case when not a.descending then b.k end) asc, (case when not a.descending then b.member_id::text end) asc
   limit least(greatest(coalesce(p_limit, 200), 1), 500)
$$;


--
-- Name: FUNCTION leads_page(p_tenant_id uuid, p_search_id uuid, p_class text, p_sort text, p_after_key text, p_limit integer, p_list text, p_dir text, p_after_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.leads_page(p_tenant_id uuid, p_search_id uuid, p_class text, p_sort text, p_after_key text, p_limit integer, p_list text, p_dir text, p_after_id uuid) IS 'A page of members of one class (qualified: the counted ones; review; excluded) joined to their leads, narrowed to one of the rail''s lists (lead_in_list), keyset-paged on the sort key in either direction, under the caller''s row security. Six sorts: found, fit, distance, business, rating, stage. Hand the last row''s page_key and member_id back as p_after_key and p_after_id; A''s packed sort_key still works on its own, split here, so a caller that names only A''s six arguments pages exactly as it did. Which memberships show is lead_member_shown (00212).';


--
-- Name: line_forwarding_set(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.line_forwarding_set(p_tenant_id uuid, p_number text, p_carrier text, p_mode text, p_test_from text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_id          uuid;
  v_destination text;
  v_facts       jsonb;
begin
  if auth.uid() is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  if p_tenant_id is null or not public.is_acting_member(p_tenant_id) then
    raise exception 'Workspace not found.' using errcode = 'P0002';
  end if;
  if p_number is null or p_number !~ '^\+[1-9][0-9]{6,14}$' then
    raise exception 'The number to keep must be a full number, like +13055550100.' using errcode = '22023';
  end if;
  if p_carrier is null or p_carrier not in ('verizon', 'att', 'tmobile', 'other', 'office') then
    raise exception 'Unknown carrier.' using errcode = '22023';
  end if;
  if p_mode is null or p_mode not in ('unanswered', 'always') then
    raise exception 'Unknown forwarding mode.' using errcode = '22023';
  end if;
  if p_test_from is not null and p_test_from !~ '^\+[1-9][0-9]{6,14}$' then
    raise exception 'The phone you will test from must be a full number.' using errcode = '22023';
  end if;

  -- The receptionist's line: where the calls go. Without one there is nothing to forward to.
  select number_e164 into v_destination
    from public.tenant_channels
   where tenant_id = p_tenant_id and kind = 'voice' and status = 'active' and number_e164 is not null
   order by created_at
   limit 1;
  if v_destination is null then
    raise exception 'Your receptionist has no line to forward to yet.' using errcode = 'P0001';
  end if;
  if v_destination = p_number then
    raise exception 'That is the receptionist''s own number — forward the number you keep, not this one.' using errcode = '22023';
  end if;

  v_facts := jsonb_build_object(
    'carrier', p_carrier,
    'mode', p_mode,
    'destination_e164', v_destination,
    'test_from', p_test_from
  );

  select id into v_id from public.lines where tenant_id = p_tenant_id and kind = 'forwarded' order by created_at limit 1;
  if v_id is null then
    insert into public.lines (tenant_id, e164, kind, provider, forwarding_state, state_since, facts)
    values (p_tenant_id, p_number, 'forwarded', 'carrier', 'instructed', now(), v_facts)
    returning id into v_id;
  else
    update public.lines
       set e164 = p_number, forwarding_state = 'instructed', state_since = now(), facts = v_facts, last_error = null
     where id = v_id;
  end if;
  return v_id;
end $_$;


--
-- Name: FUNCTION line_forwarding_set(p_tenant_id uuid, p_number text, p_carrier text, p_mode text, p_test_from text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.line_forwarding_set(p_tenant_id uuid, p_number text, p_carrier text, p_mode text, p_test_from text) IS 'Keep my number: the one forwarded row per workspace — the number kept, the carrier (or an office phone system), the mode, the receptionist''s line it forwards to, the phone to test from. Instructed until a test call proves it.';


--
-- Name: line_forwarding_test(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.line_forwarding_test(p_tenant_id uuid, p_line_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_until timestamptz := now() + interval '30 minutes';
  v_found uuid;
begin
  if auth.uid() is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  if p_tenant_id is null or not public.is_acting_member(p_tenant_id) then
    raise exception 'Workspace not found.' using errcode = 'P0002';
  end if;
  update public.lines
     set forwarding_state = 'instructed',
         state_since = now(),
         facts = facts || jsonb_build_object('test_started_at', now(), 'test_until', v_until) - 'verified_at' - 'verified_call_id' - 'verified_from'
   where id = p_line_id and tenant_id = p_tenant_id and kind = 'forwarded'
   returning id into v_found;
  if v_found is null then
    raise exception 'No such forwarded line.' using errcode = 'P0002';
  end if;
  return jsonb_build_object('ok', true, 'test_until', v_until);
end $$;


--
-- Name: FUNCTION line_forwarding_test(p_tenant_id uuid, p_line_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.line_forwarding_test(p_tenant_id uuid, p_line_id uuid) IS 'Keep my number: open a 30-minute test window. A call to the kept number that arrives on the receptionist''s line inside it marks the row verified (the call webhook does that).';


--
-- Name: lines_sms_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lines_sms_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if NEW.sms_state is distinct from OLD.sms_state then
    if NEW.sms_state = 'none' then
      raise exception 'a line does not go back to sms_state none (% refused); release it instead', OLD.sms_state;
    end if;
    if NEW.sms_state in ('otp_waiting', 'hosting') then
      raise exception 'sms_state % is not built (% -> % refused)', NEW.sms_state, OLD.sms_state, NEW.sms_state;
    end if;
  end if;
  return NEW;
end $$;


--
-- Name: FUNCTION lines_sms_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lines_sms_guard() IS 'sms_state moves as the hourly sync and the refile doors move it, in both directions among needs_record, registering, approved, active, rejected and failed. Never back to none (a line is released, which deletes the row); never into otp_waiting or hosting, which are not built.';


--
-- Name: lines_voice_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lines_voice_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if NEW.voice_state is distinct from OLD.voice_state then
    if NEW.voice_state = 'none' then
      raise exception 'a line does not go back to voice_state none (% refused); release it instead', OLD.voice_state;
    end if;
    if OLD.voice_state = 'answering' and NEW.voice_state = 'provisioning' then
      raise exception 'an answering line is not re-provisioned (answering -> provisioning refused)';
    end if;
  end if;
  return NEW;
end $$;


--
-- Name: FUNCTION lines_voice_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lines_voice_guard() IS 'Forward moves only on voice_state: none -> provisioning -> answering|failed, failed -> provisioning, answering -> failed. Never back to none (a line is released, which deletes the row); never answering -> provisioning. sms_state has its own guard (lines_sms_guard, 00116).';


--
-- Name: lookup_user_for_invite(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lookup_user_for_invite(p_tenant_id uuid, p_email text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid;
begin
  -- OWNER, not merely a member. This answers "does this address have an
  -- account", which is an enumeration oracle. Since 00121 only the service role
  -- may call it, asked by the invite route after the route's own owner check and
  -- rate bucket; a session that somehow held EXECUTE again would still have to
  -- own the workspace.
  if auth.uid() is not null and not exists (
    select 1 from public.memberships m
     where m.tenant_id = p_tenant_id and m.user_id = auth.uid() and m.role = 'owner'
  ) then
    raise exception 'Only an owner can invite people.' using errcode = '42501';
  end if;

  -- auth.users.email is stored lowercased, but the caller's input is not
  -- guaranteed to be, and a case mismatch here would re-create the bug this
  -- function exists to fix: a known account read as new.
  select u.id into v_id
    from auth.users u
   where lower(u.email) = lower(btrim(p_email))
   limit 1;

  return v_id;
end
$$;


--
-- Name: FUNCTION lookup_user_for_invite(p_tenant_id uuid, p_email text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.lookup_user_for_invite(p_tenant_id uuid, p_email text) IS 'The user id behind an email, or null. Owner-only: it answers whether an address has an account.';


--
-- Name: mark_processed(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_processed(p_tenant_id uuid, p_message_id uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  update messages
     set meta = meta || jsonb_build_object('processed_at', now())
   where id = p_message_id and tenant_id = p_tenant_id;
$$;


--
-- Name: marketing_consent_on_erase(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketing_consent_on_erase() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.erased_at is not null and old.erased_at is null then
    perform public.erase_marketing_consent(new.id);
  end if;
  return new;
end $$;


--
-- Name: member_view_set(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.member_view_set(p_tenant_id uuid, p_page text, p_view jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_user  uuid := auth.uid();
  v_views jsonb;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  if p_page is null or p_page !~ '^[a-z][a-z0-9_-]{0,31}$' then
    raise exception 'A page is a short lowercase name.' using errcode = '22023';
  end if;
  if p_view is null or jsonb_typeof(p_view) <> 'object' or pg_column_size(p_view) > 4096 then
    raise exception 'A view is a small object.' using errcode = '22023';
  end if;
  update public.memberships
     set views = coalesce(views, '{}'::jsonb) || jsonb_build_object(p_page, p_view)
   where tenant_id = p_tenant_id and user_id = v_user
  returning views into v_views;
  if v_views is null then
    raise exception 'Not a member of this workspace.' using errcode = '42501';
  end if;
  return v_views;
end $_$;


--
-- Name: FUNCTION member_view_set(p_tenant_id uuid, p_page text, p_view jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.member_view_set(p_tenant_id uuid, p_page text, p_view jsonb) IS 'Remembers one page''s view for the caller in one workspace: their own membership row, judged by auth.uid(), a small object per page.';


--
-- Name: memberships_keep_an_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.memberships_keep_an_owner() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_tenant uuid := old.tenant_id;
begin
  -- One change to this workspace's owners at a time; the counts below are read after the lock, so a change that
  -- committed while this one waited is counted.
  perform pg_advisory_xact_lock(hashtextextended('memberships_keep_an_owner:' || v_tenant::text, 0));
  if not exists (select 1 from tenants t where t.id = v_tenant) then
    return null;
  end if;
  if exists (select 1 from memberships m where m.tenant_id = v_tenant and m.role = 'owner') then
    return null;
  end if;
  if not exists (select 1 from memberships m where m.tenant_id = v_tenant) then
    return null;
  end if;
  if exists (select 1 from partner_tenants pt
              where pt.tenant_id = v_tenant and pt.origin = 'handover' and pt.handover_accepted_at is null) then
    return null;
  end if;
  raise exception 'last_owner' using errcode = 'P0001',
    hint = 'This is the only owner. Promote someone else first.';
end;
$$;


--
-- Name: FUNCTION memberships_keep_an_owner(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.memberships_keep_an_owner() IS 'A workspace keeps an owner while anyone is in it (00271): refuses, as last_owner, a removal or demotion that leaves members and no owner, judged at the end of the transaction under a per-workspace lock. A deleted workspace, one its last member left (00262) and one a partner is handing over (00214) are let go.';


--
-- Name: message_moment(jsonb, timestamp with time zone, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.message_moment(p_meta jsonb, p_channel_ts timestamp with time zone, p_created_at timestamp with time zone, p_type text, p_status text, OUT at timestamp with time zone, OUT spoken boolean, OUT moved_in boolean) RETURNS record
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
begin
  -- A history moved in (meta.backfill) keeps the time the provider gave it, or none; anything else, when the provider
  -- says, else when it was written.
  moved_in := coalesce(p_meta->>'backfill', 'false') = 'true';
  at := case when moved_in then p_channel_ts else coalesce(p_channel_ts, p_created_at) end;
  -- Something the customer actually saw or said. A reply still in its cancel window, a canceled or failed send, an
  -- internal note and a call's own summary row are not a word in the thread.
  spoken := p_type in ('text', 'template', 'media') and p_status not in ('queued', 'canceled', 'failed');
end $$;


--
-- Name: FUNCTION message_moment(p_meta jsonb, p_channel_ts timestamp with time zone, p_created_at timestamp with time zone, p_type text, p_status text, OUT at timestamp with time zone, OUT spoken boolean, OUT moved_in boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.message_moment(p_meta jsonb, p_channel_ts timestamp with time zone, p_created_at timestamp with time zone, p_type text, p_status text, OUT at timestamp with time zone, OUT spoken boolean, OUT moved_in boolean) IS 'When a message happened, whether it was spoken, and whether it came in with a history moved in, from its meta, channel_ts, created_at, type and status: people_list''s ev (00170) in one place. Its columns, not its row: a function of a table''s row is a column PostgREST serves.';


--
-- Name: messages_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.messages_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  old_rank int;
  new_rank int;
  unknown  boolean;
begin
  if NEW.conversation_id is distinct from OLD.conversation_id
     or NEW.tenant_id   is distinct from OLD.tenant_id
     or NEW.channel     is distinct from OLD.channel
     or NEW.direction   is distinct from OLD.direction
     or NEW.sender      is distinct from OLD.sender
     or NEW.type        is distinct from OLD.type
     or NEW.body        is distinct from OLD.body
     or NEW.template_name is distinct from OLD.template_name
     or NEW.channel_ts  is distinct from OLD.channel_ts
     or NEW.created_at  is distinct from OLD.created_at
     or (OLD.external_id is not null and NEW.external_id is distinct from OLD.external_id)
  then
    raise exception 'messages content columns are immutable (P3)';
  end if;
  -- Terminal, but for one row: an email whose send timed out (00177). The provider may have taken it, so its
  -- receipt may still say what became of it; until one does, it stays failed with outcome 'unknown'.
  unknown := OLD.status = 'failed' and OLD.channel = 'email' and coalesce(OLD.error->>'outcome', '') = 'unknown';
  if OLD.status in ('failed','canceled') and NEW.status is distinct from OLD.status
     and not (unknown and NEW.status in ('sent', 'delivered', 'read')) then
    raise exception 'messages.status is terminal (% -> % rejected)', OLD.status, NEW.status;
  end if;
  -- A message that has left the building cannot be un-sent. 'canceled' asserts
  -- it never went out; on a delivered row that assertion is false, and it also
  -- hides the row from the bot's own history.
  if OLD.status in ('sent','delivered','read') and NEW.status = 'canceled' then
    raise exception 'a message that was already sent cannot be canceled (% -> % rejected)', OLD.status, NEW.status;
  end if;
  old_rank := case when unknown then 1 else case OLD.status when 'received' then 0 when 'queued' then 1 when 'sent' then 2
                              when 'delivered' then 3 when 'read' then 4 else 9 end end;
  new_rank := case NEW.status when 'received' then 0 when 'queued' then 1 when 'sent' then 2
                              when 'delivered' then 3 when 'read' then 4 else 9 end;
  if new_rank < old_rank then
    raise exception 'messages.status is monotone (% -> % rejected)', OLD.status, NEW.status;
  end if;
  if NEW.status is distinct from OLD.status then
    NEW.status_updated_at := now();
    -- Each status keeps its own time: status_updated_at knows only the
    -- latest, and "delivered at 10:32, read at 10:40" is what a recipient's
    -- line on a broadcast shows. meta.status_at.<status> = now(), on the row
    -- the receipt already updates.
    NEW.meta := coalesce(NEW.meta, '{}'::jsonb)
      || jsonb_build_object('status_at',
           coalesce(NEW.meta->'status_at', '{}'::jsonb) || jsonb_build_object(NEW.status, now()));
  end if;
  return NEW;
end $$;


--
-- Name: metrics_summary(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.metrics_summary(p_tenant_id uuid, p_days integer DEFAULT 1) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  v_tz     text;
  v_name   text;
  v_status text;
  v_days   integer := greatest(coalesce(p_days, 1), 1);
  v_start  timestamptz;
  v_result jsonb;
begin
  select timezone, name, status into v_tz, v_name, v_status
    from tenants where id = p_tenant_id;
  if v_tz is null then
    return jsonb_build_object('error', 'unknown_tenant');
  end if;

  -- Tenant-local calendar days, not 24-hour multiples: the interval
  -- arithmetic this replaces shifted the window an hour across a DST change.
  v_start := ((((now() at time zone v_tz)::date) - (v_days - 1))::timestamp) at time zone v_tz;

  with
  -- everything the tenant has ever said or heard, minus the import's
  -- timestamp-less rows: they carry no true event time and can never be
  -- placed on a calendar day.
  -- NOT MATERIALIZED (00037): referenced more than once, this CTE was
  -- materialised on PG17 and the per-conversation lookup below scanned it
  -- instead of using the (conversation_id, created_at) index.
  real_msgs as not materialized (
    select * from messages
     where tenant_id = p_tenant_id
       and coalesce(meta->>'backfill', 'false') <> 'true'
  ),
  msgs as (select * from real_msgs where created_at >= v_start),
  -- an outbound message counts only once it has actually left
  out_sent as (select * from msgs where direction = 'outbound'
                 and status in ('sent', 'delivered', 'read')),
  -- ONE definition of "who answered" and "how fast", shared with
  -- report_series (00035). This function counted any later AI reply AND any
  -- later human reply, not exclusively, and timed the AI from its draft.
  replies as (select * from public.first_replies(p_tenant_id, v_start)),
  calls_win as (
    select * from calls where tenant_id = p_tenant_id and started_at >= v_start
       and status <> 'not_connected'   -- ADDED (00031): a dial that never connected is not a call
  ),
  fresh_contacts as (
    select c.id from contacts c
     where c.tenant_id = p_tenant_id
       -- ADDED (00026): a deletion must never be reported as growth.
       and c.erased_at is null
       and not exists (select 1 from messages b
                        where b.contact_id = c.id
                          and coalesce(b.meta->>'backfill', 'false') = 'true')
       -- Their first word or call, whichever came first: least() passes over
       -- the one they never had. A person with neither has no first moment, so
       -- no window holds it (00254); they scored 'infinity' and were new in
       -- every window.
       and least(
             (select min(m.channel_ts) from messages m where m.contact_id = c.id),
             (select min(k.started_at) from calls k
               where k.contact_id = c.id and k.status <> 'not_connected')   -- ADDED (00031)
           ) >= v_start
  ),
  -- live state: whose turn is it? the last thing said in the thread was theirs.
  awaiting as (
    select cv.id from conversations cv
     where cv.tenant_id = p_tenant_id
       and cv.state in ('open', 'needs_human')
       and (select r.sender from real_msgs r
             where r.conversation_id = cv.id
             order by r.created_at desc limit 1) = 'customer'
  )
  select jsonb_build_object(
    'workspace', jsonb_build_object(
      'name', v_name, 'timezone', v_tz, 'status', v_status),

    'channels', coalesce((
      select jsonb_agg(jsonb_build_object(
               'kind', tc.kind, 'status', tc.status, 'number', tc.number_e164)
             order by tc.kind)
        from tenant_channels tc where tc.tenant_id = p_tenant_id), '[]'::jsonb),

    'window', jsonb_build_object(
      'days', v_days,
      'since', v_start,
      'since_local', to_char(v_start at time zone v_tz, 'YYYY-MM-DD"T"HH24:MI:SS'),
      'now_local',   to_char(now()   at time zone v_tz, 'YYYY-MM-DD"T"HH24:MI:SS')),

    'now', jsonb_build_object(
      'escalations_open', (select count(*) from escalations
                            where tenant_id = p_tenant_id and state = 'open'),
      'oldest_open_escalation_at', (select min(created_at) from escalations
                                     where tenant_id = p_tenant_id and state = 'open'),
      'threads_needing_human', (select count(*) from conversations
                                 where tenant_id = p_tenant_id and state = 'needs_human'),
      'threads_snoozed', (select count(*) from conversations
                           where tenant_id = p_tenant_id and state = 'snoozed'),
      'threads_awaiting_reply', (select count(*) from awaiting),
      'last_inbound_at',  (select max(coalesce(channel_ts, created_at)) from real_msgs
                            where direction = 'inbound' and sender = 'customer'),
      'last_outbound_at', (select max(created_at) from real_msgs
                            where direction = 'outbound'
                              and status in ('sent', 'delivered', 'read'))),

    'period', jsonb_build_object(
      'messages_in',  (select count(*) from msgs where direction = 'inbound' and sender = 'customer'),
      'messages_out_ai',  (select count(*) from out_sent where sender = 'ai'),
      'messages_out_you', (select count(*) from out_sent where sender = 'human'),
      'conversations_active',
        (select count(distinct conversation_id) from msgs
          where direction = 'inbound' and sender = 'customer'),

      'answered_by_ai',  (select count(*) from replies where who = 'ai'),
      'answered_by_you', (select count(*) from replies where who = 'you'),
      'unanswered_in_window',
        (select count(*) from replies where who = 'none'),
      'median_reply_seconds_ai',
        (select round(percentile_cont(0.5) within group (order by ai_seconds))
           from replies where who = 'ai'),

      'send_failures', (select count(*) from msgs
                         where direction = 'outbound' and status = 'failed'),

      'escalations_new', (select count(*) from escalations
                           where tenant_id = p_tenant_id and created_at >= v_start),
      'escalation_reasons',
        coalesce((select jsonb_object_agg(reason, n) from (
          select reason, count(*) as n from escalations
           where tenant_id = p_tenant_id and state = 'open'
           group by reason) r), '{}'::jsonb),

      'calls',        (select count(*) from calls_win),
      'call_seconds', (select coalesce(round(sum(duration_ms) / 1000.0), 0) from calls_win),
      'call_sentiments',
        coalesce((select jsonb_object_agg(coalesce(sentiment, 'Unknown'), n) from (
          select sentiment, count(*) as n from calls_win group by sentiment) s), '{}'::jsonb),
      'calls_voicemail', (select count(*) from calls_win where in_voicemail),

      'new_contacts', (select count(*) from fresh_contacts))
  ) into v_result;

  return v_result;
end $$;


--
-- Name: migration_head(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.migration_head() RETURNS TABLE(head text, applied integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select max(m.version), count(*)::integer from supabase_migrations.schema_migrations m;
$$;


--
-- Name: FUNCTION migration_head(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.migration_head() IS 'The newest migration version the CLI''s ledger has applied here, and how many it has applied: keyed /api/diag answers it.';


--
-- Name: mint_reply_token(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mint_reply_token() RETURNS text
    LANGUAGE sql
    SET search_path TO 'public', 'extensions'
    AS $$
  select string_agg(substr('abcdefghijklmnopqrstuvwxyz234567', 1 + (get_byte(r.b, g.i) % 32), 1), '' order by g.i)
    from (select gen_random_bytes(24) as b) r, generate_series(0, 23) as g(i);
$$;


--
-- Name: newest_messages(uuid, uuid[], integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.newest_messages(p_tenant_id uuid, p_threads uuid[], p_each integer, p_most integer) RETURNS json
    LANGUAGE plpgsql STABLE STRICT
    SET search_path TO ''
    SET enable_bitmapscan TO 'off'
    AS $$
begin
  if cardinality(p_threads) > 100 or p_each not between 1 and 100 or p_most not between 1 and 4000 then
    raise exception using
      errcode = '22023',
      message = 'newest_messages reads at most a hundred threads, a hundred messages of each and four thousand in all';
  end if;
  -- Each thread newest first through its own index, to the limit; then the newest of those, the id breaking ties.
  return (
    select coalesce(json_agg(r order by r.created_at desc, r.id desc), '[]'::json)
      from (select m.*
              from (select distinct t.id from unnest(p_threads) as t(id)) t
              cross join lateral (
                select x.id, x.conversation_id, x.direction, x.sender, x.type, x.body, x.media, x.meta, x.status,
                       x.created_at, x.channel_ts, x.channel
                  from public.messages x
                 where x.conversation_id = t.id
                   and x.tenant_id = p_tenant_id
                 order by x.created_at desc, x.id desc
                 limit p_each
              ) m
             order by m.created_at desc, m.id desc
             limit p_most) r
  );
end
$$;


--
-- Name: FUNCTION newest_messages(p_tenant_id uuid, p_threads uuid[], p_each integer, p_most integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.newest_messages(p_tenant_id uuid, p_threads uuid[], p_each integer, p_most integer) IS 'The newest p_each messages of each of these threads in the workspace p_tenant_id, and of those the newest p_most, newest first (created_at, then id), as one JSON list in the Inbox reader''s columns: id, conversation_id, direction, sender, type, body, media, meta, status, created_at, channel_ts, channel. Under the caller''s row security. At most 100 threads, 100 of each and 4000 in all, else 22023; a null argument answers null (00258).';


--
-- Name: note_candidates(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.note_candidates(p_limit integer DEFAULT 20) RETURNS TABLE(source text, tenant_id uuid, contact_id uuid, source_id uuid, seconds integer, dnc boolean, last_suggested timestamp with time zone, workspace_today integer, turns jsonb, known jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 20), 1), 50);
begin
  return query
  with picked_calls as (
    update calls c set note_checked_at = now()
     where c.id in (
       select c2.id from calls c2
         join tenants t on t.id = c2.tenant_id and t.status = 'active'
        where c2.note_checked_at is null and c2.notified_at is not null
          and c2.contact_id is not null and c2.direction = 'inbound'
          and c2.ended_at > now() - interval '3 days'
        order by c2.ended_at
        limit v_limit
        for update of c2 skip locked
     )
    returning c.id, c.tenant_id, c.contact_id, c.duration_ms, c.transcript_object
  ),
  picked_threads as (
    -- The stamp's previous value (was) is where this read starts: only what
    -- was said since the last look is read again.
    update conversations v set note_checked_at = now()
      from (
        select v2.id, v2.note_checked_at as was from conversations v2
          join tenants t on t.id = v2.tenant_id and t.status = 'active'
         where v2.last_inbound_at is not null
           and v2.last_inbound_at < now() - interval '6 hours'
           and v2.last_inbound_at > now() - interval '7 days'
           and (v2.note_checked_at is null or v2.note_checked_at < v2.last_inbound_at)
         order by v2.last_inbound_at
         limit v_limit
         for update of v2 skip locked
      ) s
     where v.id = s.id
    returning v.id, v.tenant_id, v.contact_id, s.was
  ),
  looks as (
    select 'call'::text as source, pc.tenant_id, pc.contact_id, pc.id as source_id,
           (coalesce(pc.duration_ms, 0) / 1000)::integer as seconds,
           coalesce((
             select jsonb_agg(jsonb_build_object(
                      'who', case when x->>'role' = 'user' then 'customer' else 'business' end,
                      'text', x->>'content') order by ord)
               from jsonb_array_elements(coalesce(pc.transcript_object, '[]'::jsonb)) with ordinality as e(x, ord)
              where x->>'role' in ('user', 'agent') and coalesce(x->>'content', '') <> ''
           ), '[]'::jsonb) as turns
      from picked_calls pc
    union all
    select 'thread', pt.tenant_id, pt.contact_id,
           (select m.id from messages m
             where m.conversation_id = pt.id and m.direction = 'inbound' and m.sender = 'customer'
             order by m.created_at desc limit 1),
           null::integer,
           coalesce((
             select jsonb_agg(jsonb_build_object(
                      'who', case when m.sender = 'customer' then 'customer' else 'business' end,
                      'text', m.body) order by m.created_at)
               from (
                 select m2.sender, m2.body, m2.created_at from messages m2
                  where m2.conversation_id = pt.id
                    and m2.type = 'text' and m2.sender <> 'system' and coalesce(m2.body, '') <> ''
                    and m2.created_at > coalesce(pt.was, now() - interval '7 days')
                  order by m2.created_at desc
                  limit 40
               ) m
           ), '[]'::jsonb)
      from picked_threads pt
  )
  select l.source, l.tenant_id, l.contact_id, l.source_id, l.seconds,
         coalesce(k.dnc, false),
         (select max(e.created_at) from events e
           where e.tenant_id = l.tenant_id and e.kind = 'contact.note_suggested'
             and e.subject_type = 'contact' and e.subject_id = l.contact_id),
         (select count(*)::integer from events e
           where e.tenant_id = l.tenant_id and e.kind = 'contact.note_suggested'
             and e.created_at > now() - interval '1 day'),
         l.turns,
         coalesce((select jsonb_agg(n.body order by n.created_at desc) from person_notes n
                    where n.contact_id = l.contact_id), '[]'::jsonb)
    from looks l
    join contacts k on k.id = l.contact_id and k.erased_at is null and k.merged_into_contact_id is null
   where l.source_id is not null;
end $$;


--
-- Name: FUNCTION note_candidates(p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.note_candidates(p_limit integer) IS 'The note sweep''s batch (0007): calls whose analysis is in and quiet conversations with customer messages newer than the last look, each stamped as it is handed over (looked at once), with the turns, the notes already there, do-not-contact, the last suggestion on the person and the workspace''s count today. Service role only.';


--
-- Name: note_for_you_notify(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.note_for_you_notify(p_tenant_id uuid, p_contact_id uuid, p_note_id uuid, p_by uuid, p_for uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_by     text;
  v_person text;
begin
  if p_for is null or p_for = p_by then
    return;
  end if;
  select coalesce(nullif(btrim(p.display_name), ''), split_part(u.email, '@', 1), 'A teammate')
    into v_by
    from auth.users u left join profiles p on p.user_id = u.id
   where u.id = p_by;
  select coalesce(nullif(btrim(c.display_name), ''), nullif(btrim(c.wa_profile_name), ''), c.phone_e164, 'someone')
    into v_person
    from contacts c where c.id = p_contact_id;
  insert into notifications (tenant_id, kind, title, body, route, subject_type, subject_id, recipient_user_id)
  values (
    p_tenant_id, 'note_for_you',
    left(format('%s left you a note on %s', coalesce(v_by, 'A teammate'), coalesce(v_person, 'someone')), 200),
    'It is on their page.',
    'clients/' || p_contact_id::text,
    'contact', p_contact_id::text, p_for
  );
end $$;


--
-- Name: FUNCTION note_for_you_notify(p_tenant_id uuid, p_contact_id uuid, p_note_id uuid, p_by uuid, p_for uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.note_for_you_notify(p_tenant_id uuid, p_contact_id uuid, p_note_id uuid, p_by uuid, p_for uuid) IS 'Tell the member a note is for that it is there (0007): a note_for_you notification addressed to them, naming the writer and the person, never the words. Nothing when the note is for its own writer. Called only by the note doors.';


--
-- Name: note_page_vitals(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.note_page_vitals(p_page text, p_vitals jsonb) RETURNS integer
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
  with kept as (
    insert into public.page_vitals (id, page, metric, value)
    select distinct on (v.id) v.id, p_page, v.name, v.value
      from jsonb_to_recordset(p_vitals) as v(id text, name text, value double precision)
    on conflict (id) do update set value = excluded.value
    returning 1
  )
  select count(*)::integer from kept
$$;


--
-- Name: FUNCTION note_page_vitals(p_page text, p_vitals jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.note_page_vitals(p_page text, p_vitals jsonb) IS 'Keeps one page load''s reports ([{id, name, value}]) under the page it landed on; a known id takes the new value. Answers how many it kept. Service role: POST /api/v1/vitals.';


--
-- Name: note_sweep_backlog(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.note_sweep_backlog(p_sweep text, p_remaining integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_ticks integer;
begin
  update public.sweep_status
     set backlog_ticks = case when p_remaining > 0 then backlog_ticks + 1 else 0 end
   where sweep = p_sweep
  returning backlog_ticks into v_ticks;
  -- No row means the sweep is not registered with sweep_health, which is a
  -- deployment mistake rather than a backlog. Say zero: never alert on the
  -- absence of bookkeeping.
  return coalesce(v_ticks, 0);
end $$;


--
-- Name: FUNCTION note_sweep_backlog(p_sweep text, p_remaining integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.note_sweep_backlog(p_sweep text, p_remaining integer) IS 'Records whether a sweep finished with work left, and returns how many ticks in a row that has now been true. Atomic, because an overlapping tick reading and writing this separately would undercount precisely when the backlog is real.';


--
-- Name: notification_mark(uuid, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notification_mark(p_id uuid, p_read boolean DEFAULT NULL::boolean, p_dismissed boolean DEFAULT NULL::boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user   uuid := auth.uid();
  v_tenant uuid;
  v_for    uuid;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  select n.tenant_id, n.recipient_user_id into v_tenant, v_for from notifications n where n.id = p_id;
  if v_tenant is null
     or not exists (select 1 from memberships m where m.user_id = v_user and m.tenant_id = v_tenant)
     or (v_for is not null and v_for <> v_user) then
    raise exception 'Notification not found.' using errcode = 'P0002';
  end if;
  insert into notification_marks (notification_id, user_id, read_at, dismissed_at)
  values (p_id, v_user, case when p_read then now() end, case when p_dismissed then now() end)
  on conflict (notification_id, user_id) do update set
    read_at      = case when p_read is null then notification_marks.read_at      when p_read then coalesce(notification_marks.read_at, now()) else null end,
    dismissed_at = case when p_dismissed is null then notification_marks.dismissed_at when p_dismissed then coalesce(notification_marks.dismissed_at, now()) else null end;
  return jsonb_build_object('notification_id', p_id);
end $$;


--
-- Name: notifications_seen(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notifications_seen(p_tenant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user uuid := auth.uid();
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  if p_tenant_id is null or not exists (select 1 from memberships m where m.user_id = v_user and m.tenant_id = p_tenant_id) then
    raise exception 'Workspace not found.' using errcode = 'P0002';
  end if;
  insert into notification_reads (tenant_id, user_id, seen_at) values (p_tenant_id, v_user, now())
  on conflict (tenant_id, user_id) do update set seen_at = now();
  return jsonb_build_object('tenant_id', p_tenant_id, 'seen_at', now());
end $$;


--
-- Name: number_drift(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.number_drift() RETURNS TABLE(kind text, tenant_id uuid, detail text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  -- 1. A routing row pointing at a line that is gone. Always wrong: the row
  --    was made BY that line, so its disappearance means a delete went one way.
  select 'orphan_route'::text,
         c.tenant_id,
         'the ' || c.kind || ' route for ' || coalesce(c.number_e164, '(no number)') ||
         ' names a line that no longer exists'
    from public.tenant_channels c
   where c.config->>'line_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     -- Shaped like an id before it is cast to one: a config holding something
     -- else would otherwise make this whole function raise, and a diagnostic
     -- that dies on the data it is diagnosing is worse than no diagnostic.
     and not exists (select 1 from public.lines l where l.id = (c.config->>'line_id')::uuid)

  union all

  -- 2. A routing row publishing a number NO line of that workspace has. Not
  --    "differs from its own line": a second number riding one receptionist
  --    leaves the first row's number in place by design, and that is fine
  --    because the number is still one of the workspace's own.
  select 'route_number_unknown'::text,
         c.tenant_id,
         'the ' || c.kind || ' route publishes ' || c.number_e164 ||
         ', which is not a number this workspace has a line for'
    from public.tenant_channels c
   where c.config ? 'line_id'
     and c.number_e164 is not null
     and not exists (
       select 1 from public.lines l
        where l.tenant_id = c.tenant_id and l.e164 = c.number_e164
     )

  union all

  -- 3. A line that ANSWERS with no voice route in its workspace. Per workspace,
  --    not per line, because one route serves every number on a receptionist.
  --    A line still provisioning is not expected to be routable yet.
  select 'answering_unrouted'::text,
         l.tenant_id,
         l.e164 || ' answers calls, but nothing routes voice to this workspace'
    from public.lines l
   where l.voice_state = 'answering'
     and not exists (
       select 1 from public.tenant_channels c
        where c.tenant_id = l.tenant_id and c.kind = 'voice'
          and coalesce(c.status, 'active') = 'active'
     )

  union all

  -- 4. A line whose texting is ON with no route for its own number. Per line
  --    here, because an sms route IS the number.
  select 'texting_unrouted'::text,
         l.tenant_id,
         l.e164 || ' is switched on for texting, but nothing routes texts to it'
    from public.lines l
   where l.sms_state = 'active'
     and not exists (
       select 1 from public.tenant_channels c
        where c.tenant_id = l.tenant_id and c.kind = 'sms'
          and c.number_e164 = l.e164
          and coalesce(c.status, 'active') = 'active'
     )
   order by 1, 2;
$_$;


--
-- Name: FUNCTION number_drift(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.number_drift() IS 'Where lines and tenant_channels disagree in a way that is actually wrong: a route naming a deleted line, a route publishing a number the workspace has no line for, a line answering with nothing routing to it, a line texting with nothing routing to it. A channel row with no line at all is NOT drift -- Retell-bought voice numbers and Meta WhatsApp numbers legitimately have none. Read by /api/diag.';


--
-- Name: outreach_facts(uuid, uuid, text, text, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.outreach_facts(p_tenant_id uuid, p_contact_id uuid, p_to text, p_host text, p_since timestamp with time zone, p_lead_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.outreach_lead_facts(p_tenant_id, p_contact_id, p_to, p_lead_id) || jsonb_build_object(
    -- The ramp's days as the domains clock wrote them (they move only at midnight, or to none when clean again).
    'domain', (
      select jsonb_build_object('state', d.state, 'from_local', d.from_local, 'clean_since', d.clean_since,
                                'sent_days', coalesce(d.sent_days, 0))
        from public.sending_domains d
       where d.tenant_id = p_tenant_id and d.host = lower(btrim(p_host))),
    'sent_since', (
      select count(*) from public.messages m
       where m.tenant_id = p_tenant_id and m.channel = 'email' and m.direction = 'outbound'
         and public.email_from_host(m.meta) = lower(btrim(p_host))
         and m.created_at >= p_since - interval '30 days'
         and public.email_sent_at(m.meta, m.status_updated_at, m.created_at) >= p_since
         and (public.email_left(m.status, m.error)
              or (m.status = 'failed' and coalesce(m.error->>'outcome', '') = 'unknown')))
  )
$$;


--
-- Name: FUNCTION outreach_facts(p_tenant_id uuid, p_contact_id uuid, p_to text, p_host text, p_since timestamp with time zone, p_lead_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.outreach_facts(p_tenant_id uuid, p_contact_id uuid, p_to text, p_host text, p_since timestamp with time zone, p_lead_id uuid) IS 'The facts the send door asks of a cold email (core deliver.ts): the lead''s (outreach_lead_facts), domain {state, from_local, clean_since, sent_days}, sent_since. Service role only.';


--
-- Name: outreach_lead_facts(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.outreach_lead_facts(p_tenant_id uuid, p_contact_id uuid, p_to text, p_lead_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object(
    -- The send's own lead when it names one (a reach-out's always does); else the lead still being written to wins.
    'lead_stage', coalesce(
      (select l.stage from public.leads l
        where p_lead_id is not null and l.id = p_lead_id and l.tenant_id = p_tenant_id
          and l.contact_id = p_contact_id and l.erased_at is null and l.blanked_at is null),
      (select l.stage from public.leads l
        where p_lead_id is null and l.tenant_id = p_tenant_id and l.contact_id = p_contact_id
          and l.erased_at is null and l.blanked_at is null
        order by (l.stage in ('ready', 'nurture')) desc, l.found_at desc
        limit 1)),
    'suppressed', public.lead_address_suppressed(p_tenant_id, p_to),
    'wrote_back', exists (select 1 from public.outreach_wrote_back(p_tenant_id, array[p_contact_id])),
    -- An automatic out-of-office (00222, G8) whose day is still ahead: from this person, or answering the send's lead
    -- from another address of the business. Two arms, so the first can use reach_out_replies_away.
    'away', exists (select 1 from public.reach_out_replies r
                     where r.tenant_id = p_tenant_id and r.contact_id = p_contact_id
                       and r.intent = 'away' and r.claim = 'auto_reply'
                       and r.until_at > now() and r.undone_at is null)
            or (p_lead_id is not null
                and exists (select 1 from public.reach_out_replies r
                             where r.tenant_id = p_tenant_id and r.lead_id = p_lead_id
                               and r.intent = 'away' and r.claim = 'auto_reply'
                               and r.until_at > now() and r.undone_at is null)),
    -- Its owner stopped writing to this lead (00241, Part 6's H10): the door skips its email, and the followers
    -- leave it out.
    'stopped', p_lead_id is not null
               and exists (select 1 from public.leads l
                            where l.id = p_lead_id and l.tenant_id = p_tenant_id
                              and l.reach_out_stopped_at is not null)
  )
$$;


--
-- Name: FUNCTION outreach_lead_facts(p_tenant_id uuid, p_contact_id uuid, p_to text, p_lead_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.outreach_lead_facts(p_tenant_id uuid, p_contact_id uuid, p_to text, p_lead_id uuid) IS 'A cold email''s facts about its lead: lead_stage (the send''s own lead when named, else the one still being written to), suppressed, wrote_back (00181), away (an automatic out-of-office whose day is still ahead, 00226), stopped (its owner stopped writing to it, 00241). Service role only.';


--
-- Name: outreach_wrote_back(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.outreach_wrote_back(p_tenant_id uuid, p_contact_ids uuid[]) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select c.contact_id from public.messages m
    join public.conversations c on c.id = m.conversation_id and c.tenant_id = m.tenant_id
   where m.tenant_id = p_tenant_id and c.contact_id = any (p_contact_ids)
     and m.direction = 'inbound' and m.sender = 'customer'
     and not (m.channel = 'email' and coalesce(m.meta->'email'->>'claim', 'person') = 'auto_reply')
  union
  select c.contact_id from public.messages o
    join public.conversations c on c.id = o.conversation_id and c.tenant_id = o.tenant_id
   where o.tenant_id = p_tenant_id and c.contact_id = any (p_contact_ids)
     and o.channel = 'email' and o.direction = 'outbound' and o.meta->'email'->>'message_id' is not null
     and (exists (
            select 1 from public.messages r
             where r.tenant_id = p_tenant_id and r.channel = 'email' and r.direction = 'inbound'
               and r.sender = 'customer'
               and r.meta->'email'->>'in_reply_to' = o.meta->'email'->>'message_id'
               and coalesce(r.meta->'email'->>'claim', 'person') <> 'auto_reply')
          or exists (
            select 1 from public.messages r
             where r.tenant_id = p_tenant_id and r.channel = 'email' and r.direction = 'inbound'
               and r.sender = 'customer'
               and r.meta->'email'->'references' @> jsonb_build_array(o.meta->'email'->>'message_id')
               and coalesce(r.meta->'email'->>'claim', 'person') <> 'auto_reply'))
  union
  select k.contact_id from public.calls k
   where k.tenant_id = p_tenant_id and k.contact_id = any (p_contact_ids) and k.direction = 'inbound'
  union
  select rr.contact_id from public.reach_out_replies rr
   where rr.tenant_id = p_tenant_id and rr.contact_id = any (p_contact_ids)
     and rr.claim = 'auto_reply' and rr.intent in ('no', 'wrong_person') and rr.undone_at is null
  union
  select rr.lead_contact_id from public.reach_out_replies rr
   where rr.tenant_id = p_tenant_id and rr.lead_contact_id = any (p_contact_ids)
     and rr.claim = 'auto_reply' and rr.intent in ('no', 'wrong_person') and rr.undone_at is null
$$;


--
-- Name: page_vitals_p75(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.page_vitals_p75(p_days integer DEFAULT 7, p_most integer DEFAULT 25000) RETURNS TABLE(metric text, page text, samples integer, p75 double precision, since timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with recent as (
    select v.page, v.metric, v.value, v.at
      from public.page_vitals v
     where v.at > now() - make_interval(days => p_days)
     order by v.at desc
     limit p_most
  )
  select r.metric, r.page, count(*)::integer, percentile_cont(0.75) within group (order by r.value), min(r.at)
    from recent r
   group by grouping sets ((r.metric), (r.metric, r.page))
   order by r.metric, r.page nulls first
$$;


--
-- Name: FUNCTION page_vitals_p75(p_days integer, p_most integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.page_vitals_p75(p_days integer, p_most integer) IS 'The 75th percentile of each metric over the latest p_most reports of the last p_days: one row per metric with page null (every page), then one per metric and page. Service role: the back office.';


--
-- Name: partner_balance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_balance() RETURNS TABLE(currency text, state text, earned_cents bigint, next_payable_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select e.currency, e.state, sum(e.earned_cents)::bigint, min(e.payable_at) filter (where e.state = 'held')
    from public.partner_earnings e
    join public.partners p on p.id = e.partner_id
   where p.user_id = (select auth.uid()) and e.state <> 'void' and public.session_shows_second_factor()
   group by e.currency, e.state
$$;


--
-- Name: FUNCTION partner_balance(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.partner_balance() IS 'The calling partner''s totals by currency and state (held, payable, paid), and when the next held one is due. Answers about the caller alone.';


--
-- Name: partner_become(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_become(p_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_user uuid := auth.uid();
  v_code text := lower(btrim(coalesce(p_code, '')));
  v_row  public.partners;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  if not public.session_shows_second_factor() then
    raise exception 'Enter the code from your authenticator app first: a partner signs in with two steps.'
      using errcode = '42501';
  end if;
  -- The shape contracts cleanPartnerCode checks, checked again where the row is written.
  if v_code !~ '^[a-z0-9][a-z0-9-]{1,22}[a-z0-9]$' then
    raise exception 'A code is 3 to 24 letters, digits or dashes, starting and ending with a letter or digit.'
      using errcode = '22023';
  end if;
  if v_code in ('chanlytics', 'admin', 'support', 'signup', 'login', 'partner', 'partners') then
    raise exception 'That code is reserved. Try another.' using errcode = '22023';
  end if;
  if exists (select 1 from public.partners p where p.user_id = v_user) then
    raise exception 'You are already a partner.' using errcode = '23505';
  end if;
  begin
    insert into public.partners (user_id, code, terms_accepted_at)
    values (v_user, v_code, now())
    returning * into v_row;
  exception when unique_violation then
    raise exception 'That code is taken. Try another.' using errcode = '23505';
  end;
  return to_jsonb(v_row) - 'payout_facts' - 'user_id' - 'updated_at';
end $_$;


--
-- Name: FUNCTION partner_become(p_code text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.partner_become(p_code text) IS 'The calling session becomes a partner (0012) with this code, once. The code''s shape and the reserved words are contracts'' rule, restated here; the terms are recorded as agreed now.';


--
-- Name: partner_closed_on_erasure(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_closed_on_erasure() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  -- The person erased their account: the row stays for the ledger, and nobody is left to pay or to seat.
  if new.user_id is null and old.user_id is not null then
    new.status := 'closed';
    new.status_why := 'The partner erased their account.';
    new.status_at := now();
  end if;
  return new;
end $$;


--
-- Name: partner_earn(uuid, text, text, bigint, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_earn(p_tenant_id uuid, p_invoice_id text, p_event_id text, p_amount_cents bigint, p_currency text, p_paid_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_link    public.partner_tenants;
  v_partner public.partners;
  v_earned  bigint;
  v_row     public.partner_earnings;
  v_wait    record;
begin
  select * into v_link from public.partner_tenants where tenant_id = p_tenant_id;
  if v_link.tenant_id is null then
    return null;
  end if;
  if v_link.standing = 'disqualified' or coalesce(p_amount_cents, 0) <= 0 then
    return null;
  end if;
  select * into v_partner from public.partners where id = v_link.partner_id;
  if v_partner.status = 'closed' then
    return null;
  end if;
  -- A partner who owns the workspace is paying themselves (0012, decision 5): nothing is earned.
  if exists (select 1 from public.memberships m
              where m.tenant_id = p_tenant_id and m.user_id = v_partner.user_id and m.role = 'owner') then
    return null;
  end if;
  v_earned := floor(p_amount_cents::numeric * v_partner.share_bp / 10000);
  if v_earned <= 0 then
    return null;
  end if;
  insert into public.partner_earnings
    (partner_id, tenant_id, stripe_invoice_id, stripe_event_id, kind, amount_cents, currency, share_bp,
     earned_cents, paid_at, payable_at)
  values
    (v_partner.id, p_tenant_id, p_invoice_id, p_event_id, 'share', p_amount_cents, lower(p_currency),
     v_partner.share_bp, v_earned, p_paid_at, p_paid_at + interval '30 days')
  on conflict do nothing
  returning * into v_row;
  if v_row.id is null then
    return null;
  end if;
  insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
  values (p_tenant_id, 'partner.earned', 'billing', 'tenant', p_tenant_id,
          jsonb_build_object('partner_id', v_partner.id, 'invoice', p_invoice_id, 'amount_cents', p_amount_cents,
                             'earned_cents', v_earned, 'currency', lower(p_currency)));
  -- What arrived before the share is applied now, in the order it arrived.
  for v_wait in
    select * from public.partner_reversals_waiting where stripe_invoice_id = p_invoice_id order by created_at
  loop
    perform public.partner_reverse(v_wait.stripe_invoice_id, v_wait.stripe_event_id, v_wait.kind, v_wait.amount_cents);
    delete from public.partner_reversals_waiting where stripe_event_id = v_wait.stripe_event_id;
  end loop;
  return jsonb_build_object('id', v_row.id, 'earned_cents', v_earned, 'payable_at', v_row.payable_at);
end $$;


--
-- Name: FUNCTION partner_earn(p_tenant_id uuid, p_invoice_id text, p_event_id text, p_amount_cents bigint, p_currency text, p_paid_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.partner_earn(p_tenant_id uuid, p_invoice_id text, p_event_id text, p_amount_cents bigint, p_currency text, p_paid_at timestamp with time zone) IS 'A share of a paid plan invoice for the partner who brought this workspace (0012), at the partner''s share_bp, held thirty days. Null when nobody brought it, it is disqualified, or the invoice or delivery was written already.';


--
-- Name: partner_earnings_sweep(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_earnings_sweep(p_now timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_link        record;
  v_same_card   boolean;
  v_same_list   boolean;
  v_same_domain boolean;
  v_held        boolean;
  v_judged      int := 0;
  v_review      int := 0;
  v_payable     int := 0;
  v_void        int := 0;
  v_forgot      int := 0;
begin
  -- 1. Standing, once a workspace has paid (00203).
  for v_link in
    select pt.tenant_id, pt.partner_id, p.user_id as partner_user, t.created_at as made_at,
           pt.origin, pt.handover_accepted_by, pt.invited_by
      from public.partner_tenants pt
      join public.partners p on p.id = pt.partner_id
      join public.tenants t on t.id = pt.tenant_id
     where pt.standing is null
       and exists (select 1 from public.partner_earnings e
                    where e.tenant_id = pt.tenant_id and e.kind = 'share'
                      and (e.paid_at <= p_now - interval '7 days'
                           or exists (select 1 from public.billing_card_marks m where m.tenant_id = pt.tenant_id)))
     for update of pt skip locked
  loop
    select exists (
      select 1 from public.billing_card_marks mine
        join public.billing_card_marks theirs on theirs.card_fingerprint = mine.card_fingerprint
        join public.memberships m on m.tenant_id = theirs.tenant_id
       where mine.tenant_id = v_link.tenant_id
         and theirs.tenant_id <> v_link.tenant_id
         and m.user_id = v_link.partner_user and m.role = 'owner'
    ) into v_same_card;
    select exists (
      select 1 from public.google_listings mine
        join public.google_listings theirs on theirs.place_id = mine.place_id
        join public.tenants t on t.id = theirs.tenant_id
       where mine.tenant_id = v_link.tenant_id
         and theirs.tenant_id <> v_link.tenant_id
         and t.created_at < v_link.made_at
    ) into v_same_list;
    -- A public mailbox's domain says nothing about who is behind it; a company's says they work together.
    -- The owner who took the workspace from the partner (a handover), or who asked for the partner (an invitation).
    select coalesce(v_link.origin in ('handover', 'invite') and exists (
      select 1 from auth.users owner_u
        join auth.users partner_u on partner_u.id = v_link.partner_user
       where owner_u.id = case v_link.origin when 'handover' then v_link.handover_accepted_by
                                            else v_link.invited_by end
         and split_part(lower(owner_u.email), '@', 2) = split_part(lower(partner_u.email), '@', 2)
         and split_part(lower(partner_u.email), '@', 2) not in (
           'gmail.com', 'googlemail.com', 'outlook.com', 'hotmail.com', 'live.com', 'msn.com', 'yahoo.com',
           'ymail.com', 'icloud.com', 'me.com', 'mac.com', 'aol.com', 'proton.me', 'protonmail.com', 'pm.me',
           'gmx.com', 'gmx.net', 'mail.com', 'zoho.com', 'yandex.com', 'fastmail.com', 'hey.com')
    ), false) into v_same_domain;
    v_held := v_same_card or v_same_list or v_same_domain;
    update public.partner_tenants
       set standing = case when v_held then 'review' else 'qualified' end,
           standing_why = case
             when v_same_card then 'The card that pays for it also pays for a workspace the partner owns.'
             when v_same_list then 'Its Google listing belongs to an older workspace.'
             when v_same_domain and v_link.origin = 'invite'
               then 'Its owner asked for the partner from the partner''s own email domain.'
             when v_same_domain then 'Its owner accepted it from the partner''s own email domain.'
             else null end,
           standing_at = p_now,
           standing_by = null,
           checks = jsonb_build_object('same_card', v_same_card, 'same_listing', v_same_list,
                                       'same_domain', v_same_domain)
     where tenant_id = v_link.tenant_id;
    insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
    values (v_link.tenant_id, 'partner.standing_set', 'billing', 'tenant', v_link.tenant_id,
            jsonb_build_object('partner_id', v_link.partner_id,
                               'standing', case when v_held then 'review' else 'qualified' end,
                               'by', 'sweep'));
    v_judged := v_judged + 1;
    if v_held then v_review := v_review + 1; end if;
  end loop;

  -- 2. What is due matures, for an active partner: on a qualified workspace, or on one deleted since it paid (its
  --    standing went with it; a refund still reverses it).
  update public.partner_earnings e
     set state = 'payable'
    from public.partners p
   where e.state = 'held' and e.payable_at <= p_now
     and p.id = e.partner_id and p.status = 'active'
     and (e.tenant_id is null
          or exists (select 1 from public.partner_tenants pt
                      where pt.tenant_id = e.tenant_id and pt.standing = 'qualified'));
  get diagnostics v_payable = row_count;

  -- 3. What a disqualified workspace still held is void.
  update public.partner_earnings e
     set state = 'void'
    from public.partner_tenants pt
   where e.state = 'held' and pt.tenant_id = e.tenant_id and pt.standing = 'disqualified';
  get diagnostics v_void = row_count;

  -- 4. A reversal that waited 120 days for a share that never came is not coming.
  delete from public.partner_reversals_waiting where created_at < p_now - interval '120 days';
  get diagnostics v_forgot = row_count;

  return jsonb_build_object('judged', v_judged, 'review', v_review, 'payable', v_payable, 'void', v_void,
                            'forgot', v_forgot);
end $$;


--
-- Name: FUNCTION partner_earnings_sweep(p_now timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.partner_earnings_sweep(p_now timestamp with time zone) IS 'The partner clock (0012): judges the standing of each attributed workspace once it has paid, makes held earnings past their date payable on a qualified workspace for an active partner, and voids what a disqualified one held.';


--
-- Name: partner_handover_resend(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_handover_resend(p_tenant uuid, p_email text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_user    uuid := auth.uid();
  v_email   text := lower(btrim(coalesce(p_email, '')));
  v_mine    text;
  v_partner public.partners;
  v_row     public.partner_tenants;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  if not public.session_shows_second_factor() then
    raise exception 'Enter the code from your authenticator app first: a partner signs in with two steps.'
      using errcode = '42501';
  end if;
  select p.* into v_partner from public.partners p where p.user_id = v_user;
  if v_partner.id is null then
    raise exception 'Only a partner can hand a workspace over.' using errcode = '42501';
  end if;
  if v_partner.status <> 'active' then
    raise exception 'Your partner account is %, so it cannot hand a workspace over.', v_partner.status
      using errcode = '42501';
  end if;
  select pt.* into v_row
    from public.partner_tenants pt
   where pt.tenant_id = p_tenant and pt.partner_id = v_partner.id and pt.origin = 'handover'
   for update;
  if v_row.tenant_id is null then
    raise exception 'That is not a workspace you set up.' using errcode = 'P0002';
  end if;
  if v_row.handover_accepted_at is not null then
    raise exception 'That workspace already has its owner.' using errcode = '55000';
  end if;
  if length(v_email) > 254 or v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
    raise exception 'Enter the business owner''s email address.' using errcode = '22023';
  end if;
  select lower(u.email) into v_mine from auth.users u where u.id = v_user;
  if v_email = v_mine then
    raise exception 'That is your own address. Enter the business owner''s.' using errcode = '22023';
  end if;
  update public.partner_tenants pt
     set handover_email = v_email,
         handover_sent_at = now(),
         handover_expires_at = now() + interval '14 days',
         handover_declined_at = null
   where pt.tenant_id = p_tenant
  returning pt.* into v_row;
  insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
  values (p_tenant, 'partner.handover_sent', 'workspace', 'tenant', p_tenant,
          jsonb_build_object('partner_id', v_partner.id, 'by', v_user, 'again', true));
  return jsonb_build_object('tenant_id', v_row.tenant_id, 'email', v_row.handover_email,
                            'sent_at', v_row.handover_sent_at, 'expires_at', v_row.handover_expires_at);
end $_$;


--
-- Name: FUNCTION partner_handover_resend(p_tenant uuid, p_email text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.partner_handover_resend(p_tenant uuid, p_email text) IS 'The calling partner sends the handover of a workspace they set up again (0016), to the same address or another, open for fourteen more days. Refused once the workspace has its owner.';


--
-- Name: partner_invitations_lapse(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_invitations_lapse() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  delete from public.partner_invitations i where i.partner_id = new.id and i.declined_at is null;
  return new;
end $$;


--
-- Name: FUNCTION partner_invitations_lapse(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.partner_invitations_lapse() IS 'A partner who stops being active (paused, closed) loses the invitations waiting for them (0018): they could not join, and the owners who asked may ask someone else.';


--
-- Name: partner_invitations_mine(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_invitations_mine() RETURNS TABLE(tenant_id uuid, workspace text, sent_at timestamp with time zone, expires_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select i.tenant_id, t.name, i.sent_at, i.expires_at
    from public.partners p
    join public.partner_invitations i on i.partner_id = p.id
    join public.tenants t on t.id = i.tenant_id
   where p.user_id = auth.uid()
     and p.status = 'active'
     and i.declined_at is null
     and i.expires_at > now()
     and not exists (select 1 from public.partner_tenants pt where pt.tenant_id = i.tenant_id)
     and exists (select 1 from public.memberships m
                  where m.tenant_id = i.tenant_id and m.user_id = i.invited_by and m.role = 'owner')
   order by i.sent_at
$$;


--
-- Name: FUNCTION partner_invitations_mine(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.partner_invitations_mine() IS 'The invitations (0018) the calling partner can join: open, unanswered, from an owner who still is one, to a workspace with no partner, while the partner is active. Which workspace asked, when, and until when; the partner pane reads it.';


--
-- Name: partner_invite(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_invite(p_tenant uuid, p_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user    uuid := auth.uid();
  v_code    text := lower(btrim(coalesce(p_code, '')));
  v_partner public.partners;
  v_row     public.partner_invitations;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  if not public.is_workspace_owner(p_tenant) then
    raise exception 'Only an owner can bring in a partner.' using errcode = '42501';
  end if;
  if exists (select 1 from public.partner_tenants pt where pt.tenant_id = p_tenant) then
    raise exception 'This workspace already has a partner.' using errcode = '55000';
  end if;
  select p.* into v_partner from public.partners p where p.code = v_code;
  -- One refusal for a code that names nobody and one whose partner is paused or closed: which codes exist is not the
  -- caller's to learn a code at a time, as the /p/ page answers every code alike (0012).
  if v_partner.id is null or v_partner.status <> 'active' then
    raise exception 'No active partner has that code. Check it with them: it is the end of their link.'
      using errcode = 'P0002';
  end if;
  if v_partner.user_id = v_user then
    raise exception 'That is your own partner code: a partner is someone else who works with you.'
      using errcode = '22023';
  end if;
  if exists (select 1 from public.memberships m
              where m.tenant_id = p_tenant and m.user_id = v_partner.user_id and m.role = 'owner') then
    raise exception 'That partner owns this workspace already.' using errcode = '55000';
  end if;

  insert into public.partner_invitations (tenant_id, partner_id, invited_by, sent_at, expires_at, declined_at)
  values (p_tenant, v_partner.id, v_user, now(), now() + interval '14 days', null)
  on conflict (tenant_id) do update
    set partner_id = excluded.partner_id, invited_by = excluded.invited_by, sent_at = excluded.sent_at,
        expires_at = excluded.expires_at, declined_at = null
  returning * into v_row;
  -- Asked while the partner was joining: their accept held this row, took the seat and removed the invitation, and
  -- the insert above then wrote a new one for a workspace that has its partner now.
  if exists (select 1 from public.partner_tenants pt where pt.tenant_id = p_tenant) then
    raise exception 'This workspace already has a partner.' using errcode = '55000';
  end if;
  insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
  values (p_tenant, 'partner.invited', 'workspace', 'tenant', p_tenant,
          jsonb_build_object('partner_id', v_partner.id, 'by', v_user));
  return jsonb_build_object('code', v_partner.code, 'sent_at', v_row.sent_at, 'expires_at', v_row.expires_at);
end $$;


--
-- Name: FUNCTION partner_invite(p_tenant uuid, p_code text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.partner_invite(p_tenant uuid, p_code text) IS 'The workspace''s owner asks the partner with this code to join it (0018), for fourteen days; a second invitation replaces the first. Refused when the workspace has a partner, the code names nobody active (one refusal, whichever), or it is the caller''s own.';


--
-- Name: partner_invite_accept(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_invite_accept(p_tenant uuid) RETURNS TABLE(id uuid, slug text, name text, earns boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_user    uuid := auth.uid();
  v_partner public.partners;
  v_row     public.partner_invitations;
  v_paying  boolean;
  v_was     text;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  -- A partner's seat needs a session that showed its second factor (0013, 00218); joining one does too.
  if not public.session_shows_second_factor() then
    raise exception 'Enter the code from your authenticator app first: a partner signs in with two steps.'
      using errcode = '42501';
  end if;
  select p.* into v_partner from public.partners p where p.user_id = v_user;
  select i.* into v_row from public.partner_invitations i where i.tenant_id = p_tenant for update;
  -- Not found, and not "not yours": whether a workspace asked someone else is theirs to know.
  if v_partner.id is null or v_row.tenant_id is null or v_row.partner_id <> v_partner.id then
    raise exception 'There is no invitation for you there.' using errcode = 'P0002';
  end if;
  if v_partner.status <> 'active' then
    raise exception 'Your partner account is %, so it cannot join a workspace.', v_partner.status using errcode = '42501';
  end if;
  if v_row.declined_at is not null then
    raise exception 'You declined this invitation. Ask the owner to send it again.' using errcode = '55000';
  end if;
  if v_row.expires_at <= now() then
    raise exception 'This invitation has expired. Ask the owner to send it again.' using errcode = '55000';
  end if;
  if exists (select 1 from public.partner_tenants pt where pt.tenant_id = p_tenant) then
    raise exception 'This workspace already has a partner.' using errcode = '55000';
  end if;
  if public.is_workspace_owner(p_tenant) then
    raise exception 'You own this workspace, so you cannot be its partner.' using errcode = '55000';
  end if;
  -- An invitation stands while the owner who sent it is an owner here: one who left the team, was made something
  -- else, or deleted their account asks nobody now, and a workspace its owner left has no one to answer to.
  if v_row.invited_by is null or not exists (
       select 1 from public.memberships m
        where m.tenant_id = p_tenant and m.user_id = v_row.invited_by and m.role = 'owner') then
    raise exception 'The owner who asked you is no longer its owner. Ask the workspace to send it again.'
      using errcode = '55000';
  end if;

  -- Credit follows who brings the paying customer: a workspace that has paid for its plan, or pays outside Stripe,
  -- was not brought by this partner. The standing says so, marked as decided when they joined, and a platform admin
  -- may change it. A payment is a last_paid_at from the trial's end on, and none while the trial runs: until this
  -- change the edge stamped a trial's $0 first invoice too, at the trial's start, before the trial_end Stripe keeps on
  -- the row after a cancel; a workspace with no trial on record has no such stamp to discount.
  select coalesce(b.mode = 'direct'
                  or (b.last_paid_at is not null
                      and b.status <> 'trialing'
                      and b.last_paid_at >= coalesce(b.trial_end, '-infinity'::timestamptz)), false)
    into v_paying
    from public.billing_accounts b where b.tenant_id = p_tenant;
  v_paying := coalesce(v_paying, false);

  -- Someone already on the team (an operator, a viewer) becomes its partner: the owner asked for exactly them, and the
  -- event keeps the role they had.
  select m.role into v_was from public.memberships m where m.tenant_id = p_tenant and m.user_id = v_user;
  -- Never an owner's seat: one made an owner since the check above keeps it, and joins nothing.
  insert into public.memberships (tenant_id, user_id, role)
  values (p_tenant, v_user, 'partner')
  on conflict (user_id, tenant_id) do update set role = 'partner' where memberships.role <> 'owner';
  if not found then
    raise exception 'You own this workspace, so you cannot be its partner.' using errcode = '55000';
  end if;
  insert into public.partner_tenants
    (tenant_id, partner_id, code_used, origin, invited_by, standing, standing_why, standing_at, checks)
  values (p_tenant, v_partner.id, v_partner.code, 'invite', v_row.invited_by,
          case when v_paying then 'disqualified' end,
          case when v_paying then 'It was already paying for its plan when the partner joined, so it earns no share.' end,
          case when v_paying then now() end,
          case when v_paying then jsonb_build_object('already_paying', true) else '{}'::jsonb end);
  if v_paying then
    insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
    values (p_tenant, 'partner.standing_set', 'billing', 'tenant', p_tenant,
            jsonb_build_object('partner_id', v_partner.id, 'standing', 'disqualified', 'by', 'joining'));
  end if;
  delete from public.partner_invitations i where i.tenant_id = p_tenant;
  insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
  values (p_tenant, 'partner.invite_accepted', 'workspace', 'tenant', p_tenant,
          jsonb_build_object('partner_id', v_partner.id, 'by', v_user, 'earns', not v_paying, 'was', v_was));

  return query select t.id, t.slug, t.name, not v_paying from public.tenants t where t.id = p_tenant;
end $_$;


--
-- Name: FUNCTION partner_invite_accept(p_tenant uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.partner_invite_accept(p_tenant uuid) IS 'The invited partner joins the workspace (0018), on a session that showed its second factor: seated as partner, credited as its partner, and earning from its plan unless it was already paying when they joined.';


--
-- Name: partner_invite_decline(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_invite_decline(p_tenant uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user uuid := auth.uid();
  v_row  public.partner_invitations;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  select i.* into v_row
    from public.partner_invitations i join public.partners p on p.id = i.partner_id
   where i.tenant_id = p_tenant and p.user_id = v_user
   for update of i;
  if v_row.tenant_id is null then
    raise exception 'There is no invitation for you there.' using errcode = 'P0002';
  end if;
  if v_row.declined_at is not null then
    return;
  end if;
  update public.partner_invitations i set declined_at = now() where i.tenant_id = p_tenant;
  insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
  values (p_tenant, 'partner.invite_declined', 'workspace', 'tenant', p_tenant,
          jsonb_build_object('partner_id', v_row.partner_id, 'by', v_user));
end $$;


--
-- Name: FUNCTION partner_invite_decline(p_tenant uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.partner_invite_decline(p_tenant uuid) IS 'The invited partner says no (0018). The owner sees it on their card and may ask again, or ask someone else.';


--
-- Name: partner_invite_withdraw(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_invite_withdraw(p_tenant uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user uuid := auth.uid();
  v_row  public.partner_invitations;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  if not public.is_workspace_owner(p_tenant) then
    raise exception 'Only an owner can take back an invitation.' using errcode = '42501';
  end if;
  delete from public.partner_invitations i where i.tenant_id = p_tenant returning * into v_row;
  if v_row.tenant_id is not null then
    insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
    values (p_tenant, 'partner.invite_withdrawn', 'workspace', 'tenant', p_tenant,
            jsonb_build_object('partner_id', v_row.partner_id, 'by', v_user));
  end if;
end $$;


--
-- Name: FUNCTION partner_invite_withdraw(p_tenant uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.partner_invite_withdraw(p_tenant uuid) IS 'The workspace''s owner takes back the invitation to a partner (0018) before it is answered. Nothing to take back is not an error.';


--
-- Name: partner_letter_written(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_letter_written(p_partner uuid, p_through timestamp with time zone) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  -- Forward only: a slow tick finishing after a faster one never moves the mark back.
  with moved as (
    update public.partners
       set written_through = p_through
     where id = p_partner and written_through < p_through
    returning id
  )
  select exists (select 1 from moved)
$$;


--
-- Name: FUNCTION partner_letter_written(p_partner uuid, p_through timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.partner_letter_written(p_partner uuid, p_through timestamp with time zone) IS 'For the edge alone (0014): the letter through p_through went; the partner''s mark moves forward to it, never back.';


--
-- Name: partner_letters_due(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_letters_due(p_now timestamp with time zone DEFAULT now()) RETURNS TABLE(partner_id uuid, email text, code text, status text, since timestamp with time zone, through timestamp with time zone, news jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with who as (
    select p.id, u.email::text as email, p.code, p.status, p.status_why, p.status_at, p.written_through as since
      from public.partners p
      join auth.users u on u.id = p.user_id
     where p.letters
       and p.written_through < p_now
       and coalesce(u.email, '') <> ''
       -- A closed partner hears one thing more: that they were closed.
       and (p.status <> 'closed' or p.status_at > p.written_through)
  ),
  written as (
    select w.id,
           coalesce(jsonb_agg(jsonb_build_object('kind', e.kind, 'currency', e.currency,
                                                 'count', e.n, 'cents', e.cents)
                              order by e.kind, e.currency) filter (where e.kind is not null), '[]') as rows
      from who w
      left join lateral (
        select x.kind, x.currency, count(*)::int as n, sum(x.earned_cents)::bigint as cents
          from public.partner_earnings x
         where x.partner_id = w.id and x.created_at > w.since and x.created_at <= p_now and x.state <> 'void'
         group by x.kind, x.currency
      ) e on true
     group by w.id
  ),
  matured as (
    -- Rows that were written before the last letter and became payable since: the thirty days, or a person's yes.
    select w.id,
           coalesce(jsonb_agg(jsonb_build_object('currency', m.currency, 'cents', m.cents)
                              order by m.currency) filter (where m.currency is not null), '[]') as rows
      from who w
      left join lateral (
        select x.currency, sum(x.earned_cents)::bigint as cents
          from public.partner_earnings x
         where x.partner_id = w.id and x.state = 'payable'
           and x.created_at <= w.since and x.updated_at > w.since and x.updated_at <= p_now
         group by x.currency
      ) m on true
     group by w.id
  ),
  voided as (
    select w.id,
           coalesce(jsonb_agg(jsonb_build_object('currency', v.currency, 'cents', v.cents)
                              order by v.currency) filter (where v.currency is not null), '[]') as rows
      from who w
      left join lateral (
        select x.currency, sum(x.earned_cents)::bigint as cents
          from public.partner_earnings x
         where x.partner_id = w.id and x.state = 'void' and x.earned_cents > 0
           and x.updated_at > w.since and x.updated_at <= p_now
         group by x.currency
      ) v on true
     group by w.id
  ),
  paid as (
    select w.id,
           coalesce(jsonb_agg(jsonb_build_object('currency', o.currency, 'cents', o.total_cents,
                                                 'reference', o.reference, 'sent_at', o.sent_at)
                              order by o.sent_at) filter (where o.id is not null), '[]') as rows
      from who w
      left join public.partner_payouts o
        on o.partner_id = w.id and o.sent_at > w.since and o.sent_at <= p_now
     group by w.id
  ),
  standing as (
    -- A workspace held for review, or a person's decision on one. The sweep's own "qualified" is the ordinary path,
    -- not news; a person's is the answer to a review.
    select w.id,
           coalesce(jsonb_agg(jsonb_build_object('workspace', t.name, 'standing', pt.standing,
                                                 'why', case when pt.standing_by is not null then pt.standing_why end)
                              order by pt.standing_at) filter (where pt.tenant_id is not null), '[]') as rows
      from who w
      left join public.partner_tenants pt
        on pt.partner_id = w.id and pt.standing_at > w.since and pt.standing_at <= p_now
       and (pt.standing in ('review', 'disqualified') or pt.standing_by is not null)
       -- Decided as the partner joined at an invitation (0018): they were told then, as they know a handover they made.
       and not (pt.standing_by is null and pt.checks ? 'already_paying')
      left join public.tenants t on t.id = pt.tenant_id
     group by w.id
  ),
  brought as (
    select w.id,
           coalesce(jsonb_agg(t.name order by pt.attributed_at) filter (where pt.tenant_id is not null), '[]') as rows
      from who w
      left join public.partner_tenants pt
        on pt.partner_id = w.id and pt.origin = 'link'
       and pt.attributed_at > w.since and pt.attributed_at <= p_now
      left join public.tenants t on t.id = pt.tenant_id
     group by w.id
  ),
  -- A handover is news when its owner answers it (0016), not when the partner made it: they know that already.
  accepted as (
    select w.id,
           coalesce(jsonb_agg(t.name order by pt.handover_accepted_at) filter (where pt.tenant_id is not null), '[]')
             as rows
      from who w
      left join public.partner_tenants pt
        on pt.partner_id = w.id and pt.origin = 'handover'
       and pt.handover_accepted_at > w.since and pt.handover_accepted_at <= p_now
      left join public.tenants t on t.id = pt.tenant_id
     group by w.id
  ),
  declined as (
    select w.id,
           coalesce(jsonb_agg(t.name order by pt.handover_declined_at) filter (where pt.tenant_id is not null), '[]')
             as rows
      from who w
      left join public.partner_tenants pt
        on pt.partner_id = w.id and pt.origin = 'handover'
       and pt.handover_declined_at > w.since and pt.handover_declined_at <= p_now
      left join public.tenants t on t.id = pt.tenant_id
     group by w.id
  ),
  now_stand as (
    select w.id,
           coalesce(jsonb_agg(jsonb_build_object('currency', b.currency, 'held', b.held, 'payable', b.payable,
                                                 'paid', b.paid, 'next_payable_at', b.next_at)
                              order by b.currency) filter (where b.currency is not null), '[]') as rows
      from who w
      left join lateral (
        select x.currency,
               coalesce(sum(x.earned_cents) filter (where x.state = 'held'), 0)::bigint as held,
               coalesce(sum(x.earned_cents) filter (where x.state = 'payable'), 0)::bigint as payable,
               coalesce(sum(x.earned_cents) filter (where x.state = 'paid'), 0)::bigint as paid,
               min(x.payable_at) filter (where x.state = 'held') as next_at
          from public.partner_earnings x
         where x.partner_id = w.id and x.state <> 'void'
         group by x.currency
      ) b on true
     group by w.id
  )
  select w.id, w.email, w.code, w.status, w.since, p_now,
         jsonb_build_object(
           'written', wr.rows,
           'matured', m.rows,
           'voided', v.rows,
           'paid', pd.rows,
           'standing', s.rows,
           'brought', br.rows,
           'accepted', ac.rows,
           'declined', dc.rows,
           'status', case when w.status_at > w.since and w.status_at <= p_now
                          then jsonb_build_object('status', w.status, 'why', w.status_why) end,
           'balance', ns.rows)
    from who w
    join written wr on wr.id = w.id
    join matured m on m.id = w.id
    join voided v on v.id = w.id
    join paid pd on pd.id = w.id
    join standing s on s.id = w.id
    join brought br on br.id = w.id
    join accepted ac on ac.id = w.id
    join declined dc on dc.id = w.id
    join now_stand ns on ns.id = w.id
   where jsonb_array_length(wr.rows) > 0
      or jsonb_array_length(m.rows) > 0
      or jsonb_array_length(v.rows) > 0
      or jsonb_array_length(pd.rows) > 0
      or jsonb_array_length(s.rows) > 0
      or jsonb_array_length(br.rows) > 0
      or jsonb_array_length(ac.rows) > 0
      or jsonb_array_length(dc.rows) > 0
      or (w.status_at > w.since and w.status_at <= p_now)
   order by w.id
$$;


--
-- Name: FUNCTION partner_letters_due(p_now timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.partner_letters_due(p_now timestamp with time zone) IS 'For the edge alone (0014): each partner with letters on, an address, and a change to their ledger since written_through -- shares and reversals written, shares that became payable or void, payouts sent, workspaces brought through the link, handovers accepted or declined, held for review or decided by a person (not what was decided as they joined a workspace that asked them, 0018), their own status -- with where they stand now.';


--
-- Name: partner_letters_set(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_letters_set(p_on boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user  uuid := auth.uid();
  v_on    boolean;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  if p_on is null then
    raise exception 'Say on or off.' using errcode = '22023';
  end if;
  -- Turning it on starts from now: what changed while it was off is on the pane, not in a first long letter.
  update public.partners
     set letters = p_on,
         written_through = case when p_on and not letters then greatest(written_through, now()) else written_through end
   where user_id = v_user
  returning letters into v_on;
  if v_on is null then
    raise exception 'You are not a partner.' using errcode = 'P0002';
  end if;
  return v_on;
end $$;


--
-- Name: FUNCTION partner_letters_set(p_on boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.partner_letters_set(p_on boolean) IS 'The calling partner turns their daily letter on or off (0014). On starts from now.';


--
-- Name: partner_overview(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_overview() RETURNS TABLE(tenant_id uuid, slug text, name text, status text, timezone text, created_at timestamp with time zone, members integer, billing_mode text, billing_status text, trial_end timestamp with time zone, current_period_end timestamp with time zone, line_e164 text, line_kind text, voice_state text, sms_state text, reg_step text, reg_mock boolean, reg_sole_prop boolean, line_error text, whatsapp_number text, whatsapp_active boolean, voice_number text, voice_active boolean, last_inbound_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  -- The caller's own workspaces as partner, and only while the partner seat is theirs: the list is the check.
  return query
    select * from public.platform_overview_rows_for(array(
      select pt.tenant_id
        from public.partner_tenants pt
        join public.partners p on p.id = pt.partner_id
        join public.memberships m on m.tenant_id = pt.tenant_id and m.user_id = p.user_id and m.role = 'partner'
       where p.user_id = (select auth.uid()) and public.session_shows_second_factor()
    ));
end $$;


--
-- Name: FUNCTION partner_overview(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.partner_overview() IS 'The back office''s row (platform_overview_rows_for) for each workspace the calling partner brought and still sits on the team of (0012, P4). A caller who is no partner, or holds no seat, gets no rows.';


--
-- Name: partner_payout_mark(uuid, text, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_payout_mark(p_partner uuid, p_currency text, p_reference text, p_expected_cents bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_ref      text := nullif(btrim(coalesce(p_reference, '')), '');
  v_cur      text := lower(btrim(coalesce(p_currency, '')));
  v_ids      uuid[];
  v_total    bigint;
  v_count    int;
  v_first    timestamptz;
  v_last     timestamptz;
  v_payout   uuid;
begin
  if not public.is_platform_admin() then
    raise exception 'Not a Chanlytics platform admin.' using errcode = '42501';
  end if;
  if v_ref is null or length(v_ref) > 200 then
    raise exception 'Give the payment''s reference, in at most 200 characters.' using errcode = '22023';
  end if;
  if v_cur !~ '^[a-z]{3}$' then
    raise exception 'Unknown currency: %', p_currency using errcode = '22023';
  end if;
  perform 1 from public.partners where id = p_partner for update;
  if not found then
    raise exception 'No such partner.' using errcode = 'P0002';
  end if;

  -- The rows are locked and counted in one statement, and exactly those are settled: a row the sweep, a standing
  -- or a refund makes payable meanwhile waits for the next payout. A share of a workspace under review or
  -- disqualified is not settled; every reversal is.
  select coalesce(array_agg(d.id), '{}'), coalesce(sum(d.earned_cents), 0), count(*), min(d.paid_at), max(d.paid_at)
    into v_ids, v_total, v_count, v_first, v_last
    from (select e.id, e.earned_cents, e.paid_at
            from public.partner_earnings e
           where e.partner_id = p_partner and e.currency = v_cur and e.state = 'payable'
             and (e.earned_cents < 0 or e.tenant_id is null
                  or exists (select 1 from public.partner_tenants pt
                              where pt.tenant_id = e.tenant_id and pt.standing = 'qualified'))
             for update of e) d;

  if p_expected_cents is not null and v_total <> p_expected_cents then
    -- What is payable moved since the page was read: nothing is recorded until the person sees the new number.
    return jsonb_build_object('paid', false, 'changed', true, 'total_cents', v_total, 'currency', v_cur);
  end if;
  if v_count = 0 or v_total <= 0 then
    return jsonb_build_object('paid', false, 'total_cents', v_total, 'currency', v_cur);
  end if;

  insert into public.partner_payouts
    (partner_id, currency, total_cents, earnings, period_start, period_end, reference, sent_by)
  values (p_partner, v_cur, v_total, v_count, v_first, v_last, v_ref, auth.uid())
  returning id into v_payout;

  update public.partner_earnings set state = 'paid', payout_id = v_payout where id = any (v_ids);

  insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
  select e.tenant_id, 'partner.paid', 'billing', 'tenant', e.tenant_id,
         jsonb_build_object('partner_id', p_partner, 'payout_id', v_payout, 'earned_cents', sum(e.earned_cents),
                            'currency', v_cur, 'by', auth.uid())
    from public.partner_earnings e
   where e.payout_id = v_payout and e.tenant_id is not null
   group by e.tenant_id;

  return jsonb_build_object('paid', true, 'payout_id', v_payout, 'total_cents', v_total, 'earnings', v_count,
                            'currency', v_cur);
end $_$;


--
-- Name: FUNCTION partner_payout_mark(p_partner uuid, p_currency text, p_reference text, p_expected_cents bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.partner_payout_mark(p_partner uuid, p_currency text, p_reference text, p_expected_cents bigint) IS 'A platform admin records a payout sent by hand to a partner (0012, P5): the payable shares of qualified workspaces and every reversal in the currency, locked and settled together. Refused (paid: false, changed: true) when the total is not p_expected_cents; nothing is written when the net is not above zero.';


--
-- Name: partner_reverse(text, text, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_reverse(p_invoice_id text, p_event_id text, p_kind text, p_amount_cents bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_share   public.partner_earnings;
  v_all     bigint;
  v_same    bigint;
  v_target  bigint;
  v_delta   bigint;
  v_state   text;
  v_at      timestamptz;
  v_row     public.partner_earnings;
begin
  if p_kind not in ('refund', 'dispute', 'dispute_won') then
    raise exception 'Unknown reversal: %', p_kind using errcode = '22023';
  end if;
  select * into v_share from public.partner_earnings
   where stripe_invoice_id = p_invoice_id and kind = 'share'
   for update;
  if v_share.id is null then
    -- No share yet: it may still come (a retried invoice.paid, a replay). Kept, and applied when it is written.
    insert into public.partner_reversals_waiting (stripe_event_id, stripe_invoice_id, kind, amount_cents)
    values (p_event_id, p_invoice_id, p_kind, greatest(coalesce(p_amount_cents, 0), 0))
    on conflict (stripe_event_id) do nothing;
    return null;
  end if;
  select coalesce(sum(e.earned_cents), 0) into v_all
    from public.partner_earnings e where e.stripe_invoice_id = p_invoice_id and e.kind <> 'share';

  if p_kind = 'refund' then
    select coalesce(sum(e.earned_cents), 0) into v_same
      from public.partner_earnings e where e.stripe_invoice_id = p_invoice_id and e.kind = 'refund';
    v_target := -floor(greatest(p_amount_cents, 0)::numeric * v_share.share_bp / 10000);
    v_delta := v_target - v_same;
  elsif p_kind = 'dispute' then
    select coalesce(sum(e.earned_cents), 0) into v_same
      from public.partner_earnings e where e.stripe_invoice_id = p_invoice_id and e.kind in ('dispute', 'dispute_won');
    v_target := -floor(greatest(p_amount_cents, 0)::numeric * v_share.share_bp / 10000);
    v_delta := v_target - v_same;
  else
    select coalesce(sum(e.earned_cents), 0) into v_same
      from public.partner_earnings e where e.stripe_invoice_id = p_invoice_id and e.kind in ('dispute', 'dispute_won');
    v_delta := -v_same;
  end if;

  -- A refund or a dispute only ever takes (00203).
  if p_kind in ('refund', 'dispute') and v_delta >= 0 then
    return null;
  end if;
  if v_share.earned_cents + v_all + v_delta < 0 then
    v_delta := -(v_share.earned_cents + v_all);
  end if;
  if v_share.earned_cents + v_all + v_delta > v_share.earned_cents then
    v_delta := -v_all;
  end if;
  if v_delta = 0 then
    return null;
  end if;

  if v_share.state = 'held' then
    v_state := 'held';
    v_at := v_share.payable_at;
  elsif v_share.state = 'void' then
    v_state := 'void';
    v_at := v_share.payable_at;
  else
    v_state := 'payable';
    v_at := now();
  end if;

  insert into public.partner_earnings
    (partner_id, tenant_id, stripe_invoice_id, stripe_event_id, kind, amount_cents, currency, share_bp,
     earned_cents, paid_at, payable_at, state)
  values
    (v_share.partner_id, v_share.tenant_id, p_invoice_id, p_event_id, p_kind, greatest(p_amount_cents, 0),
     v_share.currency, v_share.share_bp, v_delta, now(), v_at, v_state)
  on conflict (stripe_event_id) do nothing
  returning * into v_row;
  if v_row.id is null then
    return null;
  end if;
  -- A workspace deleted since has no events to write to (events.tenant_id is not null).
  if v_share.tenant_id is not null then
    insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
    values (v_share.tenant_id, 'partner.reversed', 'billing', 'tenant', v_share.tenant_id,
            jsonb_build_object('partner_id', v_share.partner_id, 'invoice', p_invoice_id, 'kind', p_kind,
                               'earned_cents', v_delta, 'currency', v_share.currency));
  end if;
  return jsonb_build_object('id', v_row.id, 'earned_cents', v_delta, 'state', v_state);
end $$;


--
-- Name: FUNCTION partner_reverse(p_invoice_id text, p_event_id text, p_kind text, p_amount_cents bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.partner_reverse(p_invoice_id text, p_event_id text, p_kind text, p_amount_cents bigint) IS 'A refund, a dispute or a won dispute of an invoice a partner earned a share of (0012): the difference it makes to the share, capped so the share is taken at most once and given back at most once. Null when there is no share or nothing changes.';


--
-- Name: partner_second_factor_reset(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_second_factor_reset(p_partner uuid, p_why text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_partner public.partners;
  v_why     text := nullif(btrim(coalesce(p_why, '')), '');
begin
  if not public.is_platform_admin() then
    raise exception 'Not a Chanlytics platform admin.' using errcode = '42501';
  end if;
  if v_why is null or length(v_why) > 500 then
    raise exception 'Say why, in at most 500 characters.' using errcode = '22023';
  end if;
  select * into v_partner from public.partners where id = p_partner for update;
  if v_partner.id is null then
    raise exception 'No such partner.' using errcode = 'P0002';
  end if;
  if v_partner.user_id is null then
    raise exception 'That partner erased their account: there is no sign-in to reset.' using errcode = '55000';
  end if;

  update public.partners
     set second_factor_reset_at = now(), second_factor_reset_by = auth.uid(), second_factor_reset_why = v_why
   where id = p_partner;

  insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
  select m.tenant_id, 'platform.acted', 'platform', 'tenant', m.tenant_id,
         jsonb_build_object('action', 'partner_second_factor_reset', 'partner_id', p_partner, 'by', auth.uid())
    from public.memberships m
   where m.user_id = v_partner.user_id and m.role = 'partner';

  return v_partner.user_id;
end $$;


--
-- Name: FUNCTION partner_second_factor_reset(p_partner uuid, p_why text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.partner_second_factor_reset(p_partner uuid, p_why text) IS 'A platform admin records the reset of a partner''s second factor (0013, M2), with why, and learns whose account to act on: the dashboard then removes the factor in Supabase Auth. Written as platform.acted on each workspace the partner sits on.';


--
-- Name: partner_standing_set(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_standing_set(p_tenant uuid, p_standing text, p_why text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_link     public.partner_tenants;
  v_why      text := nullif(btrim(coalesce(p_why, '')), '');
  v_voided   int := 0;
  v_matured  int := 0;
begin
  if not public.is_platform_admin() then
    raise exception 'Not a Chanlytics platform admin.' using errcode = '42501';
  end if;
  if p_standing is null or p_standing not in ('qualified', 'review', 'disqualified') then
    raise exception 'Unknown standing: %', p_standing using errcode = '22023';
  end if;
  if v_why is null or length(v_why) > 500 then
    raise exception 'Say why, in at most 500 characters.' using errcode = '22023';
  end if;

  select * into v_link from public.partner_tenants where tenant_id = p_tenant for update;
  if v_link.tenant_id is null then
    raise exception 'No partner brought that workspace.' using errcode = 'P0002';
  end if;

  update public.partner_tenants
     set standing = p_standing, standing_why = v_why, standing_by = auth.uid(), standing_at = now()
   where tenant_id = p_tenant;

  if p_standing = 'disqualified' then
    -- Every share not yet paid is void, held or payable. A reversal stays: it is money owed back, not earned.
    update public.partner_earnings set state = 'void'
     where tenant_id = p_tenant and state in ('held', 'payable') and earned_cents > 0;
    get diagnostics v_voided = row_count;
  elsif p_standing = 'qualified' then
    update public.partner_earnings e
       set state = 'payable'
      from public.partners p
     where e.tenant_id = p_tenant and e.state = 'held' and e.payable_at <= now()
       and p.id = e.partner_id and p.status = 'active';
    get diagnostics v_matured = row_count;
  end if;

  insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
  values
    (p_tenant, 'platform.acted', 'platform', 'tenant', p_tenant,
     jsonb_build_object('action', 'partner_standing', 'standing', p_standing, 'from', v_link.standing,
                        'by', auth.uid())),
    (p_tenant, 'partner.standing_set', 'billing', 'tenant', p_tenant,
     jsonb_build_object('partner_id', v_link.partner_id, 'standing', p_standing, 'from', v_link.standing,
                        'by', 'person', 'voided', v_voided, 'matured', v_matured));

  return jsonb_build_object('tenant_id', p_tenant, 'standing', p_standing, 'from', v_link.standing,
                            'voided', v_voided, 'matured', v_matured);
end $$;


--
-- Name: FUNCTION partner_standing_set(p_tenant uuid, p_standing text, p_why text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.partner_standing_set(p_tenant uuid, p_standing text, p_why text) IS 'A platform admin decides the standing of a workspace a partner brought (0012, P5), with why. Disqualified voids what it held; qualified makes what is past its hold payable. Recorded as platform.acted and partner.standing_set on the workspace.';


--
-- Name: partner_status_set(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_status_set(p_partner uuid, p_status text, p_why text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_partner   public.partners;
  v_why       text := nullif(btrim(coalesce(p_why, '')), '');
  v_tenants   uuid[];
  v_seats     int := 0;
begin
  if not public.is_platform_admin() then
    raise exception 'Not a Chanlytics platform admin.' using errcode = '42501';
  end if;
  if p_status is null or p_status not in ('active', 'paused', 'closed') then
    raise exception 'Unknown status: %', p_status using errcode = '22023';
  end if;
  if v_why is null or length(v_why) > 500 then
    raise exception 'Say why, in at most 500 characters.' using errcode = '22023';
  end if;
  select * into v_partner from public.partners where id = p_partner for update;
  if v_partner.id is null then
    raise exception 'No such partner.' using errcode = 'P0002';
  end if;

  if p_status = 'paused' then
    -- Every partner seat becomes a viewer's, and the workspace remembers when; what they held is released (00132).
    with taken as (
      update public.memberships m
         set role = 'viewer'
        from public.partner_tenants pt
       where pt.partner_id = p_partner and m.tenant_id = pt.tenant_id
         and m.user_id = v_partner.user_id and m.role = 'partner'
      returning m.tenant_id
    )
    select coalesce(array_agg(tenant_id), '{}') into v_tenants from taken;
    update public.partner_tenants set seat_held_at = now()
     where partner_id = p_partner and tenant_id = any (v_tenants);
    update public.conversations set assignee_user_id = null
     where tenant_id = any (v_tenants) and assignee_user_id = v_partner.user_id;
    update public.conversations
       set control_kind = null, control_by = null, control_ref = null, control_until = null
     where tenant_id = any (v_tenants) and control_kind = 'person' and control_by = v_partner.user_id;
  elsif p_status = 'closed' then
    -- Off every team: their partner seats, and the viewer seats a pause left them. The departure trigger (00132)
    -- releases what they held. Nothing comes back from a close.
    with gone as (
      delete from public.memberships m
       using public.partner_tenants pt
       where pt.partner_id = p_partner and m.tenant_id = pt.tenant_id and m.user_id = v_partner.user_id
         and (m.role = 'partner'
              or (m.role = 'viewer' and pt.seat_held_at is not null and m.created_at <= pt.seat_held_at))
      returning m.tenant_id
    )
    select coalesce(array_agg(tenant_id), '{}') into v_tenants from gone;
    update public.partner_tenants set seat_held_at = null where partner_id = p_partner;
  else
    -- Restored: only the seats a pause took, still a viewer's, and made before the pause. A person the owner
    -- removed and invited back since is the owner's choice, not the pause's.
    with given as (
      update public.memberships m
         set role = 'partner'
        from public.partner_tenants pt
       where pt.partner_id = p_partner and pt.seat_held_at is not null and m.tenant_id = pt.tenant_id
         and m.user_id = v_partner.user_id and m.role = 'viewer' and m.created_at <= pt.seat_held_at
      returning m.tenant_id
    )
    select coalesce(array_agg(tenant_id), '{}') into v_tenants from given;
    update public.partner_tenants set seat_held_at = null where partner_id = p_partner and seat_held_at is not null;
  end if;
  v_seats := coalesce(array_length(v_tenants, 1), 0);

  update public.partners
     set status = p_status, status_why = v_why, status_by = auth.uid(), status_at = now()
   where id = p_partner;

  insert into public.events (tenant_id, kind, category, subject_type, subject_id, data)
  select t, 'platform.acted', 'platform', 'tenant', t,
         jsonb_build_object('action', 'partner_status', 'status', p_status, 'from', v_partner.status,
                            'by', auth.uid())
    from unnest(v_tenants) as t;

  return jsonb_build_object('partner_id', p_partner, 'status', p_status, 'from', v_partner.status, 'seats', v_seats);
end $$;


--
-- Name: FUNCTION partner_status_set(p_partner uuid, p_status text, p_why text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.partner_status_set(p_partner uuid, p_status text, p_why text) IS 'A platform admin pauses, closes or restores a partner (0012), with why, kept on the partner row. A pause makes each partner seat a viewer''s and releases what they held; a close takes them off every team; a restore gives back only the seats a pause took, made before it.';


--
-- Name: partner_workspace_money(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.partner_workspace_money() RETURNS TABLE(tenant_id uuid, name text, on_team boolean, standing text, currency text, held_cents bigint, payable_cents bigint, paid_cents bigint, month_cents bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select pt.tenant_id,
         t.name,
         exists (select 1 from public.memberships m
                  where m.tenant_id = pt.tenant_id and m.user_id = p.user_id and m.role = 'partner'),
         pt.standing,
         coalesce(e.currency, 'usd'),
         coalesce(e.held, 0)::bigint,
         coalesce(e.payable, 0)::bigint,
         coalesce(e.paid, 0)::bigint,
         coalesce(e.month, 0)::bigint
    from public.partner_tenants pt
    join public.partners p on p.id = pt.partner_id
    join public.tenants t on t.id = pt.tenant_id
    left join lateral (
      select x.currency,
             sum(x.earned_cents) filter (where x.state = 'held') as held,
             sum(x.earned_cents) filter (where x.state = 'payable') as payable,
             sum(x.earned_cents) filter (where x.state = 'paid') as paid,
             sum(x.earned_cents) filter (where x.kind = 'share' and x.state <> 'void'
                                           and x.paid_at >= date_trunc('month', now())) as month
        from public.partner_earnings x
       where x.tenant_id = pt.tenant_id and x.partner_id = pt.partner_id
       group by x.currency
    ) e on true
   where p.user_id = (select auth.uid()) and public.session_shows_second_factor()
   order by t.name, e.currency
$$;


--
-- Name: FUNCTION partner_workspace_money(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.partner_workspace_money() IS 'For each workspace the calling partner brought (0012, P4), on its team or not: whether they still sit on it, its standing, and its earnings held, payable, paid, and from this month''s payments, by currency. Answers about the caller alone.';


--
-- Name: people_list(uuid, uuid, text, integer, integer, timestamp with time zone, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.people_list(p_tenant_id uuid, p_contact_id uuid DEFAULT NULL::uuid, p_query text DEFAULT NULL::text, p_limit integer DEFAULT 1000, p_offset integer DEFAULT 0, p_after_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_after_added timestamp with time zone DEFAULT NULL::timestamp with time zone, p_after_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, display_name text, wa_profile_name text, phone_e164 text, email text, consent text, consent_source text, consent_updated_at timestamp with time zone, dnc boolean, marketing_consent text, marketing_consent_source text, marketing_consent_updated_at timestamp with time zone, channels text[], conversation_count integer, escalation_count integer, needs_human boolean, open_escalation_reason text, open_escalation_since timestamp with time zone, latest_conversation_id uuid, latest_state text, latest_paused_until timestamp with time zone, latest_assignee_user_id uuid, latest_snooze_until timestamp with time zone, latest_wa_inbound_at timestamp with time zone, last_message_at timestamp with time zone, last_message_direction text, last_message_sender text, last_inbound_text text, last_inbound_at timestamp with time zone, last_call_at timestamp with time zone, last_inbound_call_at timestamp with time zone, last_inbound_call_summary text, call_count integer, call_seconds integer, first_contact_at timestamp with time zone, earliest_row_at timestamp with time zone, has_backfill boolean, has_chat boolean, message_channels text[], queued_reply_at timestamp with time zone, came_from text, deal_id uuid, deal_stage text, deal_service text, deal_proposed_at timestamp with time zone, deal_decided_at timestamp with time zone, deal_ended_at timestamp with time zone, deal_amount_cents integer, deal_per text, deal_proposal_url text, deal_valid_until date, deal_lost_reason text, step_id uuid, step_body text, step_due_on date, step_for_user_id uuid, step_deal_id uuid, in_touch_at timestamp with time zone, added_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  -- The page first (0021): its people, in the kept order, after the cursor or the offset, and nobody else. Every read
  -- below is for them alone.
  with page as (
    select p.id, p.display_name, p.wa_profile_name, p.phone_e164, p.email,
           p.consent, p.consent_source, p.consent_updated_at, p.dnc,
           p.marketing_consent, p.marketing_consent_source, p.marketing_consent_updated_at,
           p.in_touch_at, p.added_at
      from people_page(p_tenant_id, p_contact_id, p_query, p_limit, p_offset, p_after_at, p_after_added, p_after_id) p
  ),
  ev as not materialized (
    select m.contact_id, m.direction, m.sender, m.type, m.channel, m.body, m.status, m.created_at,
           e.at, e.moved_in as backfill, e.spoken
      from messages m
      -- When it happened, whether the customer saw or said it, and whether it came with a history moved in: the one
      -- statement of the three (00259), which the kept moments read too.
      cross join lateral message_moment(m.meta, m.channel_ts, m.created_at, m.type, m.status) e
     where m.tenant_id = p_tenant_id
       and m.contact_id is not null
       and (p_contact_id is null or m.contact_id = p_contact_id)
  )
  select
    c.id, c.display_name, c.wa_profile_name, c.phone_e164, c.email,
    c.consent, c.consent_source, c.consent_updated_at, c.dnc,
    c.marketing_consent, c.marketing_consent_source, c.marketing_consent_updated_at,
    coalesce(ids.channels, '{}'::text[]),
    coalesce(cvs.n, 0),
    coalesce(esc.n, 0),
    coalesce(cvs.needs_human, false),
    oe.reason,
    oe.created_at,
    lc.id, lc.state, lc.paused_until, lc.assignee_user_id, lc.snooze_until, lc.last_wa_inbound_at,
    lm.at, lm.direction, lm.sender,
    li.body, li.at,
    lk.last_at,
    lk.last_inbound_at,
    lks.summary,
    coalesce(lk.n, 0),
    coalesce(lk.seconds, 0),
    least(ma.first_at, lk.first_at),
    least(ma.first_row_at, lk.first_row_at),
    coalesce(ma.has_backfill, false),
    coalesce(ma.has_chat, false),
    coalesce(ma.channels, '{}'::text[]),
    ma.queued_at,
    -- Where they came from: how they were added, else how a history moved in
    -- began, else their first spoken event.
    case
      when ad.source = 'calendar' then 'calendar'
      when ad.source = 'lead' then 'lead'
      when ad.source = 'import' then 'import'
      when ad.source is not null then 'manual'
      when coalesce(ma.has_backfill, false) then case when ma.backfill_first in ('call', 'whatsapp', 'sms', 'email') then ma.backfill_first else 'import' end
      when lk.first_at is not null and (ma.first_at is null or lk.first_at <= ma.first_at) then 'call'
      when ma.first_channel in ('whatsapp', 'sms', 'email') then ma.first_channel
    end,
    dl.id, dl.stage, dl.service, dl.proposed_at, dl.decided_at, dl.ended_at, dl.amount_cents, dl.per,
    dl.proposal_url, dl.valid_until, dl.lost_reason,
    st.id, st.body, st.due_on, st.for_user_id, st.deal_id,
    c.in_touch_at, c.added_at
  from page c
  left join lateral (
    -- How they were added, when a door added them: their first contact.added
    -- event, should a door ever write two.
    select coalesce(e.data->>'source', 'manual') as source
      from events e
     where e.tenant_id = p_tenant_id
       and e.subject_type = 'contact'
       and e.subject_id = c.id
       and e.kind = 'contact.added'
     order by e.created_at
     limit 1
  ) ad on true
  left join lateral (
    select array_agg(distinct ci.channel order by ci.channel) as channels
      from contact_identities ci where ci.contact_id = c.id
  ) ids on true
  left join lateral (
    select count(*)::int as n, bool_or(cv.state = 'needs_human') as needs_human
      from conversations cv where cv.contact_id = c.id
  ) cvs on true
  left join lateral (
    select count(*)::int as n
      from escalations e join conversations cv on cv.id = e.conversation_id
     where cv.contact_id = c.id
  ) esc on true
  left join lateral (
    select e.reason, e.created_at
      from escalations e join conversations cv on cv.id = e.conversation_id
     where cv.contact_id = c.id and e.state = 'open'
     order by e.created_at desc
     limit 1
  ) oe on true
  left join lateral (
    select cv.id, cv.state, cv.paused_until, cv.assignee_user_id, cv.snooze_until, cv.last_wa_inbound_at
      from conversations cv
     where cv.contact_id = c.id
     order by cv.last_message_at desc nulls last, cv.created_at desc
     limit 1
  ) lc on true
  left join lateral (
    select e.at, e.direction, e.sender
      from ev e
     where e.contact_id = c.id and e.at is not null and e.spoken
     order by e.at desc
     limit 1
  ) lm on true
  left join lateral (
    select e.at, e.body
      from ev e
     where e.contact_id = c.id and e.at is not null
       and e.direction = 'inbound' and e.spoken and e.body is not null
     order by e.at desc
     limit 1
  ) li on true
  left join lateral (
    select min(e.at) filter (where e.spoken) as first_at,
           min(e.created_at) as first_row_at,
           bool_or(e.backfill) as has_backfill,
           bool_or(e.type in ('text', 'template', 'media')) as has_chat,
           -- Which wires those words travelled: a person who only ever wrote by email has not used WhatsApp.
           array_agg(distinct e.channel order by e.channel) filter (where e.type in ('text', 'template', 'media')) as channels,
           max(e.created_at) filter (where e.direction = 'outbound' and e.status = 'queued') as queued_at,
           -- The wire of their first spoken message, for came_from.
           (array_agg(e.channel order by e.at, e.created_at) filter (where e.spoken and e.at is not null))[1] as first_channel,
           -- The first row of a history moved in, in the order it was written: a call's note is a call, anything else its wire.
           (array_agg(case when e.type = 'call_summary' then 'call' else e.channel end order by e.created_at)
              filter (where e.backfill))[1] as backfill_first
      from ev e where e.contact_id = c.id
  ) ma on true
  left join lateral (
    select count(*)::int as n,
           (coalesce(sum(k.duration_ms), 0) / 1000)::int as seconds,
           max(k.started_at) as last_at,
           -- The one that means they reached out.
           max(k.started_at) filter (where k.direction = 'inbound') as last_inbound_at,
           min(k.started_at) as first_at,
           min(k.created_at) as first_row_at
      from calls k where k.contact_id = c.id
       and k.status <> 'not_connected'
  ) lk on true
  left join lateral (
    -- What the call they placed was about: what the caller wanted, in the
    -- analysis's plain words, else the provider's summary. The attention
    -- strip reads it where a caller has written nothing.
    select coalesce(k.wanted, k.summary) as summary
      from calls k
     where k.contact_id = c.id
       and k.direction = 'inbound'
       and k.status <> 'not_connected'
       and coalesce(k.wanted, k.summary) is not null
     order by k.started_at desc
     limit 1
  ) lks on true
  left join lateral (
    -- The one deal the row shows: open or current first, then the newest.
    -- pickCurrentDeal in contracts orders a person's list the same way.
    select d.id, d.stage, d.service, d.proposed_at, d.decided_at, d.ended_at, d.amount_cents, d.per,
           d.proposal_url, d.valid_until, d.lost_reason
      from deals d
     where d.contact_id = c.id
     order by (d.stage in ('proposed', 'won')) desc, d.created_at desc
     limit 1
  ) dl on true
  left join lateral (
    -- Their next step: the earliest open one, by its day, then the one written first. A step is a note with a day,
    -- for the team only, so the receptionist never reads it; the list carries it for the Pipeline and Today.
    select n.id, n.body, n.due_on, n.for_user_id, n.deal_id
      from person_notes n
     where n.tenant_id = p_tenant_id
       and n.contact_id = c.id
       and n.due_on is not null
       and n.done_at is null
     order by n.due_on, n.created_at, n.id
     limit 1
  ) st on true
  order by c.in_touch_at desc, c.added_at desc, c.id desc
$$;


--
-- Name: FUNCTION people_list(p_tenant_id uuid, p_contact_id uuid, p_query text, p_limit integer, p_offset integer, p_after_at timestamp with time zone, p_after_added timestamp with time zone, p_after_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.people_list(p_tenant_id uuid, p_contact_id uuid, p_query text, p_limit integer, p_offset integer, p_after_at timestamp with time zone, p_after_added timestamp with time zone, p_after_id uuid) IS 'Everyone this workspace has ever heard from, with both consent answers: `consent` for conversation and their own appointments, `marketing_consent` for offers. Two answers because the carriers require them collected separately (error 30913). `came_from` says where each first came from: the door that added them (calendar, lead, import, manual); else a history moved in from before the database says how it began, in the thread''s own order (a call''s note is call, anything else its wire; import only when it names none); else their first call (call) or the wire of their first message (whatsapp, sms, email); null when nothing says. p_query matches a name, a WhatsApp name, an email address or three digits of the number; p_contact_id names one person, their row alone. The page is chosen before it is read (0021, people_page): its people come from person_moments in one whole order, latest contact first (in_touch_at, -infinity for never), then the newest added (added_at), then the id, falling, at most p_limit (1000) of them after p_offset or after the cursor p_after_at, p_after_added, p_after_id (the last row''s in_touch_at, added_at and id); every other column is read for them alone. The deal_* columns carry the newest open or current deal, else the newest of any (0004), with its link, its valid-until day and why they passed (0008). The step_* columns carry their next step: the earliest open note with a day (0007, amended), by its day and then as written.';


--
-- Name: people_page(uuid, uuid, text, integer, integer, timestamp with time zone, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.people_page(p_tenant_id uuid, p_contact_id uuid, p_query text, p_limit integer, p_offset integer, p_after_at timestamp with time zone, p_after_added timestamp with time zone, p_after_id uuid) RETURNS TABLE(id uuid, display_name text, wa_profile_name text, phone_e164 text, email text, consent text, consent_source text, consent_updated_at timestamp with time zone, dnc boolean, marketing_consent text, marketing_consent_source text, marketing_consent_updated_at timestamp with time zone, in_touch_at timestamp with time zone, added_at timestamp with time zone)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    SET enable_sort TO 'off'
    AS $$
#variable_conflict use_column
declare
  -- The search, read once rather than for each person the walk tests: its words, and its digits.
  v_words  text := nullif(trim(p_query), '');
  v_digits text := regexp_replace(coalesce(p_query, ''), '\D', '', 'g');
begin
  -- One person, by their key: no order to keep, so nothing here sorts. The query and the cursor page a list; a named
  -- person is their row alone.
  if p_contact_id is not null then
    return query
      select c.id, c.display_name, c.wa_profile_name, c.phone_e164, c.email,
             c.consent, c.consent_source, c.consent_updated_at, c.dnc,
             c.marketing_consent, c.marketing_consent_source, c.marketing_consent_updated_at,
             pm.in_touch_at, pm.added_at
        from person_moments pm
        join contacts c on c.id = pm.contact_id
       where pm.contact_id = p_contact_id
         and pm.tenant_id = p_tenant_id
         and c.tenant_id = p_tenant_id
         and c.erased_at is null
         and c.merged_into_contact_id is null;
    return;
  end if;

  -- Everyone else: the walk down person_moments_order to the end of the page. With sorting off it is the only plan,
  -- whatever the planner thinks the workspace holds.
  return query
    select c.id, c.display_name, c.wa_profile_name, c.phone_e164, c.email,
           c.consent, c.consent_source, c.consent_updated_at, c.dnc,
           c.marketing_consent, c.marketing_consent_source, c.marketing_consent_updated_at,
           pm.in_touch_at, pm.added_at
      from person_moments pm
      -- Each person's contact row, looked up by its key as the walk reaches them. The limit keeps it a look-up: joined
      -- any other way, a plan made without the arguments can read the workspace's contacts once and hold them, and
      -- compare every one with each person the walk reaches.
      cross join lateral (
        select c.id, c.display_name, c.wa_profile_name, c.phone_e164, c.email,
               c.consent, c.consent_source, c.consent_updated_at, c.dnc,
               c.marketing_consent, c.marketing_consent_source, c.marketing_consent_updated_at
          from contacts c
         where c.id = pm.contact_id
           and c.tenant_id = p_tenant_id
           and c.erased_at is null
           and c.merged_into_contact_id is null
           -- The search: a name, their name on WhatsApp, their email address, or
           -- three digits of the number, the way the page's own box matches.
           -- Nothing else is indexed here; the page still narrows by state and
           -- list over what it holds.
           and (
             v_words is null
             or c.display_name ilike '%' || v_words || '%'
             or c.wa_profile_name ilike '%' || v_words || '%'
             or c.email ilike '%' || v_words || '%'
             or (length(v_digits) >= 3
                 and regexp_replace(coalesce(c.phone_e164, ''), '\D', '', 'g') like '%' || v_digits || '%')
           )
         limit 1
      ) c
     where pm.tenant_id = p_tenant_id
       -- After the cursor: just past the last row the caller holds. Without one, a place past every row, so the
       -- comparison is always the index's own condition, whatever the plan.
       and (pm.in_touch_at, pm.added_at, pm.contact_id)
           < (coalesce(p_after_at, 'infinity'), coalesce(p_after_added, 'infinity'),
              coalesce(p_after_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'))
     order by pm.in_touch_at desc, pm.added_at desc, pm.contact_id desc
     limit least(greatest(coalesce(p_limit, 1000), 1), 1000)
     offset greatest(coalesce(p_offset, 0), 0);
end
$$;


--
-- Name: FUNCTION people_page(p_tenant_id uuid, p_contact_id uuid, p_query text, p_limit integer, p_offset integer, p_after_at timestamp with time zone, p_after_added timestamp with time zone, p_after_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.people_page(p_tenant_id uuid, p_contact_id uuid, p_query text, p_limit integer, p_offset integer, p_after_at timestamp with time zone, p_after_added timestamp with time zone, p_after_id uuid) IS 'The people on one page of People (0021), for people_list, which reads everything else for them alone: the person p_contact_id names, by their key; else the live people matching p_query in person_moments'' order (in_touch_at, then added_at, then the id, falling), after p_offset or just past the cursor p_after_at, p_after_added, p_after_id, at most p_limit (1000) of them. It walks person_moments_order to the end of the page: sorting is off, so no plan reads the workspace whole and sorts it. As the caller, so RLS decides.';


--
-- Name: person_moments_calls_added(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.person_moments_calls_added() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into public.person_moments as pm
         (contact_id, tenant_id, added_at, last_call_at, first_call_at, first_row_at)
  select c.id, c.tenant_id, c.created_at, n.last_call_at, n.first_call_at, n.first_row_at
    from (
      select k.contact_id,
             max(k.started_at) as last_call_at,
             min(k.started_at) as first_call_at,
             min(k.created_at) as first_row_at
        from new_rows k
       where k.contact_id is not null
         and k.status <> 'not_connected'
       group by k.contact_id
    ) n
    join public.contacts c on c.id = n.contact_id
   order by c.id
  on conflict (contact_id) do update
     set last_call_at = greatest(pm.last_call_at, excluded.last_call_at),
         first_call_at = least(pm.first_call_at, excluded.first_call_at),
         first_row_at = least(pm.first_row_at, excluded.first_row_at);
  return null;
end $$;


--
-- Name: person_moments_calls_changed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.person_moments_calls_changed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_back uuid[];
begin
  v_back := array(
    select distinct x.contact_id
      from (
        select o.contact_id as a, n.contact_id as b
          from old_rows o
          join new_rows n on n.id = o.id
         where o.contact_id is distinct from n.contact_id
            or (o.status = 'not_connected') is distinct from (n.status = 'not_connected')
            or o.started_at is distinct from n.started_at
            or o.created_at is distinct from n.created_at
      ) p
      cross join lateral (values (p.a), (p.b)) x (contact_id)
     where x.contact_id is not null
     order by 1
  );
  if cardinality(v_back) > 0 then
    perform public.person_moments_recompute(v_back);
  end if;
  return null;
end $$;


--
-- Name: person_moments_calls_removed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.person_moments_calls_removed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_back uuid[];
begin
  v_back := array(select distinct o.contact_id from old_rows o where o.contact_id is not null order by 1);
  if cardinality(v_back) > 0 then
    perform public.person_moments_recompute(v_back);
  end if;
  return null;
end $$;


--
-- Name: person_moments_check(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.person_moments_check(p_tenant_id uuid, p_after uuid DEFAULT NULL::uuid, p_limit integer DEFAULT NULL::integer) RETURNS TABLE(contact_id uuid, what text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  -- The workspace's people after p_after, by id, at most p_limit of them (all, when null), each whole, missing or
  -- differing: paged as the fill is, so a workspace of any size is checked a batch at a time, and the batch's last
  -- person says where the next begins.
  with people as (
    select c.id
      from public.contacts c
     where c.tenant_id = p_tenant_id
       and (p_after is null or c.id > p_after)
     order by c.id
     limit p_limit
  )
  select d.contact_id,
         case when k.contact_id is null then 'missing'
              when (d.last_word_at, d.last_call_at, d.first_word_at, d.first_call_at, d.first_row_at, d.moved_in, d.added_at)
                   is distinct from
                   (k.last_word_at, k.last_call_at, k.first_word_at, k.first_call_at, k.first_row_at, k.moved_in, k.added_at)
                then 'differs'
              else 'whole' end
    from public.person_moments_of(array(select pe.id from people pe)) d
    left join public.person_moments k on k.contact_id = d.contact_id
   order by 1
$$;


--
-- Name: FUNCTION person_moments_check(p_tenant_id uuid, p_after uuid, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.person_moments_check(p_tenant_id uuid, p_after uuid, p_limit integer) IS 'A workspace''s kept moments against its rows, its people after p_after by id, at most p_limit (all, when null): each person whole, missing (no row), or differing from what their rows say.';


--
-- Name: person_moments_contacts_added(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.person_moments_contacts_added() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into public.person_moments (contact_id, tenant_id, added_at)
  select n.id, n.tenant_id, n.created_at
    from new_rows n
   order by n.id
  on conflict (contact_id) do nothing;
  return null;
end $$;


--
-- Name: person_moments_fill(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.person_moments_fill(p_tenant_id uuid, p_after uuid, p_limit integer) RETURNS TABLE(filled integer, last_contact_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_batch uuid[];
begin
  if p_tenant_id is null or p_limit is null or p_limit < 1 or p_limit > 1000 then
    raise exception 'a batch is one workspace''s next 1 to 1,000 people' using errcode = '22023';
  end if;
  select coalesce(array_agg(b.id order by b.id), '{}')
    into v_batch
    from (
      select c.id
        from public.contacts c
       where c.tenant_id = p_tenant_id
         and (p_after is null or c.id > p_after)
       order by c.id
       limit p_limit
    ) b;
  filled := public.person_moments_recompute(v_batch);
  last_contact_id := v_batch[cardinality(v_batch)];
  return next;
end $$;


--
-- Name: FUNCTION person_moments_fill(p_tenant_id uuid, p_after uuid, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.person_moments_fill(p_tenant_id uuid, p_after uuid, p_limit integer) IS 'One batch of the fill: a workspace''s next people after p_after, by id, written from their rows. Answers how many, and the last one, for the next batch to start after.';


--
-- Name: person_moments_messages_added(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.person_moments_messages_added() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into public.person_moments as pm
         (contact_id, tenant_id, added_at, last_word_at, first_word_at, first_row_at, moved_in)
  select c.id, c.tenant_id, c.created_at, n.last_word_at, n.first_word_at, n.first_row_at, n.moved_in
    from (
      select x.contact_id,
             max(e.at) filter (where e.spoken) as last_word_at,
             min(e.at) filter (where e.spoken) as first_word_at,
             min(x.created_at) as first_row_at,
             bool_or(e.moved_in) as moved_in
        from new_rows x
        cross join lateral public.message_moment(x.meta, x.channel_ts, x.created_at, x.type, x.status) e
       where x.contact_id is not null
       group by x.contact_id
    ) n
    join public.contacts c on c.id = n.contact_id
   order by c.id
  on conflict (contact_id) do update
     set last_word_at = greatest(pm.last_word_at, excluded.last_word_at),
         first_word_at = least(pm.first_word_at, excluded.first_word_at),
         first_row_at = least(pm.first_row_at, excluded.first_row_at),
         moved_in = pm.moved_in or excluded.moved_in;
  return null;
end $$;


--
-- Name: person_moments_messages_changed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.person_moments_messages_changed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_back    uuid[];
  v_people  uuid[];
  v_at      timestamptz[];
begin
  -- One pass over the statement's rows: the people to recompute, and the words that became spoken.
  select coalesce(array_agg(distinct b.contact_id order by b.contact_id) filter (where b.contact_id is not null), '{}'),
         coalesce(array_agg(f.contact_id order by f.contact_id) filter (where f.contact_id is not null), '{}'),
         coalesce(array_agg(f.at order by f.contact_id) filter (where f.contact_id is not null), '{}')
    into v_back, v_people, v_at
    from old_rows o
    join new_rows n on n.id = o.id
    cross join lateral public.message_moment(o.meta, o.channel_ts, o.created_at, o.type, o.status) eo
    cross join lateral public.message_moment(n.meta, n.channel_ts, n.created_at, n.type, n.status) en
    cross join lateral (
      select o.contact_id is distinct from n.contact_id
             or (eo.spoken and not en.spoken)
             or eo.at is distinct from en.at
             or eo.moved_in is distinct from en.moved_in as back
    ) w
    left join lateral (values (o.contact_id), (n.contact_id)) b (contact_id) on w.back
    left join lateral (select n.contact_id, en.at) f (contact_id, at)
      on not w.back and not eo.spoken and en.spoken;
  if cardinality(v_people) > 0 then
    insert into public.person_moments as pm (contact_id, tenant_id, added_at, last_word_at, first_word_at)
    select c.id, c.tenant_id, c.created_at, s.last_word_at, s.first_word_at
      from (
        select u.contact_id, max(u.at) as last_word_at, min(u.at) as first_word_at
          from unnest(v_people, v_at) u (contact_id, at)
         where not (u.contact_id = any(v_back))
         group by u.contact_id
      ) s
      join public.contacts c on c.id = s.contact_id
     order by c.id
    on conflict (contact_id) do update
       set last_word_at = greatest(pm.last_word_at, excluded.last_word_at),
           first_word_at = least(pm.first_word_at, excluded.first_word_at);
  end if;
  if cardinality(v_back) > 0 then
    perform public.person_moments_recompute(v_back);
  end if;
  return null;
end $$;


--
-- Name: person_moments_messages_removed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.person_moments_messages_removed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_back uuid[];
begin
  v_back := array(select distinct o.contact_id from old_rows o where o.contact_id is not null order by 1);
  if cardinality(v_back) > 0 then
    perform public.person_moments_recompute(v_back);
  end if;
  return null;
end $$;


--
-- Name: person_moments_of(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.person_moments_of(p_contacts uuid[]) RETURNS TABLE(contact_id uuid, tenant_id uuid, added_at timestamp with time zone, last_word_at timestamp with time zone, last_call_at timestamp with time zone, first_word_at timestamp with time zone, first_call_at timestamp with time zone, first_row_at timestamp with time zone, moved_in boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select c.id, c.tenant_id, c.created_at,
         mm.last_word_at, kk.last_call_at, mm.first_word_at, kk.first_call_at,
         least(mm.first_row_at, kk.first_row_at),
         coalesce(mm.moved_in, false)
    from public.contacts c
    left join lateral (
      select max(e.at) filter (where e.spoken) as last_word_at,
             min(e.at) filter (where e.spoken) as first_word_at,
             min(m.created_at) as first_row_at,
             bool_or(e.moved_in) as moved_in
        from public.messages m
        cross join lateral public.message_moment(m.meta, m.channel_ts, m.created_at, m.type, m.status) e
       where m.contact_id = c.id
    ) mm on true
    left join lateral (
      select max(k.started_at) as last_call_at,
             min(k.started_at) as first_call_at,
             min(k.created_at) as first_row_at
        from public.calls k
       where k.contact_id = c.id
         and k.status <> 'not_connected'
    ) kk on true
   where c.id = any(p_contacts)
$$;


--
-- Name: FUNCTION person_moments_of(p_contacts uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.person_moments_of(p_contacts uuid[]) IS 'Each person''s moments worked out from their messages and connected calls, as people_list reads them (00170).';


--
-- Name: person_moments_recompute(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.person_moments_recompute(p_contacts uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_count integer;
begin
  if p_contacts is null or cardinality(p_contacts) = 0 then
    return 0;
  end if;
  -- Each person's row, then its lock, then their moments from their rows, each its own statement. A write in flight
  -- for one of them either committed before the lock was taken, and is read here, or waits for it, and moves the
  -- moments after, from what this wrote. The locks are taken in one order, so two recomputes never wait on each other
  -- in a circle.
  insert into public.person_moments (contact_id, tenant_id, added_at)
  select c.id, c.tenant_id, c.created_at
    from public.contacts c
   where c.id = any(p_contacts)
   order by c.id
  on conflict (contact_id) do nothing;
  perform 1 from public.person_moments pm where pm.contact_id = any(p_contacts) order by pm.contact_id for update;
  update public.person_moments pm
     set last_word_at = o.last_word_at,
         last_call_at = o.last_call_at,
         first_word_at = o.first_word_at,
         first_call_at = o.first_call_at,
         first_row_at = o.first_row_at,
         moved_in = o.moved_in
    from public.person_moments_of(p_contacts) o
   where pm.contact_id = o.contact_id;
  get diagnostics v_count = row_count;
  return v_count;
end $$;


--
-- Name: FUNCTION person_moments_recompute(p_contacts uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.person_moments_recompute(p_contacts uuid[]) IS 'Writes each person''s moments from their rows, under the person''s lock; answers how many were written.';


--
-- Name: person_note_add(uuid, text, uuid, boolean, text, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.person_note_add(p_contact_id uuid, p_body text, p_for_user_id uuid DEFAULT NULL::uuid, p_team_only boolean DEFAULT false, p_source text DEFAULT 'page'::text, p_due_on date DEFAULT NULL::date, p_deal_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user   uuid := auth.uid();
  v_tenant uuid;
  v_body   text := nullif(btrim(coalesce(p_body, '')), '');
  v_row    public.person_notes%rowtype;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  if v_body is null then
    return jsonb_build_object('error', 'empty');
  end if;
  if char_length(v_body) > 600 then
    return jsonb_build_object('error', 'too_long');
  end if;
  if p_source is null or p_source not in ('page', 'bulk') then
    return jsonb_build_object('error', 'bad_source');
  end if;
  select c.tenant_id into v_tenant
    from contacts c
   where c.id = p_contact_id and c.erased_at is null and c.merged_into_contact_id is null;
  if v_tenant is null or not public.is_acting_member(v_tenant) then
    return jsonb_build_object('error', 'not_found');
  end if;
  if p_for_user_id is not null and not exists (
    select 1 from memberships m where m.tenant_id = v_tenant and m.user_id = p_for_user_id
  ) then
    return jsonb_build_object('error', 'not_a_member');
  end if;
  if p_deal_id is not null and not exists (
    select 1 from deals d where d.id = p_deal_id and d.tenant_id = v_tenant and d.contact_id = p_contact_id
  ) then
    return jsonb_build_object('error', 'bad_deal');
  end if;
  insert into person_notes (tenant_id, contact_id, body, author_kind, author_user_id, for_user_id, team_only, source,
                            due_on, deal_id)
  values (v_tenant, p_contact_id, v_body, 'member', v_user, p_for_user_id,
          coalesce(p_team_only, false) or p_due_on is not null, p_source, p_due_on, p_deal_id)
  returning * into v_row;
  insert into events (tenant_id, kind, category, subject_type, subject_id, data)
  values (v_tenant, 'contact.noted', 'contact', 'contact', p_contact_id,
          jsonb_build_object('note_id', v_row.id, 'chars', char_length(v_body), 'by', v_user,
                             'for', p_for_user_id, 'team_only', v_row.team_only, 'source', p_source,
                             'due_on', v_row.due_on, 'deal_id', v_row.deal_id));
  perform public.note_for_you_notify(v_tenant, p_contact_id, v_row.id, v_user, p_for_user_id);
  return jsonb_build_object('note', to_jsonb(v_row));
end $$;


--
-- Name: FUNCTION person_note_add(p_contact_id uuid, p_body text, p_for_user_id uuid, p_team_only boolean, p_source text, p_due_on date, p_deal_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.person_note_add(p_contact_id uuid, p_body text, p_for_user_id uuid, p_team_only boolean, p_source text, p_due_on date, p_deal_id uuid) IS 'A member writes a note on a person (0007): up to 600 characters, optionally for one member of the team, optionally for the team only; with a day it is a step, and the team''s only; it may name one of the person''s own deals. Owner or operator. Answers {note} or {error}.';


--
-- Name: person_note_decide(uuid, boolean, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.person_note_decide(p_note_id uuid, p_keep boolean, p_body text DEFAULT NULL::text, p_team_only boolean DEFAULT NULL::boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user uuid := auth.uid();
  v_body text := nullif(btrim(coalesce(p_body, '')), '');
  v_row  public.person_notes%rowtype;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  if v_body is not null and char_length(v_body) > 600 then
    return jsonb_build_object('error', 'too_long');
  end if;
  select * into v_row from person_notes n where n.id = p_note_id for update;
  if v_row.id is null or not public.is_acting_member(v_row.tenant_id) then
    return jsonb_build_object('error', 'not_found');
  end if;
  if v_row.state <> 'suggested' then
    return jsonb_build_object('error', 'decided');
  end if;
  if not coalesce(p_keep, false) then
    delete from person_notes n where n.id = v_row.id;
    insert into events (tenant_id, kind, category, subject_type, subject_id, data)
    values (v_row.tenant_id, 'contact.note_dismissed', 'contact', 'contact', v_row.contact_id,
            jsonb_build_object('note_id', v_row.id, 'by', v_user, 'source', v_row.source));
    return jsonb_build_object('removed', v_row.id);
  end if;
  update person_notes n
     set state = 'kept', kept_by = v_user, kept_at = now(),
         body = coalesce(v_body, n.body), team_only = coalesce(p_team_only, n.team_only),
         version = n.version + 1
   where n.id = v_row.id
  returning * into v_row;
  insert into events (tenant_id, kind, category, subject_type, subject_id, data)
  values (v_row.tenant_id, 'contact.note_kept', 'contact', 'contact', v_row.contact_id,
          jsonb_build_object('note_id', v_row.id, 'by', v_user, 'source', v_row.source,
                             'changed', v_body is not null));
  return jsonb_build_object('note', to_jsonb(v_row));
end $$;


--
-- Name: FUNCTION person_note_decide(p_note_id uuid, p_keep boolean, p_body text, p_team_only boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.person_note_decide(p_note_id uuid, p_keep boolean, p_body text, p_team_only boolean) IS 'Keep or dismiss the receptionist''s suggested note (0007): kept (optionally in changed words) it is read by the receptionist from then on; dismissed, its words go. Owner or operator. Answers {note}, {removed} or {error}.';


--
-- Name: person_note_done(uuid, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.person_note_done(p_note_id uuid, p_done boolean DEFAULT true, p_version integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user uuid := auth.uid();
  v_done boolean := coalesce(p_done, true);
  v_row  public.person_notes%rowtype;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  select * into v_row from person_notes n where n.id = p_note_id for update;
  if v_row.id is null or not public.is_acting_member(v_row.tenant_id) then
    return jsonb_build_object('error', 'not_found');
  end if;
  if v_row.due_on is null then
    return jsonb_build_object('error', 'not_a_step');
  end if;
  if (v_row.done_at is not null) = v_done then
    return jsonb_build_object('note', to_jsonb(v_row));
  end if;
  if p_version is not null and p_version <> v_row.version then
    return jsonb_build_object('error', 'moved', 'version', v_row.version);
  end if;
  update person_notes n
     set done_at = case when v_done then now() end,
         done_by = case when v_done then v_user end,
         version = n.version + 1
   where n.id = v_row.id
  returning * into v_row;
  -- Each kind written out, as every event name is: what the activity log and the alerts read by.
  if v_done then
    insert into events (tenant_id, kind, category, subject_type, subject_id, data)
    values (v_row.tenant_id, 'contact.note_done', 'contact', 'contact', v_row.contact_id,
            jsonb_build_object('note_id', v_row.id, 'by', v_user, 'due_on', v_row.due_on, 'deal_id', v_row.deal_id));
  else
    insert into events (tenant_id, kind, category, subject_type, subject_id, data)
    values (v_row.tenant_id, 'contact.note_undone', 'contact', 'contact', v_row.contact_id,
            jsonb_build_object('note_id', v_row.id, 'by', v_user, 'due_on', v_row.due_on, 'deal_id', v_row.deal_id));
  end if;
  return jsonb_build_object('note', to_jsonb(v_row));
end $$;


--
-- Name: FUNCTION person_note_done(p_note_id uuid, p_done boolean, p_version integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.person_note_done(p_note_id uuid, p_done boolean, p_version integer) IS 'A step is done, or open again (0007, amended): any owner or operator; only a note with a day (not_a_step); a stale version answers {error: moved}; a press that changes nothing writes nothing. Answers {note} or {error}.';


--
-- Name: person_note_edit(uuid, text, uuid, boolean, integer, date, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.person_note_edit(p_note_id uuid, p_body text, p_for_user_id uuid DEFAULT NULL::uuid, p_team_only boolean DEFAULT false, p_version integer DEFAULT NULL::integer, p_due_on date DEFAULT NULL::date, p_deal_id uuid DEFAULT NULL::uuid, p_clear_due boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user uuid := auth.uid();
  v_body text := nullif(btrim(coalesce(p_body, '')), '');
  v_row  public.person_notes%rowtype;
  v_was  uuid;
  v_due  date;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  if v_body is null then
    return jsonb_build_object('error', 'empty');
  end if;
  if char_length(v_body) > 600 then
    return jsonb_build_object('error', 'too_long');
  end if;
  select * into v_row from person_notes n where n.id = p_note_id for update;
  if v_row.id is null or not public.is_acting_member(v_row.tenant_id) then
    return jsonb_build_object('error', 'not_found');
  end if;
  if v_row.author_kind <> 'member' or v_row.author_user_id is distinct from v_user then
    return jsonb_build_object('error', 'not_yours');
  end if;
  if p_version is not null and p_version <> v_row.version then
    return jsonb_build_object('error', 'moved', 'version', v_row.version);
  end if;
  if p_for_user_id is not null and not exists (
    select 1 from memberships m where m.tenant_id = v_row.tenant_id and m.user_id = p_for_user_id
  ) then
    return jsonb_build_object('error', 'not_a_member');
  end if;
  if p_deal_id is not null and not exists (
    select 1 from deals d where d.id = p_deal_id and d.tenant_id = v_row.tenant_id and d.contact_id = v_row.contact_id
  ) then
    return jsonb_build_object('error', 'bad_deal');
  end if;
  v_was := v_row.for_user_id;
  v_due := case when coalesce(p_clear_due, false) then null else coalesce(p_due_on, v_row.due_on) end;
  update person_notes n
     set body = v_body, for_user_id = p_for_user_id,
         team_only = coalesce(p_team_only, false) or v_due is not null,
         due_on = v_due,
         done_at = case when v_due is null then null else n.done_at end,
         done_by = case when v_due is null then null else n.done_by end,
         deal_id = coalesce(p_deal_id, n.deal_id),
         version = n.version + 1
   where n.id = v_row.id
  returning * into v_row;
  insert into events (tenant_id, kind, category, subject_type, subject_id, data)
  values (v_row.tenant_id, 'contact.note_changed', 'contact', 'contact', v_row.contact_id,
          jsonb_build_object('note_id', v_row.id, 'chars', char_length(v_body), 'by', v_user,
                             'for', p_for_user_id, 'team_only', v_row.team_only,
                             'due_on', v_row.due_on, 'deal_id', v_row.deal_id));
  -- Only a note addressed to someone new tells them; a change of words is not news to its reader.
  if p_for_user_id is distinct from v_was then
    perform public.note_for_you_notify(v_row.tenant_id, v_row.contact_id, v_row.id, v_user, p_for_user_id);
  end if;
  return jsonb_build_object('note', to_jsonb(v_row));
end $$;


--
-- Name: FUNCTION person_note_edit(p_note_id uuid, p_body text, p_for_user_id uuid, p_team_only boolean, p_version integer, p_due_on date, p_deal_id uuid, p_clear_due boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.person_note_edit(p_note_id uuid, p_body text, p_for_user_id uuid, p_team_only boolean, p_version integer, p_due_on date, p_deal_id uuid, p_clear_due boolean) IS 'Its author changes a member''s note (0007): the words, who it is for, team only, its day (kept unless sent or cleared; a day keeps it the team''s) and its deal; a stale version answers {error: moved}. Answers {note} or {error}.';


--
-- Name: person_note_remove(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.person_note_remove(p_note_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user uuid := auth.uid();
  v_row  public.person_notes%rowtype;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  select * into v_row from person_notes n where n.id = p_note_id for update;
  if v_row.id is null or not public.is_acting_member(v_row.tenant_id) then
    return jsonb_build_object('error', 'not_found');
  end if;
  if v_row.author_user_id is distinct from v_user and not public.is_workspace_owner(v_row.tenant_id) then
    return jsonb_build_object('error', 'not_yours');
  end if;
  delete from person_notes n where n.id = v_row.id;
  insert into events (tenant_id, kind, category, subject_type, subject_id, data)
  values (v_row.tenant_id, 'contact.note_removed', 'contact', 'contact', v_row.contact_id,
          jsonb_build_object('note_id', v_row.id, 'by', v_user, 'author_kind', v_row.author_kind));
  return jsonb_build_object('removed', v_row.id);
end $$;


--
-- Name: FUNCTION person_note_remove(p_note_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.person_note_remove(p_note_id uuid) IS 'Take a note away (0007): its author, or an owner. The words go; the event holds none. Answers {removed} or {error}.';


--
-- Name: person_note_suggest(uuid, uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.person_note_suggest(p_tenant_id uuid, p_contact_id uuid, p_body text, p_source text, p_source_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_body text := nullif(btrim(coalesce(p_body, '')), '');
  v_row  public.person_notes%rowtype;
begin
  if v_body is null then
    return jsonb_build_object('error', 'empty');
  end if;
  if char_length(v_body) > 600 then
    return jsonb_build_object('error', 'too_long');
  end if;
  if p_source is null or p_source not in ('call', 'thread') then
    return jsonb_build_object('error', 'bad_source');
  end if;
  if not exists (
    select 1 from contacts c
     where c.id = p_contact_id and c.tenant_id = p_tenant_id
       and c.erased_at is null and c.merged_into_contact_id is null
  ) then
    return jsonb_build_object('error', 'not_found');
  end if;
  if p_source_id is not null and exists (
    select 1 from person_notes n where n.contact_id = p_contact_id and n.source_id = p_source_id
  ) then
    return jsonb_build_object('error', 'already');
  end if;
  if (select count(*) from person_notes n where n.contact_id = p_contact_id and n.state = 'suggested') >= 3 then
    return jsonb_build_object('error', 'too_many');
  end if;
  insert into person_notes (tenant_id, contact_id, body, author_kind, state, source, source_id)
  values (p_tenant_id, p_contact_id, v_body, 'receptionist', 'suggested', p_source, p_source_id)
  returning * into v_row;
  insert into events (tenant_id, kind, category, subject_type, subject_id, data)
  values (p_tenant_id, 'contact.note_suggested', 'contact', 'contact', p_contact_id,
          jsonb_build_object('note_id', v_row.id, 'chars', char_length(v_body), 'source', p_source));
  return jsonb_build_object('note', to_jsonb(v_row));
end $$;


--
-- Name: FUNCTION person_note_suggest(p_tenant_id uuid, p_contact_id uuid, p_body text, p_source text, p_source_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.person_note_suggest(p_tenant_id uuid, p_contact_id uuid, p_body text, p_source text, p_source_id uuid) IS 'The receptionist suggests a note on a person after a call or a thread (0007). Service role only (the edge). Once per source; at most three waiting per person. Answers {note} or {error}.';


--
-- Name: person_notes_erase_on_contact(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.person_notes_erase_on_contact() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if NEW.erased_at is not null and OLD.erased_at is null then
    delete from person_notes where contact_id = NEW.id;
    update contacts set notes = null where id = NEW.id and notes is not null;
    delete from notifications
     where tenant_id = NEW.tenant_id and kind = 'note_for_you'
       and subject_type = 'contact' and subject_id = NEW.id::text;
  end if;
  return null;
end $$;


--
-- Name: FUNCTION person_notes_erase_on_contact(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.person_notes_erase_on_contact() IS 'When a person is erased, every note on them goes, and the superseded contacts.notes field is cleared (0007).';


--
-- Name: person_step_from_playbook(uuid, uuid, date, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.person_step_from_playbook(p_tenant_id uuid, p_contact_id uuid, p_due_on date, p_words text, p_for_user_id uuid DEFAULT NULL::uuid, p_source_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
-- A step the product makes for the team (Reach out, Part 5, G11): the words at most 600 characters, a day, for anyone
-- or for one member of the workspace. Once per source, which is required: a second call answers {error: 'already'} and
-- writes nothing.
-- The person must be this workspace's, not erased or merged. The event and the ring are person_note_add's (00166).
declare
  v_body text := nullif(btrim(coalesce(p_words, '')), '');
  v_row  public.person_notes%rowtype;
begin
  if v_body is null then
    return jsonb_build_object('error', 'empty');
  end if;
  if char_length(v_body) > 600 then
    return jsonb_build_object('error', 'too_long');
  end if;
  if p_due_on is null then
    return jsonb_build_object('error', 'no_day');
  end if;
  if p_source_id is null then
    return jsonb_build_object('error', 'no_source');
  end if;
  if not exists (
    select 1 from contacts c
     where c.id = p_contact_id and c.tenant_id = p_tenant_id
       and c.erased_at is null and c.merged_into_contact_id is null
  ) then
    return jsonb_build_object('error', 'not_found');
  end if;
  if p_for_user_id is not null and not exists (
    select 1 from memberships m where m.tenant_id = p_tenant_id and m.user_id = p_for_user_id
  ) then
    return jsonb_build_object('error', 'not_a_member');
  end if;
  insert into person_notes (tenant_id, contact_id, body, author_kind, state, for_user_id, team_only, source, source_id,
                            due_on)
  values (p_tenant_id, p_contact_id, v_body, 'receptionist', 'kept', p_for_user_id, true, 'reach_out', p_source_id,
          p_due_on)
  on conflict (contact_id, source_id) where source = 'reach_out' do nothing
  returning * into v_row;
  if v_row.id is null then
    return jsonb_build_object('error', 'already');
  end if;
  insert into events (tenant_id, kind, category, subject_type, subject_id, data)
  values (p_tenant_id, 'contact.noted', 'contact', 'contact', p_contact_id,
          jsonb_build_object('note_id', v_row.id, 'chars', char_length(v_body), 'by', null,
                             'for', p_for_user_id, 'team_only', v_row.team_only, 'source', 'reach_out',
                             'due_on', v_row.due_on, 'deal_id', v_row.deal_id));
  perform public.note_for_you_notify(p_tenant_id, p_contact_id, v_row.id, null, p_for_user_id);
  return jsonb_build_object('note', to_jsonb(v_row));
end $$;


--
-- Name: FUNCTION person_step_from_playbook(p_tenant_id uuid, p_contact_id uuid, p_due_on date, p_words text, p_for_user_id uuid, p_source_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.person_step_from_playbook(p_tenant_id uuid, p_contact_id uuid, p_due_on date, p_words text, p_for_user_id uuid, p_source_id uuid) IS 'A dated step the product makes for the team on a person (Reach out Part 5, G11): kept, the team''s only, by the receptionist, source reach_out, once per source_id. Writes contact.noted (by null) and rings the member it is for. Answers {note} or {error: empty | too_long | no_day | no_source | not_found | not_a_member | already}. Service role only.';


--
-- Name: platform_admin_add(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_admin_add(p_email text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid;
begin
  select u.id into v_id from auth.users u where lower(u.email) = lower(trim(p_email));
  if v_id is null then
    return format('no account for %s — nothing added', p_email);
  end if;
  insert into public.platform_admins (user_id) values (v_id) on conflict (user_id) do nothing;
  return format('%s may now open the back office', p_email);
end $$;


--
-- Name: FUNCTION platform_admin_add(p_email text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.platform_admin_add(p_email text) IS 'Adds a Chanlytics platform admin by email. Service-role only, and deliberately not reachable from the app: who may read every workspace is a decision a person makes at a console, not a button. Answers in words rather than raising, so a typo is not an outage.';


--
-- Name: platform_overview(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_overview() RETURNS TABLE(tenant_id uuid, slug text, name text, status text, timezone text, created_at timestamp with time zone, members integer, billing_mode text, billing_status text, trial_end timestamp with time zone, current_period_end timestamp with time zone, line_e164 text, line_kind text, voice_state text, sms_state text, reg_step text, reg_mock boolean, reg_sole_prop boolean, line_error text, whatsapp_number text, whatsapp_active boolean, voice_number text, voice_active boolean, last_inbound_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  -- THE guard, and the reason this is a function rather than a set of
  -- service-role reads in a route: a route can be added that forgets, and this
  -- cannot be reached without passing here first. Note that it turns the
  -- service role away too -- the check is about who is asking (auth.uid()),
  -- not about RLS -- so a key alone opens nothing.
  if not public.is_platform_admin() then
    raise exception 'Not a Chanlytics platform admin.' using errcode = '42501';
  end if;
  return query select * from public.platform_overview_rows();
end $$;


--
-- Name: FUNCTION platform_overview(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.platform_overview() IS 'Every workspace with the facts that answer most support questions: how it pays, whether its line answers, where its texting registration stands, and when a customer last reached it. Platform admins only -- the check is the first statement, which is why this is the only door to cross-tenant data.';


--
-- Name: platform_overview_rows(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_overview_rows() RETURNS TABLE(tenant_id uuid, slug text, name text, status text, timezone text, created_at timestamp with time zone, members integer, billing_mode text, billing_status text, trial_end timestamp with time zone, current_period_end timestamp with time zone, line_e164 text, line_kind text, voice_state text, sms_state text, reg_step text, reg_mock boolean, reg_sole_prop boolean, line_error text, whatsapp_number text, whatsapp_active boolean, voice_number text, voice_active boolean, last_inbound_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select * from public.platform_overview_rows_for(array(select t.id from public.tenants t));
$$;


--
-- Name: FUNCTION platform_overview_rows(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.platform_overview_rows() IS 'The back office join, in a SQL-language function so every column is validated when the migration applies. Not a door: EXECUTE is held by the owner alone, and platform_overview() -- which carries the platform-admin check -- is the only caller. Do not grant this to anything; grant the guarded function instead.';


--
-- Name: platform_overview_rows_for(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_overview_rows_for(p_tenants uuid[]) RETURNS TABLE(tenant_id uuid, slug text, name text, status text, timezone text, created_at timestamp with time zone, members integer, billing_mode text, billing_status text, trial_end timestamp with time zone, current_period_end timestamp with time zone, line_e164 text, line_kind text, voice_state text, sms_state text, reg_step text, reg_mock boolean, reg_sole_prop boolean, line_error text, whatsapp_number text, whatsapp_active boolean, voice_number text, voice_active boolean, last_inbound_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select
    t.id,
    t.slug,
    t.name,
    t.status,
    t.timezone,
    t.created_at,
    (select count(*)::integer from public.memberships m where m.tenant_id = t.id),
    b.mode,
    b.status,
    b.trial_end,
    b.current_period_end,
    l.e164,
    l.kind,
    l.voice_state,
    l.sms_state,
    l.reg_step,
    l.reg_mock,
    l.reg_sole_prop,
    l.last_error,
    wa.number_e164,
    wa.active,
    vo.number_e164,
    vo.active
    ,greatest(msg.at, call.at)
  from public.tenants t
  left join public.billing_accounts b on b.tenant_id = t.id
  -- The workspace's own line. A forwarded number sorts last: it is a real line
  -- but it is somebody else's, and "is their line answering" is about the one
  -- we provisioned whenever there is one.
  left join lateral (
    select ln.e164, ln.kind, ln.voice_state, ln.sms_state, ln.reg_step, ln.reg_mock, ln.reg_sole_prop, ln.last_error
      from public.lines ln
     where ln.tenant_id = t.id
     order by (ln.kind = 'forwarded'), ln.created_at
     limit 1
  ) l on true
  -- The channels: active if ANY row of that kind is active, and the number of the row that is (00094).
  left join lateral (
    select bool_or(c.status = 'active') as active,
           (array_agg(c.number_e164 order by (c.status <> 'active'), c.created_at desc))[1] as number_e164
      from public.tenant_channels c
     where c.tenant_id = t.id and c.kind = 'whatsapp'
  ) wa on true
  left join lateral (
    select bool_or(c.status = 'active') as active,
           (array_agg(c.number_e164 order by (c.status <> 'active'), c.created_at desc))[1] as number_e164
      from public.tenant_channels c
     where c.tenant_id = t.id and c.kind = 'voice'
  ) vo on true
  -- Ordered on the plain, indexed column (00094's reason); the coalesce chooses the value, not the order.
  left join lateral (
    select coalesce(m.channel_ts, m.created_at) as at from public.messages m
     where m.tenant_id = t.id and m.direction = 'inbound'
     order by m.created_at desc limit 1
  ) msg on true
  left join lateral (
    select c.started_at as at from public.calls c
     where c.tenant_id = t.id and c.direction = 'inbound'
     order by c.started_at desc nulls last limit 1
  ) call on true
  -- The one filter. A null or empty list matches nothing: every caller names the workspaces it may see.
  where t.id = any(coalesce(p_tenants, '{}'::uuid[]))
  order by t.created_at;
$$;


--
-- Name: FUNCTION platform_overview_rows_for(p_tenants uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.platform_overview_rows_for(p_tenants uuid[]) IS 'One row per named workspace: is it paying, is its line answering, is its texting registered, when did it last hear from a customer. The one join behind the back office and the partner''s table (0012). Owner-only: the doors that call it decide which workspaces.';


--
-- Name: platform_partner_balances(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_partner_balances() RETURNS TABLE(partner_id uuid, code text, email text, status text, share_bp integer, joined_at timestamp with time zone, workspaces integer, under_review integer, currency text, held_cents bigint, payable_cents bigint, paid_cents bigint, last_paid_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.is_platform_admin() then
    raise exception 'Not a Chanlytics platform admin.' using errcode = '42501';
  end if;
  return query
  with money as (
    select e.partner_id, e.currency,
           coalesce(sum(e.earned_cents) filter (where e.state = 'held'), 0)::bigint as held,
           coalesce(sum(e.earned_cents) filter (where e.state = 'payable'), 0)::bigint as payable,
           coalesce(sum(e.earned_cents) filter (where e.state = 'paid'), 0)::bigint as paid
      from public.partner_earnings e
     group by e.partner_id, e.currency
  )
  select p.id, p.code, u.email::text, p.status, p.share_bp, p.created_at,
         (select count(*)::int from public.partner_tenants pt where pt.partner_id = p.id),
         (select count(*)::int from public.partner_tenants pt where pt.partner_id = p.id and pt.standing = 'review'),
         m.currency,
         coalesce(m.held, 0)::bigint, coalesce(m.payable, 0)::bigint, coalesce(m.paid, 0)::bigint,
         (select max(o.sent_at) from public.partner_payouts o where o.partner_id = p.id
             and (m.currency is null or o.currency = m.currency))
    from public.partners p
    left join auth.users u on u.id = p.user_id
    left join money m on m.partner_id = p.id
   order by coalesce(m.payable, 0) desc, p.created_at;
end $$;


--
-- Name: FUNCTION platform_partner_balances(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.platform_partner_balances() IS 'Every partner for the back office (0012, P5): their workspaces, how many are under review, and per currency what is held, payable and paid. Platform admins only.';


--
-- Name: platform_partner_workspaces(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_partner_workspaces() RETURNS TABLE(tenant_id uuid, partner_id uuid, code text, attributed_at timestamp with time zone, standing text, standing_why text, standing_at timestamp with time zone, decided_by text, checks jsonb, origin text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.is_platform_admin() then
    raise exception 'Not a Chanlytics platform admin.' using errcode = '42501';
  end if;
  return query
  select pt.tenant_id, pt.partner_id, p.code, pt.attributed_at, pt.standing, pt.standing_why, pt.standing_at,
         case when pt.standing is null then null
              when pt.standing_by is not null then 'person'
              when pt.checks ? 'already_paying' then 'joining'
              else 'sweep' end,
         pt.checks, pt.origin
    from public.partner_tenants pt
    join public.partners p on p.id = pt.partner_id
   order by (pt.standing = 'review') desc nulls last, pt.attributed_at desc;
end $$;


--
-- Name: FUNCTION platform_partner_workspaces(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.platform_partner_workspaces() IS 'Who brought each workspace, how (link, handover or invite), and its standing with who decided it (the nightly check, a person, or the rule as the partner joined), for the back office (0012, P5; 0018). Platform admins only.';


--
-- Name: playbooks_due(text, timestamp with time zone, integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.playbooks_due(p_kind text, p_at timestamp with time zone, p_last_hour integer, p_limit integer, p_tenant_id uuid DEFAULT NULL::uuid) RETURNS TABLE(playbook jsonb, timezone text, due_total bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select to_jsonb(p), z.tz, count(*) over ()
    from public.playbooks p
    join public.tenants t on t.id = p.tenant_id
    cross join lateral (select public.safe_zone(coalesce(nullif(btrim(t.timezone), ''), 'America/New_York')) as tz) z
    cross join lateral (select p_at at time zone z.tz as clock) l
   where p.state = 'running' and p.kind = p_kind
     and t.status <> 'paused'
     and (p_tenant_id is null or p.tenant_id = p_tenant_id)
     and extract(hour from l.clock) between p.run_hour and p_last_hour
     and p.last_run_for is distinct from l.clock::date
   order by p.last_run_at nulls first, p.created_at, p.id
   limit greatest(coalesce(p_limit, 0), 0)
$$;


--
-- Name: FUNCTION playbooks_due(p_kind text, p_at timestamp with time zone, p_last_hour integer, p_limit integer, p_tenant_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.playbooks_due(p_kind text, p_at timestamp with time zone, p_last_hour integer, p_limit integer, p_tenant_id uuid) IS 'The running playbooks of one kind due at p_at by their workspace''s own clock (runDueNow''s rule), a paused workspace''s never, never run first, then least recently run, with due_total the count of all that were due. The playbooks sweep''s two pages (00245).';


--
-- Name: profile_set(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.profile_set(p_display_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid  uuid := auth.uid();
  v_name text := btrim(coalesce(p_display_name, ''));
begin
  if v_uid is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  if char_length(v_name) > 80 then
    raise exception 'A name is at most 80 characters.' using errcode = '22023';
  end if;
  insert into public.profiles (user_id, display_name)
  values (v_uid, v_name)
  on conflict (user_id) do update set display_name = excluded.display_name;
  return jsonb_build_object('display_name', v_name);
end $$;


--
-- Name: FUNCTION profile_set(p_display_name text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.profile_set(p_display_name text) IS 'Your own display name, trimmed, at most 80 characters; empty clears it. The only write path to profiles.';


--
-- Name: provision_tenant(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.provision_tenant(p_tenant_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into public.policies (tenant_id, class, mode, limits)
  select p_tenant_id, c.class, c.mode,
         case when c.class = 'reply'
              then '{"max_replies_day": 20, "pause_hours": 24, "max_llm_tokens_day": 1000000}'::jsonb
              else '{}'::jsonb end
  from (values
    ('faq','auto'), ('booking','auto'), ('reply','auto'),
    ('reengage','ask'), ('campaign','ask'), ('reviews','ask'), ('money','never'), ('follow_up','ask'),
    ('outreach','veto')
  ) as c(class, mode)
  on conflict (tenant_id, class, subject_type, subject_id) do nothing;

  insert into public.tenant_config (tenant_id) values (p_tenant_id)
  on conflict (tenant_id) do nothing;

  insert into public.billing_accounts (tenant_id, mode, status) values (p_tenant_id, 'stripe', 'none')
  on conflict (tenant_id) do nothing;
end $$;


--
-- Name: FUNCTION provision_tenant(p_tenant_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.provision_tenant(p_tenant_id uuid) IS 'Idempotently give a tenant its policy matrix and an empty config row. Called by the tenants insert trigger; safe to call again.';


--
-- Name: provision_tenant_on_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.provision_tenant_on_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform public.provision_tenant(new.id);
  return new;
end $$;


--
-- Name: purge_ask(interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_ask(p_keep interval DEFAULT '90 days'::interval) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_count integer;
begin
  delete from public.ask_threads where last_at < now() - p_keep;
  get diagnostics v_count = row_count;
  return v_count;
end $$;


--
-- Name: FUNCTION purge_ask(p_keep interval); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.purge_ask(p_keep interval) IS 'Drops Ask threads (and their messages) untouched for longer than p_keep (default 90 days). Ask messages quote customers; they are not the record.';


--
-- Name: purge_cron_history(interval, integer, interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_cron_history(p_keep interval DEFAULT '14 days'::interval, p_keep_per_job integer DEFAULT 30, p_keep_frequent interval DEFAULT '1 day'::interval) RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with ranked as (
    select d.runid,
           row_number() over (partition by d.jobid order by d.start_time desc nulls first) as rn,
           coalesce(j.schedule like '% seconds', false) as frequent
      from cron.job_run_details d
      left join cron.job j on j.jobid = d.jobid
  ),
  gone as (
    delete from cron.job_run_details d
     using ranked r
     where r.runid = d.runid
       and r.rn > p_keep_per_job
       and d.start_time < now() - case when r.frequent then p_keep_frequent else p_keep end
    returning 1
  )
  select count(*)::integer from gone
$$;


--
-- Name: FUNCTION purge_cron_history(p_keep interval, p_keep_per_job integer, p_keep_frequent interval); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.purge_cron_history(p_keep interval, p_keep_per_job integer, p_keep_frequent interval) IS 'Bounds cron.job_run_details: drops runs older than p_keep, or older than p_keep_frequent for a job pg_cron schedules in seconds, except the most recent p_keep_per_job of each job. Rows with a null start_time are never deleted. Scheduled daily as purge-cron-history (00026).';


--
-- Name: purge_events(interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_events(p_keep interval DEFAULT '30 days'::interval) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_count integer;
begin
  delete from public.events
   where kind in (
     'webhook.auth', 'webhook.delivery',
     'ingest.allowlist_skip', 'ingest.unreachable_sender', 'ingest.unroutable',
     'usage.llm_tokens', 'usage.ask_tokens'
   )
     and created_at < now() - p_keep;
  get diagnostics v_count = row_count;
  return v_count;
end $$;


--
-- Name: FUNCTION purge_events(p_keep interval); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.purge_events(p_keep interval) IS 'Drops the evidence kinds (webhook receipts and deliveries, the allowlist''s skips, unreachable and unroutable inbounds, the two model-usage rows) older than p_keep (default 30 days; contracts RETENTION_DAYS.events_evidence). Every other event kind is the record and is never purged here.';


--
-- Name: purge_jobs(interval, interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_jobs(p_finished interval DEFAULT '7 days'::interval, p_failed interval DEFAULT '90 days'::interval) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET lock_timeout TO '3s'
    AS $_$
declare
  v_total integer := 0;
  v_n     integer;
begin
  -- A thousand at a time, so no one statement holds the ledger for long.
  loop
    delete from public.jobs j
     where j.id in (
       select c.id from public.jobs c
        where ((c.state in ('done', 'canceled') and c.updated_at < now() - p_finished)
            or (c.state = 'failed' and c.updated_at < now() - p_failed))
          -- A CASE, not an AND, so the cast only ever sees a well-formed id (a
          -- scrubbed payload has none): Postgres promises no order among ANDs.
          and not exists (
            select 1 from public.messages m
             where c.kind = 'outbound_send'
               and m.id = case
                            when c.payload->>'message_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                            then (c.payload->>'message_id')::uuid
                          end
               and m.status = 'queued'
          )
        limit 1000
     );
    get diagnostics v_n = row_count;
    v_total := v_total + v_n;
    exit when v_n < 1000;
  end loop;
  return v_total;
end $_$;


--
-- Name: FUNCTION purge_jobs(p_finished interval, p_failed interval); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.purge_jobs(p_finished interval, p_failed interval) IS 'Nightly. Deletes done and canceled jobs a week after they last changed and failed ones after 90 days, a thousand at a time, keeping any finished outbound_send whose message is still queued. Never reads a scheduled or fired row. Numbers: contracts'' RETENTION_DAYS.';


--
-- Name: purge_leads(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_leads() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_total integer := 0;
  v_n     integer;
  r       record;
begin
  -- Untouched for 90 days: no person, no contact, no export. Set aside.
  update public.leads
     set stage = 'archived', closed_reason = 'stale'
   where stage = 'ready' and contact_id is null and contacted_at is null and exported_at is null
     and found_at < now() - interval '90 days' and erased_at is null and blanked_at is null;
  get diagnostics v_n = row_count; v_total := v_total + v_n;
  -- Set aside for 180 days since it was found: its details go.
  for r in select l.id from public.leads l
            where l.closed_reason = 'stale' and l.blanked_at is null and l.erased_at is null and l.found_at < now() - interval '180 days'
  loop
    v_total := v_total + public.lead_blank(r.id);
  end loop;
  -- A place a search left out, 30 days on: the membership's details go and
  -- the lead's with them when nothing else holds it; the membership stays,
  -- excluded, so the count of what was left out does not move.
  for r in select distinct m.lead_id from public.lead_search_members m
            where m.class = 'excluded' and m.blanked_at is null and m.created_at < now() - interval '30 days'
  loop
    if not exists (select 1 from public.lead_search_members m2 where m2.lead_id = r.lead_id and m2.class <> 'excluded' and m2.blanked_at is null)
       and not exists (select 1 from public.leads l where l.id = r.lead_id and (l.contact_id is not null or l.contacted_at is not null or l.exported_at is not null)) then
      v_total := v_total + public.lead_blank(r.lead_id);
    else
      update public.lead_search_members set judgment = '{}'::jsonb, reason = '', blanked_at = now()
       where lead_id = r.lead_id and class = 'excluded' and blanked_at is null;
    end if;
  end loop;
  -- The judge's answers outlive nothing they judged.
  delete from public.lead_judgments where created_at < now() - interval '180 days';
  return v_total;
end $$;


--
-- Name: FUNCTION purge_leads(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.purge_leads() IS 'Nightly. A lead untouched for 90 days is set aside (archived, stale); set aside and 180 days since it was found, its details are removed (lead_blank); a place a search left out loses its details after 30 days but stays counted as left out. Judgments older than 180 days go. Numbers: contracts'' RETENTION_DAYS.';


--
-- Name: purge_notifications(interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_notifications(p_keep interval DEFAULT '90 days'::interval) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_n integer;
begin
  delete from notifications where created_at < now() - p_keep;
  get diagnostics v_n = row_count;
  return v_n;
end $$;


--
-- Name: push_device_forget(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.push_device_forget(p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user uuid := auth.uid();
  v_gone integer;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  delete from push_devices where token = p_token and user_id = v_user;
  get diagnostics v_gone = row_count;
  return jsonb_build_object('forgotten', v_gone);
end $$;


--
-- Name: push_device_register(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.push_device_register(p_token text, p_platform text, p_app_version text DEFAULT NULL::text, p_activity_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user uuid := auth.uid();
  v_id   uuid;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  delete from push_devices where token = p_token and user_id <> v_user;
  -- The activity token is this phone's now: another row that still holds it lets it go.
  if p_activity_token is not null then
    update push_devices set activity_token = null where activity_token = p_activity_token and token <> p_token;
  end if;
  insert into push_devices (user_id, token, platform, app_version, activity_token, last_seen_at)
  values (v_user, p_token, p_platform, p_app_version, p_activity_token, now())
  on conflict (token) do update
    set platform = excluded.platform,
        app_version = excluded.app_version,
        -- A phone that has not said its activity token this time keeps the one it said before.
        activity_token = coalesce(excluded.activity_token, push_devices.activity_token),
        last_seen_at = now()
  returning id into v_id;
  return jsonb_build_object('id', v_id);
end $$;


--
-- Name: put_channel_credentials(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.put_channel_credentials(p_channel_id uuid, p_secret jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault'
    AS $$
declare
  v_name text := 'wa-creds-' || p_channel_id::text;
  v_id   uuid;
begin
  if not exists (select 1 from public.tenant_channels where id = p_channel_id) then
    raise exception 'put_channel_credentials: no such channel';
  end if;
  select id into v_id from vault.secrets where name = v_name;
  if v_id is null then
    perform vault.create_secret(p_secret::text, v_name, 'WhatsApp business token for channel ' || p_channel_id::text);
  else
    perform vault.update_secret(v_id, p_secret::text);
  end if;
  update public.tenant_channels set credentials_ref = v_name where id = p_channel_id;
  return v_name;
end $$;


--
-- Name: FUNCTION put_channel_credentials(p_channel_id uuid, p_secret jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.put_channel_credentials(p_channel_id uuid, p_secret jsonb) IS 'Service-role only: stores a channel''s credentials in Vault under wa-creds-<channel id> and points credentials_ref at it. The only write path for a credential.';


