--
-- Name: FUNCTION set_template_title(p_template_id uuid, p_title text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_template_title(p_template_id uuid, p_title text) IS 'Owner or operator names a template in the workspace''s own words; empty clears it. Meta''s name is untouched.';


--
-- Name: setup_request(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.setup_request(p_tenant_id uuid, p_what text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user uuid := auth.uid();
  v_last timestamptz;
  v_title text;
  v_body text;
  v_route text;
begin
  if v_user is null then
    raise exception 'Sign in required.' using errcode = '28000';
  end if;
  if p_tenant_id is null or not public.is_acting_member(p_tenant_id) then
    raise exception 'Workspace not found.' using errcode = 'P0002';
  end if;
  if p_what is null or p_what not in ('line', 'port', 'repair', 'forwarding') then
    raise exception 'Unknown request.' using errcode = '22023';
  end if;

  select max(e.created_at) into v_last
    from events e
   where e.tenant_id = p_tenant_id
     and e.kind = 'setup.requested'
     and e.data->>'what' = p_what;
  if v_last is not null and v_last > now() - interval '1 day' then
    return jsonb_build_object('ok', true, 'already', true, 'requested_at', v_last);
  end if;

  if p_what = 'line' then
    v_title := 'We got your request for a phone line';
    v_body := 'A person at Chanlytics will set up your line with you — a number, the receptionist answering it, and forwarding from the number you have. You will hear from us by email.';
    v_route := 'admin/setup';
  elsif p_what = 'port' then
    v_title := 'We got your request to bring your number';
    v_body := 'A person at Chanlytics will move the number you have onto Chanlytics with you. Keep your current phone service until the move is finished — cancelling it first can lose the number. You will hear from us by email.';
    v_route := 'admin/setup';
  elsif p_what = 'forwarding' then
    v_title := 'We got your request to set up forwarding';
    v_body := 'A person at Chanlytics will set up forwarding in your phone system with you on a call. You will hear from us by email to find a time.';
    v_route := 'start/phone';
  else
    v_title := 'We got your request to repair your settings';
    v_body := 'A person at Chanlytics will repair the business settings the receptionist can no longer read; until then it stays silent. You will hear from us by email.';
    v_route := 'admin/workspace';
  end if;

  insert into notifications (tenant_id, kind, title, body, route, subject_type, subject_id)
  values (p_tenant_id, 'alert', v_title, v_body, v_route, 'setup', null);

  insert into events (tenant_id, kind, category, subject_type, subject_id, data)
  values (p_tenant_id, 'setup.requested', 'setup', 'tenant', p_tenant_id,
          jsonb_build_object('what', p_what, 'by', v_user));

  return jsonb_build_object('ok', true, 'already', false, 'requested_at', now());
end $$;


--
-- Name: FUNCTION setup_request(p_tenant_id uuid, p_what text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.setup_request(p_tenant_id uuid, p_what text) IS 'Setup: the owner asks a person at Chanlytics for something the product cannot do by itself -- a phone line, bringing a number over, setting up forwarding in an office phone system, or repairing a configuration the receptionist cannot read. A bell row for the workspace, an event for the platform; idempotent within a day per thing.';


--
-- Name: stamp_email_complaint(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stamp_email_complaint(p_tenant_id uuid, p_message_id uuid, p_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_n integer;
begin
  update public.messages m
     set meta = jsonb_set(m.meta, '{email,complained_at}', to_jsonb(p_at), true)
   where m.id = p_message_id and m.tenant_id = p_tenant_id and m.channel = 'email' and m.direction = 'outbound'
     and m.meta ? 'email' and not (m.meta->'email' ? 'complained_at');
  get diagnostics v_n = row_count;
  return v_n > 0;
end $$;


--
-- Name: stamp_email_left_as(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stamp_email_left_as(p_tenant_id uuid, p_message_id uuid, p_left_as text, p_why text) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with stamped as (
    update public.messages m
       set meta = jsonb_set(
             coalesce(m.meta, '{}'::jsonb),
             '{email}',
             coalesce(m.meta->'email', '{}'::jsonb)
               || jsonb_build_object('left_as', p_left_as, 'left_as_why', p_why)
           )
     where m.id = p_message_id
       and m.tenant_id = p_tenant_id
       and m.channel = 'email'
       and m.direction = 'outbound'
       and p_left_as in ('own', 'mailbox')
       and (p_why is null or char_length(p_why) <= 60)
    returning 1
  )
  select exists (select 1 from stamped)
$$;


--
-- Name: FUNCTION stamp_email_left_as(p_tenant_id uuid, p_message_id uuid, p_left_as text, p_why text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.stamp_email_left_as(p_tenant_id uuid, p_message_id uuid, p_left_as text, p_why text) IS 'How a person''s email reply left (core deliver): own (the domain it was frozen with) or mailbox, and why not own. Merged into meta.email. Service role only.';


--
-- Name: stamp_email_sent(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stamp_email_sent(p_tenant_id uuid, p_message_id uuid, p_provider_id text, p_rfc_message_id text) RETURNS TABLE(status text, conversation_id uuid)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  update messages m
     set external_id = coalesce(m.external_id, p_provider_id),
         meta = jsonb_set(
           coalesce(m.meta, '{}'::jsonb),
           '{email}',
           coalesce(m.meta->'email', '{}'::jsonb)
             || jsonb_strip_nulls(jsonb_build_object('message_id', p_rfc_message_id))
         )
   where m.id = p_message_id
     and m.tenant_id = p_tenant_id
     and m.channel = 'email'
     and m.direction = 'outbound'
  returning m.status, m.conversation_id;
$$;


--
-- Name: sweep_health(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sweep_health() RETURNS TABLE(sweep text, healthy boolean, detail text, last_request_at timestamp with time zone, status_code integer, scheduled boolean, alerted_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with last_ok as (
    -- When each job last succeeded. cron.job_run_details is bounded by
    -- purge_cron_history (00026): 14 days, at least 30 runs per job, one day
    -- for the ten-second jobs.
    select d.jobid, max(d.end_time) as at
      from cron.job_run_details d
     where d.status = 'succeeded'
     group by d.jobid
  ),
  latest as (
    -- How each job's most recent run ended.
    select distinct on (d.jobid) d.jobid, d.status, left(d.return_message, 160) as message
      from cron.job_run_details d
     order by d.jobid, d.start_time desc
  ),
  observed as (
    select e.sweep, e.jobname, e.max_silence, e.judged_by, e.registered_at,
           e.request_id, e.requested_at, e.note, e.alerted_at,
           j.jobid is not null                    as job_exists,
           coalesce(j.active, false)              as job_active,
           j.schedule                             as job_schedule,
           r.id is not null                       as has_response,
           r.status_code,
           coalesce(r.timed_out, false)           as timed_out,
           r.error_msg,
           left(r.content, 200)                   as content,
           -- net._http_response is UNLOGGED: a Postgres crash truncates it and
           -- the sequence behind net.http_post resets with it. If pg_net has
           -- recorded anything NEWER than our request, a missing row is really
           -- missing; if it has not, the table was emptied and we say nothing.
           exists (select 1 from net._http_response nr where nr.id > e.request_id)
                                                  as newer_response_seen,
           -- pg_net deletes an answer six hours after recording it, with
           -- everything as old, and a clock that records its looks keeps its
           -- last real ask judged for longer than that. If pg_net holds
           -- nothing OLDER than our request, any answer it had went with the
           -- rest and was judged while it was held, and we say nothing.
           exists (select 1 from net._http_response nr where nr.id < e.request_id)
                                                  as older_response_seen,
           ok.at                                  as last_ok,
           lt.status                              as last_status,
           lt.message                             as last_message
      from public.sweep_status e
      left join lateral (
        select jobid, active, schedule from cron.job
         where jobname = e.jobname order by jobid limit 1
      ) j on true
      left join last_ok ok on ok.jobid = j.jobid
      left join latest  lt on lt.jobid = j.jobid
      left join net._http_response r on r.id = e.request_id
  ),
  judged as (
    select o.*,
      case
        when o.jobname is null then
          'this clock is not registered: sweep_status names no cron job for it'
        when not o.job_exists then
          'no cron job named ' || o.jobname || ' is scheduled'
        when not o.job_active then
          'the cron job ' || o.jobname || ' is disabled'

        -- Judged on its runs: the jobs that never leave the database.
        when o.judged_by = 'run' and o.last_status = 'failed' then
          'the last run of ' || o.jobname || ' failed: ' || coalesce(o.last_message, '(no message)')
        when o.judged_by = 'run' and o.max_silence is null then
          null
        when o.judged_by = 'run' and o.last_ok is null and o.registered_at > now() - o.max_silence then
          null
        when o.judged_by = 'run' and o.last_ok is null then
          'the job ' || o.jobname || ' has never succeeded; it is scheduled ' || coalesce(o.job_schedule, '(unknown)')
        when o.judged_by = 'run' and o.last_ok < now() - o.max_silence then
          'the job ' || o.jobname || ' last succeeded at ' ||
          to_char(o.last_ok at time zone 'utc', 'YYYY-MM-DD HH24:MI') || ' UTC; it is scheduled ' ||
          coalesce(o.job_schedule, '(unknown)')
        when o.judged_by = 'run' then
          null

        -- Judged on the request it enqueued and what the edge answered, as 00098 did.
        when o.note is not null then
          'the trigger could not send the request: ' || o.note
        when o.max_silence is not null and o.requested_at is null then
          'this sweep has never enqueued a request'
        when o.max_silence is not null and o.requested_at < now() - o.max_silence then
          'last enqueued a request at ' ||
          to_char(o.requested_at at time zone 'utc', 'YYYY-MM-DD HH24:MI') || ' UTC, ' ||
          round((extract(epoch from (now() - o.requested_at)) / 60)::numeric)::text ||
          ' minutes ago; ' || o.jobname || ' is scheduled ' || coalesce(o.job_schedule, '(unknown)')
        when o.requested_at is null or o.requested_at < now() - interval '1 hour' then
          null
        when not o.has_response and o.request_id is not null
             and o.requested_at < now() - interval '2 minutes'
             and o.older_response_seen and o.newer_response_seen then
          'the request was enqueued at ' || to_char(o.requested_at at time zone 'utc', 'HH24:MI') ||
          ' UTC and pg_net never recorded a response'
        when o.timed_out then
          'the request timed out before the edge answered'
        when o.error_msg is not null then
          'pg_net could not complete the request: ' || o.error_msg
        when o.status_code is not null and (o.status_code < 200 or o.status_code > 299) then
          'the edge answered ' || o.status_code || ': ' || coalesce(o.content, '(no body)')
      end as detail
      from observed o
  )
  select j.sweep,
         j.detail is null,
         j.detail,
         case when j.judged_by = 'run' then j.last_ok else j.requested_at end,
         j.status_code,
         j.job_exists and j.job_active,
         j.alerted_at
    from judged j
   order by j.sweep;
$$;


--
-- Name: FUNCTION sweep_health(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sweep_health() IS 'One row per registered clock (public.sweep_status): healthy, why not, when it last spoke (a request enqueued, or a run that succeeded), what the edge answered, whether pg_cron still has it, and when it was last alerted. The health sweep mails the unhealthy ones and stamps alerted_at only after delivery; /api/health answers 503 to an outside monitor when any is unhealthy.';


--
-- Name: sweep_mark_alerted(text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sweep_mark_alerted(p_alerted text[], p_healthy text[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_stamped integer;
  v_cleared integer;
begin
  insert into public.sweep_status (sweep, alerted_at)
  select x, now() from unnest(coalesce(p_alerted, '{}'::text[])) as x
  on conflict (sweep) do update set alerted_at = excluded.alerted_at;
  get diagnostics v_stamped = row_count;

  update public.sweep_status
     set alerted_at = null
   where sweep = any(coalesce(p_healthy, '{}'::text[]))
     and alerted_at is not null;
  get diagnostics v_cleared = row_count;

  return v_stamped + v_cleared;
end $$;


--
-- Name: FUNCTION sweep_mark_alerted(p_alerted text[], p_healthy text[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sweep_mark_alerted(p_alerted text[], p_healthy text[]) IS 'Records that an alert was DELIVERED for each sweep in p_alerted, and clears the suppression stamp of each sweep in p_healthy. Returns rows stamped + rows cleared.';


--
-- Name: sweep_recent_responses(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sweep_recent_responses(p_limit integer DEFAULT 10) RETURNS TABLE(request_id bigint, status_code integer, body text, created_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'net'
    AS $$
  select r.id, r.status_code, left(r.content, 500), r.created
    from net._http_response r
   order by r.created desc
   limit greatest(1, least(p_limit, 100));
$$;


--
-- Name: sweep_schedules(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sweep_schedules() RETURNS TABLE(jobname text, schedule text, active boolean, last_run timestamp with time zone, last_status text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'cron'
    AS $$
  select j.jobname, j.schedule, j.active,
         d.start_time, d.status
    from cron.job j
    left join lateral (
      select start_time, status
        from cron.job_run_details d
       where d.jobid = j.jobid
       order by start_time desc
       limit 1
    ) d on true
   order by j.jobname;
$$;


--
-- Name: sweep_status_registered(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sweep_status_registered() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if NEW.jobname is null and not exists (select 1 from public.sweep_status s where s.sweep = NEW.sweep) then
    raise exception 'sweep % is not registered: insert it with the cron job it is (jobname) and how it is judged (judged_by) first', NEW.sweep;
  end if;
  return NEW;
end $$;


--
-- Name: FUNCTION sweep_status_registered(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sweep_status_registered() IS 'A sweep name that has no row must arrive with its cron job name; the upserts the sweeps themselves make land on rows that exist. Replaces the CHECK on the name that 00083 to 00097 kept widening.';


--
-- Name: take_rate(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.take_rate(p_bucket text, p_actor text, p_limit integer, p_window_ms integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_window interval := make_interval(secs => p_window_ms / 1000.0);
  v_since  timestamptz := clock_timestamp() - make_interval(secs => p_window_ms / 1000.0);
  v_n      int;
  v_oldest timestamptz;
begin
  perform pg_advisory_xact_lock(hashtext(p_bucket || ':' || p_actor));
  delete from public.rate_hits where bucket = p_bucket and actor = p_actor and at < v_since;
  select count(*), min(at) into v_n, v_oldest
    from public.rate_hits where bucket = p_bucket and actor = p_actor;
  if v_n >= p_limit then
    return jsonb_build_object(
      'allowed', false,
      'retry_after_s', greatest(1, ceil(extract(epoch from (v_oldest + v_window - clock_timestamp())))::int)
    );
  end if;
  insert into public.rate_hits (bucket, actor) values (p_bucket, p_actor);
  return jsonb_build_object('allowed', true, 'used', v_n + 1);
end
$$;


--
-- Name: FUNCTION take_rate(p_bucket text, p_actor text, p_limit integer, p_window_ms integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.take_rate(p_bucket text, p_actor text, p_limit integer, p_window_ms integer) IS 'Count one hit for an actor in a bucket, or say when to try again. The actor is any label: a user id, or a hashed network or address for the public sign-up door.';


--
-- Name: team_roster(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.team_roster(p_tenant_id uuid) RETURNS TABLE(membership_id uuid, member_user_id uuid, email text, role text, joined_at timestamp with time zone, display_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  -- THE guard. A definer function that reads auth.users and does not check who
  -- is asking is an email-enumeration endpoint for every workspace at once.
  if not exists (
    select 1 from public.memberships m
     where m.tenant_id = p_tenant_id and m.user_id = auth.uid()
       and (m.role <> 'partner' or public.session_shows_second_factor())
  ) then
    raise exception 'Not a member of this workspace.' using errcode = '42501';
  end if;

  -- Every reference is qualified: the OUT parameters are in scope for the
  -- whole body, and an unqualified `email` or `display_name` is ambiguous at
  -- call time.
  return query
    select m.id, m.user_id, u.email::text, m.role, m.created_at, coalesce(p.display_name, '')::text
      from public.memberships m
      join auth.users u on u.id = m.user_id
      left join public.profiles p on p.user_id = m.user_id
     where m.tenant_id = p_tenant_id
     order by m.created_at;
end $$;


--
-- Name: FUNCTION team_roster(p_tenant_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.team_roster(p_tenant_id uuid) IS 'Members of a workspace with their emails and the names they gave, in one query. Caller must belong to the workspace.';


