CREATE FUNCTION public.trigger_calendar_sweep() RETURNS bigint
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$ select public.request_sweep('calendar', '/api/cron/calendar') $$;


--
-- Name: FUNCTION trigger_calendar_sweep(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.trigger_calendar_sweep() IS 'Asks the edge to read each workspace''s calendar feed. Recorded in public.sweep_status.';


--
-- Name: trigger_call_reconcile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_call_reconcile() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_pending int;
begin
  select count(*) into v_pending
    from public.calls
   where (status = 'ongoing'
          and (updated_at < now() - interval '5 minutes'
               or started_at < now() - interval '30 minutes'))
      or (status in ('ended', 'error')
          and updated_at < now() - interval '5 minutes'
          and recording->>'fetch_state' = 'pending'
          and coalesce((recording->>'attempts')::int, 0) < 3)
      -- a call that ended without an analysis still owes the thread a line
      or (status in ('ended', 'error')
          and message_id is null
          and conversation_id is not null
          and ended_at < now() - interval '15 minutes')
      -- audio past its retention (contracts RETENTION_DAYS.call_recordings):
      -- exactly what the sweep's first leg, purgeExpiredRecordings, selects
      or (recording->>'fetch_state' = 'stored'
          and started_at < now() - interval '90 days');
  if v_pending = 0 then
    -- 00026: clearing the note here is load-bearing. On an idle line this is
    -- every tick, and a note one transient Vault failure wrote would otherwise
    -- outlive its fault and be mailed to the platform four times a day.
    update public.sweep_status set note = null where sweep = 'calls' and note is not null;
    return null;
  end if;

  -- The request id and when it was enqueued, or, when Vault cannot send it,
  -- the note: whichever it is, where sweep_health() reads it.
  return public.request_sweep('calls', '/api/cron/calls', 65000);
end $$;


--
-- Name: FUNCTION trigger_call_reconcile(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.trigger_call_reconcile() IS 'Asks the edge (api/cron/calls) to sweep when the calls table owes it work: a call still marked ongoing, a recording copy still pending, a thread still owed its call line, or audio past its retention. Asks through request_sweep(), which records the request so sweep_health() judges the answer, and waits 65 s, past the sweep''s own 60. With nothing owed, clears the note and records nothing else.';


--
-- Name: trigger_deadman_sweep(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_deadman_sweep() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_key text;
  v_url text;
  v_id  bigint;
begin
  select public.get_cron_sweep_key() into v_key;
  select decrypted_secret into v_url from vault.decrypted_secrets where name = 'edge_base_url';
  if v_key is null or v_url is null then
    raise warning 'deadman sweep not configured (missing cron_sweep_key or edge_base_url)';
    insert into public.sweep_status (sweep, note)
         values ('deadman', 'missing cron_sweep_key or edge_base_url in Vault')
    on conflict (sweep) do update set note = excluded.note, request_id = null;
    return null;
  end if;
  select net.http_post(
    url     := v_url || '/api/cron/deadman',
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-cron-key', v_key),
    body    := '{}'::jsonb,
    timeout_milliseconds := 20000
  ) into v_id;
  insert into public.sweep_status (sweep, request_id, requested_at, note)
       values ('deadman', v_id, now(), null)
  on conflict (sweep) do update
     set request_id = excluded.request_id, requested_at = excluded.requested_at, note = null;
  return v_id;
end $$;


--
-- Name: FUNCTION trigger_deadman_sweep(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.trigger_deadman_sweep() IS 'Asks the edge to flag escalations nobody picked up. Records the pg_net request id in public.sweep_status so the answer can be found later.';


--
-- Name: trigger_domains_sweep(); Type: FUNCTION; Schema: public; Owner: -
