CREATE FUNCTION public.trigger_domains_sweep() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  if exists (select 1 from public.sending_domains d where d.state in ('verifying', 'verified', 'held')) then
    return public.request_sweep('domains', '/api/cron/domains', 65000);
  end if;
  insert into public.sweep_status (sweep, requested_at) values ('domains', now())
  on conflict (sweep) do update set requested_at = excluded.requested_at;
  return null;
end $$;


--
-- Name: FUNCTION trigger_domains_sweep(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.trigger_domains_sweep() IS 'The domains clock (Reach out). Calls the edge (/api/cron/domains) only when a domain is being checked or can send; otherwise records that it looked.';


--
-- Name: trigger_google_sweep(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_google_sweep() RETURNS bigint
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$ select public.request_sweep('google', '/api/cron/google') $$;


--
-- Name: FUNCTION trigger_google_sweep(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.trigger_google_sweep() IS 'Asks the edge to read each linked Google listing. Recorded in public.sweep_status.';


--
-- Name: trigger_jobs_tick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_jobs_tick() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  if exists (
    select 1 from public.jobs
     where (state = 'scheduled' and due_at <= now())
        or (state = 'fired' and lease_until < now())
  ) then
    return public.request_sweep('jobs', '/api/jobs/tick');
  end if;
  -- Nothing due: the look itself is the evidence. requested_at moves;
  -- request_id and note stay as the last real call left them, so a failed
  -- answer or a missing Vault secret stays visible until a call succeeds.
  insert into public.sweep_status (sweep, requested_at) values ('jobs', now())
  on conflict (sweep) do update set requested_at = excluded.requested_at;
  return null;
end $$;


--
-- Name: FUNCTION trigger_jobs_tick(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.trigger_jobs_tick() IS 'The ledger heartbeat. Calls the edge through request_sweep() only when a job is due or a lease has run out; otherwise records that it looked, so sweep_health() can tell a quiet ledger from a stopped clock.';


--
-- Name: trigger_leads_sweep(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_leads_sweep() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  -- Any round that has not ended, not only one waiting or checking: a round
  -- whose lead_round_start job died before it wrote a run sits in 'queued'
  -- with no run at all, and nothing but the sweep can end it and give its
  -- allowance and budget back (lead_rounds_live serves this predicate).
  if exists (select 1 from public.lead_runs r where r.state in ('claimed', 'starting', 'running', 'unknown'))
     or exists (select 1 from public.lead_rounds r where r.state <> 'ended') then
    return public.request_sweep('leads', '/api/cron/leads');
  end if;
  insert into public.sweep_status (sweep, requested_at) values ('leads', now())
  on conflict (sweep) do update set requested_at = excluded.requested_at;
  return null;
end $$;


--
-- Name: FUNCTION trigger_leads_sweep(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.trigger_leads_sweep() IS 'The lead finder''s clock. Calls the edge (/api/cron/leads) only when a run is live or a round has not ended -- a round whose start job died sits queued with no run, and its reservation comes back only when something ends it; otherwise records that it looked, so sweep_health() can tell a quiet engine from a stopped clock.';


