--
-- Name: trigger_notes_sweep(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_notes_sweep() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  if exists (
       select 1 from calls c
        where c.note_checked_at is null and c.notified_at is not null and c.contact_id is not null
          and c.direction = 'inbound' and c.ended_at > now() - interval '3 days'
     ) or exists (
       select 1 from conversations v
        where v.last_inbound_at < now() - interval '6 hours'
          and v.last_inbound_at > now() - interval '7 days'
          and (v.note_checked_at is null or v.note_checked_at < v.last_inbound_at)
     ) then
    return public.request_sweep('notes', '/api/cron/notes');
  end if;
  insert into public.sweep_status (sweep, requested_at) values ('notes', now())
  on conflict (sweep) do update set requested_at = excluded.requested_at;
  return null;
end $$;


--
-- Name: FUNCTION trigger_notes_sweep(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.trigger_notes_sweep() IS 'The note sweep''s clock (0007). Calls the edge (/api/cron/notes) only when a call or a quiet conversation is waiting for its look; otherwise records that it looked.';


--
-- Name: trigger_partners_sweep(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_partners_sweep() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  -- Only when something can be judged or can mature, or a partner has a letter due: a share held behind a review or
  -- a paused partner is not due, and asking the edge about it every day would be asking for nothing.
  if exists (select 1 from public.partner_tenants pt
              where pt.standing is null
                and exists (select 1 from public.partner_earnings e where e.tenant_id = pt.tenant_id))
     or exists (select 1 from public.partner_earnings e
                  join public.partners p on p.id = e.partner_id and p.status = 'active'
                 where e.state = 'held' and e.payable_at <= now()
                   and (e.tenant_id is null
                        or exists (select 1 from public.partner_tenants pt
                                    where pt.tenant_id = e.tenant_id and pt.standing in ('qualified', 'disqualified'))))
     or exists (select 1 from public.partner_letters_due(now())) then
    return public.request_sweep('partners', '/api/cron/partners', 55000);
  end if;
  insert into public.sweep_status (sweep, requested_at) values ('partners', now())
  on conflict (sweep) do update set requested_at = excluded.requested_at;
  return null;
end $$;


--
-- Name: FUNCTION trigger_partners_sweep(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.trigger_partners_sweep() IS 'The partner clock (0012, P3; 0014). Calls the edge once a day when a workspace awaits its standing, an earning can mature, or a partner has a letter due; otherwise records that it looked.';


