    activity_started_at timestamp with time zone,
    CONSTRAINT calls_direction_check CHECK ((direction = ANY (ARRAY['inbound'::text, 'outbound'::text]))),
    CONSTRAINT calls_outcome_check CHECK (((outcome IS NULL) OR (outcome = ANY (ARRAY['answered'::text, 'booking_link_sent'::text, 'callback_needed'::text, 'voicemail'::text, 'no_request'::text, 'other'::text])))),
    CONSTRAINT calls_status_check CHECK ((status = ANY (ARRAY['registered'::text, 'ongoing'::text, 'ended'::text, 'error'::text, 'not_connected'::text])))
);


--
-- Name: COLUMN calls.notified_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.calls.notified_at IS 'When the post-call summary email and memory note were sent. Set once by an UPDATE ... WHERE notified_at IS NULL, so a retried call_analyzed sends nothing twice.';


--
-- Name: COLUMN calls.wanted; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.calls.wanted IS 'What the caller wanted, in one plain sentence, from the post-call analysis.';


--
-- Name: COLUMN calls.outcome; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.calls.outcome IS 'How the call ended for the caller: one of the six the analysis picks from.';


--
-- Name: COLUMN calls.follow_up; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.calls.follow_up IS 'What a person at the salon should do next for this caller; null when nothing.';


--
-- Name: COLUMN calls.caller_name; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.calls.caller_name IS 'The name the caller gave, exactly as said; a suggestion, never applied to the contact by itself.';


--
-- Name: COLUMN calls.note_checked_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.calls.note_checked_at IS 'When the note sweep looked at this call (0007): once, after its analysis; null until then.';


--
-- Name: COLUMN calls.activity_started_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.calls.activity_started_at IS 'When the call''s Live Activity was started on the workspace''s phones. Set once by an UPDATE ... WHERE activity_started_at IS NULL, so a redelivered call_started starts nothing twice.';


--
-- Name: capability_activations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.capability_activations (
    tenant_id uuid NOT NULL,
    capability text NOT NULL,
    activated_at timestamp with time zone DEFAULT now() NOT NULL,
    activated_by uuid,
    deactivated_at timestamp with time zone,
    note text,
    CONSTRAINT capability_activations_capability_check CHECK ((capability = ANY (ARRAY['voice'::text, 'whatsapp'::text, 'sms'::text]))),
    CONSTRAINT capability_activations_note_check CHECK (((note IS NULL) OR (length(note) <= 200)))
);


--
-- Name: TABLE capability_activations; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.capability_activations IS 'One row per capability an owner has switched on for their workspace: when, by whom, and when switched off again. Readiness and test evidence are computed from other records (contracts capabilityStatus); this is the owner''s act.';


--
-- Name: COLUMN capability_activations.deactivated_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.capability_activations.deactivated_at IS 'Set when the owner switches the capability off again; the row stays, so the history of the decision does.';


--
-- Name: contact_identities; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.contact_identities (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    contact_id uuid NOT NULL,
    channel text NOT NULL,
    external_id text NOT NULL,
    raw jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT contact_identities_channel_check CHECK ((channel = ANY (ARRAY['whatsapp'::text, 'voice'::text, 'sms'::text, 'email'::text, 'instagram'::text])))
);


--
-- Name: contacts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.contacts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    phone_e164 text,
    display_name text,
    wa_profile_name text,
    consent text DEFAULT 'unknown'::text NOT NULL,
    consent_source text,
    consent_updated_at timestamp with time zone,
    dnc boolean DEFAULT false NOT NULL,
    merged_into_contact_id uuid,
    first_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    last_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    erased_at timestamp with time zone,
    notes text,
    marketing_consent text DEFAULT 'unknown'::text NOT NULL,
    marketing_consent_source text,
    marketing_consent_updated_at timestamp with time zone,
    erasing_since timestamp with time zone,
    erased_phone_hash text,
    email text,
    erased_email_hash text,
    email_suppressed_at timestamp with time zone,
    email_suppressed_reason text,
    proposal_url text,
    email_marketing text DEFAULT 'unknown'::text NOT NULL,
    email_marketing_source text,
    email_marketing_updated_at timestamp with time zone,
    CONSTRAINT contacts_consent_check CHECK ((consent = ANY (ARRAY['unknown'::text, 'opted_in'::text, 'opted_out'::text]))),
    CONSTRAINT contacts_email_check CHECK (((email IS NULL) OR ((email = lower(btrim(email))) AND ((char_length(email) >= 3) AND (char_length(email) <= 254)) AND (email ~ '^[^[:space:]@<>]+@[^[:space:]@<>]+\.[^[:space:]@<>]+$'::text)))),
    CONSTRAINT contacts_email_marketing_check CHECK ((email_marketing = ANY (ARRAY['unknown'::text, 'opted_in'::text, 'opted_out'::text]))),
    CONSTRAINT contacts_email_suppressed_check CHECK ((((email_suppressed_at IS NULL) = (email_suppressed_reason IS NULL)) AND ((email_suppressed_reason IS NULL) OR (email_suppressed_reason = ANY (ARRAY['hard_bounce'::text, 'complaint'::text, 'provider'::text]))))),
    CONSTRAINT contacts_marketing_consent_check CHECK ((marketing_consent = ANY (ARRAY['unknown'::text, 'opted_in'::text, 'opted_out'::text]))),
    CONSTRAINT contacts_notes_check CHECK (((notes IS NULL) OR ((char_length(notes) >= 1) AND (char_length(notes) <= 600)))),
    CONSTRAINT contacts_proposal_url_check CHECK (((proposal_url IS NULL) OR ((proposal_url = btrim(proposal_url)) AND ((char_length(proposal_url) >= 10) AND (char_length(proposal_url) <= 500)) AND (proposal_url ~ '^https?://[^[:space:]]+$'::text))))
);


--
-- Name: COLUMN contacts.erased_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contacts.erased_at IS 'Set by erase_contact(). The row is a tombstone: no phone, no names, no identities. It exists so decisions.subject_id and events.subject_id still resolve, and so a repeat request is a no-op rather than a second destruction.';


--
-- Name: COLUMN contacts.notes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contacts.notes IS 'Superseded by person_notes (0007): moved there by 00157 and no longer read by the receptionist or the page. Kept for a page loaded before that deploy.';


--
-- Name: COLUMN contacts.marketing_consent; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contacts.marketing_consent IS 'Whether this person said yes to OFFERS specifically -- separate from public.contacts.consent, which is their answer about conversation and appointments. Never implied: only a text from their own handset or an operator recording a signed form sets it. Carrier error 30913 is what a single combined answer earns.';


--
-- Name: COLUMN contacts.marketing_consent_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contacts.marketing_consent_source IS 'How the marketing answer was given: the same vocabulary consent_source uses. "customer_message" is a text from their own handset, which is the express WRITTEN consent the carriers require for promotional messages.';


--
-- Name: COLUMN contacts.erasing_since; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contacts.erasing_since IS 'A deletion request, written before anything is destroyed: from this moment the wire refuses the person. erased_at is the completion.';


--
-- Name: COLUMN contacts.erased_phone_hash; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contacts.erased_phone_hash IS 'sha256 hex of "<tenant_id>:<E.164>", written when the erasure begins and the number still exists, so the calendar import and a late call event do not bring the person back.';


--
-- Name: COLUMN contacts.email; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contacts.email IS 'The person''s email address as normalizeEmail stores it: trimmed, lower-cased. One per workspace. A person may have this and no number.';


--
-- Name: COLUMN contacts.erased_email_hash; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contacts.erased_email_hash IS 'sha256 hex of "<tenant_id>:<address>", written when an erasure begins and the address still exists, so mail arriving from it later does not bring the person back.';


--
-- Name: COLUMN contacts.email_suppressed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contacts.email_suppressed_at IS 'When this address stopped being sent to: a permanent bounce, a complaint, or the provider''s own suppression. The wire refuses it from then on (deliver: email_suppressed).';


--
-- Name: COLUMN contacts.proposal_url; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contacts.proposal_url IS 'The owner''s proposal for this person, as a web address (normalizeLink stores it). The receptionist sends the address when they ask about price or the proposal, and states none of its figures. Never a file.';


--
-- Name: COLUMN contacts.email_marketing; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contacts.email_marketing IS 'Whether this person may be sent marketing email (a reach-out, an offer): unknown until they say, opted_out once they unsubscribe. Apart from consent and marketing_consent, which are the texting and WhatsApp answers.';


--
-- Name: conversations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.conversations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    contact_id uuid NOT NULL,
    state text DEFAULT 'open'::text NOT NULL,
    paused_until timestamp with time zone,
    snooze_until timestamp with time zone,
    assignee_user_id uuid,
    last_message_at timestamp with time zone,
    last_inbound_at timestamp with time zone,
    last_wa_inbound_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    control_kind text,
    control_by uuid,
    control_ref text,
    control_until timestamp with time zone,
    note_checked_at timestamp with time zone,
    CONSTRAINT conversations_control_check CHECK ((((control_kind IS NULL) = (control_until IS NULL)) AND ((control_kind IS NULL) OR (control_kind = ANY (ARRAY['person'::text, 'call'::text]))) AND ((control_kind IS DISTINCT FROM 'person'::text) OR (control_by IS NOT NULL)) AND ((control_kind IS DISTINCT FROM 'call'::text) OR (control_ref IS NOT NULL)) AND ((control_kind IS NOT NULL) OR ((control_by IS NULL) AND (control_ref IS NULL))))),
    CONSTRAINT conversations_state_check CHECK ((state = ANY (ARRAY['open'::text, 'needs_human'::text, 'snoozed'::text, 'archived'::text])))
);


--
-- Name: COLUMN conversations.control_kind; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.conversations.control_kind IS 'Who is answering on this thread right now: person, call, or nobody. Apart from assignee_user_id, which is who is RESPONSIBLE and may outlive the exchange.';


--
-- Name: COLUMN conversations.control_until; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.conversations.control_until IS 'When the hold lapses on its own. A hold with no expiry is how a thread ends up held for ever by somebody who has gone.';


--
-- Name: COLUMN conversations.note_checked_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.conversations.note_checked_at IS 'When the note sweep last read this conversation (0007): it reads again only after newer customer messages have gone quiet.';


--
-- Name: deals; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.deals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    contact_id uuid NOT NULL,
    lead_id uuid,
    service text,
    stage text NOT NULL,
    proposed_at timestamp with time zone DEFAULT now() NOT NULL,
    decided_at timestamp with time zone,
    ended_at timestamp with time zone,
    amount_cents integer,
    per text,
    currency text DEFAULT 'USD'::text NOT NULL,
    note text,
    evidence jsonb,
    source text DEFAULT 'person'::text NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    proposal_url text,
    valid_until date,
    lost_reason text,
    CONSTRAINT deals_amount_cents_check CHECK (((amount_cents IS NULL) OR (amount_cents >= 0))),
    CONSTRAINT deals_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT deals_lost_reason_check CHECK (((lost_reason IS NULL) OR (lost_reason = ANY (ARRAY['price'::text, 'timing'::text, 'elsewhere'::text, 'no_reply'::text, 'not_a_fit'::text, 'other'::text])))),
    CONSTRAINT deals_note_check CHECK (((note IS NULL) OR ((char_length(note) >= 1) AND (char_length(note) <= 200)))),
    CONSTRAINT deals_per_check CHECK (((per IS NULL) OR (per = ANY (ARRAY['once'::text, 'month'::text, 'year'::text])))),
    CONSTRAINT deals_proposal_url_check CHECK (((proposal_url IS NULL) OR ((proposal_url = btrim(proposal_url)) AND ((char_length(proposal_url) >= 10) AND (char_length(proposal_url) <= 500)) AND (proposal_url ~ '^https?://[^[:space:]]+$'::text)))),
    CONSTRAINT deals_service_check CHECK (((service IS NULL) OR ((char_length(service) >= 1) AND (char_length(service) <= 80)))),
    CONSTRAINT deals_source_check CHECK ((source = ANY (ARRAY['person'::text, 'payment'::text]))),
    CONSTRAINT deals_stage_check CHECK ((stage = ANY (ARRAY['proposed'::text, 'won'::text, 'lost'::text, 'ended'::text])))
);


--
-- Name: TABLE deals; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.deals IS 'One engagement a person is deciding on or has taken (0004): proposed (a proposal out), won (a client), lost (passed), ended. Written by deal_record on a person''s word, an Ask card through the same route, or a payment webhook later (source); never by the receptionist. A stage is an assertion, so no guard: every move is an event and version refuses a stale press. One open engagement (proposed or won) per person per service.';


--
-- Name: COLUMN deals.proposal_url; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.deals.proposal_url IS 'The proposal this deal sent, as a web address (normalizeLink stores it; 00154''s rule). The receptionist sends it when they ask about the proposal and states none of its figures. Blanked when the person is erased: an address can name a person.';


--
-- Name: COLUMN deals.valid_until; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.deals.valid_until IS 'The last day the proposal stands, by the business''s calendar; null when it says none.';


--
-- Name: COLUMN deals.lost_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.deals.lost_reason IS 'Why they passed, set with the move to lost and cleared by any other stage: price, timing, elsewhere, no_reply, not_a_fit, other. The words for it are the deal''s note.';


--
-- Name: decisions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.decisions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    subject_type text NOT NULL,
    subject_id uuid NOT NULL,
    verb text NOT NULL,
    actor_type text NOT NULL,
    actor_user_id uuid,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    undo_of uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT decisions_actor_type_check CHECK ((actor_type = ANY (ARRAY['user'::text, 'ai'::text, 'system'::text, 'owner_phone'::text]))),
    CONSTRAINT decisions_actor_user_id_check CHECK (((actor_type = 'user'::text) OR (actor_user_id IS NULL))),
    CONSTRAINT decisions_subject_type_check CHECK ((subject_type = ANY (ARRAY['conversation'::text, 'escalation'::text, 'draft'::text, 'lead'::text, 'message'::text, 'agent'::text, 'membership'::text, 'invitation'::text, 'contact'::text, 'call'::text, 'channel'::text, 'broadcast'::text, 'playbook'::text, 'review'::text, 'workspace'::text, 'deal'::text, 'list'::text]))),
    CONSTRAINT decisions_verb_check CHECK ((verb = ANY (ARRAY['approve'::text, 'edit'::text, 'decline'::text, 'snooze'::text, 'wake'::text, 'take_over'::text, 'hand_back'::text, 'resolve'::text, 'archive'::text, 'reply'::text, 'cancel_send'::text, 'pause_agent'::text, 'resume_agent'::text, 'invite'::text, 'revoke_invite'::text, 'change_role'::text, 'remove_member'::text, 'erase'::text, 'whisper'::text, 'connect_channel'::text, 'consent_change'::text, 'send_broadcast'::text, 'cancel_broadcast'::text, 'start_playbook'::text, 'pause_playbook'::text, 'reply_review'::text, 'export'::text, 'end_call'::text, 'record_deal'::text, 'make_list'::text, 'rename_list'::text, 'change_list_rule'::text, 'add_to_list'::text, 'drop_from_list'::text, 'archive_list'::text, 'restore_list'::text, 'delete_list'::text, 'import'::text])))
);


--
-- Name: erasure_keying; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.erasure_keying (
    id boolean DEFAULT true NOT NULL,
    keyed_at timestamp with time zone,
    CONSTRAINT erasure_keying_id_check CHECK (id)
);


--
-- Name: TABLE erasure_keying; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.erasure_keying IS 'When the stored erasure digests were re-keyed (00263 erasure_rekey): null until then, and every digest is the legacy sha256 until then.';


--
-- Name: escalations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.escalations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    conversation_id uuid NOT NULL,
    reason text NOT NULL,
    details text,
    state text DEFAULT 'open'::text NOT NULL,
    resolved_by_user_id uuid,
    decision_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deadman_alerted_at timestamp with time zone,
    CONSTRAINT escalations_reason_check CHECK ((reason = ANY (ARRAY['human_token'::text, 'non_text'::text, 'refusal'::text, 'rate_cap'::text, 'policy_block'::text, 'send_failed'::text, 'deadman'::text, 'brain_error'::text, 'manual'::text, 'opt_out'::text, 'state_unavailable'::text, 'stale'::text, 'person_hold'::text, 'budget'::text, 'policy_ask'::text, 'callback'::text, 'paused'::text, 'carriers'::text, 'email_review'::text]))),
    CONSTRAINT escalations_state_check CHECK ((state = ANY (ARRAY['open'::text, 'resolved'::text])))
);


--
-- Name: COLUMN escalations.deadman_alerted_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.escalations.deadman_alerted_at IS 'When the watchdog flagged this as unanswered. Set once; NULL means never flagged.';


--
-- Name: events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    kind text NOT NULL,
    category text DEFAULT 'system'::text NOT NULL,
    subject_type text,
    subject_id uuid,
    data jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    version smallint DEFAULT 1 NOT NULL
)
PARTITION BY RANGE (created_at);


--
-- Name: COLUMN events.version; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.events.version IS 'The version of this kind''s data (packages/db events.ts, 00264): raised when a kind''s shape changes, so a reader can tell an old row from a new one. 1 for every kind to date.';


--
-- Name: events_default; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.events_default (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    kind text NOT NULL,
    category text DEFAULT 'system'::text NOT NULL,
    subject_type text,
    subject_id uuid,
    data jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    version smallint DEFAULT 1 NOT NULL
);


--
-- Name: TABLE events_default; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.events_default IS 'Catch-all so a lapsed partition precreate degrades ingest instead of aborting it. Rows here mean the monthly cron needs attention.';


--
-- Name: google_connections; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.google_connections (
    tenant_id uuid NOT NULL,
    google_email text,
    google_sub text,
    account_name text NOT NULL,
    account_title text,
    location_name text,
    location_title text,
    scopes text[] DEFAULT '{}'::text[] NOT NULL,
    connected_by uuid,
    connected_at timestamp with time zone DEFAULT now() NOT NULL,
    last_synced_at timestamp with time zone,
    sync_error text,
    credentials_ref text,
    facts jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT google_connections_account_name_check CHECK ((account_name ~~ 'accounts/%'::text)),
    CONSTRAINT google_connections_location_name_check CHECK (((location_name IS NULL) OR (location_name ~~ 'locations/%'::text)))
);


--
-- Name: TABLE google_connections; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.google_connections IS 'A workspace''s Google Business Profile, connected by its owner: the account, the location, whose Google account, when it last synced. The token is in Vault. Members read; the edge writes.';


--
-- Name: google_listing_days; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.google_listing_days (
    tenant_id uuid NOT NULL,
    day date NOT NULL,
    rating numeric(2,1),
    review_count integer NOT NULL,
    CONSTRAINT google_listing_days_review_count_check CHECK ((review_count >= 0))
);


--
-- Name: TABLE google_listing_days; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.google_listing_days IS 'The listing''s rating and count per local day, one row per read day: the trend, and what a period gained.';


--
-- Name: google_listings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.google_listings (
    tenant_id uuid NOT NULL,
    place_id text NOT NULL,
    name text NOT NULL,
    address text,
    maps_uri text,
    business_status text,
    rating numeric(2,1),
    review_count integer,
    linked_by uuid,
    linked_at timestamp with time zone DEFAULT now() NOT NULL,
    checked_at timestamp with time zone,
    check_error text,
    facts jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT google_listings_name_check CHECK (((char_length(name) >= 1) AND (char_length(name) <= 200))),
    CONSTRAINT google_listings_place_id_check CHECK (((char_length(place_id) >= 10) AND (char_length(place_id) <= 300))),
    CONSTRAINT google_listings_rating_check CHECK (((rating IS NULL) OR ((rating >= (1)::numeric) AND (rating <= (5)::numeric)))),
    CONSTRAINT google_listings_review_count_check CHECK (((review_count IS NULL) OR (review_count >= 0)))
);


--
-- Name: TABLE google_listings; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.google_listings IS 'A workspace''s business on Google Maps, as the public listing says it: the place, the rating, the count, when it was last read. Members read; the edge writes.';


--
-- Name: google_reviews; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.google_reviews (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    review_id text NOT NULL,
    origin text DEFAULT 'places'::text NOT NULL,
    rating smallint,
    author text,
    author_uri text,
    author_photo_uri text,
    body text,
    language_code text,
    published_at timestamp with time zone,
    reply_text text,
    replied_at timestamp with time zone,
    maps_uri text,
    first_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    last_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT google_reviews_origin_check CHECK ((origin = ANY (ARRAY['places'::text, 'profile'::text]))),
    CONSTRAINT google_reviews_rating_check CHECK (((rating IS NULL) OR ((rating >= 1) AND (rating <= 5))))
);


--
-- Name: TABLE google_reviews; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.google_reviews IS 'Reviews of the workspace''s listing as Google showed them, one row per review, kept from the first time it was seen. Members read; the edge writes.';


--
-- Name: idempotency_keys; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.idempotency_keys (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    key text NOT NULL,
    route text NOT NULL,
    request_hash text,
    response jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: invitations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.invitations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    email text NOT NULL,
    role text NOT NULL,
    invited_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone DEFAULT (now() + '7 days'::interval) NOT NULL,
    accepted_at timestamp with time zone,
    revoked_at timestamp with time zone,
    CONSTRAINT invitations_role_check CHECK ((role = ANY (ARRAY['operator'::text, 'viewer'::text])))
);


--
-- Name: lead_judgments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lead_judgments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    round_id uuid NOT NULL,
    batch integer DEFAULT 0 NOT NULL,
    op_id text NOT NULL,
    request_hash text,
    answer jsonb NOT NULL,
    model text,
    tokens integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE lead_judgments; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.lead_judgments IS 'The judge''s answer for one batch, kept by operation id (sha256 of run:offset:batch), so a replayed page finds it and pays nothing (E4). No member policy: the peek reads the member''s own judgment.';


--
-- Name: lead_niche_priors; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lead_niche_priors (
    category_key text NOT NULL,
    places integer DEFAULT 0 NOT NULL,
    matched integer DEFAULT 0 NOT NULL,
    with_email integer DEFAULT 0 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT lead_niche_priors_category_key_check CHECK ((category_key ~ '^[a-z][a-z0-9_]{1,39}$'::text)),
    CONSTRAINT lead_niche_priors_matched_check CHECK ((matched >= 0)),
    CONSTRAINT lead_niche_priors_places_check CHECK ((places >= 0)),
    CONSTRAINT lead_niche_priors_with_email_check CHECK ((with_email >= 0))
);


--
-- Name: TABLE lead_niche_priors; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.lead_niche_priors IS 'Platform-wide counts per kind of business: places judged, how many qualified, how many had an email. Aggregates only; nothing names a workspace or a place.';


--
-- Name: lead_operations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lead_operations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    kind text NOT NULL,
    search_id uuid,
    lead_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    before jsonb DEFAULT '{}'::jsonb NOT NULL,
    after jsonb DEFAULT '{}'::jsonb NOT NULL,
    version integer NOT NULL,
    by uuid,
    at timestamp with time zone DEFAULT now() NOT NULL,
    undone_at timestamp with time zone,
    CONSTRAINT lead_operations_kind_check CHECK ((kind = ANY (ARRAY['undo_search'::text, 'keep'::text, 'exclude'::text, 'put_back'::text, 'include'::text, 'stop'::text, 'stage'::text, 'bulk'::text])))
);


--
-- Name: TABLE lead_operations; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.lead_operations IS 'Every undo-able act: what it changed, from what, by whom, when. lead_undo takes the id and the version the client saw and refuses when anyone changed the rows since (E9).';


--
-- Name: lead_places; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lead_places (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    lead_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    place_id text NOT NULL,
    title text,
    street text,
    found_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE lead_places; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.lead_places IS 'A duplicate listing (the same name, address and phone) folded into the lead already held, so rediscovery maps back (E6).';


--
-- Name: lead_platform; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lead_platform (
    id boolean DEFAULT true NOT NULL,
    searches_on boolean DEFAULT false NOT NULL,
    tenants_on uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    note text,
    prices_checked_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT lead_platform_id_check CHECK (id),
    CONSTRAINT lead_platform_note_check CHECK ((char_length(note) <= 200))
);


--
-- Name: TABLE lead_platform; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.lead_platform IS 'One row. searches_on is the kill switch for every workspace; tenants_on lists the workspaces that may search while it is off (release A''s internal runs). Read through lead_searches_on(); written by hand.';


--
-- Name: lead_preferences; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lead_preferences (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    kind text NOT NULL,
    category_key text,
    example text,
    from_lead_id uuid,
    active boolean DEFAULT true NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT lead_preferences_example_check CHECK ((char_length(example) <= 120)),
    CONSTRAINT lead_preferences_kind_check CHECK ((kind = ANY (ARRAY['chain'::text, 'wrong_kind'::text, 'too_far'::text])))
);


--
-- Name: TABLE lead_preferences; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.lead_preferences IS 'Learned exclusions, scoped to the kind of business (P5). Release C draws them; A1 holds the rows.';


--
-- Name: lead_rounds; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lead_rounds (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    search_id uuid NOT NULL,
    seq integer NOT NULL,
    purpose text NOT NULL,
    plan jsonb NOT NULL,
    plan_version integer NOT NULL,
    target integer NOT NULL,
    state text DEFAULT 'queued'::text NOT NULL,
    ending text,
    ending_pending text,
    question jsonb,
    answered text,
    waiting_since timestamp with time zone,
    allowance_reserved integer DEFAULT 0 NOT NULL,
    allowance_used integer DEFAULT 0 NOT NULL,
    cost_reserved_usd numeric(10,4) DEFAULT 0 NOT NULL,
    cost_usd numeric(10,4) DEFAULT 0 NOT NULL,
    judge_tokens integer DEFAULT 0 NOT NULL,
    judge_model text,
    month text NOT NULL,
    day text NOT NULL,
    started_at timestamp with time zone,
    ended_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    platform_day text DEFAULT to_char((now() AT TIME ZONE 'UTC'::text), 'YYYY-MM-DD'::text) NOT NULL,
    nearby jsonb DEFAULT '[]'::jsonb NOT NULL,
    CONSTRAINT lead_rounds_allowance_reserved_check CHECK ((allowance_reserved >= 0)),
    CONSTRAINT lead_rounds_allowance_used_check CHECK ((allowance_used >= 0)),
    CONSTRAINT lead_rounds_answered_check CHECK ((answered = ANY (ARRAY['keep'::text, 'include'::text, 'stop'::text]))),
    CONSTRAINT lead_rounds_check CHECK (((state = 'ended'::text) = (ending IS NOT NULL))),
    CONSTRAINT lead_rounds_cost_reserved_usd_check CHECK ((cost_reserved_usd >= (0)::numeric)),
    CONSTRAINT lead_rounds_cost_usd_check CHECK ((cost_usd >= (0)::numeric)),
    CONSTRAINT lead_rounds_day_check CHECK ((day ~ '^\d{4}-\d{2}-\d{2}$'::text)),
    CONSTRAINT lead_rounds_ending_check CHECK ((ending = ANY (ARRAY['target_reached'::text, 'searched_everything'::text, 'month_leads_used'::text, 'budget_used'::text, 'few_new_matches'::text, 'stopped'::text, 'source_failed'::text, 'question_unanswered'::text, 'paused'::text]))),
    CONSTRAINT lead_rounds_ending_pending_check CHECK ((ending_pending = ANY (ARRAY['target_reached'::text, 'searched_everything'::text, 'month_leads_used'::text, 'budget_used'::text, 'few_new_matches'::text, 'stopped'::text, 'source_failed'::text, 'question_unanswered'::text, 'paused'::text]))),
    CONSTRAINT lead_rounds_month_check CHECK ((month ~ '^\d{4}-\d{2}$'::text)),
    CONSTRAINT lead_rounds_plan_version_check CHECK ((plan_version >= 1)),
    CONSTRAINT lead_rounds_platform_day_check CHECK ((platform_day ~ '^\d{4}-\d{2}-\d{2}$'::text)),
    CONSTRAINT lead_rounds_purpose_check CHECK ((purpose = ANY (ARRAY['probe'::text, 'main'::text, 'topup'::text, 'renew'::text]))),
    CONSTRAINT lead_rounds_seq_check CHECK ((seq >= 1)),
    CONSTRAINT lead_rounds_state_check CHECK ((state = ANY (ARRAY['queued'::text, 'probing'::text, 'waiting_on_owner'::text, 'running'::text, 'checking'::text, 'ended'::text]))),
    CONSTRAINT lead_rounds_target_check CHECK ((target >= 0))
);


--
-- Name: TABLE lead_rounds; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.lead_rounds IS 'The unit of execution and of money: the probe (seq 1), each top-up and each Find new ones. Carries the plan it ran, its reservation and spend, one ending; final once ended (lead_rounds_guard). The search''s state is its latest round''s.';


--
-- Name: COLUMN lead_rounds.ending_pending; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.lead_rounds.ending_pending IS 'Set by the collect that moved the round to checking, or by Stop during the checks; lead_check_commit''s last batch ends the round with it.';


--
-- Name: COLUMN lead_rounds.platform_day; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.lead_rounds.platform_day IS 'The platform-wide day counter (tenant_id null, UTC) this round reserved in, so every release and settle reaches the row it took from, whatever day it is when the round ends.';


--
-- Name: COLUMN lead_rounds.nearby; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.lead_rounds.nearby IS 'Where to look next when the round ran dry (00145): the nearest ZIP centres past its area, as the plan''s area rows, nearest first; [] when it found what it asked for.';


--
-- Name: lead_runs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lead_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    round_id uuid NOT NULL,
    purpose text NOT NULL,
    term text,
    actor text NOT NULL,
    build text NOT NULL,
    apify_run_id text,
    dataset_id text,
    state text DEFAULT 'claimed'::text NOT NULL,
    claimed_by text,
    claimed_at timestamp with time zone,
    webhook_token_hash text NOT NULL,
    lease_owner text,
    lease_gen integer DEFAULT 0 NOT NULL,
    lease_until timestamp with time zone,
    read_offset integer DEFAULT 0 NOT NULL,
    items_seen integer DEFAULT 0 NOT NULL,
    cap_usd numeric(10,4),
    usage_usd numeric(10,4) DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    finished_at timestamp with time zone,
    CONSTRAINT lead_runs_purpose_check CHECK ((purpose = ANY (ARRAY['discover'::text, 'check'::text]))),
    CONSTRAINT lead_runs_read_offset_check CHECK ((read_offset >= 0)),
    CONSTRAINT lead_runs_state_check CHECK ((state = ANY (ARRAY['claimed'::text, 'starting'::text, 'running'::text, 'succeeded'::text, 'failed'::text, 'aborted'::text, 'timed_out'::text, 'unknown'::text])))
);


--
-- Name: TABLE lead_runs; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.lead_runs IS 'One provider execution: a discover run per term, a check run per batch of addresses. Written ''claimed'' (the row exists), claimed by a dispatch token before the provider is called (E1), leased by owner token and generation while a page is read (E3); the webhook token is made with the row and never rewritten.';


--
-- Name: lead_search_members; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lead_search_members (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    search_id uuid NOT NULL,
    lead_id uuid NOT NULL,
    round_id uuid,
    tenant_id uuid NOT NULL,
    judgment jsonb DEFAULT '{}'::jsonb NOT NULL,
    class text NOT NULL,
    excluded_by text,
    fit text,
    reason text DEFAULT ''::text NOT NULL,
    distance_m integer,
    counted boolean DEFAULT false NOT NULL,
    counted_month text,
    kept_at timestamp with time zone,
    kept_by uuid,
    blanked_at timestamp with time zone,
    version integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT lead_search_members_check CHECK ((counted = (counted_month IS NOT NULL))),
    CONSTRAINT lead_search_members_class_check CHECK ((class = ANY (ARRAY['qualified'::text, 'review'::text, 'excluded'::text]))),
    CONSTRAINT lead_search_members_counted_month_check CHECK ((counted_month ~ '^\d{4}-\d{2}$'::text)),
    CONSTRAINT lead_search_members_fit_check CHECK ((fit = ANY (ARRAY['strong'::text, 'look'::text, 'long'::text]))),
    CONSTRAINT lead_search_members_reason_check CHECK ((char_length(reason) <= 120))
);


--
-- Name: TABLE lead_search_members; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.lead_search_members IS 'One lead in one search, with that search''s judgment ({answer, reasons, shares}), class, fit and distance. counted_month is the month it counted in (S11). The round''s tallies are counts over this table, never stored twice. version guards Undo (E9).';


--
-- Name: lead_searches; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lead_searches (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    created_by uuid,
    via text NOT NULL,
    card text NOT NULL,
    name text NOT NULL,
    asked text NOT NULL,
    plan jsonb NOT NULL,
    removed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    thread_id uuid,
    CONSTRAINT lead_searches_asked_check CHECK ((char_length(asked) <= 400)),
    CONSTRAINT lead_searches_name_check CHECK (((char_length(name) >= 1) AND (char_length(name) <= 120))),
    CONSTRAINT lead_searches_via_check CHECK ((via = ANY (ARRAY['people'::text, 'ask'::text, 'import'::text, 'chosen'::text])))
);


--
-- Name: TABLE lead_searches; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.lead_searches IS 'The saved object: who was asked for, in the owner''s words, and the current plan. No state and no counters: lead_searches_view derives both from the rounds and the members.';


--
-- Name: COLUMN lead_searches.via; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.lead_searches.via IS 'How the search was made: people (the finder on the page), ask (the finder through Ask), import (a file of the owner''s own, 00242) or chosen (leads picked on Leads for a reach-out, 00242). An import or a chosen search has no finder plan: its plan carries `list` and no area, and it is never searched again.';


--
-- Name: COLUMN lead_searches.thread_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.lead_searches.thread_id IS 'The Ask thread the search was planned in (00172), so an answer to its question lands there. Only ever the planner''s own thread; null for a search made on the page, for every search before 00172, and once the thread is gone.';


--
-- Name: leads; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.leads (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    place_id text,
    business_name text DEFAULT ''::text NOT NULL,
    category text,
    street text,
    city text,
    region text,
    postal_code text,
    country text DEFAULT 'US'::text NOT NULL,
    lat double precision,
    lng double precision,
    website_host text,
    instagram_url text,
    phone_e164 text,
    phone_sources smallint DEFAULT 0 NOT NULL,
    phone_wrong boolean DEFAULT false NOT NULL,
    email text,
    email_alternates jsonb DEFAULT '[]'::jsonb NOT NULL,
    email_state text DEFAULT 'none'::text NOT NULL,
    email_checked_at timestamp with time zone,
    rating numeric(2,1),
    reviews integer,
    stage text DEFAULT 'ready'::text NOT NULL,
    closed_reason text,
    last_outcome text,
    last_note text,
    contacted_at timestamp with time zone,
    exported_at timestamp with time zone,
    contact_id uuid,
    converted_at timestamp with time zone,
    found_at timestamp with time zone DEFAULT now() NOT NULL,
    erased_at timestamp with time zone,
    blanked_at timestamp with time zone,
    version integer DEFAULT 1 NOT NULL,
    about text,
    hours jsonb DEFAULT '[]'::jsonb NOT NULL,
    image_url text,
    price text,
    reviews_dist jsonb,
    facebook_url text,
    linkedin_url text,
    tiktok_url text,
    claimed boolean,
    maps_url text,
    rank integer,
    neighborhood text,
    logo_url text,
    mark_path text,
    resume_at timestamp with time zone,
    website_root boolean,
    booked_at timestamp with time zone,
    reach_out_stopped_at timestamp with time zone,
    CONSTRAINT leads_closed_reason_check CHECK ((closed_reason = ANY (ARRAY['said_no'::text, 'not_a_fit'::text, 'customer'::text, 'stale'::text, 'search_removed'::text]))),
    CONSTRAINT leads_email_state_check CHECK ((email_state = ANY (ARRAY['none'::text, 'checking'::text, 'ok'::text, 'catch_all'::text, 'unknown'::text, 'invalid'::text]))),
    CONSTRAINT leads_mark_path_shape CHECK (((mark_path IS NULL) OR (mark_path ~ '^[0-9a-f]{64}\.(png|jpg|webp|gif|ico)$'::text))),
    CONSTRAINT leads_stage_check CHECK ((stage = ANY (ARRAY['ready'::text, 'nurture'::text, 'converted'::text, 'archived'::text])))
);


--
-- Name: TABLE leads; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.leads IS 'A place: one physical location, outside contacts. Unique by place id in the workspace; a shared phone, email or website is looked up and marked on the member, never merged (25). Stage is the relationship; class lives on the membership.';


--
-- Name: COLUMN leads.version; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.leads.version IS 'Bumped by every door that changes this lead. The page sends it back with an Undo and lead_undo refuses when anyone changed the row since (E9).';


--
-- Name: COLUMN leads.about; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.leads.about IS 'The listing''s own line about the business: Google''s, else the owner''s; capped at 600 characters and stripped of control characters before it is stored. For the owner, never the judge.';


--
-- Name: COLUMN leads.hours; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.leads.hours IS 'Opening hours as the listing shows them, [{day, hours}] up to seven, in the business''s own words ("9 AM to 6 PM", "Closed").';


--
-- Name: COLUMN leads.reviews_dist; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.leads.reviews_dist IS '{one, two, three, four, five}: how many reviews at each star, for the spread beside the rating.';


--
-- Name: COLUMN leads.claimed; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.leads.claimed IS 'true when the owner has claimed the listing; false when Maps still offers "claim this business"; null when the item did not say. An unclaimed listing rarely watches its email.';


--
-- Name: COLUMN leads.rank; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.leads.rank IS 'Where the place stood in the term''s results on Maps when it was found: "#3 for wedding planner".';


--
-- Name: COLUMN leads.neighborhood; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.leads.neighborhood IS 'The neighbourhood the listing names (D5, 00146): "Hawthorne", for the row''s one line about where. Null when the source did not say.';


--
-- Name: COLUMN leads.logo_url; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.leads.logo_url IS 'The business''s own mark (D6, 00147): the logo its home page declares, else the icon it made for a home screen. An address on their own site, read by the engine as it collects; null when the site declared none, or when there is no site.';


--
-- Name: COLUMN leads.mark_path; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.leads.mark_path IS 'The copy of the business''s mark we keep (00161): <sha256>.<png|jpg|webp|gif|ico> in the public lead-marks bucket, stored by the collect once the bytes at logo_url passed core''s check. What every tile draws; null when there is no copy yet.';


--
-- Name: COLUMN leads.resume_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.leads.resume_at IS 'The day a reply said to write again (a "not now") or that they are back (an "away" in their own words), at 9:00 in the business''s zone (Reach out Part 5, G12). Written by the reading''s door; the undo of a no never touches it. The chain is stopped by the reply itself (outreach_wrote_back), so nothing sends by it: Leads says it, and a dated step on Today is due that day.';


--
-- Name: COLUMN leads.website_root; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.leads.website_root IS 'Whether the listing''s website is its host''s root (00237): false for a page under the host (an ISP''s "/~dana/", a directory''s listing), which is no proof the host is the business''s own; null when not known. A reply''s no closes the host''s domain only when this is not false (contracts ownedDomainOf).';


--
-- Name: COLUMN leads.booked_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.leads.booked_at IS 'When the first appointment the calendar sweep saw for this lead starts, when it starts after an email of a reach-out left (Reach out Part 6, H2; reach_out_booked). Stamped once, whatever the lead''s stage: a lead that wrote back and then booked is Talking already and booked all the same. Reports and Leads count and say it.';


--
-- Name: COLUMN leads.reach_out_stopped_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.leads.reach_out_stopped_at IS 'When its owner stopped a reach-out writing to this lead (Reach out Part 6, H10; reach_out_lead_stop). The send door refuses its email (outreach_lead_facts.stopped, outreach_stopped) and no later step reaches it (reach_out_followers). The lead is not closed: stopping is not a no.';


--
-- Name: lead_searches_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.lead_searches_view WITH (security_invoker='true') AS
 SELECT s.id,
    s.tenant_id,
    s.created_by,
    s.via,
    s.card,
    s.name,
    s.asked,
    s.plan,
    s.removed_at,
    s.created_at,
    r.id AS round_id,
    r.seq,
    r.purpose,
    r.state,
    r.ending,
    r.ending_pending,
    r.question,
    r.answered,
    r.target,
    r.plan_version,
    r.judge_tokens,
    r.cost_usd,
    r.waiting_since,
    r.ended_at,
    COALESCE(c.qualified, (0)::bigint) AS qualified,
    COALESCE(c.review, (0)::bigint) AS review,
    COALESCE(c.excluded, (0)::bigint) AS excluded,
    COALESCE(c.counted, (0)::bigint) AS counted,
    COALESCE(c.emails_checked, (0)::bigint) AS emails_checked,
    COALESCE(c.with_phone, (0)::bigint) AS with_phone,
    u.id AS undo_op_id,
    u.version AS undo_version,
    COALESCE(r.nearby, '[]'::jsonb) AS nearby,
    COALESCE(c.strong, (0)::bigint) AS strong,
    COALESCE(c.look, (0)::bigint) AS look,
    COALESCE(c.long, (0)::bigint) AS long,
    s.thread_id
   FROM (((public.lead_searches s
     LEFT JOIN LATERAL ( SELECT r_1.id,
            r_1.seq,
            r_1.purpose,
            r_1.state,
            r_1.ending,
            r_1.ending_pending,
            r_1.question,
            r_1.answered,
            r_1.target,
            r_1.plan_version,
            r_1.judge_tokens,
            r_1.cost_usd,
            r_1.waiting_since,
            r_1.ended_at,
            r_1.nearby
           FROM public.lead_rounds r_1
          WHERE (r_1.search_id = s.id)
          ORDER BY r_1.seq DESC
         LIMIT 1) r ON (true))
     LEFT JOIN LATERAL ( SELECT count(*) FILTER (WHERE ((m.class = 'qualified'::text) AND (m.blanked_at IS NULL))) AS qualified,
            count(*) FILTER (WHERE ((m.class = 'review'::text) AND (m.blanked_at IS NULL))) AS review,
            count(*) FILTER (WHERE (m.class = 'excluded'::text)) AS excluded,
            count(*) FILTER (WHERE m.counted) AS counted,
            count(*) FILTER (WHERE ((m.class = 'qualified'::text) AND (m.blanked_at IS NULL) AND (l.email_state = 'ok'::text))) AS emails_checked,
            count(*) FILTER (WHERE ((m.class = 'qualified'::text) AND (m.blanked_at IS NULL) AND (l.phone_e164 IS NOT NULL) AND (NOT l.phone_wrong))) AS with_phone,
            count(*) FILTER (WHERE ((m.class = 'qualified'::text) AND (m.blanked_at IS NULL) AND (m.fit = 'strong'::text))) AS strong,
            count(*) FILTER (WHERE ((m.class = 'qualified'::text) AND (m.blanked_at IS NULL) AND (m.fit = 'look'::text))) AS look,
            count(*) FILTER (WHERE ((m.class = 'qualified'::text) AND (m.blanked_at IS NULL) AND (m.fit = 'long'::text))) AS long
           FROM (public.lead_search_members m
             JOIN public.leads l ON ((l.id = m.lead_id)))
          WHERE (m.search_id = s.id)) c ON (true))
     LEFT JOIN LATERAL ( SELECT o.id,
            o.version
           FROM public.lead_operations o
          WHERE ((o.search_id = s.id) AND (o.kind = 'undo_search'::text) AND (o.undone_at IS NULL) AND (o.at > (now() - '24:00:00'::interval)))
          ORDER BY o.at DESC
         LIMIT 1) u ON (true));


--
-- Name: VIEW lead_searches_view; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.lead_searches_view IS 'Every column of lead_searches with its latest round (round_id, seq, purpose, state, ending, ending_pending, question, answered, target, plan_version, judge_tokens, cost_usd -- what that round has spent, so cost per Qualified lead is read from here -- waiting_since and ended_at) and its counts over the members: qualified, review, excluded, counted, emails_checked (a qualified lead whose address was checked and answered) and with_phone (a qualified lead with a number nobody has marked wrong). Excluded members stay counted after their details are blanked, so "40 left out" stays 40. undo_op_id and undo_version name the operation this search''s Undo takes while its twenty-four hours run, and are null once it is undone or the day is out. nearby (00145): where to look next when the round ran dry, the nearest ZIP centres past its area, nearest first; [] otherwise. strong, look and long (00146): the qualified members by fit band, for the band bar over the table. thread_id (00172): the Ask thread the search was planned in, or null.';


--
-- Name: lead_suggestions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lead_suggestions (
    tenant_id uuid NOT NULL,
    business_line text NOT NULL,
    by_owner boolean DEFAULT false NOT NULL,
    items jsonb DEFAULT '[]'::jsonb NOT NULL,
    made_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT lead_suggestions_business_line_check CHECK (((char_length(business_line) >= 3) AND (char_length(business_line) <= 160)))
);


--
-- Name: TABLE lead_suggestions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.lead_suggestions IS 'The three or four kinds of business worth reaching, written from the workspace''s business line (§8.9). One row per workspace; by_owner says the line is the owner''s own words, not the workspace''s name and services. The service writes it; members read it.';


--
-- Name: lead_suppressions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lead_suppressions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    kind text NOT NULL,
    hash text NOT NULL,
    what text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT lead_suppressions_kind_check CHECK ((kind = ANY (ARRAY['email'::text, 'place'::text, 'phone'::text, 'domain'::text]))),
    CONSTRAINT lead_suppressions_what_check CHECK ((what = ANY (ARRAY['email_opt_out'::text, 'customer'::text, 'erased'::text, 'said_no'::text])))
);


--
-- Name: TABLE lead_suppressions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.lead_suppressions IS 'By what happened (S8): an email opt-out stops email to that address (calls stay); a customer is hidden from every search; an erasure hides the place, the number and the address for good; a reply read as no (Reach out Part 5) stops the address that said it and, when it is the business''s own, the domain (kind domain, the hash of the part after the "@", N6). A bounce is email_state = invalid on the lead, never a row here. The hash is lead_suppression_hash(). The send door''s facts, the audience and the finder ask an address through lead_addresses_suppressed.';


--
-- Name: lines; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lines (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    e164 text,
    kind text DEFAULT 'chanlytics'::text NOT NULL,
    provider text NOT NULL,
    area_code integer,
    subaccount_sid text,
    number_sid text,
    trunk_sid text,
    credential_list_sid text,
    termination_uri text,
    messaging_service_sid text,
    retell_agent_id text,
    voice_state text DEFAULT 'none'::text NOT NULL,
    sms_state text DEFAULT 'none'::text NOT NULL,
    whatsapp_state text DEFAULT 'none'::text NOT NULL,
    port_state text DEFAULT 'none'::text NOT NULL,
    forwarding_state text DEFAULT 'none'::text NOT NULL,
    step text,
    last_error text,
    state_since timestamp with time zone DEFAULT now() NOT NULL,
    facts jsonb DEFAULT '{}'::jsonb NOT NULL,
    credentials_ref text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    profile_sid text,
    a2p_profile_sid text,
    brand_sid text,
    campaign_sid text,
    reg_step text,
    reg_mock boolean DEFAULT false NOT NULL,
    reg_sole_prop boolean DEFAULT false NOT NULL,
    CONSTRAINT lines_forwarding_state_check CHECK ((forwarding_state = ANY (ARRAY['none'::text, 'instructed'::text, 'verified'::text]))),
    CONSTRAINT lines_kind_check CHECK ((kind = ANY (ARRAY['chanlytics'::text, 'hosted'::text, 'ported'::text, 'forwarded'::text]))),
    CONSTRAINT lines_port_state_check CHECK ((port_state = ANY (ARRAY['none'::text, 'requested'::text, 'scheduled'::text, 'done'::text, 'rejected'::text]))),
    CONSTRAINT lines_provider_check CHECK ((provider = ANY (ARRAY['twilio'::text, 'dry'::text, 'carrier'::text]))),
    CONSTRAINT lines_reg_step_check CHECK (((reg_step IS NULL) OR (reg_step = ANY (ARRAY['profile'::text, 'business'::text, 'representative'::text, 'address'::text, 'document'::text, 'primary'::text, 'submit'::text, 'a2p_profile'::text, 'brand'::text, 'campaign'::text])))),
    CONSTRAINT lines_sms_state_check CHECK ((sms_state = ANY (ARRAY['none'::text, 'needs_record'::text, 'otp_waiting'::text, 'registering'::text, 'approved'::text, 'rejected'::text, 'hosting'::text, 'active'::text, 'failed'::text]))),
    CONSTRAINT lines_step_check CHECK (((step IS NULL) OR (step = ANY (ARRAY['subaccount'::text, 'number'::text, 'trunk'::text, 'agent'::text, 'import'::text, 'messaging'::text, 'channel'::text])))),
    CONSTRAINT lines_voice_state_check CHECK ((voice_state = ANY (ARRAY['none'::text, 'provisioning'::text, 'answering'::text, 'failed'::text]))),
    CONSTRAINT lines_whatsapp_state_check CHECK ((whatsapp_state = ANY (ARRAY['none'::text, 'connecting'::text, 'connected'::text, 'coexistence'::text, 'failed'::text])))
);


--
-- Name: TABLE lines; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.lines IS 'The number as an ASSET: one row per number Chanlytics bought or forwards, and the state of getting it working -- subaccount, trunk, receptionist, messaging service, carrier registration, porting, forwarding. Routing lives in tenant_channels, which this table is the source for (tenant_channels.config.line_id points back here). A number provisioned elsewhere -- inside Retell, or a WhatsApp number through Meta -- has a channel row and no row here.';


--
-- Name: COLUMN lines.reg_sole_prop; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.lines.reg_sole_prop IS 'True when the carrier registration on this line is the SOLE_PROPRIETOR brand rather than the standard one: one number, one campaign, about one message a second. Written when the filing is made, never derived from the business record afterwards -- the record can change and the filed brand cannot.';


--
-- Name: mailboxes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.mailboxes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
