    CONSTRAINT partner_earnings_paid_has_payout CHECK (((state = 'paid'::text) = (payout_id IS NOT NULL))),
    CONSTRAINT partner_earnings_share_bp_check CHECK (((share_bp >= 0) AND (share_bp <= 10000))),
    CONSTRAINT partner_earnings_state_check CHECK ((state = ANY (ARRAY['held'::text, 'payable'::text, 'paid'::text, 'void'::text])))
);


--
-- Name: TABLE partner_earnings; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.partner_earnings IS 'What a partner earned (0012), one row per movement, written only by the Stripe webhook through partner_earn and partner_reverse. held until payable_at, then payable once the workspace qualifies; void when it is disqualified while held.';


