    CONSTRAINT partner_reversals_waiting_amount_cents_check CHECK ((amount_cents >= 0)),
    CONSTRAINT partner_reversals_waiting_kind_check CHECK ((kind = ANY (ARRAY['refund'::text, 'dispute'::text, 'dispute_won'::text])))
);


--
-- Name: TABLE partner_reversals_waiting; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.partner_reversals_waiting IS 'A refund or dispute of an invoice whose share is not written yet (0012): applied by partner_earn when the share arrives, forgotten after 120 days. The service role''s alone.';


--
-- Name: partner_tenants; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.partner_tenants (
    tenant_id uuid NOT NULL,
    partner_id uuid NOT NULL,
    code_used text NOT NULL,
    attributed_at timestamp with time zone DEFAULT now() NOT NULL,
    standing text,
    standing_why text,
    standing_by uuid,
    standing_at timestamp with time zone,
    checks jsonb DEFAULT '{}'::jsonb NOT NULL,
    seat_held_at timestamp with time zone,
    origin text DEFAULT 'link'::text NOT NULL,
    handover_email text,
    handover_sent_at timestamp with time zone,
    handover_expires_at timestamp with time zone,
    handover_accepted_at timestamp with time zone,
    handover_accepted_by uuid,
    handover_declined_at timestamp with time zone,
    invited_by uuid,
    CONSTRAINT partner_tenants_handover_check CHECK ((((origin = ANY (ARRAY['link'::text, 'invite'::text])) AND (handover_email IS NULL) AND (handover_sent_at IS NULL) AND (handover_expires_at IS NULL) AND (handover_accepted_at IS NULL) AND (handover_declined_at IS NULL)) OR ((origin = 'handover'::text) AND (handover_email IS NOT NULL) AND (handover_email = lower(handover_email)) AND (handover_sent_at IS NOT NULL) AND (handover_expires_at IS NOT NULL)))),
    CONSTRAINT partner_tenants_origin_check CHECK ((origin = ANY (ARRAY['link'::text, 'handover'::text, 'invite'::text]))),
    CONSTRAINT partner_tenants_standing_check CHECK ((standing = ANY (ARRAY['qualified'::text, 'review'::text, 'disqualified'::text])))
);


--
-- Name: TABLE partner_tenants; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.partner_tenants IS 'Which partner brought this workspace (0012), one row per workspace and never moved to another partner: through their link when it was made, set up and handed over (0016), or asked for by its owner (0018), as origin says. standing is what the sweep, a person, or the rule as an invited partner joined decided about it; null until one has.';


--
-- Name: COLUMN partner_tenants.seat_held_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.partner_tenants.seat_held_at IS 'When pausing the partner took their seat on this workspace (0012): their membership is a viewer''s until partner_status_set restores it. Null when the seat was never taken.';


--
-- Name: COLUMN partner_tenants.origin; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.partner_tenants.origin IS 'How the partner came to this workspace: link, the business made it through their link (0012); handover, the partner made it and handed it to its owner (0016); invite, its owner asked the partner to join it (0018).';


--
-- Name: COLUMN partner_tenants.handover_email; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.partner_tenants.handover_email IS 'The address the workspace is handed to (0016), lower case. Only its owner by that address may accept it.';


