    CONSTRAINT partners_status_check CHECK ((status = ANY (ARRAY['active'::text, 'paused'::text, 'closed'::text])))
);


--
-- Name: TABLE partners; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.partners IS 'A partner (0012): a person who brings workspaces to Chanlytics through their link, sets them up as a member of their team, and earns share_bp of what each pays. One per account.';


--
-- Name: COLUMN partners.letters; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.partners.letters IS 'Whether the partner is emailed what changed in their ledger, once a day (0014). Theirs to turn off.';


--
-- Name: COLUMN partners.written_through; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.partners.written_through IS 'Every change to this partner''s ledger up to this instant has been written to them, or was not theirs to hear (letters off) (0014).';


--
-- Name: COLUMN partners.second_factor_reset_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.partners.second_factor_reset_at IS 'When a person at Chanlytics last removed this partner''s second factor (0013), so they could enrol again. The why is second_factor_reset_why, the who second_factor_reset_by.';


--
-- Name: person_moments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.person_moments (
    contact_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    added_at timestamp with time zone NOT NULL,
    last_word_at timestamp with time zone,
    last_call_at timestamp with time zone,
    first_word_at timestamp with time zone,
    first_call_at timestamp with time zone,
    first_row_at timestamp with time zone,
    moved_in boolean DEFAULT false NOT NULL,
    in_touch_at timestamp with time zone GENERATED ALWAYS AS (COALESCE(GREATEST(last_word_at, last_call_at), '-infinity'::timestamp with time zone)) STORED NOT NULL,
    new_at timestamp with time zone GENERATED ALWAYS AS (
CASE
    WHEN (NOT moved_in) THEN COALESCE(LEAST(first_word_at, first_call_at), first_row_at)
    ELSE NULL::timestamp with time zone
END) STORED
);


--
-- Name: TABLE person_moments; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.person_moments IS 'Each person''s moments, kept as their messages and calls are written (0021): when they were last in touch, which orders People, and when they first got in touch, which says who is new. Written only by the triggers on contacts, messages and calls, and by the fill.';


--
-- Name: person_notes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.person_notes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    contact_id uuid NOT NULL,
    body text NOT NULL,
    author_kind text DEFAULT 'member'::text NOT NULL,
    author_user_id uuid,
    for_user_id uuid,
    team_only boolean DEFAULT false NOT NULL,
    state text DEFAULT 'kept'::text NOT NULL,
    source text DEFAULT 'page'::text NOT NULL,
    source_id uuid,
    kept_by uuid,
    kept_at timestamp with time zone,
    version integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    due_on date,
    done_at timestamp with time zone,
    done_by uuid,
    deal_id uuid,
    CONSTRAINT person_notes_author_check CHECK ((((author_kind = 'member'::text) AND (state = 'kept'::text)) OR (author_kind = 'receptionist'::text))),
    CONSTRAINT person_notes_author_kind_check CHECK ((author_kind = ANY (ARRAY['member'::text, 'receptionist'::text]))),
    CONSTRAINT person_notes_body_check CHECK (((char_length(body) >= 1) AND (char_length(body) <= 600))),
    CONSTRAINT person_notes_done_is_a_step CHECK (((done_at IS NULL) OR (due_on IS NOT NULL))),
    CONSTRAINT person_notes_source_check CHECK ((source = ANY (ARRAY['page'::text, 'bulk'::text, 'moved'::text, 'call'::text, 'thread'::text, 'reach_out'::text]))),
    CONSTRAINT person_notes_state_check CHECK ((state = ANY (ARRAY['kept'::text, 'suggested'::text]))),
    CONSTRAINT person_notes_step_is_the_teams CHECK (((due_on IS NULL) OR team_only))
);


--
-- Name: TABLE person_notes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.person_notes IS 'A person''s notes (0007), one row each: the words, who wrote them (a member, or the receptionist), when, the member they are for, and whether they are for the team only. The receptionist reads kept notes that are not team_only; its own notes are suggested until a member keeps them. Written only by the person_note_* doors. Never sent to the customer.';


--
-- Name: COLUMN person_notes.due_on; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.person_notes.due_on IS 'The day this note is due (0007, amended): a note with a day is a step, the team''s only (person_notes_step_is_the_teams). By the business''s calendar; null for a note.';


--
-- Name: COLUMN person_notes.done_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.person_notes.done_at IS 'When the step was done; null while it is open. Only a step is done (person_notes_done_is_a_step).';


--
-- Name: COLUMN person_notes.done_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.person_notes.done_by IS 'Who marked the step done; null while it is open, and for a member no longer on the team.';


--
-- Name: COLUMN person_notes.deal_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.person_notes.deal_id IS 'The deal this note moves, when it names one: one of the person''s own (the doors refuse anyone else''s). Kept, as null, when the deal goes.';


--
-- Name: platform_admins; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.platform_admins (
    user_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: playbooks; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.playbooks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    name text NOT NULL,
    trigger text NOT NULL,
    template_id uuid,
    template_name text,
    template_language text,
    params jsonb DEFAULT '[]'::jsonb NOT NULL,
    policy_class text NOT NULL,
    state text DEFAULT 'running'::text NOT NULL,
    run_hour integer DEFAULT 10 NOT NULL,
    cap_per_run integer DEFAULT 25 NOT NULL,
    gap_days integer DEFAULT 90 NOT NULL,
    cadence_days integer DEFAULT 30 NOT NULL,
    created_by uuid,
    last_run_for date,
    last_run_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    list_id uuid,
    list_key text,
    kind text DEFAULT 'moment'::text NOT NULL,
    lead_search_id uuid,
    after_playbook_id uuid,
    after_days integer,
    gap_minutes integer,
    domain_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    signed_by text,
    include_unconfirmed boolean DEFAULT false NOT NULL,
    hand jsonb,
    CONSTRAINT playbooks_cadence_days_check CHECK (((cadence_days >= 1) AND (cadence_days <= 90))),
    CONSTRAINT playbooks_cap_per_run_check CHECK (((cap_per_run >= 1) AND (cap_per_run <= 500))),
    CONSTRAINT playbooks_gap_days_check CHECK (((gap_days >= 7) AND (gap_days <= 365))),
    CONSTRAINT playbooks_kind_check CHECK ((kind = ANY (ARRAY['moment'::text, 'reach_out'::text]))),
    CONSTRAINT playbooks_list_key_shape CHECK (((list_key IS NULL) OR (list_key ~ '^[a-z_]{1,40}$'::text))),
    CONSTRAINT playbooks_name_check CHECK (((length(name) >= 1) AND (length(name) <= 80))),
    CONSTRAINT playbooks_one_list CHECK (((list_key IS NULL) OR (list_id IS NULL))),
    CONSTRAINT playbooks_policy_class_check CHECK ((policy_class = ANY (ARRAY['reengage'::text, 'campaign'::text, 'booking'::text, 'follow_up'::text, 'outreach'::text]))),
    CONSTRAINT playbooks_reach_out_gap CHECK (((kind <> 'reach_out'::text) OR (gap_minutes = ANY (ARRAY[5, 8, 12, 20, 30, 60])))),
    CONSTRAINT playbooks_reach_out_shape CHECK (
CASE kind
    WHEN 'reach_out'::text THEN COALESCE(((policy_class = 'outreach'::text) AND (gap_minutes IS NOT NULL) AND ((gap_minutes >= 5) AND (gap_minutes <= 120)) AND
    CASE trigger
        WHEN 'lead_first'::text THEN ((lead_search_id IS NOT NULL) AND (after_playbook_id IS NULL) AND (after_days IS NULL))
        WHEN 'after_step'::text THEN ((after_playbook_id IS NOT NULL) AND (after_days IS NOT NULL) AND ((after_days >= 2) AND (after_days <= 30)) AND (lead_search_id IS NULL))
        ELSE false
    END), false)
    ELSE COALESCE(((policy_class <> 'outreach'::text) AND (trigger <> ALL (ARRAY['lead_first'::text, 'after_step'::text])) AND (lead_search_id IS NULL) AND (after_playbook_id IS NULL) AND (after_days IS NULL) AND (gap_minutes IS NULL) AND (domain_ids = '{}'::uuid[])), false)
END),
    CONSTRAINT playbooks_root_settings CHECK ((((signed_by IS NULL) OR ((char_length(btrim(signed_by)) >= 1) AND (char_length(btrim(signed_by)) <= 60))) AND (((kind = 'reach_out'::text) AND (trigger = 'lead_first'::text)) OR ((signed_by IS NULL) AND (NOT include_unconfirmed))))),
    CONSTRAINT playbooks_run_hour_check CHECK (((run_hour >= 9) AND (run_hour <= 20))),
    CONSTRAINT playbooks_state_check CHECK ((state = ANY (ARRAY['running'::text, 'paused'::text]))),
    CONSTRAINT playbooks_template_or_hand CHECK (
CASE
    WHEN (hand IS NULL) THEN ((template_id IS NOT NULL) AND (template_name IS NOT NULL) AND (template_language IS NOT NULL))
    ELSE COALESCE(((kind = 'reach_out'::text) AND (trigger = 'after_step'::text) AND (template_id IS NULL) AND (template_name IS NULL) AND (template_language IS NULL) AND (jsonb_typeof(hand) = 'object'::text) AND ((hand ->> 'kind'::text) = ANY (ARRAY['call'::text, 'note'::text])) AND (jsonb_typeof((hand -> 'words'::text)) = 'string'::text) AND ((char_length(btrim((hand ->> 'words'::text))) >= 1) AND (char_length(btrim((hand ->> 'words'::text))) <= 280)) AND (((hand - 'kind'::text) - 'words'::text) = '{}'::jsonb)), false)
END),
    CONSTRAINT playbooks_trigger_check CHECK ((trigger = ANY (ARRAY['quiet_30'::text, 'new_week'::text, 'phoned_only'::text, 'everyone_monthly'::text, 'visit_tomorrow'::text, 'visited'::text, 'lapsed'::text, 'saved_list'::text, 'proposal_waiting'::text, 'lead_first'::text, 'after_step'::text])))
);


--
-- Name: COLUMN playbooks.list_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.playbooks.list_id IS 'The list of the workspace''s own a saved_list playbook runs on. A list a playbook names is archived, never deleted (0009): the playbook pauses and keeps it.';


--
-- Name: COLUMN playbooks.list_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.playbooks.list_key IS 'The People list a saved_list playbook runs on, by its id (contracts lists.ts BUILTIN_LISTS). Null when it runs on one of the workspace''s own lists (list_id), and for every other trigger.';


--
-- Name: COLUMN playbooks.hand; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.playbooks.hand IS 'A reach-out''s last step that hands each lead it reaches to the team (Reach out Part 5, G20): {kind: call | note, words}. Such a step has no template.';


--
-- Name: policies; Type: TABLE; Schema: public; Owner: -
