    CONSTRAINT segments_name_check CHECK (((length(name) >= 1) AND (length(name) <= 60))),
    CONSTRAINT segments_rule_is_an_object CHECK (((rule IS NULL) OR (jsonb_typeof(rule) = 'object'::text)))
);


--
-- Name: COLUMN segments.rule; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.segments.rule IS 'A smart list''s rule, in contracts list-rules.ts''s vocabulary: who is on it is judged on every read. Null for a list kept by hand.';


--
-- Name: COLUMN segments.archived_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.segments.archived_at IS 'When the list was archived: it leaves People''s rail and still resolves for the playbooks that name it. Null for a live list.';


--
-- Name: sending_domains; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sending_domains (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    host text NOT NULL,
    from_local text NOT NULL,
    from_name text NOT NULL,
    provider_domain_id text,
    records jsonb DEFAULT '[]'::jsonb NOT NULL,
    state text DEFAULT 'records'::text NOT NULL,
    provider_status text,
    dmarc text,
    held_why text,
    held_at timestamp with time zone,
    verified_at timestamp with time zone,
    clean_since timestamp with time zone,
    checked_at timestamp with time zone,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    sent_recent integer,
    bounced_recent integer,
    complaints integer,
    counted_since timestamp with time zone,
    sent_days integer,
    resume_by text DEFAULT 'owner'::text NOT NULL,
    CONSTRAINT sending_domains_dmarc_check CHECK ((dmarc = ANY (ARRAY['found'::text, 'missing'::text]))),
    CONSTRAINT sending_domains_from_local_check CHECK (((char_length(from_local) <= 40) AND (from_local ~ '^[a-z0-9]+([.-][a-z0-9]+)*$'::text))),
    CONSTRAINT sending_domains_from_name_check CHECK (((char_length(btrim(from_name)) >= 1) AND (char_length(btrim(from_name)) <= 80))),
    CONSTRAINT sending_domains_held_is_whole CHECK ((((state = 'held'::text) = (held_why IS NOT NULL)) AND ((held_why IS NULL) = (held_at IS NULL)))),
    CONSTRAINT sending_domains_held_why_check CHECK ((held_why = ANY (ARRAY['verification'::text, 'dmarc'::text, 'bounces'::text, 'complaint'::text, 'provider'::text, 'unsubscribes'::text]))),
    CONSTRAINT sending_domains_host_check CHECK ((((char_length(host) >= 4) AND (char_length(host) <= 253)) AND (host ~ '^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$'::text))),
    CONSTRAINT sending_domains_records_check CHECK ((jsonb_typeof(records) = 'array'::text)),
    CONSTRAINT sending_domains_resume_by_check CHECK ((resume_by = ANY (ARRAY['owner'::text, 'platform'::text]))),
    CONSTRAINT sending_domains_sending_is_dated CHECK (((state <> ALL (ARRAY['verified'::text, 'held'::text])) OR ((verified_at IS NOT NULL) AND (clean_since IS NOT NULL)))),
    CONSTRAINT sending_domains_state_check CHECK ((state = ANY (ARRAY['records'::text, 'verifying'::text, 'verified'::text, 'held'::text])))
);


--
-- Name: TABLE sending_domains; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.sending_domains IS 'The domains a workspace sends cold email from (Reach out): the identity, the provider''s records, and where each stands. Members read; the service role writes (apps/edge lib/email/sending-domains.ts).';


--
-- Name: COLUMN sending_domains.counted_since; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sending_domains.counted_since IS 'Where the reputation count starts (bounces, complaints): set when the domain is first verified and when its owner resumes it, never by a DNS release. clean_since is the ramp''s clock (contracts domainDailyCap).';


--
-- Name: COLUMN sending_domains.sent_days; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sending_domains.sent_days IS 'The days it sent on before today since it was clean, within the last 90 (sending_domain_capacity, D15), as the domains clock last wrote them: the ramp the send door and Connections read. Zero when clean again (a hold released, a first verify); null until written, read as none.';


--
-- Name: COLUMN sending_domains.resume_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sending_domains.resume_by IS 'Who lifts its reputation hold: the owner (Resume), or the platform, when it was held for its reputation twice in thirty days (Reach out D16, 00188).';


--
-- Name: sweep_status; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sweep_status (
    sweep text NOT NULL,
    request_id bigint,
    requested_at timestamp with time zone,
    note text,
    alerted_at timestamp with time zone,
    backlog_ticks integer DEFAULT 0 NOT NULL,
    jobname text,
    max_silence interval,
    judged_by text DEFAULT 'request'::text NOT NULL,
    registered_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT sweep_status_judged_by_check CHECK ((judged_by = ANY (ARRAY['request'::text, 'run'::text])))
);


--
-- Name: TABLE sweep_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.sweep_status IS 'One row per pg_cron -> pg_net sweep: the last request id (joins net._http_response.id), when it was enqueued, why it could not be, and when we last emailed about it being broken.';


--
-- Name: COLUMN sweep_status.note; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sweep_status.note IS 'Set when the trigger could not send at all (missing Vault secret). Cleared by the next tick that either sends successfully or finds nothing to send. Distinct from a failed RESPONSE, which has no note and a status_code.';


--
-- Name: COLUMN sweep_status.alerted_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sweep_status.alerted_at IS 'Suppression stamp, set only after an alert was actually DELIVERED, cleared on recovery.';


--
-- Name: COLUMN sweep_status.backlog_ticks; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sweep_status.backlog_ticks IS 'Consecutive ticks this sweep finished with work still queued. Reset to 0 the moment it drains. At 3 the sweep answers 503, which turns it red in sweep_health and mails the platform.';


--
-- Name: COLUMN sweep_status.jobname; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sweep_status.jobname IS 'The cron.job this clock is. Null means unregistered, which sweep_health() reports as unhealthy.';


--
-- Name: COLUMN sweep_status.max_silence; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sweep_status.max_silence IS 'How long the clock may go without speaking (a request enqueued, or a run that succeeded) before it is unhealthy. Null: silence is not a fault; only the last answer is judged.';


--
-- Name: COLUMN sweep_status.judged_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sweep_status.judged_by IS 'request: judged on the HTTP request it enqueued and what the edge answered. run: judged on cron.job_run_details, for the jobs that never leave the database.';


--
-- Name: COLUMN sweep_status.registered_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sweep_status.registered_at IS 'A run-judged clock that has never run is healthy until max_silence has passed since it was registered.';


--
-- Name: templates; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.templates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    channel text NOT NULL,
    name text NOT NULL,
    language text NOT NULL,
    meta_status text DEFAULT 'pending'::text NOT NULL,
    body_preview text,
    variables jsonb DEFAULT '[]'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    category text,
    meta_id text,
    components jsonb,
    quality text,
    rejected_reason text,
    synced_at timestamp with time zone,
    source text DEFAULT 'meta'::text NOT NULL,
    created_by uuid,
    hidden_at timestamp with time zone,
    title text,
    CONSTRAINT templates_category_check CHECK ((category = ANY (ARRAY['marketing'::text, 'utility'::text, 'authentication'::text]))),
    CONSTRAINT templates_channel_check CHECK ((channel = ANY (ARRAY['whatsapp'::text, 'voice'::text, 'sms'::text, 'email'::text, 'instagram'::text]))),
    CONSTRAINT templates_meta_status_check CHECK ((meta_status = ANY (ARRAY['approved'::text, 'pending'::text, 'rejected'::text, 'paused'::text, 'disabled'::text]))),
    CONSTRAINT templates_source_check CHECK ((source = ANY (ARRAY['meta'::text, 'chanlytics'::text]))),
    CONSTRAINT templates_title_check CHECK (((title IS NULL) OR ((char_length(title) >= 1) AND (char_length(title) <= 60))))
);


--
-- Name: COLUMN templates.category; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.templates.category IS 'Meta''s category: marketing (needs the customer''s recorded yes), utility, authentication. Null until synced.';


--
-- Name: COLUMN templates.synced_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.templates.synced_at IS 'When the row last matched what Meta returned. Null means written by hand or by a webhook only.';


--
-- Name: COLUMN templates.source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.templates.source IS 'meta: written in WhatsApp Manager and read by the sync. chanlytics: written here and submitted to Meta.';


--
-- Name: COLUMN templates.hidden_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.templates.hidden_at IS 'Hidden from the composers by the workspace (or on first sight, for Meta''s sample). The row stays, syncs keep it, the wire may still send it by name.';


--
-- Name: COLUMN templates.title; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.templates.title IS 'What the workspace calls the template; null means its Meta name, made words. Never sent anywhere.';


--
-- Name: tenant_channels; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tenant_channels (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    kind text NOT NULL,
    external_id text NOT NULL,
    number_e164 text,
    waba_id text,
    credentials_ref text,
    status text DEFAULT 'active'::text NOT NULL,
    config jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tenant_channels_kind_check CHECK ((kind = ANY (ARRAY['whatsapp'::text, 'voice'::text, 'sms'::text, 'email'::text, 'instagram'::text]))),
    CONSTRAINT tenant_channels_status_check CHECK ((status = ANY (ARRAY['active'::text, 'disabled'::text])))
);


--
-- Name: TABLE tenant_channels; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.tenant_channels IS 'The ROUTING table: one row per thing an inbound webhook must resolve to a workspace. A voice row is keyed on the receptionist (external_id = agent id) so several numbers may share one; an sms or whatsapp row is keyed on the number, because a message arrives addressed to one. config.line_id names the lines row that created it, when a line did -- numbers provisioned inside Retell or through Meta legitimately have none. See public.number_drift() for what disagreement between the two looks like.';


--
-- Name: COLUMN tenant_channels.config; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_channels.config IS 'Provider facts for this route. Set by the provisioning saga: line_id (the lines row behind it, when there is one), provider, messaging_service_sid, provisioned_at, provisioned_by.';


--
-- Name: tenant_config; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tenant_config (
    tenant_id uuid NOT NULL,
    config jsonb DEFAULT '{}'::jsonb NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    calendar_checked_at timestamp with time zone
);


--
-- Name: COLUMN tenant_config.updated_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_config.updated_by IS 'Who last wrote this config. Null for rows written before 00085, and for writes the platform makes on a workspace''s behalf. The change itself is in events (kind = settings.changed).';


--
-- Name: COLUMN tenant_config.calendar_checked_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_config.calendar_checked_at IS 'When the calendar sweep last read this workspace''s feed. Null = never, and never is served first. Ordering on this is what stops the sweep serving the same early tenants every hour once there are more workspaces than fit in one tick.';


--
-- Name: tenants; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tenants (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    slug text NOT NULL,
    name text NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    timezone text DEFAULT 'America/New_York'::text NOT NULL,
    locale text DEFAULT 'en'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    sells_by text,
    left_empty_at timestamp with time zone,
    CONSTRAINT tenants_sells_by_check CHECK (((sells_by IS NULL) OR (sells_by = ANY (ARRAY['booking'::text, 'proposal'::text])))),
    CONSTRAINT tenants_status_check CHECK ((status = ANY (ARRAY['active'::text, 'paused'::text, 'test'::text])))
);


--
-- Name: COLUMN tenants.timezone; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenants.timezone IS 'IANA zone. Decides what "today" means in metrics (00009), which closures are upcoming, and the hours the receptionist states. Owner-settable since 00084; validated as a real zone by the contracts layer, which is the only place that can ask Intl.';


--
-- Name: COLUMN tenants.sells_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenants.sells_by IS 'How this workspace''s customers buy (0008): booking (they book an appointment) or proposal (some get a proposal first). Deals are on exactly when it is proposal; null is not asked yet. Owner-settable through PATCH workspaces, like the timezone (00084).';


--
-- Name: COLUMN tenants.left_empty_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenants.left_empty_at IS 'When the workspace''s last member left it (delete_my_account, 00262): it is paused, its plan is ended, and billing never resumes it. Null while anyone is in it.';


--
-- Name: usage_ledger; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.usage_ledger WITH (security_invoker='true') AS
 SELECT u.tenant_id,
    u.created_at AS at,
    'model'::text AS meter,
    u.purpose,
    u.model,
    ((((u.input_tokens + u.output_tokens) + u.cache_read_tokens) + u.cache_write_tokens))::numeric AS quantity,
    u.input_tokens,
    u.output_tokens,
    u.cache_read_tokens,
    u.cache_write_tokens,
    u.usd
   FROM public.ai_usage u
  WHERE (NOT u.shadow)
UNION ALL
 SELECT e.tenant_id,
    e.created_at AS at,
    'voice_seconds'::text AS meter,
    NULL::text AS purpose,
    NULL::text AS model,
    COALESCE(((e.data ->> 'seconds'::text))::numeric, (0)::numeric) AS quantity,
    0 AS input_tokens,
    0 AS output_tokens,
    0 AS cache_read_tokens,
    0 AS cache_write_tokens,
    NULL::numeric AS usd
   FROM public.events e
  WHERE (e.kind = 'usage.voice_seconds'::text)
UNION ALL
 SELECT e.tenant_id,
    e.created_at AS at,
    'wa_conversation'::text AS meter,
    NULL::text AS purpose,
    NULL::text AS model,
    1 AS quantity,
    0 AS input_tokens,
    0 AS output_tokens,
    0 AS cache_read_tokens,
    0 AS cache_write_tokens,
    NULL::numeric AS usd
   FROM public.events e
  WHERE (e.kind = 'usage.wa_conversation'::text);


--
-- Name: VIEW usage_ledger; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.usage_ledger IS 'A workspace''s metered use, one row per use: each model call (ai_usage, with its dollars), each call''s seconds and each WhatsApp conversation opened (the usage events the reports read). Security invoker: a member reads their own workspace''s rows.';


--
-- Name: waitlist; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.waitlist (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    email text NOT NULL,
    business text,
    source text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    invited_at timestamp with time zone,
    invited_by uuid
);


--
-- Name: TABLE waitlist; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.waitlist IS 'People who asked for a workspace while sign-up was closed. Service-role only: deny-all RLS, no policies, because nobody here has a workspace to be scoped to yet. Drained oldest-first; invited_at is the stamp that takes a row out of the queue.';


--
-- Name: COLUMN waitlist.invited_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.waitlist.invited_at IS 'When an invite was sent. Null means still waiting, and the partial index on that predicate is what makes the queue cheap to read.';


