--
-- Name: ask_messages ask_messages_own_delete; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY ask_messages_own_delete ON public.ask_messages FOR DELETE TO authenticated USING ((user_id = ( SELECT auth.uid() AS uid)));


--
-- Name: ask_messages ask_messages_own_insert; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY ask_messages_own_insert ON public.ask_messages FOR INSERT TO authenticated WITH CHECK (((user_id = ( SELECT auth.uid() AS uid)) AND (EXISTS ( SELECT 1
   FROM public.ask_threads t
  WHERE ((t.id = ask_messages.thread_id) AND (t.user_id = ( SELECT auth.uid() AS uid)) AND (t.tenant_id = ask_messages.tenant_id))))));


--
-- Name: ask_messages ask_messages_own_select; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY ask_messages_own_select ON public.ask_messages FOR SELECT TO authenticated USING (((user_id = ( SELECT auth.uid() AS uid)) AND (EXISTS ( SELECT 1
   FROM public.memberships m
  WHERE ((m.user_id = ( SELECT auth.uid() AS uid)) AND (m.tenant_id = ask_messages.tenant_id))))));


